@dataclass(frozen=True)
class FaltinsenCase:
    boat: BoatConfig
    waves: WaveConfig
    equilibrium: EquilibriumState
    bow_x_from_cg_m: float
    expected_lambda_w: float
    expected_trim_deg: float
    expected_fn_b: float


def make_faltinsen_ch9_case() -> FaltinsenCase:
    """Return the prescribed running condition used in Faltinsen Ch. 9 examples."""

    b = 1.0
    rho = 1025.0
    g = 9.80665
    fn_b = 3.0
    beta_deg = 20.0
    state = PrescribedRunningStateConfig(
        enabled=True,
        trim_deg=4.0,
        lambda_w=4.0,
        fn_b=fn_b,
        mass_over_rho_b3=1.28,
        lcg_over_b=2.13,
        vcg_over_b=0.25,
        r55_over_b=1.3,
    )
    base_boat = BoatConfig(
        length_m=6.5 * b,
        beam_m=b,
        deadrise_deg=beta_deg,
        mass_kg=1.0,
        lcg_m=2.13,
        vcg_m=0.25,
        pitch_radius_gyration_m=1.3,
        rho_water_kg_m3=rho,
        gravity_m_s2=g,
        wetted_lengths_type=1,
        initial_trim_deg=4.0,
        initial_z_wl_m=0.0,
    )
    boat = boat_with_prescribed_ratios(base_boat, state)
    speed = fn_b * math.sqrt(g * b)
    eq = make_prescribed_equilibrium(boat, speed, state)
    waves = WaveConfig(
        heading_deg=180.0,
        regular_height_m=0.02,
        regular_period_s=3.0,
        period_min_s=0.8,
        period_max_s=8.0,
        period_count=180,
        spectrum="pm",
        significant_height_m=0.02,
        peak_period_s=3.0,
        component_count=64,
        seed=20260717,
    )
    return FaltinsenCase(
        boat=boat,
        waves=waves,
        equilibrium=eq,
        bow_x_from_cg_m=-(boat.length_m - boat.lcg_m),
        expected_lambda_w=float(state.lambda_w),
        expected_trim_deg=float(state.trim_deg),
        expected_fn_b=fn_b,
    )


def _status_from_error(error: float | None, tolerance: float | None) -> str:
    if error is None or tolerance is None:
        return "NOT_EVALUATED"
    if not np.isfinite(error):
        return "FAIL"
    return "PASS" if error <= tolerance else "FAIL"


def _row(
    metric: str,
    expected: float | str,
    actual: float | str,
    tolerance: float | None,
    rel_error: float | None = None,
    status: str | None = None,
    note: str = "",
    benchmark: str = "faltinsen_ch9_prescribed_state",
) -> dict[str, float | str]:
    if status is None:
        status = _status_from_error(rel_error, tolerance)
    return {
        "benchmark": benchmark,
        "metric": metric,
        "expected": expected,
        "actual": actual,
        "rel_error": "" if rel_error is None else rel_error,
        "tolerance": "" if tolerance is None else tolerance,
        "status": status,
        "note": note,
    }


def _regular_components_for_validation(waves: WaveConfig, eq: EquilibriumState, g: float) -> WaveComponents:
    omega0 = np.array([2.0 * math.pi / waves.regular_period_s], dtype=float)
    omega_e = omega0 + (omega0**2 / g) * eq.speed_through_water_mps
    return WaveComponents(
        omega0=omega0,
        omega_e=omega_e,
        wavenumber=omega0**2 / g,
        amplitude=np.array([0.5 * waves.regular_height_m], dtype=float),
        phase=np.array([0.0], dtype=float),
    )


def _positive_imag_modes(eigenvalues: np.ndarray, nondim_scale: float) -> list[complex]:
    scaled = list(eigenvalues * nondim_scale)
    positive = [v for v in scaled if np.imag(v) > 1e-7]
    if len(positive) >= 2:
        return sorted(positive, key=lambda value: float(np.imag(value)), reverse=True)[:2]
    return sorted(scaled, key=lambda value: abs(float(np.imag(value))), reverse=True)[:2]


def _faltinsen_table_9_2_eigenvalue_comparison(matrices: HydroMatrices, boat: BoatConfig) -> pd.DataFrame:
    nondim_scale = math.sqrt(boat.beam_m / boat.gravity_m_s2)
    modes = _positive_imag_modes(matrices.stability_eigenvalues, nondim_scale)
    rows: list[dict[str, float | str]] = []
    for index, expected in enumerate(FALTINSEN_TABLE_9_2_MODES):
        actual = modes[index] if index < len(modes) else complex(float("nan"), float("nan"))
        real = float(np.real(actual))
        imag = abs(float(np.imag(actual)))
        expected_real = float(expected["real"])
        expected_imag = float(expected["imag_abs"])
        real_error = abs(real - expected_real) / max(abs(expected_real), 1e-12)
        imag_error = abs(imag - expected_imag) / max(abs(expected_imag), 1e-12)
        rows.append(
            {
                "benchmark": "faltinsen_ch9_prescribed_state",
                "source": "Faltinsen Table 9.2",
                "mode": str(expected["mode"]),
                "actual_eigenvalue_nondim": f"{real:+.10g}{float(np.imag(actual)):+.10g}j"
                if np.isfinite(real) and np.isfinite(float(np.imag(actual)))
                else "",
                "expected_real_part": expected_real,
                "actual_real_part": real,
                "real_part_rel_error": real_error,
                "real_part_tolerance": 0.10,
                "real_part_status": _status_from_error(real_error, 0.10),
                "expected_imaginary_abs": expected_imag,
                "actual_imaginary_abs": imag,
                "imaginary_abs_rel_error": imag_error,
                "imaginary_abs_tolerance": 0.10,
                "imaginary_abs_status": _status_from_error(imag_error, 0.10),
                "mode_status": "PASS"
                if _status_from_error(real_error, 0.10) == "PASS"
                and _status_from_error(imag_error, 0.10) == "PASS"
                else "FAIL",
                "nondim_scale": nondim_scale,
            }
        )
    return pd.DataFrame(rows)


def _add_eigenvalue_rows(rows: list[dict[str, float | str]], matrices: HydroMatrices, boat: BoatConfig) -> None:
    comparison = _faltinsen_table_9_2_eigenvalue_comparison(matrices, boat)
    for _, item in comparison.iterrows():
        rows.append(
            _row(
                f"{item['mode']}_real_part",
                float(item["expected_real_part"]),
                float(item["actual_real_part"]),
                float(item["real_part_tolerance"]),
                float(item["real_part_rel_error"]),
                status=str(item["real_part_status"]),
                note="Nondimensional eigenvalue real part, scaled by sqrt(B/g).",
            )
        )
        rows.append(
            _row(
                f"{item['mode']}_imaginary_part",
                float(item["expected_imaginary_abs"]),
                float(item["actual_imaginary_abs"]),
                float(item["imaginary_abs_tolerance"]),
                float(item["imaginary_abs_rel_error"]),
                status=str(item["imaginary_abs_status"]),
                note="Nondimensional modal frequency, scaled by sqrt(B/g).",
            )
        )


def _add_running_state_rows(rows: list[dict[str, float | str]], case: FaltinsenCase) -> None:
    eq = case.equilibrium
    rows.extend(
        [
            _row(
                "prescribed_fn_b",
                case.expected_fn_b,
                eq.fn_b,
                1e-9,
                abs(eq.fn_b - case.expected_fn_b) / case.expected_fn_b,
            ),
            _row(
                "prescribed_trim_deg",
                case.expected_trim_deg,
                eq.trim_deg,
                1e-9,
                abs(eq.trim_deg - case.expected_trim_deg) / case.expected_trim_deg,
            ),
            _row(
                "prescribed_lambda_w",
                case.expected_lambda_w,
                eq.geometry.lambda_w,
                1e-6,
                abs(eq.geometry.lambda_w - case.expected_lambda_w) / case.expected_lambda_w,
            ),
            _row(
                "calm_force_heave_residual_weight_fraction",
                "near zero for solved equilibrium",
                eq.residual[0],
                None,
                None,
                "INFO",
                "This benchmark prescribes the running state; this residual diagnoses consistency with the current Savitsky force implementation.",
            ),
            _row(
                "calm_force_pitch_residual_weight_beam_fraction",
                "near zero for solved equilibrium",
                eq.residual[1],
                None,
                None,
                "INFO",
                "This benchmark prescribes the running state; this residual diagnoses consistency with the current Savitsky force implementation.",
            ),
        ]
    )


def _add_rao_rows(rows: list[dict[str, float | str]], rao: pd.DataFrame, boat: BoatConfig) -> None:
    scale = math.sqrt(boat.beam_m / boat.gravity_m_s2)
    rao = rao.copy()
    rao["omega_e_hat"] = rao["omega_e_rad_s"] * scale
    finite = bool(np.isfinite(rao.select_dtypes(include=[np.number]).to_numpy()).all())
    rows.append(
        _row(
            "rao_values_finite",
            "all finite",
            "all finite" if finite else "contains NaN/Inf",
            None,
            None,
            "PASS" if finite else "FAIL",
            "Frequency-domain numerical sanity check.",
        )
    )
    rows.append(
        _row(
            "jump_or_dryout_assessment",
            "not applicable to linear frequency-domain benchmark",
            "not evaluated in Faltinsen Ch. 9 RAO gate",
            None,
            None,
            "INFO",
            "Jumping/flight/dryout must be assessed with Fridsma/Katayama nonlinear time-domain benchmarks.",
        )
    )
    expected_peaks = [float(mode["imag_abs"]) for mode in FALTINSEN_TABLE_9_2_MODES]
    for column, label in [
        ("heave_rao_m_per_m", "heave_rao_peak_location"),
        ("pitch_rao_rad_per_m", "pitch_rao_peak_location"),
    ]:
        idx = int(rao[column].idxmax())
        actual_peak = float(rao.loc[idx, "omega_e_hat"])
        expected_peak = min(expected_peaks, key=lambda value: abs(value - actual_peak))
        rel_error = abs(actual_peak - expected_peak) / expected_peak
        rows.append(
            _row(
                label,
                expected_peak,
                actual_peak,
                0.10,
                rel_error,
                note="Modal peak location checked against the nearest Table 9.2 modal frequency; digitized lambda/L curve checks are reported separately.",
            )
        )

def _load_faltinsen_reference_curves(reference_root: str | Path | None = None) -> dict[str, ReferenceCurve | None]:
    return {
        "heave": load_reference_curve(
            "faltinsen_ch9",
            "fig_9_34_heave_rao_digitized.csv",
            "lambda_over_l",
            "heave_rao_m_per_m",
            reference_root,
        ),
        "pitch": load_reference_curve(
            "faltinsen_ch9",
            "fig_9_35_pitch_rao_digitized.csv",
            "lambda_over_l",
            "pitch_rao_rad_per_wave_slope",
            reference_root,
        ),
    }


def _add_digitized_reference_rows(
    rows: list[dict[str, float | str]],
    rao: pd.DataFrame,
    references: dict[str, ReferenceCurve | None],
    reference_root: str | Path | None,
) -> None:
    specs = [
        ("heave", "heave_rao_m_per_m", "fig_9_34_heave_rao_digitized.csv", 0.10, 0.20, 0.25),
        ("pitch", "pitch_rao_rad_per_wave_slope", "fig_9_35_pitch_rao_digitized.csv", 0.10, 0.20, 0.25),
    ]
    for label, y_column, filename, peak_x_tol, peak_y_tol, rmse_tol in specs:
        reference = references[label]
        if reference is None:
            expected_path = reference_curve_path(reference_root, "faltinsen_ch9", filename)
            rows.append(
                _row(
                    f"{label}_rao_digitized_reference_curve",
                    str(expected_path),
                    "missing",
                    None,
                    None,
                    "NOT_EVALUATED",
                    "Digitize Faltinsen Fig. 9.34/9.35 into this CSV to activate peak-amplitude and curve-shape checks.",
                )
            )
            continue
        comparison = compare_reference_curve(rao, reference.x_column, y_column, reference)
        rows.extend(
            [
                _row(
                    f"{label}_rao_digitized_points",
                    ">=2",
                    len(reference.data),
                    None,
                    None,
                    "PASS",
                    f"Loaded {reference.path}.",
                ),
                _row(
                    f"{label}_rao_digitized_peak_location",
                    comparison.reference_peak_x,
                    comparison.computed_peak_x,
                    peak_x_tol,
                    comparison.peak_x_rel_error,
                    note="Peak location compared against digitized Faltinsen RAO curve in lambda/L coordinates.",
                ),
                _row(
                    f"{label}_rao_digitized_peak_amplitude",
                    comparison.reference_peak_y,
                    comparison.computed_peak_y,
                    peak_y_tol,
                    comparison.peak_y_rel_error,
                    note="Peak amplitude compared against digitized Faltinsen RAO curve.",
                ),
                _row(
                    f"{label}_rao_digitized_curve_nrmse",
                    0.0,
                    comparison.normalized_rmse,
                    rmse_tol,
                    comparison.normalized_rmse,
                    note=f"Normalized RMSE over {comparison.overlap_point_count} overlapping digitized points.",
                ),
            ]
        )


def _plot_faltinsen_rao(
    rao: pd.DataFrame,
    matrices: HydroMatrices,
    boat: BoatConfig,
    path: Path,
    references: dict[str, ReferenceCurve | None] | None = None,
) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    scale = math.sqrt(boat.beam_m / boat.gravity_m_s2)
    data = rao.copy()
    data["omega_e_hat"] = data["omega_e_rad_s"] * scale
    eig_freqs = [mode["imag_abs"] for mode in FALTINSEN_TABLE_9_2_MODES]
    actual_modes = _positive_imag_modes(matrices.stability_eigenvalues, scale)

    fig, axes = plt.subplots(2, 1, figsize=(8, 7), sharex=True)
    x_column = "lambda_over_l" if "lambda_over_l" in data.columns else "omega_e_hat"
    x_label = "Wavelength ratio, lambda/L" if x_column == "lambda_over_l" else "Encounter frequency, omega_e sqrt(B/g)"
    axes[0].plot(data[x_column], data["heave_rao_m_per_m"], label="computed heave")
    pitch_column = "pitch_rao_rad_per_wave_slope" if "pitch_rao_rad_per_wave_slope" in data.columns else "pitch_rao_rad_per_m"
    axes[1].plot(data[x_column], data[pitch_column], label="computed pitch", color="tab:orange")
    if references:
        if references.get("heave") is not None:
            ref = references["heave"]
            axes[0].scatter(ref.data[ref.x_column], ref.data[ref.y_column], s=18, color="black", label="digitized Fig. 9.34")
        if references.get("pitch") is not None:
            ref = references["pitch"]
            axes[1].scatter(ref.data[ref.x_column], ref.data[ref.y_column], s=18, color="black", label="digitized Fig. 9.35")
    for ax in axes:
        if x_column == "omega_e_hat":
            for freq in eig_freqs:
                ax.axvline(freq, color="0.25", linestyle="--", linewidth=0.8, alpha=0.6, label="Faltinsen Table 9.2" if freq == eig_freqs[0] else None)
            for mode in actual_modes:
                ax.axvline(abs(float(np.imag(mode))), color="tab:red", linestyle=":", linewidth=0.9, alpha=0.7)
        ax.grid(True, alpha=0.3)
        ax.legend()
    axes[0].set_ylabel("Heave RAO (m/m)")
    axes[1].set_ylabel("Pitch RAO |eta5|/(k zeta_a)")
    axes[1].set_xlabel(x_label)
    fig.tight_layout()
    fig.savefig(path, dpi=180)
    plt.close(fig)


def _truthy(value: object) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)) and np.isfinite(value):
        return bool(value)
    text = str(value).strip().lower()
    return text in {"1", "true", "t", "yes", "y", "jumping"}


def _katayama_reference_path(reference_root: str | Path | None = None) -> Path:
    return reference_curve_path(reference_root, "katayama", KATAYAMA_CLASSIFICATION_FILENAME)


def _load_katayama_classification_data(reference_root: str | Path | None = None) -> tuple[Path, pd.DataFrame | None, list[str]]:
    path = _katayama_reference_path(reference_root)
    if not path.exists():
        return path, None, KATAYAMA_REQUIRED_COLUMNS
    data = pd.read_csv(path)
    missing = [column for column in KATAYAMA_REQUIRED_COLUMNS if column not in data.columns]
    if missing:
        return path, data, missing
    numeric_columns = [
        "length_m",
        "beam_m",
        "draft_m",
        "mass_kg",
        "lcg_from_transom_m",
        "kg_above_keel_m",
        "deadrise_deg",
        "pitch_radius_gyration_m",
        "fn_l",
        "wave_height_over_draft",
        "lambda_over_loa",
    ]
    for column in numeric_columns:
        data[column] = pd.to_numeric(data[column], errors="coerce")
    data["expected_jumping_bool"] = data["expected_jumping"].map(_truthy)
    data = data.dropna(subset=numeric_columns).reset_index(drop=True)
    return path, data, []


def _wave_period_from_wavelength(wavelength_m: float, g: float) -> float:
    wavenumber = 2.0 * math.pi / max(wavelength_m, 1e-12)
    omega = math.sqrt(g * wavenumber)
    return 2.0 * math.pi / omega


def _katayama_case_prediction(row: pd.Series) -> dict[str, float | str | bool]:
    g = 9.80665
    length = float(row["length_m"])
    beam = float(row["beam_m"])
    draft = float(row["draft_m"])
    lcg = float(row["lcg_from_transom_m"])
    boat = BoatConfig(
        length_m=length,
        beam_m=beam,
        deadrise_deg=float(row["deadrise_deg"]),
        mass_kg=float(row["mass_kg"]),
        lcg_m=lcg,
        vcg_m=float(row["kg_above_keel_m"]),
        pitch_radius_gyration_m=float(row["pitch_radius_gyration_m"]),
        rho_water_kg_m3=1000.0,
        gravity_m_s2=g,
        wetted_lengths_type=1,
        initial_trim_deg=4.0,
        initial_z_wl_m=0.0,
        trim_bounds_deg=(0.5, 18.0),
    )
    speed = float(row["fn_l"]) * math.sqrt(g * length)
    wave_height = float(row["wave_height_over_draft"]) * draft
    wavelength = float(row["lambda_over_loa"]) * length
    wave_period = _wave_period_from_wavelength(wavelength, g)
    waves = WaveConfig(
        heading_deg=180.0,
        regular_height_m=wave_height,
        regular_period_s=wave_period,
        period_min_s=wave_period,
        period_max_s=wave_period,
        period_count=1,
        spectrum="pm",
        significant_height_m=wave_height,
        peak_period_s=wave_period,
        component_count=1,
        seed=20260717,
    )
    eq = solve_equilibrium(boat, speed)
    matrices = compute_hydro_matrices(boat, eq)
    components = _regular_components_for_validation(waves, eq, g)
    duration = max(8.0 * wave_period, 5.0)
    time_step = min(0.01, wave_period / 100.0)
    discard = min(max(2.0 * wave_period, 1.0), 0.5 * duration)
    bow_x = -(length - lcg)
    timeseries = simulate_time_domain(boat, waves, eq, matrices, components, duration, time_step, bow_x)
    steady = timeseries[timeseries["time_s"] >= discard]
    if steady.empty:
        steady = timeseries
    transom_draft = max(eq.geometry.transom_draft_m, 1e-9)
    rel_motion = (steady["heave_m"] - steady["wave_elevation_m"]).abs()
    rel_motion_over_draft = float(rel_motion.max() / transom_draft)
    cg_accel_g = float(steady["heave_accel_mps2"].abs().max() / g)
    bow_accel_g = float(steady["bow_vertical_accel_mps2"].abs().max() / g)
    predicted_jumping = bool(rel_motion_over_draft > KATAYAMA_JUMP_DRYOUT_THRESHOLD)
    return {
        "case_id": str(row["case_id"]),
        "speed_mps": speed,
        "fn_l": float(row["fn_l"]),
        "fn_b": speed / math.sqrt(g * beam),
        "wave_height_m": wave_height,
        "wave_period_s": wave_period,
        "wavelength_m": wavelength,
        "lambda_over_loa": float(row["lambda_over_loa"]),
        "equilibrium_converged": bool(eq.converged),
        "trim_deg": float(eq.trim_deg),
        "lambda_w": float(eq.geometry.lambda_w),
        "transom_draft_m": float(eq.geometry.transom_draft_m),
        "max_relative_heave_over_transom_draft": rel_motion_over_draft,
        "max_cg_vertical_accel_g": cg_accel_g,
        "max_bow_vertical_accel_g": bow_accel_g,
        "dryout_threshold": KATAYAMA_JUMP_DRYOUT_THRESHOLD,
        "predicted_jumping": predicted_jumping,
        "expected_jumping": bool(row["expected_jumping_bool"]),
        "observed_class": str(row["observed_class"]),
        "classification_match": predicted_jumping == bool(row["expected_jumping_bool"]),
        "note": "Screening classification: relative heave to transom draft, not a full flight/re-entry impact model.",
    }


def _plot_katayama_classification(results: pd.DataFrame, path: Path) -> None:
    if results.empty:
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    fig, ax = plt.subplots(figsize=(7, 4.5))
    for expected, marker, label in [(False, "o", "observed non-jumping"), (True, "s", "observed jumping")]:
        subset = results[results["expected_jumping"].eq(expected)]
        if subset.empty:
            continue
        colors = np.where(subset["classification_match"], "tab:green", "tab:red")
        ax.scatter(subset["fn_l"], subset["lambda_over_loa"], marker=marker, s=90, c=colors, edgecolors="black", label=label)
        for _, item in subset.iterrows():
            ax.annotate(str(item["case_id"]), (float(item["fn_l"]), float(item["lambda_over_loa"])), xytext=(5, 5), textcoords="offset points", fontsize=8)
    ax.set_xlabel("Length Froude number Fn_L")
    ax.set_ylabel("Wavelength ratio lambda/LOA")
    ax.set_title("Katayama regular head-wave jumping classification")
    ax.grid(True, alpha=0.3)
    ax.legend()
    fig.tight_layout()
    fig.savefig(path, dpi=180)
    plt.close(fig)


def validate_katayama_classification(
    out_dir: Path,
    reference_root: str | Path | None = None,
) -> pd.DataFrame:
    out_dir.mkdir(parents=True, exist_ok=True)
    fig_dir = out_dir / "figures"
    fig_dir.mkdir(parents=True, exist_ok=True)
    rows: list[dict[str, float | str]] = []
    path, data, missing = _load_katayama_classification_data(reference_root)
    benchmark = "katayama_regular_head_waves"
    if data is None:
        rows.append(
            _row(
                "katayama_classification_dataset_available",
                str(path),
                "missing",
                None,
                None,
                "NOT_EVALUATED",
                "Add source-backed Katayama jumping classification cases to activate this experimental gate.",
                benchmark=benchmark,
            )
        )
        summary = pd.DataFrame(rows)
        summary.to_csv(out_dir / "katayama_classification_summary.csv", index=False)
        return summary
    if missing:
        rows.append(
            _row(
                "katayama_classification_dataset_schema",
                "required columns present",
                f"missing: {', '.join(missing)}",
                None,
                None,
                "FAIL",
                "The Katayama benchmark CSV is present but cannot be used by the validation command.",
                benchmark=benchmark,
            )
        )
        summary = pd.DataFrame(rows)
        summary.to_csv(out_dir / "katayama_classification_summary.csv", index=False)
        return summary

    rows.extend(
        [
            _row(
                "katayama_classification_dataset_available",
                str(path),
                "loaded",
                None,
                None,
                "PASS",
                "Source-backed Table 1 / Fig. 7 classification cases are available.",
                benchmark=benchmark,
            ),
            _row(
                "katayama_classification_case_count",
                ">=3",
                len(data),
                None,
                None,
                "PASS" if len(data) >= 3 else "FAIL",
                "Minimum useful gate: one non-jumping case and two jumping cases.",
                benchmark=benchmark,
            ),
        ]
    )

    predictions: list[dict[str, float | str | bool]] = []
    for _, item in data.iterrows():
        case_id = str(item["case_id"])
        try:
            prediction = _katayama_case_prediction(item)
            predictions.append(prediction)
            expected = "jumping" if prediction["expected_jumping"] else "non_jumping"
            actual = "jumping" if prediction["predicted_jumping"] else "non_jumping"
            rows.append(
                _row(
                    f"{case_id}_jumping_classification",
                    expected,
                    actual,
                    None,
                    None,
                    "PASS" if prediction["classification_match"] else "FAIL",
                    (
                        f"Fn_L={prediction['fn_l']:.3g}, lambda/LOA={prediction['lambda_over_loa']:.3g}, "
                        f"relative motion/draft={prediction['max_relative_heave_over_transom_draft']:.3g}, "
                        f"threshold={KATAYAMA_JUMP_DRYOUT_THRESHOLD:.3g}; {prediction['note']}"
                    ),
                    benchmark=benchmark,
                )
            )
            rows.append(
                _row(
                    f"{case_id}_equilibrium_converged",
                    "true",
                    str(prediction["equilibrium_converged"]),
                    None,
                    None,
                    "PASS" if prediction["equilibrium_converged"] else "FAIL",
                    f"Solved trim={prediction['trim_deg']:.3g} deg and lambda_W={prediction['lambda_w']:.3g}.",
                    benchmark=benchmark,
                )
            )
        except Exception as exc:
            rows.append(
                _row(
                    f"{case_id}_jumping_classification",
                    "computed",
                    f"error: {exc}",
                    None,
                    None,
                    "FAIL",
                    "Katayama validation case could not be simulated.",
                    benchmark=benchmark,
                )
            )

    results = pd.DataFrame(predictions)
    if not results.empty:
        accuracy = float(results["classification_match"].mean())
        rows.append(
            _row(
                "katayama_classification_accuracy",
                "1.0 for current source-backed Fig. 7 screening cases",
                accuracy,
                None,
                None,
                "PASS" if math.isclose(accuracy, 1.0) else "FAIL",
                "This gate only checks clear jump/non-jump separation; amplitude validation still requires digitized motion and acceleration curves.",
                benchmark=benchmark,
            )
        )
        results.to_csv(out_dir / "katayama_classification.csv", index=False)
        _plot_katayama_classification(results, fig_dir / "katayama_classification.png")
    summary = pd.DataFrame(rows)
    summary.to_csv(out_dir / "katayama_classification_summary.csv", index=False)
    return summary


def _dataset_schema_status(
    path: Path,
    required_columns: list[str],
    required_any_columns: list[list[str]] | None = None,
) -> tuple[str, str]:
    if not path.exists():
        return "missing", ""
    data = pd.read_csv(path, nrows=5)
    missing = [column for column in required_columns if column not in data.columns]
    for alternatives in required_any_columns or []:
        if not any(column in data.columns for column in alternatives):
            missing.append("one of [" + ", ".join(alternatives) + "]")
    if missing:
        return "schema_missing", ", ".join(missing)
    return "schema_ok", ""


def _optional_text(row: pd.Series, key: str, default: str = "") -> str:
    if key not in row or pd.isna(row[key]):
        return default
    return str(row[key])


def _numeric_cell(row: pd.Series, key: str, default: float) -> float:
    if key not in row or pd.isna(row[key]):
        return float(default)
    try:
        return float(row[key])
    except (TypeError, ValueError):
        return float(default)


def _bool_cell(row: pd.Series, key: str, default: bool) -> bool:
    if key not in row or pd.isna(row[key]):
        return bool(default)
    value = row[key]
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return bool(value)
    text = str(value).strip().lower()
    if text in {"1", "true", "t", "yes", "y", "on"}:
        return True
    if text in {"0", "false", "f", "no", "n", "off"}:
        return False
    raise ValueError(f"Cannot parse boolean value for {key!r}: {value!r}")


def _cell_has_value(row: pd.Series, key: str) -> bool:
    if key not in row:
        return False
    value = row[key]
    try:
        if pd.isna(value):
            return False
    except (TypeError, ValueError):
        pass
    text = str(value).strip()
    return text != "" and text.lower() not in {"nan", "none", "null"}


def _optional_cell_text(row: pd.Series, key: str) -> str:
    if not _cell_has_value(row, key):
        return ""
    return str(row[key]).strip()


def _optional_cell_float(row: pd.Series, key: str) -> float | None:
    if not _cell_has_value(row, key):
        return None
    return float(row[key])


def _regular_wave_period_from_wavelength(wavelength_m: float, gravity_m_s2: float) -> float:
    wavenumber = 2.0 * math.pi / max(float(wavelength_m), 1e-12)
    omega = math.sqrt(float(gravity_m_s2) * wavenumber)
    return 2.0 * math.pi / omega


def _merge_katayama_case_defaults(data: pd.DataFrame, reference_root: str | Path | None = None) -> pd.DataFrame:
    classification_path = _katayama_reference_path(reference_root)
    if not classification_path.exists() or "case_id" not in data.columns:
        return data
    classification = pd.read_csv(classification_path)
    if "case_id" not in classification.columns:
        return data
    fill_columns = [
        "length_m",
        "beam_m",
        "draft_m",
        "mass_kg",
        "lcg_from_transom_m",
        "kg_above_keel_m",
        "deadrise_deg",
        "pitch_radius_gyration_m",
    ]
    merged = data.copy()
    defaults = classification.set_index("case_id")
    for idx, row in merged.iterrows():
        case_id = row.get("case_id")
        if case_id not in defaults.index:
            continue
        source = defaults.loc[case_id]
        for column in fill_columns:
            if column not in merged.columns:
                merged[column] = np.nan
            if pd.isna(merged.at[idx, column]) and column in source.index:
                merged.at[idx, column] = source[column]
    return merged


def _amplitude_boat_from_row(row: pd.Series) -> tuple[BoatConfig, str]:
    rho = _numeric_cell(row, "rho_water_kg_m3", 1025.0)
    gravity = _numeric_cell(row, "gravity_m_s2", 9.80665)
    beam = _numeric_cell(row, "beam_m", 1.0)
    length = _numeric_cell(row, "length_m", _numeric_cell(row, "loa_m", _numeric_cell(row, "length_over_b", 6.5) * beam))
    deadrise = _numeric_cell(row, "deadrise_deg", 20.0)
    mass = _numeric_cell(row, "mass_kg", _numeric_cell(row, "mass_over_rho_b3", 1.28) * rho * beam**3)
    lcg = _numeric_cell(
        row,
        "lcg_m",
        _numeric_cell(row, "lcg_from_transom_m", _numeric_cell(row, "lcg_over_b", 2.13) * beam),
    )
    vcg = _numeric_cell(row, "vcg_m", _numeric_cell(row, "kg_above_keel_m", _numeric_cell(row, "vcg_over_b", 0.25) * beam))
    r55 = _numeric_cell(row, "pitch_radius_gyration_m", _numeric_cell(row, "r55_over_b", 1.3) * beam)
    wetted_lengths_type = int(_numeric_cell(row, "wetted_lengths_type", 1.0))
    trim_upper = _numeric_cell(row, "trim_upper_deg", 18.0)
    notes = []
    for column in ["length_m", "beam_m", "mass_kg", "lcg_from_transom_m", "kg_above_keel_m", "pitch_radius_gyration_m"]:
        if column not in row or pd.isna(row[column]):
            notes.append(f"default_{column}")
    boat = BoatConfig(
        length_m=length,
        beam_m=beam,
        deadrise_deg=deadrise,
        mass_kg=mass,
        lcg_m=lcg,
        vcg_m=vcg,
        pitch_radius_gyration_m=r55,
        rho_water_kg_m3=rho,
        gravity_m_s2=gravity,
        wetted_lengths_type=wetted_lengths_type,
        initial_trim_deg=_numeric_cell(row, "initial_trim_deg", 4.0),
        initial_z_wl_m=_numeric_cell(row, "initial_z_wl_m", 0.0),
        trim_bounds_deg=(_numeric_cell(row, "trim_lower_deg", 0.5), trim_upper),
    )
    return boat, ",".join(notes) if notes else "row_geometry"


def _amplitude_speed(row: pd.Series, boat: BoatConfig) -> float:
    if "speed_mps" in row and not pd.isna(row["speed_mps"]):
        return float(row["speed_mps"])
    if "fn_b" in row and not pd.isna(row["fn_b"]):
        return float(row["fn_b"]) * math.sqrt(boat.gravity_m_s2 * boat.beam_m)
    if "fn_l" in row and not pd.isna(row["fn_l"]):
        return float(row["fn_l"]) * math.sqrt(boat.gravity_m_s2 * boat.length_m)
    raise ValueError("Amplitude benchmark row needs speed_mps, fn_b, or fn_l.")


def _first_numeric_alias(row: pd.Series, aliases: tuple[str, ...]) -> tuple[float | None, str]:
    for key in aliases:
        if _cell_has_value(row, key):
            return float(row[key]), key
    return None, ""


def _amplitude_equilibrium(row: pd.Series, boat: BoatConfig, speed_mps: float) -> tuple[EquilibriumState, str]:
    trim, trim_source = _first_numeric_alias(
        row,
        (
            "running_trim_deg",
            "prescribed_trim_deg",
            "calm_water_trim_deg",
            "trim_deg",
        ),
    )
    lambda_w, lambda_source = _first_numeric_alias(
        row,
        (
            "running_lambda_w",
            "prescribed_lambda_w",
            "mean_wetted_length_over_b",
            "lm_over_b",
            "lambda_w",
        ),
    )
    if trim is not None and lambda_w is not None:
        z_wl, z_source = _first_numeric_alias(row, ("running_z_wl_m", "prescribed_z_wl_m", "z_wl_m"))
        state = PrescribedRunningStateConfig(
            enabled=True,
            trim_deg=float(trim),
            lambda_w=float(lambda_w),
            z_wl_m=None if z_wl is None else float(z_wl),
        )
        source = f"prescribed_running_state({trim_source},{lambda_source}"
        if z_source:
            source += f",{z_source}"
        source += ")"
        return make_prescribed_equilibrium(boat, speed_mps, state), source
    return solve_equilibrium(boat, speed_mps), "solved_equilibrium"


def _amplitude_wave(row: pd.Series, boat: BoatConfig) -> tuple[WaveConfig, float, float]:
    draft = _numeric_cell(row, "draft_m", max(0.08 * boat.beam_m, 1e-6))
    height = _numeric_cell(
        row,
        "wave_height_m",
        _numeric_cell(
            row,
            "regular_height_m",
            _numeric_cell(
                row,
                "wave_height_over_b",
                _numeric_cell(row, "wave_height_over_draft", 0.0) * draft / boat.beam_m,
            )
            * boat.beam_m,
        ),
    )
    if height <= 0.0:
        raise ValueError("Amplitude benchmark row needs a positive wave height.")
    wavelength = _numeric_cell(
        row,
        "wavelength_m",
        _numeric_cell(
            row,
            "lambda_over_l",
            _numeric_cell(row, "lambda_over_loa", _numeric_cell(row, "lambda_over_b", np.nan) * boat.beam_m / boat.length_m),
        )
        * boat.length_m,
    )
    if not np.isfinite(wavelength) or wavelength <= 0.0:
        raise ValueError("Amplitude benchmark row needs wavelength_m, lambda_over_l, lambda_over_loa, or lambda_over_b.")
    period = _numeric_cell(
        row,
        "wave_period_s",
        _numeric_cell(row, "regular_period_s", _regular_wave_period_from_wavelength(wavelength, boat.gravity_m_s2)),
    )
    waves = WaveConfig(
        heading_deg=_numeric_cell(row, "wave_heading_deg", 180.0),
        regular_height_m=height,
        regular_period_s=period,
        period_min_s=period,
        period_max_s=period,
        period_count=1,
        spectrum="pm",
        significant_height_m=height,
        peak_period_s=period,
        component_count=1,
        seed=20260717,
    )
    return waves, height, wavelength


def _amplitude_prediction(row: pd.Series) -> dict[str, float | str | bool]:
    boat, geometry_note = _amplitude_boat_from_row(row)
    speed = _amplitude_speed(row, boat)
    waves, wave_height, wavelength = _amplitude_wave(row, boat)
    eq, equilibrium_source = _amplitude_equilibrium(row, boat, speed)
    matrices = compute_hydro_matrices(boat, eq)
    bow_x = _numeric_cell(row, "bow_x_from_cg_m", -(boat.length_m - boat.lcg_m))
    rao = solve_rao(boat, waves, eq, matrices, bow_x).iloc[0]
    wave_amplitude = 0.5 * wave_height
    time_domain = _amplitude_time_domain_diagnostics(
        boat,
        waves,
        eq,
        matrices,
        bow_x,
        wave_amplitude,
        time_domain_model=_optional_text(row, "time_domain_model", "linear"),
        duration_s=_optional_cell_float(row, "time_domain_duration_s"),
        discard_s=_optional_cell_float(row, "time_domain_discard_s"),
        time_step_s=_optional_cell_float(row, "time_domain_time_step_s"),
    )
    return {
        "computed_heave_rao_m_per_m": float(rao["heave_rao_m_per_m"]),
        "computed_pitch_rao_rad_per_m": float(rao["pitch_rao_rad_per_m"]),
        "computed_cg_accel_g": float(rao["heave_accel_rao_mps2_per_m"] * wave_amplitude / boat.gravity_m_s2),
        "computed_bow_accel_g": float(rao["bow_accel_rao_mps2_per_m"] * wave_amplitude / boat.gravity_m_s2),
        "speed_mps": float(speed),
        "fn_b": float(eq.fn_b),
        "trim_deg": float(eq.trim_deg),
        "lambda_w": float(eq.geometry.lambda_w),
        "wave_height_m": float(wave_height),
        "wavelength_m": float(wavelength),
        "lambda_over_l": float(wavelength / boat.length_m),
        "lambda_over_b": float(wavelength / boat.beam_m),
        "wavenumber_rad_m": float(2.0 * math.pi / wavelength),
        "wave_period_s": float(waves.regular_period_s),
        "hull_length_m": float(boat.length_m),
        "hull_beam_m": float(boat.beam_m),
        "equilibrium_converged": bool(eq.converged),
        "equilibrium_source": equilibrium_source,
        "equilibrium_residual_heave": float(eq.residual[0]),
        "equilibrium_residual_pitch": float(eq.residual[1]),
        "geometry_note": geometry_note,
        **time_domain,
    }


def _amplitude_frequency_prediction(row: pd.Series) -> dict[str, float | str | bool]:
    boat, geometry_note = _amplitude_boat_from_row(row)
    speed = _amplitude_speed(row, boat)
    waves, wave_height, wavelength = _amplitude_wave(row, boat)
    eq, equilibrium_source = _amplitude_equilibrium(row, boat, speed)
    matrices = compute_hydro_matrices(boat, eq)
    bow_x = _numeric_cell(row, "bow_x_from_cg_m", -(boat.length_m - boat.lcg_m))
    rao = solve_rao(boat, waves, eq, matrices, bow_x).iloc[0]
    wavenumber = 2.0 * math.pi / wavelength
    return {
        "computed_heave_rao_m_per_m": float(rao["heave_rao_m_per_m"]),
        "computed_pitch_rao_rad_per_m": float(rao["pitch_rao_rad_per_m"]),
        "computed_pitch_rao_rad_per_wave_slope": float(rao["pitch_rao_rad_per_m"] / max(wavenumber, 1e-12)),
        "speed_mps": float(speed),
        "fn_b": float(eq.fn_b),
        "trim_deg": float(eq.trim_deg),
        "lambda_w": float(eq.geometry.lambda_w),
        "wave_height_m": float(wave_height),
        "wavelength_m": float(wavelength),
        "lambda_over_l": float(wavelength / boat.length_m),
        "lambda_over_b": float(wavelength / boat.beam_m),
        "wavenumber_rad_m": float(wavenumber),
        "wave_period_s": float(waves.regular_period_s),
        "hull_length_m": float(boat.length_m),
        "hull_beam_m": float(boat.beam_m),
        "equilibrium_converged": bool(eq.converged),
        "equilibrium_source": equilibrium_source,
        "equilibrium_residual_heave": float(eq.residual[0]),
        "equilibrium_residual_pitch": float(eq.residual[1]),
        "geometry_note": geometry_note,
        "response_model": "frequency_domain_linear_rao",
    }


def _katayama_qualitative_case_row(fn_l: float, wave_height_over_draft: float, lambda_over_loa: float) -> pd.Series:
    return pd.Series(
        {
            "case_id": f"katayama_fn{fn_l:g}_hwd{wave_height_over_draft:g}_lambda{lambda_over_loa:g}",
            "length_m": 0.625,
            "beam_m": 0.250,
            "draft_m": 0.059,
            "mass_kg": 4.28,
            "lcg_from_transom_m": 0.285,
            "kg_above_keel_m": 0.111,
            "deadrise_deg": 22.0,
            "pitch_radius_gyration_m": 0.15625,
            "fn_l": fn_l,
            "wave_height_over_draft": wave_height_over_draft,
            "lambda_over_loa": lambda_over_loa,
        }
    )


def _katayama_qualitative_predictions() -> pd.DataFrame:
    records: list[dict[str, float | str | bool]] = []
    heights_by_fn = {
        1.21: (KATAYAMA_QUALITATIVE_HEIGHTS[0],),
        3.63: KATAYAMA_QUALITATIVE_HEIGHTS,
    }
    for fn_l, heights in heights_by_fn.items():
        for height in heights:
            for lambda_over_loa in KATAYAMA_QUALITATIVE_LAMBDA_OVER_LOA:
                row = _katayama_qualitative_case_row(fn_l, height, lambda_over_loa)
                record: dict[str, float | str | bool] = {
                    "case_id": str(row["case_id"]),
                    "fn_l": fn_l,
                    "wave_height_over_draft": height,
                    "lambda_over_loa": lambda_over_loa,
                    "source_statement": KATAYAMA_QUALITATIVE_SOURCE,
                    "response_model": "frequency_domain_linear_rao",
                }
                try:
                    prediction = _amplitude_frequency_prediction(row)
                    record.update(prediction)
                    record["prediction_status"] = "computed"
                    record["prediction_note"] = ""
                except Exception as exc:
                    record["prediction_status"] = "error"
                    record["prediction_note"] = str(exc)
                    record["computed_heave_rao_m_per_m"] = float("nan")
                    record["computed_pitch_rao_rad_per_m"] = float("nan")
                    record["computed_pitch_rao_rad_per_wave_slope"] = float("nan")
                records.append(record)
    return pd.DataFrame(records)


def _katayama_nonlinear_pilot_predictions() -> pd.DataFrame:
    records: list[dict[str, float | str | bool]] = []
    duration_s = 2.5
    time_step_s = 0.01
    discard_s = 0.8
    for height in KATAYAMA_QUALITATIVE_HEIGHTS:
        for lambda_over_loa in KATAYAMA_NONLINEAR_PILOT_LAMBDA_OVER_LOA:
            row = _katayama_qualitative_case_row(3.63, height, lambda_over_loa)
            record: dict[str, float | str | bool] = {
                "case_id": str(row["case_id"]),
                "fn_l": 3.63,
                "wave_height_over_draft": height,
                "lambda_over_loa": lambda_over_loa,
                "duration_s": duration_s,
                "time_step_s": time_step_s,
                "discard_s": discard_s,
                "source_statement": KATAYAMA_QUALITATIVE_SOURCE,
                "response_model": "nonlinear_time_domain_rk4_pilot",
            }
            try:
                boat, geometry_note = _amplitude_boat_from_row(row)
                speed = _amplitude_speed(row, boat)
                waves, wave_height, wavelength = _amplitude_wave(row, boat)
                eq, equilibrium_source = _amplitude_equilibrium(row, boat, speed)
                matrices = compute_hydro_matrices(boat, eq)
                bow_x = _numeric_cell(row, "bow_x_from_cg_m", -(boat.length_m - boat.lcg_m))
                components = _regular_components_for_validation(waves, eq, boat.gravity_m_s2)
                with warnings.catch_warnings():
                    warnings.simplefilter("ignore", RuntimeWarning)
                    timeseries = simulate_time_domain_rk4(
                        boat,
                        waves,
                        eq,
                        matrices,
                        components,
                        duration_s=duration_s,
                        time_step_s=time_step_s,
                        bow_x_from_cg_m=bow_x,
                    )
                steady = timeseries[timeseries["time_s"] >= discard_s]
                if steady.empty:
                    steady = timeseries
                wave_amplitude = 0.5 * wave_height
                wavenumber = 2.0 * math.pi / wavelength
                transom_draft = max(eq.geometry.transom_draft_m, 1e-9)
                rel_motion = (steady["heave_m"] - steady["wave_elevation_m"]).abs()
                max_relative_heave_over_transom_draft = float(rel_motion.max() / transom_draft)
                heave_rao = _half_peak_to_peak(steady["heave_m"]) / max(wave_amplitude, 1e-12)
                pitch_rao_per_m = _half_peak_to_peak(steady["pitch_rad"]) / max(wave_amplitude, 1e-12)
                dryout_risk = bool(max_relative_heave_over_transom_draft > KATAYAMA_JUMP_DRYOUT_THRESHOLD)
                accepted_for_peak_trend = bool(
                    not dryout_risk
                    and np.isfinite(heave_rao)
                    and np.isfinite(pitch_rao_per_m)
                    and abs(float(heave_rao)) < 10.0
                    and abs(float(pitch_rao_per_m / max(wavenumber, 1e-12))) < 10.0
                )
                record.update(
                    {
                        "computed_heave_rao_m_per_m": float(heave_rao),
                        "computed_pitch_rao_rad_per_m": float(pitch_rao_per_m),
                        "computed_pitch_rao_rad_per_wave_slope": float(pitch_rao_per_m / max(wavenumber, 1e-12)),
                        "speed_mps": float(speed),
                        "fn_b": float(eq.fn_b),
                        "trim_deg": float(eq.trim_deg),
                        "lambda_w": float(eq.geometry.lambda_w),
                        "wave_height_m": float(wave_height),
                        "wavelength_m": float(wavelength),
                        "lambda_over_l": float(wavelength / boat.length_m),
                        "lambda_over_b": float(wavelength / boat.beam_m),
                        "wavenumber_rad_m": float(wavenumber),
                        "wave_period_s": float(waves.regular_period_s),
                        "equilibrium_converged": bool(eq.converged),
                        "equilibrium_source": equilibrium_source,
                        "geometry_note": geometry_note,
                        "max_relative_heave_over_transom_draft": max_relative_heave_over_transom_draft,
                        "dryout_risk_flag": dryout_risk,
                        "accepted_for_peak_trend": accepted_for_peak_trend,
                        "max_cg_vertical_accel_g": float(steady["heave_accel_mps2"].abs().max() / boat.gravity_m_s2),
                        "max_bow_vertical_accel_g": float(steady["bow_vertical_accel_mps2"].abs().max() / boat.gravity_m_s2),
                        "prediction_status": "computed",
                        "prediction_note": "short deterministic nonlinear RK4 pilot; use for trend triage, not final amplitude acceptance",
                    }
                )
            except Exception as exc:
                record.update(
                    {
                        "computed_heave_rao_m_per_m": float("nan"),
                        "computed_pitch_rao_rad_per_m": float("nan"),
                        "computed_pitch_rao_rad_per_wave_slope": float("nan"),
                        "max_relative_heave_over_transom_draft": float("nan"),
                        "dryout_risk_flag": True,
                        "accepted_for_peak_trend": False,
                        "max_cg_vertical_accel_g": float("nan"),
                        "max_bow_vertical_accel_g": float("nan"),
                        "prediction_status": "error",
                        "prediction_note": str(exc),
                    }
                )
            records.append(record)
    return pd.DataFrame(records)


def _metric_series(data: pd.DataFrame, fn_l: float, height: float, metric: str) -> tuple[np.ndarray, np.ndarray]:
    subset = data[
        data["fn_l"].astype(float).round(6).eq(round(fn_l, 6))
        & data["wave_height_over_draft"].astype(float).round(6).eq(round(height, 6))
    ].sort_values("lambda_over_loa")
    x = pd.to_numeric(subset["lambda_over_loa"], errors="coerce").to_numpy(dtype=float)
    y = pd.to_numeric(subset[metric], errors="coerce").to_numpy(dtype=float)
    mask = np.isfinite(x) & np.isfinite(y)
    return x[mask], y[mask]


def _monotonic_nondecreasing(values: np.ndarray, relative_tolerance: float = 0.05) -> bool:
    if values.size < 2:
        return False
    for previous, current in zip(values[:-1], values[1:]):
        allowed_drop = relative_tolerance * max(abs(float(previous)), 1e-12)
        if float(current) < float(previous) - allowed_drop:
            return False
    return True


def _interior_peak_index(values: np.ndarray, relative_prominence: float = 0.03) -> int | None:
    if values.size < 3:
        return None
    peak_index = int(np.nanargmax(values))
    if peak_index <= 0 or peak_index >= values.size - 1:
        return None
    peak = float(values[peak_index])
    left = float(values[peak_index - 1])
    right = float(values[peak_index + 1])
    if peak >= left * (1.0 + relative_prominence) and peak >= right * (1.0 + relative_prominence):
        return peak_index
    return None


def _interior_peak_or_plateau_index(values: np.ndarray, relative_tolerance: float = 0.03) -> int | None:
    peak = _interior_peak_index(values, relative_tolerance)
    if peak is not None:
        return peak
    if values.size < 4:
        return None
    max_value = float(np.nanmax(values))
    if not np.isfinite(max_value):
        return None
    plateau = np.where(values >= max_value * (1.0 - relative_tolerance))[0]
    if plateau.size and int(plateau[0]) < values.size - 2:
        return int(plateau[0])
    return None


def _peak_value_and_lambda(lambdas: np.ndarray, values: np.ndarray) -> tuple[float, float]:
    if values.size == 0:
        return float("nan"), float("nan")
    peak_index = int(np.nanargmax(values))
    return float(values[peak_index]), float(lambdas[peak_index])


def _net_nonincreasing_with_drop(values: np.ndarray, relative_tolerance: float = 0.03) -> bool:
    if values.size < 2:
        return False
    for previous, current in zip(values[:-1], values[1:]):
        if float(current) > float(previous) * (1.0 + relative_tolerance):
            return False
    return float(values[-1]) < float(values[0]) * (1.0 - relative_tolerance)


def _net_nondecreasing_with_rise(values: np.ndarray, relative_tolerance: float = 0.03) -> bool:
    if values.size < 2:
        return False
    for previous, current in zip(values[:-1], values[1:]):
        if float(current) < float(previous) * (1.0 - relative_tolerance):
            return False
    return float(values[-1]) > float(values[0]) * (1.0 + relative_tolerance)


def _plot_katayama_qualitative_trends(data: pd.DataFrame, path: Path) -> None:
    if data.empty:
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    fig, axes = plt.subplots(2, 2, figsize=(10, 7), sharex=True)
    metrics = [
        ("computed_heave_rao_m_per_m", "Heave RAO (m/m)"),
        ("computed_pitch_rao_rad_per_wave_slope", "Pitch RAO theta/(k zeta_a)"),
    ]
    for column_index, (metric, label) in enumerate(metrics):
        fn121 = data[data["fn_l"].astype(float).round(6).eq(1.21)].sort_values("lambda_over_loa")
        axes[0, column_index].plot(fn121["lambda_over_loa"], fn121[metric], marker="o", label="H/d=0.17")
        axes[0, column_index].set_title("Fn_L=1.21")
        axes[0, column_index].set_ylabel(label)
        axes[0, column_index].grid(True, alpha=0.3)
        axes[0, column_index].legend()
        for height in KATAYAMA_QUALITATIVE_HEIGHTS:
            subset = data[
                data["fn_l"].astype(float).round(6).eq(3.63)
                & data["wave_height_over_draft"].astype(float).round(6).eq(round(height, 6))
            ].sort_values("lambda_over_loa")
            axes[1, column_index].plot(subset["lambda_over_loa"], subset[metric], marker="o", label=f"H/d={height:g}")
        axes[1, column_index].set_title("Fn_L=3.63")
        axes[1, column_index].set_xlabel("Wavelength ratio lambda/LOA")
        axes[1, column_index].set_ylabel(label)
        axes[1, column_index].grid(True, alpha=0.3)
        axes[1, column_index].legend()
    fig.suptitle("Katayama qualitative trend probe")
    fig.tight_layout()
    fig.savefig(path, dpi=180)
    plt.close(fig)


def _plot_katayama_nonlinear_pilot(data: pd.DataFrame, path: Path) -> None:
    if data.empty:
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    fig, axes = plt.subplots(1, 2, figsize=(10, 4.2), sharex=True)
    metrics = [
        ("computed_heave_rao_m_per_m", "Heave RAO (m/m)"),
        ("computed_pitch_rao_rad_per_wave_slope", "Pitch RAO theta/(k zeta_a)"),
    ]
    for ax, (metric, label) in zip(axes, metrics):
        for height in KATAYAMA_QUALITATIVE_HEIGHTS:
            subset = data[data["wave_height_over_draft"].astype(float).round(6).eq(round(height, 6))].sort_values(
                "lambda_over_loa"
            )
            marker = "s" if subset["dryout_risk_flag"].astype(bool).any() else "o"
            ax.plot(subset["lambda_over_loa"], subset[metric], marker=marker, label=f"H/d={height:g}")
        ax.set_xlabel("Wavelength ratio lambda/LOA")
        ax.set_ylabel(label)
        ax.grid(True, alpha=0.3)
        ax.legend()
    fig.suptitle("Katayama nonlinear RK4 pilot at Fn_L=3.63")
    fig.tight_layout()
    fig.savefig(path, dpi=180)
    plt.close(fig)


def validate_katayama_qualitative_trends(out_dir: Path) -> pd.DataFrame:
    out_dir.mkdir(parents=True, exist_ok=True)
    fig_dir = out_dir / "figures"
    fig_dir.mkdir(parents=True, exist_ok=True)
    benchmark = "katayama_regular_wave_qualitative_trends"
    data = _katayama_qualitative_predictions()
    pilot = _katayama_nonlinear_pilot_predictions()
    data.to_csv(out_dir / "katayama_qualitative_trends.csv", index=False)
    pilot.to_csv(out_dir / "katayama_nonlinear_pilot_trends.csv", index=False)
    _plot_katayama_qualitative_trends(data, fig_dir / "katayama_qualitative_trends.png")
    _plot_katayama_nonlinear_pilot(pilot, fig_dir / "katayama_nonlinear_pilot_trends.png")

    rows: list[dict[str, float | str]] = [
        _row(
            "katayama_qualitative_source_statement_recorded",
            "published qualitative statements documented",
            KATAYAMA_QUALITATIVE_SOURCE,
            None,
            None,
            "PASS",
            "This qualitative gate is source-text-backed only; it does not replace digitized Fig. 9/Fig. 10 amplitude curves.",
            benchmark=benchmark,
        )
    ]
    if data["prediction_status"].astype(str).ne("computed").any():
        failed = int(data["prediction_status"].astype(str).ne("computed").sum())
        rows.append(
            _row(
                "katayama_qualitative_prediction_grid_computed",
                "all probe points computed",
                f"{failed} error rows",
                None,
                None,
                "FAIL",
                "The qualitative trend gate cannot be interpreted until all probe points are finite.",
                benchmark=benchmark,
            )
        )
        summary = pd.DataFrame(rows)
        summary.to_csv(out_dir / "katayama_qualitative_trends_summary.csv", index=False)
        return summary

    rows.append(
        _row(
            "katayama_qualitative_prediction_grid_computed",
            f"{len(data)} finite frequency-domain probe points",
            len(data),
            None,
            None,
            "PASS",
            "Probe values are written to katayama_qualitative_trends.csv.",
            benchmark=benchmark,
        )
    )

    metric_specs = [
        ("heave", "computed_heave_rao_m_per_m"),
        ("pitch", "computed_pitch_rao_rad_per_wave_slope"),
    ]
    for label, metric in metric_specs:
        lambdas, values = _metric_series(data, 1.21, KATAYAMA_QUALITATIVE_HEIGHTS[0], metric)
        status = "PASS" if _monotonic_nondecreasing(values) else "FAIL"
        actual = "; ".join(f"{x:.3g}:{y:.3g}" for x, y in zip(lambdas, values))
        rows.append(
            _row(
                f"fn1p21_{label}_monotonic_lambda_trend",
                "monotonic nondecreasing with wavelength",
                actual,
                None,
                None,
                status,
                (
                    "Katayama source text reports the low-speed response increasing with wavelength; "
                    "current actual values are frequency-domain linear RAO samples."
                ),
                benchmark=benchmark,
            )
        )

    for label, metric in metric_specs:
        lambdas, values = _metric_series(data, 3.63, KATAYAMA_QUALITATIVE_HEIGHTS[0], metric)
        peak_index = _interior_peak_or_plateau_index(values) if label == "pitch" else _interior_peak_index(values)
        if peak_index is None:
            actual = "no interior peak or plateau detected"
            status = "FAIL"
        else:
            actual = f"peak_or_plateau lambda/LOA={lambdas[peak_index]:.3g}, value={values[peak_index]:.3g}"
            status = "PASS"
        rows.append(
            _row(
                f"fn3p63_{label}_peak_or_plateau_exists",
                "interior peak or clear plateau at high speed",
                actual,
                None,
                None,
                status,
                "Source text describes a peaked high-speed response before wave-height-dependent nonlinear changes.",
                benchmark=benchmark,
            )
        )

    for label, metric in metric_specs:
        peak_values: list[float] = []
        peak_lambdas: list[float] = []
        for height in KATAYAMA_QUALITATIVE_HEIGHTS:
            lambdas, values = _metric_series(data, 3.63, height, metric)
            peak_value, peak_lambda = _peak_value_and_lambda(lambdas, values)
            peak_values.append(peak_value)
            peak_lambdas.append(peak_lambda)
        value_status = "PASS" if _net_nonincreasing_with_drop(np.asarray(peak_values, dtype=float)) else "FAIL"
        lambda_status = "PASS" if _net_nondecreasing_with_rise(np.asarray(peak_lambdas, dtype=float)) else "FAIL"
        peak_value_text = "; ".join(
            f"H/d={height:g}:peak={value:.3g}"
            for height, value in zip(KATAYAMA_QUALITATIVE_HEIGHTS, peak_values)
        )
        peak_lambda_text = "; ".join(
            f"H/d={height:g}:lambda/LOA={value:.3g}"
            for height, value in zip(KATAYAMA_QUALITATIVE_HEIGHTS, peak_lambdas)
        )
        rows.append(
            _row(
                f"fn3p63_{label}_wave_height_peak_amplitude_decreases",
                "peak amplitude decreases as H/d increases",
                peak_value_text,
                None,
                None,
                value_status,
                "A purely linear frequency-domain RAO is expected to fail this nonlinear wave-height trend if no amplitude-dependent mechanism is present.",
                benchmark=benchmark,
            )
        )
        rows.append(
            _row(
                f"fn3p63_{label}_wave_height_peak_shifts_longer",
                "peak wavelength increases as H/d increases",
                peak_lambda_text,
                None,
                None,
                lambda_status,
                "This probes whether the model captures the source-reported wave-height-dependent peak shift.",
                benchmark=benchmark,
            )
        )

    if pilot["prediction_status"].astype(str).ne("computed").any():
        failed = int(pilot["prediction_status"].astype(str).ne("computed").sum())
        rows.append(
            _row(
                "katayama_nonlinear_pilot_grid_computed",
                "all nonlinear pilot points computed",
                f"{failed} error rows",
                None,
                None,
                "FAIL",
                "Short RK4 nonlinear pilot could not compute every probe point.",
                benchmark=benchmark,
            )
        )
    else:
        rows.append(
            _row(
                "katayama_nonlinear_pilot_grid_computed",
                f"{len(pilot)} finite short nonlinear RK4 probe points",
                len(pilot),
                None,
                None,
                "PASS",
                "Pilot values are written to katayama_nonlinear_pilot_trends.csv; this is a trend diagnostic, not amplitude acceptance.",
                benchmark=benchmark,
            )
        )
        for label, metric in metric_specs:
            accepted = pilot[pilot["accepted_for_peak_trend"].astype(bool)]
            small_lambdas, small_values = _metric_series(accepted, 3.63, KATAYAMA_QUALITATIVE_HEIGHTS[0], metric)
            medium_lambdas, medium_values = _metric_series(accepted, 3.63, KATAYAMA_QUALITATIVE_HEIGHTS[1], metric)
            small_peak, small_lambda = _peak_value_and_lambda(small_lambdas, small_values)
            medium_peak, medium_lambda = _peak_value_and_lambda(medium_lambdas, medium_values)
            comparable = np.isfinite([small_peak, small_lambda, medium_peak, medium_lambda]).all()
            decreases = bool(comparable and medium_peak < small_peak * 0.98)
            shifts = bool(comparable and medium_lambda > small_lambda * 1.03)
            rows.append(
                _row(
                    f"fn3p63_{label}_nonlinear_pilot_medium_wave_peak_amplitude_decreases",
                    "H/d=0.34 pilot peak lower than H/d=0.17",
                    f"H/d=0.17:peak={small_peak:.3g}; H/d=0.34:peak={medium_peak:.3g}",
                    None,
                    None,
                    "PASS" if decreases else "FAIL",
                    "Short nonlinear pilot check for the source-reported peak reduction; full digitized amplitude curves remain required.",
                    benchmark=benchmark,
                )
            )
            rows.append(
                _row(
                    f"fn3p63_{label}_nonlinear_pilot_medium_wave_peak_shifts_longer",
                    "H/d=0.34 pilot peak wavelength longer than H/d=0.17",
                    f"H/d=0.17:lambda/LOA={small_lambda:.3g}; H/d=0.34:lambda/LOA={medium_lambda:.3g}",
                    None,
                    None,
                    "PASS" if shifts else "FAIL",
                    "Short nonlinear pilot check for the source-reported peak shift; full digitized amplitude curves remain required.",
                    benchmark=benchmark,
                )
            )
        large = pilot[pilot["wave_height_over_draft"].astype(float).round(6).eq(round(KATAYAMA_QUALITATIVE_HEIGHTS[2], 6))]
        large_dryout = bool(large["dryout_risk_flag"].astype(bool).any())
        rows.append(
            _row(
                "fn3p63_nonlinear_pilot_large_wave_model_limit_reported",
                "H/d=0.68 pilot explicitly reports dryout/model-limit risk when present",
                "; ".join(
                    f"lambda/LOA={float(item['lambda_over_loa']):.3g}:dryout={bool(item['dryout_risk_flag'])}"
                    for _, item in large.iterrows()
                ),
                None,
                None,
                "PASS" if large_dryout else "FAIL",
                "Large-wave pilot rows are not used to force amplitude-trend acceptance; they keep flight/re-entry risk visible.",
                benchmark=benchmark,
            )
        )

    summary = pd.DataFrame(rows)
    summary.to_csv(out_dir / "katayama_qualitative_trends_summary.csv", index=False)
    return summary


def _amplitude_reference_value(
    row: pd.Series,
    reference_column: str,
    prediction: dict[str, float | str | bool],
) -> tuple[float, str]:
    if reference_column in row and not pd.isna(row[reference_column]):
        return float(row[reference_column]), reference_column
    if reference_column == "pitch_rao_rad_per_m" and "pitch_rao_rad_per_wave_slope" in row:
        pitch_per_wave_slope = float(row["pitch_rao_rad_per_wave_slope"])
        if not np.isfinite(pitch_per_wave_slope):
            return pitch_per_wave_slope, "pitch_rao_rad_per_wave_slope"
        return pitch_per_wave_slope * float(prediction["wavenumber_rad_m"]), "pitch_rao_rad_per_wave_slope"
    raise KeyError(f"{reference_column} is missing.")


def _amplitude_reference_available(row: pd.Series, reference_column: str) -> bool:
    if reference_column in row and _cell_has_value(row, reference_column):
        return True
    return reference_column == "pitch_rao_rad_per_m" and _cell_has_value(row, "pitch_rao_rad_per_wave_slope")


def _amplitude_required_metrics(benchmark: str) -> set[str]:
    if benchmark == "katayama_regular_wave_amplitudes":
        return {"heave_rao_m_per_m", "pitch_rao_rad_per_m"}
    return {"heave_rao_m_per_m", "pitch_rao_rad_per_m", "cg_accel_g", "bow_accel_g"}


def _half_peak_to_peak(values: pd.Series | np.ndarray) -> float:
    array = np.asarray(values, dtype=float)
    array = array[np.isfinite(array)]
    if array.size == 0:
        return float("nan")
    return float(0.5 * (np.max(array) - np.min(array)))


def _amplitude_time_domain_diagnostics(
    boat: BoatConfig,
    waves: WaveConfig,
    eq: EquilibriumState,
    matrices: HydroMatrices,
    bow_x_from_cg_m: float,
    wave_amplitude_m: float,
    time_domain_model: str = "linear",
    duration_s: float | None = None,
    discard_s: float | None = None,
    time_step_s: float | None = None,
) -> dict[str, float | str | bool]:
    components = _regular_components_for_validation(waves, eq, boat.gravity_m_s2)
    omega_e = abs(float(components.omega_e[0])) if len(components.omega_e) else 0.0
    encounter_period = 2.0 * math.pi / max(omega_e, 1e-8)
    duration = duration_s if duration_s is not None else max(8.0 * encounter_period, 4.0 * waves.regular_period_s, 2.0)
    time_step = (
        time_step_s
        if time_step_s is not None
        else max(min(encounter_period / 50.0, waves.regular_period_s / 80.0, 0.04), 0.01)
    )
    discard = discard_s if discard_s is not None else min(0.5 * duration, max(3.0 * encounter_period, 2.0 * waves.regular_period_s))
    requested_model = time_domain_model.strip().lower().replace("-", "_")
    if requested_model in {"nonlinear", "nonlinear_time_domain"}:
        method = "nonlinear_time_domain"
        try:
            timeseries = simulate_time_domain(
                boat,
                waves,
                eq,
                matrices,
                components,
                duration,
                time_step,
                bow_x_from_cg_m,
            )
        except RuntimeError:
            timeseries = simulate_linear_response(
                boat,
                eq,
                matrices,
                components,
                duration,
                time_step,
                bow_x_from_cg_m,
            )
            method = "linear_rao_superposition_fallback"
    else:
        timeseries = simulate_time_domain(
            boat,
            waves,
            eq,
            matrices,
            components,
            duration,
            time_step,
            bow_x_from_cg_m,
        ) if requested_model == "nonlinear_smoke" else simulate_linear_response(
            boat,
            eq,
            matrices,
            components,
            duration,
            time_step,
            bow_x_from_cg_m,
        )
        method = "nonlinear_smoke" if requested_model == "nonlinear_smoke" else "linear_rao_superposition"
    steady = timeseries[timeseries["time_s"] >= discard]
    if steady.empty:
        steady = timeseries
    finite = bool(np.isfinite(steady.select_dtypes(include=[np.number]).to_numpy()).all())
    transom_draft = max(float(eq.geometry.transom_draft_m), 1e-9)
    relative_heave = steady["heave_m"] - steady["wave_elevation_m"]
    max_relative_heave_over_transom_draft = float(relative_heave.abs().max() / transom_draft)
    dryout_risk = bool(max_relative_heave_over_transom_draft > KATAYAMA_JUMP_DRYOUT_THRESHOLD)
    cg_accel_g = _half_peak_to_peak(steady["heave_accel_mps2"]) / boat.gravity_m_s2
    bow_accel_g = _half_peak_to_peak(steady["bow_vertical_accel_mps2"]) / boat.gravity_m_s2
    max_cg_accel_g = float(steady["heave_accel_mps2"].abs().max() / boat.gravity_m_s2)
    max_bow_accel_g = float(steady["bow_vertical_accel_mps2"].abs().max() / boat.gravity_m_s2)
    impact_accel_risk = bool(max_cg_accel_g > 3.0 or max_bow_accel_g > 3.0)
    if dryout_risk and impact_accel_risk:
        limit_note = "possible_jump_or_wetted_surface_loss_and_impact_acceleration_check_against_experiment"
    elif dryout_risk:
        limit_note = "possible_jump_or_wetted_surface_loss_check_against_experiment"
    elif impact_accel_risk:
        limit_note = "impact_acceleration_risk_check_against_experiment"
    else:
        limit_note = "regular_wave_time_domain_diagnostic_with_no_dryout_or_impact_flag"
    return {
        "time_domain_method": method,
        "time_domain_duration_s": float(duration),
        "time_domain_discard_s": float(discard),
        "time_domain_time_step_s": float(time_step),
        "time_domain_finite_response": finite,
        "time_domain_heave_rao_m_per_m": _half_peak_to_peak(steady["heave_m"]) / max(wave_amplitude_m, 1e-12),
        "time_domain_pitch_rao_rad_per_m": _half_peak_to_peak(steady["pitch_rad"]) / max(wave_amplitude_m, 1e-12),
        "time_domain_cg_accel_g": cg_accel_g,
        "time_domain_bow_accel_g": bow_accel_g,
        "time_domain_max_relative_heave_over_transom_draft": max_relative_heave_over_transom_draft,
        "time_domain_max_cg_accel_g": max_cg_accel_g,
        "time_domain_max_bow_accel_g": max_bow_accel_g,
        "time_domain_dryout_risk_flag": dryout_risk,
        "time_domain_impact_accel_risk_flag": impact_accel_risk,
        "time_domain_limit_note": limit_note,
    }


def _plot_amplitude_comparison(comparison: pd.DataFrame, path: Path, title: str) -> None:
    if comparison.empty:
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    metric_labels = {
        "heave_rao_m_per_m": "Heave RAO (m/m)",
        "pitch_rao_rad_per_m": "Pitch RAO (rad/m)",
        "cg_accel_g": "CG vertical accel (g)",
        "bow_accel_g": "Bow vertical accel (g)",
    }
    metrics = [metric for metric in metric_labels if comparison["metric"].astype(str).eq(metric).any()]
    ncols = 2
    nrows = int(math.ceil(max(len(metrics), 1) / ncols))
    fig, axes = plt.subplots(nrows, ncols, figsize=(10, max(3.2 * nrows, 4.0)), squeeze=False)
    for ax, metric in zip(axes.ravel(), metrics):
        subset = comparison[comparison["metric"].astype(str).eq(metric)].copy()
        subset["lambda_over_l_plot"] = pd.to_numeric(
            subset.get("lambda_over_l"),
            errors="coerce",
        )
        if subset["lambda_over_l_plot"].isna().all() and "wavelength_m" in subset:
            subset["lambda_over_l_plot"] = pd.to_numeric(subset["wavelength_m"], errors="coerce")
        subset = subset.sort_values("lambda_over_l_plot")
        ax.plot(
            subset["lambda_over_l_plot"],
            subset["reference_value"],
            marker="o",
            label="digitized experiment",
        )
        ax.plot(
            subset["lambda_over_l_plot"],
            subset["computed_value"],
            marker="s",
            label="frequency-domain model",
        )
        if "time_domain_value" in subset.columns:
            td_values = pd.to_numeric(subset["time_domain_value"], errors="coerce")
            if td_values.notna().any():
                ax.plot(
                    subset["lambda_over_l_plot"],
                    td_values,
                    marker="^",
                    linestyle="--",
                    label="time-domain diagnostic",
                )
        failing = subset[subset["status"].astype(str).eq("FAIL")]
        if not failing.empty:
            ax.scatter(
                failing["lambda_over_l_plot"],
                failing["computed_value"],
                facecolors="none",
                edgecolors="tab:red",
                s=80,
                linewidths=1.2,
                label="failed tolerance",
            )
        ax.set_title(metric_labels[metric])
        ax.set_xlabel("Wavelength ratio lambda/L")
        ax.set_ylabel(metric_labels[metric])
        ax.grid(True, alpha=0.3)
    for ax in axes.ravel()[len(metrics) :]:
        ax.axis("off")
    handles, labels = axes[0, 0].get_legend_handles_labels()
    if handles:
        fig.legend(handles, labels, loc="upper center", ncol=min(3, len(handles)))
    fig.suptitle(title)
    fig.tight_layout(rect=(0, 0, 1, 0.93))
    fig.savefig(path, dpi=180)
    plt.close(fig)


def _amplitude_wavelength_band(lambda_over_l: float) -> str:
    if not np.isfinite(lambda_over_l):
        return "unknown_wavelength"
    if lambda_over_l < 1.5:
        return "short_wave_lambda_over_l_lt_1p5"
    if lambda_over_l <= 3.5:
        return "mid_wave_1p5_to_3p5"
    return "long_wave_lambda_over_l_gt_3p5"


def _amplitude_residual_recommendation(metric: str, wavelength_band: str, median_ratio: float) -> str:
    direction = "underprediction" if median_ratio < 1.0 else "overprediction"
    if metric in {"cg_accel_g", "bow_accel_g"} and direction == "underprediction":
        return (
            "Audit dynamic lift, slamming/re-entry, and bow acceleration reconstruction; "
            "the current compact RAO path is too soft for this acceleration band."
        )
    if metric in {"heave_rao_m_per_m", "pitch_rao_rad_per_m"} and direction == "overprediction":
        return (
            "Audit nonlinear wetted-length variation and response saturation near resonance; "
            "the current linear RAO path is amplifying this motion band."
        )
    if wavelength_band.startswith("short_wave") and direction == "underprediction":
        return (
            "Audit encounter-frequency excitation and short-wave pressure integration; "
            "the current model loses response in the short-wave band."
        )
    return "Use the residual profile to choose the next hydrodynamic-force or excitation audit before changing gates."


def _write_amplitude_residual_summary(
    comparison: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
) -> tuple[Path, pd.DataFrame]:
    """Write metric- and wavelength-band residual diagnostics for amplitude gates."""

    data = comparison.copy()
    data["reference_value_numeric"] = pd.to_numeric(data["reference_value"], errors="coerce")
    data["computed_value_numeric"] = pd.to_numeric(data["computed_value"], errors="coerce")
    data["rel_error_numeric"] = pd.to_numeric(data["rel_error"], errors="coerce")
    data["lambda_over_l_numeric"] = pd.to_numeric(data.get("lambda_over_l"), errors="coerce")
    data["wavelength_band"] = data["lambda_over_l_numeric"].map(_amplitude_wavelength_band)
    data["computed_over_reference"] = data["computed_value_numeric"] / data["reference_value_numeric"].replace(0.0, np.nan)
    data["signed_relative_error"] = data["computed_over_reference"] - 1.0
    rows: list[dict[str, float | str | int]] = []
    group_columns = ["metric", "wavelength_band"]
    for (metric, wavelength_band), group in data.groupby(group_columns, sort=False):
        ratio = pd.to_numeric(group["computed_over_reference"], errors="coerce")
        rel_error = pd.to_numeric(group["rel_error_numeric"], errors="coerce")
        signed_error = pd.to_numeric(group["signed_relative_error"], errors="coerce")
        status = group["status"].astype(str)
        median_ratio = float(ratio.median()) if ratio.notna().any() else float("nan")
        rows.append(
            {
                "benchmark": benchmark,
                "summary_type": "metric_wavelength_band",
                "metric": str(metric),
                "wavelength_band": str(wavelength_band),
                "case_count": int(len(group)),
                "pass_checks": int(status.eq("PASS").sum()),
                "fail_checks": int(status.eq("FAIL").sum()),
                "median_computed_over_reference": median_ratio,
                "median_signed_relative_error": float(signed_error.median()) if signed_error.notna().any() else float("nan"),
                "median_abs_relative_error": float(rel_error.median()) if rel_error.notna().any() else float("nan"),
                "max_abs_relative_error": float(rel_error.max()) if rel_error.notna().any() else float("nan"),
                "dominant_bias": "underprediction" if median_ratio < 1.0 else "overprediction",
                "lambda_over_l_min": float(group["lambda_over_l_numeric"].min()),
                "lambda_over_l_max": float(group["lambda_over_l_numeric"].max()),
                "recommendation": _amplitude_residual_recommendation(str(metric), str(wavelength_band), median_ratio),
            }
        )
    for metric, group in data.groupby("metric", sort=False):
        ratio = pd.to_numeric(group["computed_over_reference"], errors="coerce")
        rel_error = pd.to_numeric(group["rel_error_numeric"], errors="coerce")
        signed_error = pd.to_numeric(group["signed_relative_error"], errors="coerce")
        status = group["status"].astype(str)
        median_ratio = float(ratio.median()) if ratio.notna().any() else float("nan")
        rows.append(
            {
                "benchmark": benchmark,
                "summary_type": "metric_overall",
                "metric": str(metric),
                "wavelength_band": "all",
                "case_count": int(len(group)),
                "pass_checks": int(status.eq("PASS").sum()),
                "fail_checks": int(status.eq("FAIL").sum()),
                "median_computed_over_reference": median_ratio,
                "median_signed_relative_error": float(signed_error.median()) if signed_error.notna().any() else float("nan"),
                "median_abs_relative_error": float(rel_error.median()) if rel_error.notna().any() else float("nan"),
                "max_abs_relative_error": float(rel_error.max()) if rel_error.notna().any() else float("nan"),
                "dominant_bias": "underprediction" if median_ratio < 1.0 else "overprediction",
                "lambda_over_l_min": float(group["lambda_over_l_numeric"].min()),
                "lambda_over_l_max": float(group["lambda_over_l_numeric"].max()),
                "recommendation": _amplitude_residual_recommendation(str(metric), "all", median_ratio),
            }
        )
    summary = pd.DataFrame(rows)
    if not summary.empty:
        summary = summary.sort_values(
            ["fail_checks", "max_abs_relative_error", "metric", "wavelength_band"],
            ascending=[False, False, True, True],
        ).reset_index(drop=True)
    path = out_dir / f"{benchmark}_residual_summary.csv"
    summary.to_csv(path, index=False)
    return path, summary


def _amplitude_shape_status(
    case_count: int,
    fail_checks: int,
    correlation: float,
    normalized_rmse: float,
    slope_delta: float,
) -> str:
    if case_count < 3:
        return "shape_insufficient_frequency_rows"
    if fail_checks == 0:
        return "shape_regression_target"
    if not np.isfinite(correlation) or not np.isfinite(normalized_rmse):
        return "shape_insufficient_variation_or_data"
    if correlation >= 0.95 and normalized_rmse <= 0.25 and (not np.isfinite(slope_delta) or abs(slope_delta) <= 0.25):
        return "mostly_scale_or_tolerance_gap"
    if correlation >= 0.85 and normalized_rmse <= 0.45:
        return "moderate_shape_match_remaining_scale_or_local_error"
    return "frequency_shape_gap"


def _amplitude_shape_recommendation(metric: str, prediction_model: str, shape_status: str) -> str:
    if shape_status == "shape_regression_target":
        return "Keep this as a regression target for the current amplitude gate."
    if shape_status == "mostly_scale_or_tolerance_gap":
        return "Audit amplitude normalization, wave-height convention, and coordinate conversion before changing frequency-dependent physics."
    if shape_status == "moderate_shape_match_remaining_scale_or_local_error":
        return "Inspect local wavelength bands and model-limit flags; the global curve trend is partly present but not within tolerance."
    if shape_status == "shape_insufficient_frequency_rows":
        return "Add more source-backed wavelength points before using this as curve-shape evidence."
    if metric in {"cg_accel_g", "bow_accel_g"}:
        return "Prioritize acceleration reconstruction, dynamic lift, and impact/slamming terms; this curve is not a simple scale match."
    if prediction_model.startswith("time_domain"):
        return "Time-domain diagnostics do not recover the source curve shape; audit nonlinear wetted-surface and forcing terms before promotion."
    return "Prioritize frequency-dependent excitation/radiation/restoring changes; the current curve shape does not match the experiment."


def _write_amplitude_shape_audit(
    comparison: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
) -> tuple[Path, Path, pd.DataFrame]:
    """Write reference-vs-predicted curve-shape diagnostics for amplitude gates."""

    audit_path = out_dir / f"{benchmark}_shape_audit.csv"
    summary_path = out_dir / f"{benchmark}_shape_summary.csv"
    if comparison.empty:
        empty = pd.DataFrame()
        empty.to_csv(audit_path, index=False)
        empty.to_csv(summary_path, index=False)
        return audit_path, summary_path, empty

    data = comparison.copy()
    data["reference_numeric"] = pd.to_numeric(data["reference_value"], errors="coerce")
    data["lambda_numeric"] = pd.to_numeric(data.get("lambda_over_l"), errors="coerce")
    model_specs = [
        ("frequency_domain_linear_rao", "computed_value", "status", "rel_error"),
        ("time_domain_diagnostic", "time_domain_value", "time_domain_status", "time_domain_rel_error"),
    ]
    audit_rows: list[dict[str, float | str | int]] = []
    summary_rows: list[dict[str, float | str | int]] = []
    for prediction_model, value_column, status_column, error_column in model_specs:
        if value_column not in data.columns:
            continue
        model_data = data.copy()
        model_data["predicted_numeric"] = pd.to_numeric(model_data[value_column], errors="coerce")
        for metric, group in model_data.groupby("metric", sort=False):
            finite = group[
                np.isfinite(group["lambda_numeric"])
                & np.isfinite(group["reference_numeric"])
                & np.isfinite(group["predicted_numeric"])
            ].copy()
            finite.sort_values("lambda_numeric", inplace=True)
            if finite.empty:
                continue
            lambdas = finite["lambda_numeric"].to_numpy(dtype=float)
            reference = finite["reference_numeric"].to_numpy(dtype=float)
            predicted = finite["predicted_numeric"].to_numpy(dtype=float)
            scale = _best_fit_signed_scale(predicted, reference)
            scaled_predicted = scale * predicted if np.isfinite(scale) else np.full_like(predicted, np.nan)
            reference_slope = _log_abs_slope_vs_frequency(lambdas, reference)
            predicted_slope = _log_abs_slope_vs_frequency(lambdas, predicted)
            slope_delta = predicted_slope - reference_slope if np.isfinite(predicted_slope) and np.isfinite(reference_slope) else math.nan
            correlation = _finite_signed_correlation(reference, predicted)
            scaled_correlation = _finite_signed_correlation(reference, scaled_predicted)
            normalized_rmse = _normalized_shape_rmse(predicted, reference, scale)
            ratio = _finite_array_ratio(predicted, reference)
            status_text = finite[status_column].astype(str) if status_column in finite.columns else finite["status"].astype(str)
            pass_checks = int(status_text.eq("PASS").sum())
            fail_checks = int(status_text.eq("FAIL").sum())
            shape_status = _amplitude_shape_status(
                int(len(finite)),
                fail_checks,
                correlation,
                normalized_rmse,
                slope_delta,
            )
            rel_errors = (
                pd.to_numeric(finite[error_column], errors="coerce").to_numpy(dtype=float)
                if error_column in finite.columns
                else np.full(len(finite), np.nan)
            )
            for row_index, (_, item) in enumerate(finite.iterrows()):
                audit_rows.append(
                    {
                        "benchmark": benchmark,
                        "case_id": item.get("case_id", ""),
                        "metric": str(metric),
                        "prediction_model": prediction_model,
                        "lambda_over_l": float(item["lambda_numeric"]),
                        "reference_value": float(item["reference_numeric"]),
                        "predicted_value": float(item["predicted_numeric"]),
                        "best_fit_scaled_predicted_value": float(scaled_predicted[row_index])
                        if np.isfinite(scaled_predicted[row_index])
                        else float("nan"),
                        "predicted_over_reference": float(ratio[row_index]) if np.isfinite(ratio[row_index]) else float("nan"),
                        "rel_error": float(rel_errors[row_index]) if np.isfinite(rel_errors[row_index]) else float("nan"),
                        "status": str(status_text.iloc[row_index]),
                        "best_fit_signed_scale_to_reference": scale,
                        "shape_status": shape_status,
                    }
                )
            summary_rows.append(
                {
                    "benchmark": benchmark,
                    "metric": str(metric),
                    "prediction_model": prediction_model,
                    "case_count": int(len(finite)),
                    "pass_checks": pass_checks,
                    "fail_checks": fail_checks,
                    "lambda_over_l_min": float(np.nanmin(lambdas)),
                    "lambda_over_l_max": float(np.nanmax(lambdas)),
                    "reference_log_abs_slope_vs_log_lambda": reference_slope,
                    "predicted_log_abs_slope_vs_log_lambda": predicted_slope,
                    "predicted_minus_reference_log_slope": slope_delta,
                    "signed_shape_correlation": correlation,
                    "scaled_signed_shape_correlation": scaled_correlation,
                    "best_fit_signed_scale_to_reference": scale,
                    "best_fit_normalized_shape_rmse": normalized_rmse,
                    "predicted_over_reference_median": _finite_median(ratio),
                    "predicted_over_reference_spread": _finite_positive_spread(ratio),
                    "median_rel_error": float(pd.to_numeric(finite[error_column], errors="coerce").median())
                    if error_column in finite.columns
                    else float("nan"),
                    "max_rel_error": float(pd.to_numeric(finite[error_column], errors="coerce").max())
                    if error_column in finite.columns
                    else float("nan"),
                    "shape_status": shape_status,
                    "recommendation": _amplitude_shape_recommendation(str(metric), prediction_model, shape_status),
                }
            )
    audit = pd.DataFrame(audit_rows)
    summary = pd.DataFrame(summary_rows)
    if not summary.empty:
        summary = summary.sort_values(
            ["fail_checks", "best_fit_normalized_shape_rmse", "metric", "prediction_model"],
            ascending=[False, True, True, True],
        ).reset_index(drop=True)
    audit.to_csv(audit_path, index=False)
    summary.to_csv(summary_path, index=False)
    return audit_path, summary_path, summary


def _plot_amplitude_response_model_diagnostics(data: pd.DataFrame, path: Path, title: str) -> None:
    if data.empty:
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    metric_labels = {
        "heave_rao_m_per_m": "Heave RAO (m/m)",
        "pitch_rao_rad_per_m": "Pitch RAO (rad/m)",
        "cg_accel_g": "CG vertical accel (g)",
        "bow_accel_g": "Bow vertical accel (g)",
    }
    model_styles = {
        "frequency_domain_linear_rao": ("s", "-"),
        "linear_rao_superposition": ("^", "--"),
        "nonlinear_time_domain": ("D", ":"),
        "linear_rao_superposition_fallback": ("x", ":"),
    }
    metrics = [metric for metric in metric_labels if data["metric"].astype(str).eq(metric).any()]
    fig, axes = plt.subplots(2, 2, figsize=(10, 7), squeeze=False)
    for ax, metric in zip(axes.ravel(), metrics):
        subset = data[data["metric"].astype(str).eq(metric)].copy()
        subset["lambda_over_l_plot"] = pd.to_numeric(subset["lambda_over_l"], errors="coerce")
        reference = subset.drop_duplicates("case_id").sort_values("lambda_over_l_plot")
        ax.plot(reference["lambda_over_l_plot"], reference["reference_value"], marker="o", color="black", label="digitized experiment")
        for model, group in subset.groupby("response_model", sort=False):
            group = group.sort_values("lambda_over_l_plot")
            marker, linestyle = model_styles.get(str(model), ("o", "-."))
            ax.plot(
                group["lambda_over_l_plot"],
                group["predicted_value"],
                marker=marker,
                linestyle=linestyle,
                label=str(model),
            )
            limited = group[group["model_limit_flag"].astype(bool)]
            if not limited.empty:
                ax.scatter(
                    limited["lambda_over_l_plot"],
                    limited["predicted_value"],
                    facecolors="none",
                    edgecolors="tab:red",
                    s=95,
                    linewidths=1.2,
                    label=f"{model} model limit",
                )
        ax.set_title(metric_labels[metric])
        ax.set_xlabel("Wavelength ratio lambda/L")
        ax.set_ylabel(metric_labels[metric])
        ax.grid(True, alpha=0.3)
    for ax in axes.ravel()[len(metrics) :]:
        ax.axis("off")
    handles, labels = axes[0, 0].get_legend_handles_labels()
    if handles:
        unique: dict[str, Any] = {}
        for handle, label in zip(handles, labels):
            unique.setdefault(label, handle)
        fig.legend(unique.values(), unique.keys(), loc="upper center", ncol=min(3, len(unique)))
    fig.suptitle(title)
    fig.tight_layout(rect=(0, 0, 1, 0.9))
    fig.savefig(path, dpi=180)
    plt.close(fig)


def _amplitude_response_model_summary(data: pd.DataFrame, benchmark: str) -> pd.DataFrame:
    rows: list[dict[str, float | str | int]] = []
    for (model, metric), group in data.groupby(["response_model", "metric"], sort=False):
        rel = pd.to_numeric(group["rel_error"], errors="coerce")
        rows.append(
            {
                "benchmark": benchmark,
                "summary_type": "model_metric",
                "response_model": str(model),
                "metric": str(metric),
                "case_count": int(len(group)),
                "pass_checks": int(group["status"].astype(str).eq("PASS").sum()),
                "fail_checks": int(group["status"].astype(str).eq("FAIL").sum()),
                "model_limit_checks": int(group["model_limit_flag"].astype(bool).sum()),
                "median_abs_relative_error": float(rel.median()) if rel.notna().any() else float("nan"),
                "max_abs_relative_error": float(rel.max()) if rel.notna().any() else float("nan"),
            }
        )
    for model, group in data.groupby("response_model", sort=False):
        rel = pd.to_numeric(group["rel_error"], errors="coerce")
        rows.append(
            {
                "benchmark": benchmark,
                "summary_type": "model_overall",
                "response_model": str(model),
                "metric": "all",
                "case_count": int(len(group)),
                "pass_checks": int(group["status"].astype(str).eq("PASS").sum()),
                "fail_checks": int(group["status"].astype(str).eq("FAIL").sum()),
                "model_limit_checks": int(group["model_limit_flag"].astype(bool).sum()),
                "median_abs_relative_error": float(rel.median()) if rel.notna().any() else float("nan"),
                "max_abs_relative_error": float(rel.max()) if rel.notna().any() else float("nan"),
            }
        )
    return pd.DataFrame(rows)


def _write_fridsma_response_model_diagnostics(
    data: pd.DataFrame,
    comparison: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
) -> tuple[Path, Path, pd.DataFrame]:
    records: list[dict[str, float | str | bool]] = []
    comparison_index = {
        (str(item["case_id"]), str(item["metric"])): item
        for _, item in comparison.iterrows()
    }
    for _, item in comparison.iterrows():
        case_id = str(item["case_id"])
        metric = str(item["metric"])
        tolerance = float(item["tolerance"])
        for model, value_column, method, limit_flag, limit_note in [
            ("frequency_domain_linear_rao", "computed_value", "frequency_domain_linear_rao", False, ""),
            (
                str(item.get("time_domain_method", "linear_rao_superposition")),
                "time_domain_value",
                str(item.get("time_domain_method", "linear_rao_superposition")),
                _truthy(item.get("time_domain_dryout_risk_flag", False))
                or _truthy(item.get("time_domain_impact_accel_risk_flag", False)),
                str(item.get("time_domain_limit_note", "")),
            ),
        ]:
            actual = float(item[value_column])
            expected = float(item["reference_value"])
            error = abs(actual - expected) / max(abs(expected), 1e-12)
            records.append(
                {
                    "benchmark": benchmark,
                    "case_id": case_id,
                    "metric": metric,
                    "lambda_over_l": float(item["lambda_over_l"]),
                    "reference_value": expected,
                    "predicted_value": actual,
                    "rel_error": error,
                    "tolerance": tolerance,
                    "status": "PASS" if np.isfinite(error) and error <= tolerance else "FAIL",
                    "response_model": model,
                    "time_domain_method": method,
                    "model_limit_flag": limit_flag,
                    "model_limit_note": limit_note,
                }
            )

    for idx, row in data.iterrows():
        case_id = _optional_text(row, "case_id", f"row_{idx}")
        try:
            boat, _ = _amplitude_boat_from_row(row)
            speed = _amplitude_speed(row, boat)
            waves, wave_height, _ = _amplitude_wave(row, boat)
            eq, _ = _amplitude_equilibrium(row, boat, speed)
            matrices = compute_hydro_matrices(boat, eq)
            bow_x = _numeric_cell(row, "bow_x_from_cg_m", -(boat.length_m - boat.lcg_m))
            nonlinear = _amplitude_time_domain_diagnostics(
                boat,
                waves,
                eq,
                matrices,
                bow_x,
                0.5 * wave_height,
                time_domain_model="nonlinear",
                duration_s=max(4.0 * waves.regular_period_s, 4.0),
                discard_s=max(2.0 * waves.regular_period_s, 2.0),
                time_step_s=0.04,
            )
        except Exception as exc:
            nonlinear = {
                "time_domain_method": "nonlinear_time_domain_error",
                "time_domain_heave_rao_m_per_m": float("nan"),
                "time_domain_pitch_rao_rad_per_m": float("nan"),
                "time_domain_cg_accel_g": float("nan"),
                "time_domain_bow_accel_g": float("nan"),
                "time_domain_finite_response": False,
                "time_domain_dryout_risk_flag": True,
                "time_domain_impact_accel_risk_flag": True,
                "time_domain_limit_note": str(exc),
            }
        for reference_column, _, time_domain_column, tolerance in AMPLITUDE_METRIC_SPECS:
            comp = comparison_index.get((case_id, reference_column))
            if comp is None:
                continue
            expected = float(comp["reference_value"])
            actual = float(nonlinear[time_domain_column])
            error = abs(actual - expected) / max(abs(expected), 1e-12)
            model_limit = bool(
                not bool(nonlinear.get("time_domain_finite_response", False))
                or bool(nonlinear.get("time_domain_dryout_risk_flag", False))
                or bool(nonlinear.get("time_domain_impact_accel_risk_flag", False))
                or not np.isfinite(actual)
                or abs(actual) > 100.0 * max(abs(expected), 1e-12)
            )
            records.append(
                {
                    "benchmark": benchmark,
                    "case_id": case_id,
                    "metric": reference_column,
                    "lambda_over_l": float(comp["lambda_over_l"]),
                    "reference_value": expected,
                    "predicted_value": actual,
                    "rel_error": error,
                    "tolerance": tolerance,
                    "status": "PASS" if np.isfinite(error) and error <= tolerance else "FAIL",
                    "response_model": str(nonlinear.get("time_domain_method", "nonlinear_time_domain")),
                    "time_domain_method": str(nonlinear.get("time_domain_method", "nonlinear_time_domain")),
                    "time_domain_duration_s": float(nonlinear.get("time_domain_duration_s", float("nan"))),
                    "time_domain_discard_s": float(nonlinear.get("time_domain_discard_s", float("nan"))),
                    "time_domain_time_step_s": float(nonlinear.get("time_domain_time_step_s", float("nan"))),
                    "model_limit_flag": model_limit,
                    "model_limit_note": str(nonlinear.get("time_domain_limit_note", "")),
                }
            )
    diagnostics = pd.DataFrame(records)
    comparison_path = out_dir / f"{benchmark}_response_model_comparison.csv"
    summary_path = out_dir / f"{benchmark}_response_model_summary.csv"
    diagnostics.to_csv(comparison_path, index=False)
    summary = _amplitude_response_model_summary(diagnostics, benchmark)
    summary.to_csv(summary_path, index=False)
    _plot_amplitude_response_model_diagnostics(
        diagnostics,
        out_dir / "figures" / f"{benchmark}_response_model_comparison.png",
        f"{benchmark} response-model diagnostics",
    )
    return comparison_path, summary_path, summary


def _amplitude_dataset_rows(
    path: Path,
    benchmark: str,
    out_dir: Path,
    reference_root: str | Path | None = None,
) -> list[dict[str, float | str]]:
    data = pd.read_csv(path)
    if benchmark == "katayama_regular_wave_amplitudes":
        data = _merge_katayama_case_defaults(data, reference_root)
    comparison_rows: list[dict[str, float | str | bool]] = []
    summary_rows: list[dict[str, float | str]] = []
    required_metrics = _amplitude_required_metrics(benchmark)
    for idx, item in data.iterrows():
        case_id = _optional_text(item, "case_id", f"row_{idx}")
        try:
            prediction = _amplitude_prediction(item)
            for reference_column, computed_column, time_domain_column, tolerance in AMPLITUDE_METRIC_SPECS:
                if not _amplitude_reference_available(item, reference_column):
                    status = "FAIL" if reference_column in required_metrics else "NOT_EVALUATED"
                    summary_rows.append(
                        _row(
                            f"{case_id}_{reference_column}_reference_available",
                            f"source-backed {reference_column}",
                            "missing",
                            None,
                            None,
                            status,
                            (
                                f"{reference_column} is required for this benchmark row."
                                if status == "FAIL"
                                else f"{reference_column} is optional for partial Katayama motion-only activation; "
                                "the full acceleration target remains pending."
                            ),
                            benchmark=benchmark,
                        )
                    )
                    continue
                expected, reference_source_column = _amplitude_reference_value(item, reference_column, prediction)
                actual = float(prediction[computed_column])
                time_domain_actual = float(prediction[time_domain_column])
                if not np.isfinite(expected):
                    raise ValueError(f"{reference_column} is not finite.")
                denom = max(abs(expected), 1e-12)
                error = abs(actual - expected) / denom
                time_domain_error = abs(time_domain_actual - expected) / denom
                status = "PASS" if error <= tolerance else "FAIL"
                time_domain_status = (
                    "PASS" if np.isfinite(time_domain_error) and time_domain_error <= tolerance else "FAIL"
                )
                metric = f"{case_id}_{reference_column}"
                summary_rows.append(
                    _row(
                        metric,
                        expected,
                        actual,
                        tolerance,
                        error,
                        status,
                        (
                            f"speed={prediction['speed_mps']:.6g} m/s; trim={prediction['trim_deg']:.6g} deg; "
                            f"lambda_W={prediction['lambda_w']:.6g}; geometry={prediction['geometry_note']}; "
                            f"equilibrium={prediction['equilibrium_source']}; "
                            f"reference_source={reference_source_column}"
                        ),
                        benchmark=benchmark,
                    )
                )
                comparison_rows.append(
                    {
                        "benchmark": benchmark,
                        "row": idx,
                        "case_id": case_id,
                        "metric": reference_column,
                        "reference_source_column": reference_source_column,
                        "reference_value": expected,
                        "computed_value": actual,
                        "rel_error": error,
                        "time_domain_value": time_domain_actual,
                        "time_domain_rel_error": time_domain_error,
                        "time_domain_status": time_domain_status,
                        "tolerance": tolerance,
                        "status": status,
                        **prediction,
                    }
                )
            if str(prediction["equilibrium_source"]).startswith("prescribed_running_state"):
                summary_rows.append(
                    _row(
                        f"{case_id}_prescribed_running_state_applied",
                        "source-backed prescribed running state",
                        f"trim={prediction['trim_deg']:.6g}; lambda_W={prediction['lambda_w']:.6g}",
                        None,
                        None,
                        "PASS",
                        (
                            "The benchmark row supplies trim/lambda_W from the source; calm-force residuals are "
                            f"diagnostic only: heave={prediction['equilibrium_residual_heave']:.6g}, "
                            f"pitch={prediction['equilibrium_residual_pitch']:.6g}."
                        ),
                        benchmark=benchmark,
                    )
                )
            else:
                summary_rows.append(
                    _row(
                        f"{case_id}_equilibrium_converged",
                        "true",
                        str(prediction["equilibrium_converged"]),
                        None,
                        None,
                        "PASS" if prediction["equilibrium_converged"] else "FAIL",
                        "Equilibrium convergence for the reconstructed experimental amplitude case.",
                        benchmark=benchmark,
                    )
                )
        except Exception as exc:
            summary_rows.append(
                _row(
                    f"{case_id}_amplitude_case",
                    "computed amplitude metrics",
                    f"error: {exc}",
                    None,
                    None,
                    "FAIL",
                    f"Could not evaluate amplitude benchmark row {idx}.",
                    benchmark=benchmark,
                )
            )
    if comparison_rows:
        comparison = pd.DataFrame(comparison_rows)
        comparison.to_csv(out_dir / f"{benchmark}_comparison.csv", index=False)
        figure_path = out_dir / "figures" / f"{benchmark}_comparison.png"
        _plot_amplitude_comparison(comparison, figure_path, benchmark)
        residual_path, residual_summary = _write_amplitude_residual_summary(comparison, out_dir, benchmark)
        shape_audit_path, shape_summary_path, shape_summary = _write_amplitude_shape_audit(comparison, out_dir, benchmark)
        max_error = float(pd.to_numeric(comparison["rel_error"], errors="coerce").max())
        pass_fraction = float(comparison["status"].eq("PASS").mean())
        summary_rows.append(
            _row(
                f"{benchmark}_max_relative_error",
                "within per-metric amplitude tolerances",
                max_error,
                None,
                None,
                "PASS" if comparison["status"].eq("PASS").all() else "FAIL",
                f"Pass fraction={pass_fraction:.3g}; figure=figures/{benchmark}_comparison.png.",
                benchmark=benchmark,
                )
            )
        if not shape_summary.empty:
            worst_shape = shape_summary.iloc[0]
            summary_rows.append(
                _row(
                    f"{benchmark}_shape_audit",
                    "write reference-vs-predicted amplitude curve-shape diagnostics",
                    (
                        f"worst={worst_shape['metric']}/{worst_shape['prediction_model']}; "
                        f"fail_checks={int(worst_shape['fail_checks'])}; "
                        f"shape_status={worst_shape['shape_status']}"
                    ),
                    None,
                    None,
                    "INFO",
                    (
                        f"Wrote {shape_audit_path.name} and {shape_summary_path.name}; "
                        "informational only and does not change the hard gate."
                    ),
                    benchmark=benchmark,
                )
            )
        if not residual_summary.empty:
            worst = residual_summary.iloc[0]
            summary_rows.append(
                _row(
                    f"{benchmark}_residual_summary",
                    "write residual diagnostics by metric and wavelength band",
                    (
                        f"worst={worst['metric']}/{worst['wavelength_band']}; "
                        f"fail_checks={int(worst['fail_checks'])}; "
                        f"max_rel_error={float(worst['max_abs_relative_error']):.6g}"
                    ),
                    None,
                    None,
                    "INFO",
                    f"Wrote {residual_path.name}; informational only and does not change the hard gate.",
                    benchmark=benchmark,
                )
            )
        if benchmark == "fridsma_regular_wave_amplitudes":
            model_comparison_path, model_summary_path, model_summary = _write_fridsma_response_model_diagnostics(
                data,
                comparison,
                out_dir,
                benchmark,
            )
            overall = model_summary[model_summary["summary_type"].astype(str).eq("model_overall")].copy()
            if not overall.empty:
                overall["sort_error"] = pd.to_numeric(overall["median_abs_relative_error"], errors="coerce")
                lowest_median = overall.sort_values(["sort_error", "model_limit_checks"], ascending=[True, True]).iloc[0]
                no_limit = overall[pd.to_numeric(overall["model_limit_checks"], errors="coerce").eq(0)]
                best_no_limit = (
                    no_limit.sort_values(["sort_error", "fail_checks"], ascending=[True, True]).iloc[0]
                    if not no_limit.empty
                    else lowest_median
                )
                summary_rows.append(
                    _row(
                        f"{benchmark}_response_model_diagnostics",
                        "write frequency/linear/nonlinear response-model diagnostics",
                        (
                            f"lowest_median_model={lowest_median['response_model']}; "
                            f"lowest_median_rel_error={float(lowest_median['median_abs_relative_error']):.6g}; "
                            f"lowest_median_model_limit_checks={int(lowest_median['model_limit_checks'])}; "
                            f"best_no_limit_model={best_no_limit['response_model']}; "
                            f"pass={int(best_no_limit['pass_checks'])}/{int(best_no_limit['case_count'])}; "
                            f"median_rel_error={float(best_no_limit['median_abs_relative_error']):.6g}"
                        ),
                        None,
                        None,
                        "INFO",
                        (
                            f"Wrote {model_comparison_path.name}, {model_summary_path.name}, and "
                            f"figures/{benchmark}_response_model_comparison.png; diagnostics do not relax the hard gate."
                        ),
                        benchmark=benchmark,
                    )
                )
    return summary_rows

def _ma2005_hull_name(row: pd.Series) -> str:
    return str(row.get("hull", "")).strip().lower().replace("-", "_").replace(" ", "_")


def _ma2005_is_sl7(hull_name: str) -> bool:
    normalized = hull_name.strip().lower().replace("-", "_").replace(" ", "_")
    return "sl7" in normalized or "sl_7" in normalized


def _ma2005_lcg_metadata(row: pd.Series, hull_name: str, length_m: float) -> dict[str, float | str]:
    explicit_lcg = _optional_cell_float(row, "lcg_from_transom_m")
    explicit_aft = _optional_cell_float(row, "lcg_aft_of_amidship_m")
    if explicit_lcg is not None:
        aft = 0.5 * length_m - explicit_lcg
        return {
            "lcg_from_transom_m": float(explicit_lcg),
            "lcg_aft_of_amidship_m": float(aft),
            "lcg_source": "explicit_lcg_from_transom_m",
        }
    if explicit_aft is not None:
        return {
            "lcg_from_transom_m": float(0.5 * length_m - explicit_aft),
            "lcg_aft_of_amidship_m": float(explicit_aft),
            "lcg_source": "explicit_lcg_aft_of_amidship_m",
        }
    if _ma2005_is_sl7(hull_name):
        aft = float(MA2005_SL7_TABLE2_DEFAULTS["lcg_aft_of_amidship_m"])
        return {
            "lcg_from_transom_m": float(0.5 * length_m - aft),
            "lcg_aft_of_amidship_m": aft,
            "lcg_source": "defaulted_from_ma2005_table2_lcg_aft_of_amidship",
        }
    return {
        "lcg_from_transom_m": float(0.5 * length_m),
        "lcg_aft_of_amidship_m": 0.0,
        "lcg_source": "default_midship_lcg",
    }


def _ma2005_pitch_radius_metadata(row: pd.Series, hull_name: str, length_m: float) -> dict[str, float | str]:
    explicit = _optional_cell_float(row, "pitch_radius_gyration_m")
    if explicit is not None:
        return {
            "pitch_radius_gyration_m": float(explicit),
            "pitch_radius_source": "explicit_pitch_radius_gyration_m",
        }
    ratio = _optional_cell_float(row, "pitch_radius_gyration_over_lbp")
    if ratio is None:
        ratio = _optional_cell_float(row, "pitch_radius_gyration_over_l")
    if ratio is not None:
        return {
            "pitch_radius_gyration_m": float(ratio * length_m),
            "pitch_radius_source": "explicit_pitch_radius_gyration_ratio",
        }
    if _ma2005_is_sl7(hull_name):
        table_ratio = float(MA2005_SL7_TABLE2_DEFAULTS["pitch_radius_gyration_over_lbp"])
        return {
            "pitch_radius_gyration_m": float(table_ratio * length_m),
            "pitch_radius_source": "defaulted_from_ma2005_table2_0p21_lbp",
        }
    if "wigley" in hull_name:
        return {
            "pitch_radius_gyration_m": float(MA2005_WIGLEY_TABLE1_DEFAULTS["pitch_radius_gyration_m"]),
            "pitch_radius_source": "defaulted_from_ma2005_table1_kyy",
        }
    return {"pitch_radius_gyration_m": math.nan, "pitch_radius_source": "not_supplied"}


def _ma2005_trim_metadata(row: pd.Series, hull_name: str) -> dict[str, float | str]:
    explicit = _optional_cell_float(row, "trim_by_stern_m")
    if explicit is not None:
        return {"trim_by_stern_m": float(explicit), "trim_source": "explicit_trim_by_stern_m"}
    if _ma2005_is_sl7(hull_name):
        return {
            "trim_by_stern_m": float(MA2005_SL7_TABLE2_DEFAULTS["trim_by_stern_m"]),
            "trim_source": "defaulted_from_ma2005_table2_trim_by_stern",
        }
    return {"trim_by_stern_m": 0.0, "trim_source": "default_zero_trim"}


def _ma2005_geometry_metadata(row: pd.Series, base_dir: Path | None = None) -> dict[str, Any]:
    hull_name = _ma2005_hull_name(row)
    length = _numeric_cell(row, "length_m", 1.0)
    beam = _numeric_cell(row, "beam_m", 0.138 * length if _ma2005_is_sl7(hull_name) else 0.1 * length)
    draft = _numeric_cell(row, "draft_m", 0.045 * length if _ma2005_is_sl7(hull_name) else 0.0625 * length)
    station_count = int(_numeric_cell(row, "station_count", 41.0))
    offsets_file = _optional_cell_text(row, "offsets_file")
    resolved_offsets = ""
    if offsets_file:
        offsets_path = Path(offsets_file)
        if not offsets_path.is_absolute() and base_dir is not None:
            offsets_path = base_dir / offsets_path
        resolved_offsets = str(offsets_path)

    lcg = _ma2005_lcg_metadata(row, hull_name, length)
    pitch_radius = _ma2005_pitch_radius_metadata(row, hull_name, length)
    trim = _ma2005_trim_metadata(row, hull_name)

    if offsets_file:
        default_source = "offsets_file"
        geometry_status = "REAL_OFFSETS"
        validation_status = "PASS"
        note = "Station geometry is loaded from offsets_file."
    elif "wigley" in hull_name:
        default_source = str(MA2005_WIGLEY_TABLE1_DEFAULTS["geometry_source"])
        geometry_status = "ANALYTIC_FORMULA"
        validation_status = "PASS"
        note = "Wigley III uses the documented analytic parabolic hull formula."
    elif _ma2005_is_sl7(hull_name):
        default_source = str(MA2005_SL7_TABLE2_DEFAULTS["geometry_source"])
        geometry_status = "SURROGATE_NEEDS_REAL_OFFSETS"
        validation_status = "NOT_EVALUATED"
        note = "SL-7 real offsets_file is not supplied; the coefficient gate uses an SL-7-like surrogate hull."
    else:
        default_source = "unsupported"
        geometry_status = "UNSUPPORTED"
        validation_status = "FAIL"
        note = "Unsupported Ma 2005 hull name."

    return {
        "hull": str(row.get("hull", "")),
        "hull_name_normalized": hull_name,
        "geometry_source": _optional_cell_text(row, "geometry_source") or default_source,
        "geometry_status": geometry_status,
        "validation_status": validation_status,
        "length_m": float(length),
        "beam_m": float(beam),
        "draft_m": float(draft),
        "displacement_volume_m3": _numeric_cell(row, "displacement_volume_m3", math.nan),
        "station_count": int(station_count),
        "offsets_file": offsets_file,
        "resolved_offsets_file": resolved_offsets,
        "source_figure": _optional_cell_text(row, "source_figure"),
        "source_note": _optional_cell_text(row, "source_note"),
        "note": note,
        **lcg,
        **pitch_radius,
        **trim,
    }


def _ma2005_hull_from_row(row: pd.Series, base_dir: Path | None = None):
    meta = _ma2005_geometry_metadata(row, base_dir=base_dir)
    hull_name = str(meta["hull_name_normalized"])
    length = float(meta["length_m"])
    lcg = float(meta["lcg_from_transom_m"])
    if meta["offsets_file"]:
        return station_hull_from_mapping(
            {
                "length_m": length,
                "lcg_from_transom_m": lcg,
                "offsets_file": meta["offsets_file"],
            },
            base_dir=base_dir,
        )
    if "wigley" in hull_name:
        return make_wigley_iii_hull(
            length_m=length,
            beam_m=float(meta["beam_m"]),
            draft_m=float(meta["draft_m"]),
            station_count=int(meta["station_count"]),
            lcg_from_transom_m=lcg,
        )
    if _ma2005_is_sl7(hull_name):
        return make_sl7_surrogate_hull(
            length_m=length,
            beam_m=float(meta["beam_m"]),
            draft_m=float(meta["draft_m"]),
            station_count=int(meta["station_count"]),
            lcg_from_transom_m=lcg,
        )
    raise ValueError(f"Unsupported Ma2005 hull '{row.get('hull', '')}'. Expected Wigley III or SL-7.")


def _coefficient_matrix_indices(coefficient: str) -> tuple[str, int, int]:
    name = coefficient.strip().upper()
    if len(name) != 3 or name[0] not in {"A", "B"} or not name[1:].isdigit():
        raise ValueError(f"Unsupported coefficient label '{coefficient}'. Use labels such as A33 or B55.")
    dof_map = {"1": 0, "2": 1, "3": 2, "4": 3, "5": 4, "6": 5}
    if name[1] not in dof_map or name[2] not in dof_map:
        raise ValueError(f"Coefficient '{coefficient}' contains an invalid DOF index.")
    return name[0], dof_map[name[1]], dof_map[name[2]]


def _normalize_ma2005_coefficient_filter(coefficients: tuple[str, ...] | list[str] | None) -> tuple[str, ...] | None:
    if not coefficients:
        return None
    normalized: list[str] = []
    for coefficient in coefficients:
        for token in str(coefficient).replace(",", " ").split():
            name = token.strip().upper()
            if not name:
                continue
            _coefficient_matrix_indices(name)
            if name not in normalized:
                normalized.append(name)
    return tuple(normalized) if normalized else None


def _ma2005_diagnostic_subset(
    path: Path,
    coefficients: tuple[str, ...] | list[str] | None = None,
    row_limit: int | None = None,
) -> tuple[pd.DataFrame, str]:
    data = pd.read_csv(path)
    notes: list[str] = []
    coefficient_filter = _normalize_ma2005_coefficient_filter(coefficients)
    if coefficient_filter is not None:
        data = data[data["coefficient"].astype(str).str.strip().str.upper().isin(coefficient_filter)].copy()
        notes.append(f"coefficients={','.join(coefficient_filter)}")
    if row_limit is not None:
        if int(row_limit) <= 0:
            raise ValueError("ma_compare_row_limit must be a positive integer when supplied.")
        data = data.head(int(row_limit)).copy()
        notes.append(f"row_limit={int(row_limit)}")
    return data, "; ".join(notes) if notes else "full dataset"


def _coefficient_scale(
    prefix: str,
    row_idx: int,
    col_idx: int,
    rho: float,
    length: float,
    gravity: float,
    displacement_volume: float,
) -> float:
    rotational = int(row_idx >= 3) + int(col_idx >= 3)
    scale = rho * displacement_volume * length**rotational
    if prefix == "B":
        scale *= math.sqrt(gravity / length)
    return scale


def _ma2005_documented_length_power(row_idx: int, col_idx: int) -> int:
    """Return the Eq. (34) length power implied by translational/rotational DOFs."""

    return int(row_idx >= 3) + int(col_idx >= 3)


def _ma2005_scale_for_length_power(
    prefix: str,
    length_power: int,
    rho: float,
    length: float,
    gravity: float,
    displacement_volume: float,
) -> float:
    power = int(length_power)
    if power < 0:
        raise ValueError("length_power must be non-negative.")
    scale = float(rho) * float(displacement_volume) * float(length) ** power
    if str(prefix).strip().upper() == "B":
        scale *= math.sqrt(float(gravity) / float(length))
    return float(scale)


def _ma2005_eq34_normalization_formula(prefix: str, row_idx: int, col_idx: int) -> str:
    """Return an explicit Eq. (34)-style denominator for the comparison table."""

    name = f"{str(prefix).strip().upper()}{row_idx + 1}{col_idx + 1}"
    length_power = _ma2005_documented_length_power(row_idx, col_idx)
    denominator = "rho*displacement_volume"
    if length_power == 1:
        denominator += "*L"
    elif length_power == 2:
        denominator += "*L^2"
    if str(prefix).strip().upper() == "B":
        denominator += "*sqrt(g/L)"
        return f"{name} = raw_{name.lower()} / ({denominator}); equivalent to raw/(rho*...)*sqrt(L/g)"
    return f"{name} = raw_{name.lower()} / ({denominator})"


def _ma2005_speed_from_row(row: pd.Series, hull_length_m: float, gravity_m_s2: float) -> tuple[float, float]:
    if "speed_mps" in row and not pd.isna(row["speed_mps"]):
        speed = float(row["speed_mps"])
        fn_l = speed / math.sqrt(gravity_m_s2 * hull_length_m)
        return speed, fn_l
    if "fn_l" in row and not pd.isna(row["fn_l"]):
        fn_l = float(row["fn_l"])
        return fn_l * math.sqrt(gravity_m_s2 * hull_length_m), fn_l
    speed_case = str(row.get("speed_case", ""))
    match = re.search(r"fn\s*[_=:-]?\s*([0-9]+(?:\.[0-9]+)?)", speed_case, flags=re.IGNORECASE)
    if match:
        fn_l = float(match.group(1))
        return fn_l * math.sqrt(gravity_m_s2 * hull_length_m), fn_l
    return 0.0, 0.0


def _ma2005_matrix_cache_key(
    row: pd.Series,
    omega_rad_s: float,
    speed_mps: float,
    hydro_model: str,
    bem_free_surface_panel_count_per_side: int,
    bem_body_panel_count: int | None,
    base_dir: Path | None = None,
) -> tuple[float | int | str, ...]:
    meta = _ma2005_geometry_metadata(row, base_dir=base_dir)
    model = str(hydro_model).strip().lower()
    if model in MA2005_MATCHED_BIE_ALIASES:
        model = MA2005_MATCHED_BIE_MODEL
    matched_bie_settings: tuple[float | int | str, ...] = ()
    if model == MA2005_MATCHED_BIE_MODEL:
        matched_bie_settings = (
            round(float(_numeric_cell(row, "matched_control_surface_radius_beams", 3.0)), 12),
            int(_numeric_cell(row, "matched_history_steps", 40.0)),
            int(_numeric_cell(row, "matched_history_quadrature_count", 16.0)),
            round(float(_numeric_cell(row, "matched_history_k_max", 15.0)), 12),
            round(float(_numeric_cell(row, "matched_inner_a_scale", 1.0)), 12),
            round(float(_numeric_cell(row, "matched_inner_b_scale", 1.0)), 12),
            round(float(_numeric_cell(row, "matched_inner_diagonal_sign", -1.0)), 12),
            round(float(_numeric_cell(row, "matched_inner_free_surface_self_diagonal_scale", 1.0)), 12),
            round(float(_numeric_cell(row, "matched_inner_free_surface_known_potential_rhs_scale", 1.0)), 12),
            round(float(_numeric_cell(row, "matched_inner_free_surface_known_potential_body_row_scale", 1.0)), 12),
            round(float(_numeric_cell(row, "matched_inner_free_surface_known_potential_free_row_scale", 1.0)), 12),
            round(float(_numeric_cell(row, "matched_inner_free_surface_known_potential_control_row_scale", 1.0)), 12),
            round(float(_numeric_cell(row, "matched_inner_free_surface_unknown_normal_column_scale", 1.0)), 12),
            round(float(_numeric_cell(row, "matched_pitch_oscillation_scale", 1.0)), 12),
            round(float(_numeric_cell(row, "matched_pitch_forward_speed_scale", 1.0)), 12),
            int(_bool_cell(row, "matched_use_free_surface_marching", True)),
            round(float(_numeric_cell(row, "matched_time_step_scale", 1.0)), 12),
            int(_numeric_cell(row, "matched_free_surface_substeps_per_station", 1.0)),
            round(float(_numeric_cell(row, "matched_free_surface_velocity_scale", 1.0)), 12),
            str(_optional_text(row, "matched_free_surface_normal_derivative_source", "raw")).strip().lower(),
            round(float(_numeric_cell(row, "matched_free_surface_time_direction_sign", 1.0)), 12),
            round(float(_numeric_cell(row, "matched_free_surface_dynamic_gravity_sign", -1.0)), 12),
            str(_optional_text(row, "matched_free_surface_potential_elevation_level", "updated")).strip().lower(),
            str(_optional_text(row, "matched_control_row_free_surface_potential_source", "shared")).strip().lower(),
            round(float(_numeric_cell(row, "matched_history_rhs_scale", 1.0)), 12),
            int(_bool_cell(row, "matched_apply_local_time_phase", True)),
            int(_bool_cell(row, "matched_local_time_phase_gradient_correction", True)),
            int(_bool_cell(row, "matched_clip_inner_free_surface_to_waterline", True)),
            int(_bool_cell(row, "matched_two_zone_inner_free_surface", False)),
            str(
                _optional_text(
                    row,
                    "matched_force_assembly_route",
                    "eq32_stokes_body_plus_end",
                )
            )
            .strip()
            .lower(),
        )
    return (
        model,
        int(meta["station_count"]),
        str(meta["hull"]),
        str(meta["geometry_source"]),
        str(meta["resolved_offsets_file"]),
        float(meta["length_m"]),
        float(meta["beam_m"]),
        float(meta["draft_m"]),
        float(meta["lcg_from_transom_m"]),
        round(float(omega_rad_s), 12),
        round(float(speed_mps), 12),
        int(bem_free_surface_panel_count_per_side),
        "" if bem_body_panel_count is None else int(bem_body_panel_count),
        *matched_bie_settings,
    )


def _ma2005_external_pdstrip_cache_key(
    row: pd.Series,
    rho: float,
    gravity: float,
    point_count_per_side: int = 8,
    base_dir: Path | None = None,
) -> tuple[float | int | str, ...]:
    meta = _ma2005_geometry_metadata(row, base_dir=base_dir)
    return (
        "external_pdstrip_sections_parsed",
        int(meta["station_count"]),
        str(meta["hull"]),
        str(meta["geometry_source"]),
        str(meta["resolved_offsets_file"]),
        float(meta["length_m"]),
        float(meta["beam_m"]),
        float(meta["draft_m"]),
        float(meta["lcg_from_transom_m"]),
        round(float(rho), 9),
        round(float(gravity), 9),
        int(point_count_per_side),
    )


def _ma2005_external_pdstrip_cache_work_dir(
    cache_dir: str | Path,
    row: pd.Series,
    rho: float,
    gravity: float,
    point_count_per_side: int = 8,
    base_dir: Path | None = None,
) -> Path:
    key = _ma2005_external_pdstrip_cache_key(row, rho, gravity, point_count_per_side, base_dir=base_dir)
    digest = hashlib.sha1("|".join(str(value) for value in key).encode("utf-8")).hexdigest()[:16]
    hull_name = re.sub(r"[^a-z0-9_]+", "_", str(row.get("hull", "hull")).strip().lower()).strip("_")
    return Path(cache_dir) / f"{hull_name or 'hull'}_{digest}"


def _ma2005_external_pdstrip_sectionresults(
    row: pd.Series,
    hull: object,
    rho: float,
    gravity: float,
    cache: dict[tuple[float | int | str, ...], object],
    persistent_cache_dir: str | Path | None = None,
    source_dir: str | Path | None = None,
    compiler: str = "gfortran",
    point_count_per_side: int = 8,
    base_dir: Path | None = None,
) -> object:
    cache_key = _ma2005_external_pdstrip_cache_key(row, rho, gravity, point_count_per_side, base_dir=base_dir)
    if cache_key in cache:
        return cache[cache_key]
    if persistent_cache_dir is not None:
        work_dir = _ma2005_external_pdstrip_cache_work_dir(
            persistent_cache_dir,
            row,
            rho,
            gravity,
            point_count_per_side,
            base_dir=base_dir,
        )
        sectionresults = work_dir / "sectionresults"
        if sectionresults.exists():
            try:
                parsed = parse_sectionresults(sectionresults)
                cache[cache_key] = parsed
                return parsed
            except ValueError:
                pass
        work_dir.mkdir(parents=True, exist_ok=True)
        result = run_pdstrip_station_hull_sections(
            work_dir,
            hull,
            source_dir=source_dir,
            compiler=compiler,
            rho_water_kg_m3=rho,
            gravity_m_s2=gravity,
            title=f"Ma 2005 external PDSTRIP section reference: {row.get('hull', '')}",
            point_count_per_side=point_count_per_side,
        )
        if result.status != "PASS" or result.parsed is None:
            raise RuntimeError(f"External PDSTRIP section run failed: {result.message}")
        cache[cache_key] = result.parsed
        return result.parsed
    with tempfile.TemporaryDirectory(prefix="planing_pdstrip_ma_") as tmp:
        result = run_pdstrip_station_hull_sections(
            Path(tmp) / "pdstrip_sections",
            hull,
            source_dir=source_dir,
            compiler=compiler,
            rho_water_kg_m3=rho,
            gravity_m_s2=gravity,
            title=f"Ma 2005 external PDSTRIP section reference: {row.get('hull', '')}",
            point_count_per_side=point_count_per_side,
        )
        if result.status != "PASS" or result.parsed is None:
            raise RuntimeError(f"External PDSTRIP section run failed: {result.message}")
        cache[cache_key] = result.parsed
        return result.parsed


def _ma2005_longitudinal_matrix_index(dof_index: int) -> int | None:
    return {2: 0, 4: 1}.get(int(dof_index))


def _ma2005_force_component_to_coefficient_raw(force: complex, prefix: str, omega_rad_s: float) -> float:
    omega = float(omega_rad_s)
    if omega <= 0.0:
        raise ValueError("omega_rad_s must be positive.")
    value = complex(force)
    if str(prefix).strip().upper() == "A":
        return float(np.real(value) / omega**2)
    return float(-np.imag(value) / omega)


def _ma2005_force_for_assembly_route(
    route_name: str,
    *,
    time_force: complex,
    gradient_force: complex,
    stokes_force: complex,
    row_measure_force: complex,
    end_force: complex,
) -> complex:
    """Reconstruct the selected whole-ship force using the formulation route semantics."""

    route = str(route_name).strip().lower()
    aliases = {
        "current": "current_hybrid_pressure_gradient_plus_end",
        "current_hybrid": "current_hybrid_pressure_gradient_plus_end",
        "hybrid_pressure_gradient_plus_end": "current_hybrid_pressure_gradient_plus_end",
        "current_hybrid_pressure_gradient_plus_end": "current_hybrid_pressure_gradient_plus_end",
        "eq31": "eq31_pressure_gradient_only",
        "eq31_pressure": "eq31_pressure_gradient_only",
        "eq31_pressure_gradient_only": "eq31_pressure_gradient_only",
        "eq32": "eq32_stokes_body_plus_end",
        "eq32_stokes": "eq32_stokes_body_plus_end",
        "eq32_stokes_body_plus_end": "eq32_stokes_body_plus_end",
        "eq32_stokes_body_only": "eq32_stokes_body_only",
        "eq31_pressure_gradient_plus_row_measure_transport": "eq31_pressure_gradient_plus_row_measure_transport",
        "eq31_plus_row_measure_transport": "eq31_pressure_gradient_plus_row_measure_transport",
        "eq31_pressure_gradient_minus_row_measure_transport": "eq31_pressure_gradient_minus_row_measure_transport",
        "eq31_minus_row_measure_transport": "eq31_pressure_gradient_minus_row_measure_transport",
        "eq31_pressure_gradient_plus_row_measure_transport_plus_end": (
            "eq31_pressure_gradient_plus_row_measure_transport_plus_end"
        ),
        "eq31_plus_row_measure_transport_plus_end": (
            "eq31_pressure_gradient_plus_row_measure_transport_plus_end"
        ),
        "eq31_pressure_gradient_minus_row_measure_transport_plus_end": (
            "eq31_pressure_gradient_minus_row_measure_transport_plus_end"
        ),
        "eq31_minus_row_measure_transport_plus_end": (
            "eq31_pressure_gradient_minus_row_measure_transport_plus_end"
        ),
        "all_terms": "all_terms_pressure_gradient_stokes_end",
        "all_terms_pressure_gradient_stokes_end": "all_terms_pressure_gradient_stokes_end",
    }
    if route not in aliases:
        raise ValueError(f"Unsupported matched force assembly route for audit: {route_name!r}.")
    route = aliases[route]
    if route == "current_hybrid_pressure_gradient_plus_end":
        return time_force + gradient_force + end_force
    if route == "eq31_pressure_gradient_only":
        return time_force + gradient_force
    if route == "eq32_stokes_body_plus_end":
        return time_force + stokes_force + end_force
    if route == "eq32_stokes_body_only":
        return time_force + stokes_force
    if route == "eq31_pressure_gradient_plus_row_measure_transport":
        return time_force + gradient_force + row_measure_force
    if route == "eq31_pressure_gradient_minus_row_measure_transport":
        return time_force + gradient_force - row_measure_force
    if route == "eq31_pressure_gradient_plus_row_measure_transport_plus_end":
        return time_force + gradient_force + row_measure_force + end_force
    if route == "eq31_pressure_gradient_minus_row_measure_transport_plus_end":
        return time_force + gradient_force - row_measure_force + end_force
    return time_force + gradient_force + stokes_force + end_force


def _ma2005_matched_component_diagnostics(
    hydro: Any,
    *,
    prefix: str,
    row_idx: int,
    col_idx: int,
    normalization_scale: float,
    omega_rad_s: float,
    reference_value: float | None = None,
) -> dict[str, float | str]:
    """Return row-level diagnostics for a matched-BIE provider Ma 2005 coefficient."""

    hp_row = _ma2005_longitudinal_matrix_index(row_idx)
    hp_col = _ma2005_longitudinal_matrix_index(col_idx)
    diagnostics: dict[str, float | str] = {
        column: "" for column in MA2005_MATCHED_DIAGNOSTIC_COLUMNS
    }
    diagnostics.update(
        {
            "provider_route": str(hydro.metadata.get("provider_route", "")),
            "provider_formulation": str(hydro.metadata.get("provider_formulation", "")),
            "matched_actual_force_assembly_route": str(hydro.metadata.get("force_assembly_route", "")),
            "matched_validity_status": str(hydro.validity.status),
            "matched_validity_note": " ".join(str(note) for note in hydro.validity.notes),
            "matched_diagnostic_scope": (
                "body pressure is decomposed into time-derivative and pressure-gradient terms; "
                "free-surface state norms, inner free-surface normal-derivative update gain/phase, "
                "pressure-to-state gains, adjacent-station body-potential continuity, panel-index "
                "geometry continuity, station geometry normalization, central/forward/backward gradient "
                "comparisons, diagnostic-only phase-aligned gradient checks, force-density peak locations, "
                "aft-active-station single-section audits, diagnostic-only end-station exclusion matrices, "
                "Eq.24 outer-control residuals, Stokes body forward-speed term, body-contour end term, "
                "fixed-control-surface end-term diagnostic, "
                "component-closure residuals, diagnostic-only Eq.30/Eq.32 term-combination candidates, "
                "and diagnostic-only pressure-sign candidates motivated by the closed-cylinder audit "
                "are reported for failure triage."
            ),
        }
    )
    if hp_row is None or hp_col is None:
        return diagnostics

    scale = max(float(normalization_scale), 1e-300)
    breakdown = hydro.contribution_breakdown

    def force_matrix(name: str) -> np.ndarray:
        value = np.asarray(breakdown.get(name, np.zeros((1, 2, 2), dtype=complex)), dtype=complex)
        if value.ndim != 3 or value.shape[0] < 1:
            return np.zeros((2, 2), dtype=complex)
        return value[0]

    def component_pair(force: complex) -> tuple[float, float]:
        raw_value = _ma2005_force_component_to_coefficient_raw(force, prefix, omega_rad_s)
        return raw_value, float(raw_value / scale)

    time_force = force_matrix("heave_pitch_time_derivative_force_matrices")[hp_row, hp_col]
    gradient_force = force_matrix("heave_pitch_forward_speed_force_matrices")[hp_row, hp_col]
    stokes_force = force_matrix("heave_pitch_stokes_body_forward_speed_force_matrices")[hp_row, hp_col]
    row_measure_force = force_matrix("heave_pitch_row_measure_transport_force_matrices")[hp_row, hp_col]
    end_force = force_matrix("heave_pitch_end_term_force_matrices")[hp_row, hp_col]
    control_surface_end_force = force_matrix(
        "heave_pitch_control_surface_end_term_force_matrices_diagnostic"
    )[hp_row, hp_col]
    body_force = time_force + gradient_force
    total_force = force_matrix("heave_pitch_complex_force_matrices")[hp_row, hp_col]
    selected_force = _ma2005_force_for_assembly_route(
        str(hydro.metadata.get("force_assembly_route", "current_hybrid_pressure_gradient_plus_end")),
        time_force=time_force,
        gradient_force=gradient_force,
        stokes_force=stokes_force,
        row_measure_force=row_measure_force,
        end_force=end_force,
    )
    closure_force = total_force - selected_force

    components = {
        "body_pressure": component_pair(body_force),
        "time_derivative": component_pair(time_force),
        "pressure_gradient": component_pair(gradient_force),
        "stokes_body_forward": component_pair(stokes_force),
        "row_measure_transport": component_pair(row_measure_force),
        "end_term": component_pair(end_force),
        "control_surface_end_term": component_pair(control_surface_end_force),
    }
    candidate_forces = {
        "time_only": time_force,
        "time_plus_pressure_gradient": time_force + gradient_force,
        "time_plus_pressure_gradient_plus_end": time_force + gradient_force + end_force,
        "time_plus_stokes_body": time_force + stokes_force,
        "time_plus_stokes_body_plus_end": time_force + stokes_force + end_force,
        "time_plus_pressure_gradient_plus_stokes_body": time_force + gradient_force + stokes_force,
        "time_plus_pressure_gradient_plus_row_measure_transport": (
            time_force + gradient_force + row_measure_force
        ),
        "time_plus_pressure_gradient_minus_row_measure_transport": (
            time_force + gradient_force - row_measure_force
        ),
        "time_plus_pressure_gradient_plus_row_measure_transport_plus_end": (
            time_force + gradient_force + row_measure_force + end_force
        ),
        "time_plus_pressure_gradient_minus_row_measure_transport_plus_end": (
            time_force + gradient_force - row_measure_force + end_force
        ),
        "all_terms": time_force + gradient_force + stokes_force + end_force,
    }
    pressure_sign_candidate_forces = {
        "time_derivative_flipped_keep_gradient_end": -time_force + gradient_force + end_force,
        "pressure_gradient_flipped_keep_time_end": time_force - gradient_force + end_force,
        "body_pressure_flipped_keep_end": -(time_force + gradient_force) + end_force,
        "body_pressure_and_end_flipped": -(time_force + gradient_force + end_force),
        "all_terms_flipped": -(time_force + gradient_force + stokes_force + end_force),
    }
    candidate_pairs = {name: component_pair(force) for name, force in candidate_forces.items()}
    pressure_sign_candidate_pairs = {
        name: component_pair(force) for name, force in pressure_sign_candidate_forces.items()
    }
    closure_pair = component_pair(closure_force)
    diagnostics.update(
        {
            "matched_body_pressure_component_raw": components["body_pressure"][0],
            "matched_body_pressure_component_value": components["body_pressure"][1],
            "matched_time_derivative_component_raw": components["time_derivative"][0],
            "matched_time_derivative_component_value": components["time_derivative"][1],
            "matched_pressure_gradient_component_raw": components["pressure_gradient"][0],
            "matched_pressure_gradient_component_value": components["pressure_gradient"][1],
            "matched_stokes_body_forward_component_raw": components["stokes_body_forward"][0],
            "matched_stokes_body_forward_component_value": components["stokes_body_forward"][1],
            "matched_row_measure_transport_component_raw": components["row_measure_transport"][0],
            "matched_row_measure_transport_component_value": components["row_measure_transport"][1],
            "matched_end_term_component_raw": components["end_term"][0],
            "matched_end_term_component_value": components["end_term"][1],
            "matched_control_surface_end_term_component_raw": components["control_surface_end_term"][0],
            "matched_control_surface_end_term_component_value": components["control_surface_end_term"][1],
            "matched_force_closure_residual_raw": closure_pair[0],
            "matched_force_closure_residual_value": closure_pair[1],
            "matched_candidate_time_only_value": candidate_pairs["time_only"][1],
            "matched_candidate_time_plus_pressure_gradient_value": candidate_pairs[
                "time_plus_pressure_gradient"
            ][1],
            "matched_candidate_time_plus_pressure_gradient_plus_end_value": candidate_pairs[
                "time_plus_pressure_gradient_plus_end"
            ][1],
            "matched_candidate_time_plus_stokes_body_value": candidate_pairs["time_plus_stokes_body"][1],
            "matched_candidate_time_plus_stokes_body_plus_end_value": candidate_pairs[
                "time_plus_stokes_body_plus_end"
            ][1],
            "matched_candidate_time_plus_pressure_gradient_plus_stokes_body_value": candidate_pairs[
                "time_plus_pressure_gradient_plus_stokes_body"
            ][1],
            "matched_candidate_time_plus_pressure_gradient_plus_row_measure_transport_value": candidate_pairs[
                "time_plus_pressure_gradient_plus_row_measure_transport"
            ][1],
            "matched_candidate_time_plus_pressure_gradient_minus_row_measure_transport_value": candidate_pairs[
                "time_plus_pressure_gradient_minus_row_measure_transport"
            ][1],
            "matched_candidate_time_plus_pressure_gradient_plus_row_measure_transport_plus_end_value": candidate_pairs[
                "time_plus_pressure_gradient_plus_row_measure_transport_plus_end"
            ][1],
            "matched_candidate_time_plus_pressure_gradient_minus_row_measure_transport_plus_end_value": candidate_pairs[
                "time_plus_pressure_gradient_minus_row_measure_transport_plus_end"
            ][1],
            "matched_candidate_all_terms_value": candidate_pairs["all_terms"][1],
            "matched_pressure_sign_candidate_time_derivative_flipped_keep_gradient_end_value": (
                pressure_sign_candidate_pairs["time_derivative_flipped_keep_gradient_end"][1]
            ),
            "matched_pressure_sign_candidate_pressure_gradient_flipped_keep_time_end_value": (
                pressure_sign_candidate_pairs["pressure_gradient_flipped_keep_time_end"][1]
            ),
            "matched_pressure_sign_candidate_body_pressure_flipped_keep_end_value": (
                pressure_sign_candidate_pairs["body_pressure_flipped_keep_end"][1]
            ),
            "matched_pressure_sign_candidate_body_pressure_and_end_flipped_value": (
                pressure_sign_candidate_pairs["body_pressure_and_end_flipped"][1]
            ),
            "matched_pressure_sign_candidate_all_terms_flipped_value": (
                pressure_sign_candidate_pairs["all_terms_flipped"][1]
            ),
        }
    )
    dominant_name, dominant_pair = max(components.items(), key=lambda item: abs(float(item[1][1])))
    diagnostics["matched_dominant_force_component"] = dominant_name
    diagnostics["matched_dominant_force_component_value"] = float(dominant_pair[1])
    selected_raw = _ma2005_force_component_to_coefficient_raw(total_force, prefix, omega_rad_s)
    diagnostics["matched_selected_coefficient_raw_from_total_force"] = float(selected_raw)
    reference_raw: float | None = None
    if reference_value is not None and np.isfinite(float(reference_value)):
        expected_raw = float(reference_value) * scale
        reference_raw = float(expected_raw)
        diagnostics["matched_selected_reference_raw_coefficient"] = float(expected_raw)
        diagnostics["matched_selected_raw_to_reference_raw_ratio"] = (
            float(selected_raw / expected_raw) if abs(expected_raw) > 1e-300 else float("nan")
        )
        diagnostics["matched_selected_required_scale_to_reference"] = (
            float(expected_raw / selected_raw) if abs(selected_raw) > 1e-300 else float("nan")
        )
        candidate_errors: dict[str, float] = {}
        for name, pair in candidate_pairs.items():
            raw = float(pair[0])
            ratio = float(raw / expected_raw) if abs(expected_raw) > 1e-300 else float("nan")
            diagnostics[f"matched_candidate_{name}_raw_to_reference_raw_ratio"] = ratio
            candidate_errors[name] = abs(ratio - 1.0) if np.isfinite(ratio) else float("inf")
        best_name = min(candidate_errors, key=candidate_errors.get)
        best_pair = candidate_pairs[best_name]
        best_ratio = diagnostics[f"matched_candidate_{best_name}_raw_to_reference_raw_ratio"]
        diagnostics["matched_candidate_best_combination"] = best_name
        diagnostics["matched_candidate_best_value"] = float(best_pair[1])
        diagnostics["matched_candidate_best_raw_to_reference_raw_ratio"] = float(best_ratio)
        diagnostics["matched_candidate_best_abs_relative_error"] = float(candidate_errors[best_name])
        pressure_sign_candidate_errors: dict[str, float] = {}
        for name, pair in pressure_sign_candidate_pairs.items():
            raw = float(pair[0])
            ratio = float(raw / expected_raw) if abs(expected_raw) > 1e-300 else float("nan")
            diagnostics[f"matched_pressure_sign_candidate_{name}_raw_to_reference_raw_ratio"] = ratio
            pressure_sign_candidate_errors[name] = abs(ratio - 1.0) if np.isfinite(ratio) else float("inf")
        sign_best_name = min(pressure_sign_candidate_errors, key=pressure_sign_candidate_errors.get)
        sign_best_pair = pressure_sign_candidate_pairs[sign_best_name]
        sign_best_ratio = diagnostics[
            f"matched_pressure_sign_candidate_{sign_best_name}_raw_to_reference_raw_ratio"
        ]
        diagnostics["matched_pressure_sign_candidate_best_combination"] = sign_best_name
        diagnostics["matched_pressure_sign_candidate_best_value"] = float(sign_best_pair[1])
        diagnostics["matched_pressure_sign_candidate_best_raw_to_reference_raw_ratio"] = float(sign_best_ratio)
        diagnostics["matched_pressure_sign_candidate_best_abs_relative_error"] = float(
            pressure_sign_candidate_errors[sign_best_name]
        )

    def max_breakdown(name: str) -> float:
        value = np.asarray(breakdown.get(name, np.asarray([], dtype=float)), dtype=float)
        if value.size == 0:
            return float("nan")
        finite = np.abs(value[np.isfinite(value)])
        if finite.size == 0:
            return float("nan")
        return float(np.max(finite))

    def median_breakdown(name: str) -> float:
        value = np.asarray(breakdown.get(name, np.asarray([], dtype=float)), dtype=float)
        if value.size == 0:
            return float("nan")
        finite = value[np.isfinite(value)]
        if finite.size == 0:
            return float("nan")
        return float(np.median(finite))

    def min_positive_breakdown(name: str) -> float:
        value = np.asarray(breakdown.get(name, np.asarray([], dtype=float)), dtype=float)
        if value.size == 0:
            return float("nan")
        finite = value[np.isfinite(value) & (value > 0.0)]
        if finite.size == 0:
            return float("nan")
        return float(np.min(finite))

    def min_breakdown(name: str) -> float:
        value = np.asarray(breakdown.get(name, np.asarray([], dtype=float)), dtype=float)
        if value.size == 0:
            return float("nan")
        finite = value[np.isfinite(value)]
        if finite.size == 0:
            return float("nan")
        return float(np.min(finite))

    def selected_matrix_breakdown(name: str) -> float:
        value = np.asarray(breakdown.get(name, np.asarray([], dtype=float)), dtype=float)
        if value.ndim == 3 and value.shape[0] >= 1 and value.shape[1:] == (2, 2):
            return float(value[0, hp_row, hp_col])
        if value.ndim == 2 and value.shape == (2, 2):
            return float(value[hp_row, hp_col])
        return float("nan")

    def selected_density_lobes(name: str) -> tuple[float, float, float]:
        x_values = np.asarray(breakdown.get("station_x_m", np.asarray([], dtype=float)), dtype=float)
        density = np.asarray(breakdown.get(name, np.asarray([], dtype=complex)), dtype=complex)
        if (
            x_values.ndim != 2
            or x_values.shape[0] < 1
            or density.ndim != 4
            or density.shape[0] < 1
            or density.shape[1] != x_values.shape[1]
            or density.shape[2:] != (2, 2)
        ):
            return float("nan"), float("nan"), float("nan")
        x = x_values[0]
        selected_density = density[0, :, hp_row, hp_col]
        coefficient_density = np.asarray(
            [
                _ma2005_force_component_to_coefficient_raw(value, prefix, omega_rad_s) / scale
                for value in selected_density
            ],
            dtype=float,
        )
        finite_mask = np.isfinite(x) & np.isfinite(coefficient_density)
        if np.count_nonzero(finite_mask) < 2:
            return float("nan"), float("nan"), float("nan")
        x = x[finite_mask]
        coefficient_density = coefficient_density[finite_mask]
        order = np.argsort(x)
        x = x[order]
        coefficient_density = coefficient_density[order]
        positive = float(np.trapezoid(np.maximum(coefficient_density, 0.0), x))
        negative = float(np.trapezoid(np.minimum(coefficient_density, 0.0), x))
        net = positive + negative
        absolute_sum = positive + abs(negative)
        if absolute_sum <= 1e-300:
            cancellation = 0.0
        else:
            cancellation = float(absolute_sum / max(abs(net), 1e-300))
        return positive, negative, cancellation

    def selected_station_breakdown(name: str, station_index: int = 0) -> float:
        value = np.asarray(breakdown.get(name, np.asarray([], dtype=float)), dtype=float)
        if value.ndim == 2 and value.shape[0] >= 1 and value.shape[1] > station_index:
            return float(value[0, station_index])
        if value.ndim == 1 and value.size > station_index:
            return float(value[station_index])
        if value.ndim == 1 and value.size == 1:
            return float(value[0])
        return float("nan")

    def first_breakdown_row(name: str) -> np.ndarray:
        value = np.asarray(breakdown.get(name, np.asarray([], dtype=float)), dtype=float)
        if value.ndim == 2 and value.shape[0] >= 1:
            return np.asarray(value[0], dtype=float)
        if value.ndim == 1:
            return np.asarray(value, dtype=float)
        return np.asarray([], dtype=float)

    solve_order_indices = first_breakdown_row("station_solve_order_indices")
    solve_order_x_over_l = first_breakdown_row("station_solve_order_x_over_l")
    solve_order_local_time = first_breakdown_row("station_solve_order_local_time_s")

    def first_value(values: np.ndarray) -> float:
        return float(values[0]) if values.size else float("nan")

    def last_value(values: np.ndarray) -> float:
        return float(values[-1]) if values.size else float("nan")

    def finite_monotonic(values: np.ndarray, *, sign: str) -> bool:
        finite = np.asarray(values[np.isfinite(values)], dtype=float)
        if finite.size < 2:
            return False
        diffs = np.diff(finite)
        if sign == "increasing":
            return bool(np.all(diffs > 0.0))
        if sign == "decreasing":
            return bool(np.all(diffs < 0.0))
        raise ValueError("sign must be increasing or decreasing.")

    solve_x_decreasing = finite_monotonic(solve_order_x_over_l, sign="decreasing")
    solve_time_increasing = finite_monotonic(solve_order_local_time, sign="increasing")
    solve_order_matches_a1 = bool(solve_x_decreasing and solve_time_increasing)

    def selected_exclusion_component(name: str) -> tuple[float, float]:
        force = force_matrix(name)[hp_row, hp_col]
        return component_pair(force)

    def selected_exclusion_raw_ratio(name: str) -> float:
        if reference_raw is None or abs(reference_raw) <= 1e-300:
            return float("nan")
        raw_value, _ = selected_exclusion_component(name)
        return float(raw_value / reference_raw)

