                        f"G={numeric(projection_transport, 'direct_pressure_gradient_integral_value'):.6g}; "
                        f"T={numeric(projection_transport, 'projection_transport_integral_value'):.6g}; "
                        f"endpoint={numeric(projection_transport, 'projection_endpoint_jump_value'):.6g}; "
