def _write_ma2005_phi_phi_n_kernel_normalization_trace_audit(
    comparison: pd.DataFrame,
    time_pressure_pi_kernel_trace_summary: pd.DataFrame,
    body_potential_normalization_trace_summary: pd.DataFrame,
    phi_n_orientation_summary: pd.DataFrame,
    a1_semantic_normal_summary: pd.DataFrame,
    sc_shared_unknown_convention_summary: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Trace A1/Ma potential, normal derivative, and kernel normalization.

    A1 states the motion potential as `phi_j` for unit radiation motion and
    maps it to the local-time potential `psi_j = phi_j exp(i omega t)`.  The
    matched equations then use raw simple-Green kernels with `-pi` inner
    self terms and `+pi` outer-control self terms.  This diagnostic keeps that
    chain explicit so factors such as `2*pi` or `1/pi^2` are not promoted into
    the default matched-BIE path without a derivation that also closes the
    open-Wigley body-potential scale gap.
    """

    out_path = Path(out_dir)
    detail_path = out_path / f"{benchmark}_phi_phi_n_kernel_normalization_trace_audit.csv"
    summary_path = out_path / f"{benchmark}_phi_phi_n_kernel_normalization_trace_summary.csv"

    detail_columns = [
        "benchmark",
        "trace_item",
        "a1_source",
        "code_source",
        "evidence_value",
        "supports_default_kernel_normalization_change",
        "blocks_default_kernel_normalization_change",
        "diagnostic_status",
        "notes",
        "next_required_evidence",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "gate_role",
        "path_diagnostic_status",
    ]
    summary_columns = [
        "benchmark",
        "target_coefficients",
        "comparison_row_count",
        "current_target_fail_count",
        "trace_item_count",
        "blocking_trace_count",
        "supporting_default_normalization_change_count",
        "current_inner_a_scale_unique",
        "current_inner_b_scale_unique",
        "current_inner_diagonal_sign_unique",
        "current_control_diagonal_sign_unique",
        "current_time_step_scale_unique",
        "pi_kernel_supporting_trace_count",
        "one_over_pi_squared_pass_count",
        "stored_to_semantic_match_count",
        "stored_to_semantic_reversal_count",
        "default_promotable_conversion_count",
        "closed_section_corrected_relative_error",
        "open_section_potential_ratio_min",
        "open_section_potential_ratio_max",
        "body_potential_trace_conclusion",
        "diagnostic_conclusion",
        "next_required_evidence",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "gate_role",
        "path_diagnostic_status",
    ]

    def first(frame: pd.DataFrame | None) -> pd.Series:
        return frame.iloc[0] if frame is not None and not frame.empty else pd.Series(dtype=object)

    def num(frame: pd.DataFrame | None, key: str, default: float = float("nan")) -> float:
        row = first(frame)
        if row.empty:
            return default
        return _numeric_cell(row, key, default)

    def text(frame: pd.DataFrame | None, key: str, default: str = "") -> str:
        row = first(frame)
        if row.empty:
            return default
        return _optional_text(row, key, default)

    def unique_values(frame: pd.DataFrame, column: str, default: str = "missing") -> str:
        if frame is None or frame.empty or column not in frame.columns:
            return default
        values = []
        for value in frame[column].dropna().tolist():
            if isinstance(value, float) and not np.isfinite(value):
                continue
            values.append(str(value))
        unique = sorted(set(values))
        return ";".join(unique) if unique else default

    target_names = {"A33", "B33", "A35", "B35", "A53", "B53", "A55", "B55"}
    if not comparison.empty and "coefficient" in comparison.columns:
        target = comparison[comparison["coefficient"].astype(str).str.strip().str.upper().isin(target_names)].copy()
    else:
        target = pd.DataFrame()
    current_fail_count = int(
        pd.to_numeric(target.get("gate_error_ratio", pd.Series(dtype=float)), errors="coerce").gt(1.0).sum()
    )

    inner_a = unique_values(comparison, "matched_inner_a_scale")
    inner_b = unique_values(comparison, "matched_inner_b_scale")
    inner_diag = unique_values(comparison, "matched_inner_diagonal_sign")
    control_diag = unique_values(comparison, "matched_control_diagonal_sign")
    if control_diag == "missing":
        control_diag = "default_+1.0_from_assemble_outer_control_surface_system"
    time_step_scale = unique_values(comparison, "matched_time_step_scale")

    pi_support = int(num(time_pressure_pi_kernel_trace_summary, "supporting_default_kernel_trace_count", 0.0))
    if pi_support == 0:
        pi_support = int(num(time_pressure_pi_kernel_trace_summary, "supporting_trace_count", 0.0))
    pi2_pass = int(num(time_pressure_pi_kernel_trace_summary, "one_over_pi_squared_pass_count", 0.0))
    body_conclusion = text(
        body_potential_normalization_trace_summary,
        "diagnostic_conclusion",
        "missing_body_potential_normalization_trace_summary",
    )
    closed_error = num(body_potential_normalization_trace_summary, "closed_section_corrected_relative_error")
    open_min = num(body_potential_normalization_trace_summary, "open_section_median_potential_norm_ratio_min")
    open_max = num(body_potential_normalization_trace_summary, "open_section_median_potential_norm_ratio_max")
    semantic_match = int(num(a1_semantic_normal_summary, "stored_to_semantic_match_count", 0.0))
    semantic_reversal = int(num(a1_semantic_normal_summary, "stored_to_semantic_reversal_count", 0.0))
    default_conversion = int(num(sc_shared_unknown_convention_summary, "default_promotable_conversion_count", 0.0))
    phi_orientation_conclusion = text(
        phi_n_orientation_summary,
        "diagnostic_conclusion",
        "missing_phi_n_orientation_summary",
    )
    semantic_conclusion = text(
        a1_semantic_normal_summary,
        "diagnostic_conclusion",
        "missing_a1_semantic_normal_summary",
    )
    sc_conclusion = text(
        sc_shared_unknown_convention_summary,
        "diagnostic_conclusion",
        "missing_sc_shared_unknown_convention_summary",
    )

    exclusion = (
        "A1/Ma text and the current raw-kernel code trace the Eq.11/Eq.16/Eq.25 self-term "
        "normalization, but they do not trace a default body-potential or time-pressure rescale. "
        "Changing kernel constants, phi_n signs, or S_C sign conversions would therefore be an "
        "unverified normalization change."
    )
    next_required = (
        "Derive phi, phi_n, Eq.23/Eq.24 unknown continuity, and Eq.30/Eq.32 pressure recovery "
        "from the original Ma/A1 formulation through the open Wigley station system, or obtain "
        "independent open-Wigley radiation pressure/body-potential reference data."
    )

    rows = [
        {
            "benchmark": benchmark,
            "trace_item": "a1_phi_psi_unit_motion_definition",
            "a1_source": "A1 Eq.1, Eq.2, Eq.4, Eq.8, Eq.10",
            "code_source": "matched station sweep stores body_potential from solved psi_body; pressure uses phi-equivalent harmonic amplitude",
            "evidence_value": "phi_j is the unit radiation potential; psi_j(t)=phi_j*exp(i*omega*t); no A1 text factor of 1/pi^2 is traced",
            "supports_default_kernel_normalization_change": False,
            "blocks_default_kernel_normalization_change": True,
            "diagnostic_status": "potential_definition_traced_without_extra_scale",
            "notes": "This traces the potential symbol and time-harmonic mapping, not an admissible rescale.",
            "next_required_evidence": next_required,
            "candidate_default_gate_eligible": False,
            "candidate_exclusion_reason": exclusion,
            "gate_role": "diagnostic_phi_phi_n_kernel_normalization_trace_not_hard_gate",
            "path_diagnostic_status": "INFO",
        },
        {
            "benchmark": benchmark,
            "trace_item": "a1_inner_kernel_eq11_eq25",
            "a1_source": "A1 Eq.11 and Eq.25 with alpha=1 for Eq.23",
            "code_source": "formulation.py:_inner_a_matrix/_log_normal_derivative_between_raw; assemble_matched_section_system",
            "evidence_value": f"inner_a_scale={inner_a}; inner_b_scale={inner_b}; inner_diagonal_sign={inner_diag}",
            "supports_default_kernel_normalization_change": False,
            "blocks_default_kernel_normalization_change": True,
            "diagnostic_status": "inner_raw_kernel_self_term_matches_a1_minus_pi_convention",
            "notes": "The matched system uses raw ln(r) kernels and a default -pi inner self term; this is not the /2pi closed-BEM helper path.",
            "next_required_evidence": next_required,
            "candidate_default_gate_eligible": False,
            "candidate_exclusion_reason": exclusion,
            "gate_role": "diagnostic_phi_phi_n_kernel_normalization_trace_not_hard_gate",
            "path_diagnostic_status": "INFO",
        },
        {
            "benchmark": benchmark,
            "trace_item": "a1_outer_control_kernel_eq16_eq25",
            "a1_source": "A1 Eq.16 and Eq.25 with alpha=2 for Eq.24",
            "code_source": "formulation.py:assemble_outer_control_surface_system",
            "evidence_value": f"control_diagonal_sign={control_diag}; time_step_scale={time_step_scale}",
            "supports_default_kernel_normalization_change": False,
            "blocks_default_kernel_normalization_change": True,
            "diagnostic_status": "outer_control_self_term_traced_as_positive_pi_default",
            "notes": "A sign or constant change on the outer S_C rows is still diagnostic-only unless the history RHS and full gate close together.",
            "next_required_evidence": next_required,
            "candidate_default_gate_eligible": False,
            "candidate_exclusion_reason": exclusion,
            "gate_role": "diagnostic_phi_phi_n_kernel_normalization_trace_not_hard_gate",
            "path_diagnostic_status": "INFO",
        },
        {
            "benchmark": benchmark,
            "trace_item": "phi_n_orientation_and_semantic_normal",
            "a1_source": "A1 Eq.4, Eq.10, Eq.23, Section 3.4 normal statements",
            "code_source": f"{benchmark}_phi_n_orientation_summary.csv;{benchmark}_a1_semantic_normal_summary.csv",
            "evidence_value": (
                f"phi_n_orientation={phi_orientation_conclusion}; semantic={semantic_conclusion}; "
                f"matches={semantic_match}; reversals={semantic_reversal}"
            ),
            "supports_default_kernel_normalization_change": False,
            "blocks_default_kernel_normalization_change": True,
            "diagnostic_status": "blanket_phi_n_normal_flip_not_supported",
            "notes": "The code-level source-normal orientation and the A1 semantic normals are not enough to justify a default normal flip.",
            "next_required_evidence": next_required,
            "candidate_default_gate_eligible": False,
            "candidate_exclusion_reason": exclusion,
            "gate_role": "diagnostic_phi_phi_n_kernel_normalization_trace_not_hard_gate",
            "path_diagnostic_status": "INFO",
        },
        {
            "benchmark": benchmark,
            "trace_item": "sc_shared_unknown_continuity",
            "a1_source": "A1 Section 3.4 continuity of psi_j and psi_nj on S_C",
            "code_source": f"{benchmark}_sc_shared_unknown_convention_summary.csv",
            "evidence_value": f"sc_shared_unknown={sc_conclusion}; default_promotable_conversions={default_conversion}",
            "supports_default_kernel_normalization_change": False,
            "blocks_default_kernel_normalization_change": True,
            "diagnostic_status": "sc_sign_conversion_not_defaultable",
            "notes": "Eq.23/Eq.24 share the same control unknowns in the current system; an inner/outer sign conversion remains unproved.",
            "next_required_evidence": next_required,
            "candidate_default_gate_eligible": False,
            "candidate_exclusion_reason": exclusion,
            "gate_role": "diagnostic_phi_phi_n_kernel_normalization_trace_not_hard_gate",
            "path_diagnostic_status": "INFO",
        },
        {
            "benchmark": benchmark,
            "trace_item": "one_over_pi_squared_and_body_potential_gap",
            "a1_source": "A1 Eq.30, Eq.32, Eq.34 combined with Eq.11/Eq.16/Eq.25",
            "code_source": (
                f"{benchmark}_time_pressure_pi_kernel_trace_summary.csv;"
                f"{benchmark}_body_potential_normalization_trace_summary.csv"
            ),
            "evidence_value": (
                f"pi_support={pi_support}; one_over_pi2_pass={pi2_pass}; "
                f"closed_error={closed_error:.12g}; open_ratio=[{open_min:.12g},{open_max:.12g}]; "
                f"body_trace={body_conclusion}"
            ),
            "supports_default_kernel_normalization_change": False,
            "blocks_default_kernel_normalization_change": True,
            "diagnostic_status": "body_potential_scale_gap_remains_untraced_by_kernel_normalization",
            "notes": "The observed A33/A53 scale clue is not derived from the traced raw-kernel normalization.",
            "next_required_evidence": next_required,
            "candidate_default_gate_eligible": False,
            "candidate_exclusion_reason": exclusion,
            "gate_role": "diagnostic_phi_phi_n_kernel_normalization_trace_not_hard_gate",
            "path_diagnostic_status": "INFO",
        },
    ]
    detail = pd.DataFrame(rows, columns=detail_columns)
    supports = int(detail["supports_default_kernel_normalization_change"].astype(bool).sum())
    blocks = int(detail["blocks_default_kernel_normalization_change"].astype(bool).sum())
    if (
        pi_support == 0
        and supports == 0
        and default_conversion == 0
        and "untraced" in body_conclusion
    ):
        conclusion = "phi_phi_n_kernel_chain_traced_but_no_default_normalization_change_supported"
    elif supports == 0:
        conclusion = "phi_phi_n_kernel_normalization_trace_blocks_default_rescale_without_open_section_reference"
    else:
        conclusion = "phi_phi_n_kernel_normalization_trace_requires_gate_closing_evidence"

    summary = pd.DataFrame(
        [
            {
                "benchmark": benchmark,
                "target_coefficients": "A33,B33,A35,B35,A53,B53,A55,B55",
                "comparison_row_count": int(len(comparison)),
                "current_target_fail_count": current_fail_count,
                "trace_item_count": int(len(detail)),
                "blocking_trace_count": blocks,
                "supporting_default_normalization_change_count": supports,
                "current_inner_a_scale_unique": inner_a,
                "current_inner_b_scale_unique": inner_b,
                "current_inner_diagonal_sign_unique": inner_diag,
                "current_control_diagonal_sign_unique": control_diag,
                "current_time_step_scale_unique": time_step_scale,
                "pi_kernel_supporting_trace_count": pi_support,
                "one_over_pi_squared_pass_count": pi2_pass,
                "stored_to_semantic_match_count": semantic_match,
                "stored_to_semantic_reversal_count": semantic_reversal,
                "default_promotable_conversion_count": default_conversion,
                "closed_section_corrected_relative_error": closed_error,
                "open_section_potential_ratio_min": open_min,
                "open_section_potential_ratio_max": open_max,
                "body_potential_trace_conclusion": body_conclusion,
                "diagnostic_conclusion": conclusion,
                "next_required_evidence": next_required,
                "candidate_default_gate_eligible": False,
                "candidate_exclusion_reason": exclusion,
                "gate_role": "diagnostic_phi_phi_n_kernel_normalization_trace_not_hard_gate",
                "path_diagnostic_status": "INFO" if len(detail) else "NOT_EVALUATED",
            }
        ],
        columns=summary_columns,
    )
    detail.to_csv(detail_path, index=False)
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _write_ma2005_a1_frequency_ladder_audit(
    comparison: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
    *,
    reference_path: Path | None = None,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Audit Gate 1 frequencies against the A1/Ma stated Wigley III frequency ladder.

    A1 states that the Wigley III comparison uses circular frequencies
    3, 4, 5, 6, 7, 8, 10, and 12 rad/s.  The plotted Ma figure axes and this
    package use the nondimensional frequency `omega * sqrt(L/g)`.  This audit
    keeps the current sparse Gate 1 points unchanged while making the reference
    frequency ambiguity machine-readable.
    """

    detail_path = out_dir / f"{benchmark}_a1_frequency_ladder_audit.csv"
    summary_path = out_dir / f"{benchmark}_a1_frequency_ladder_summary.csv"
    if reference_path is None:
        reference_path = (
            Path(__file__).resolve().parents[1]
            / "benchmarks"
            / "ma2005"
            / "journee1992_wigley_iii_forced_coefficients.csv"
        )

    detail_columns = [
        "benchmark",
        "source",
        "source_row",
        "coefficient",
        "omega_e_sqrt_l_over_g",
        "reference_value",
        "length_m",
        "gravity_m_s2",
        "nearest_a1_circular_frequency_rad_s",
        "nearest_a1_omega_sqrt_l_over_g",
        "omega_abs_delta_to_a1_ladder",
        "omega_rel_delta_to_a1_ladder",
        "a1_ladder_match",
        "a1_stated_circular_frequencies_rad_s",
        "a1_converted_omega_sqrt_l_over_g_ladder",
        "frequency_trace_status",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "gate_role",
        "path_diagnostic_status",
    ]
    summary_columns = [
        "benchmark",
        "gate1_row_count",
        "gate1_ladder_match_count",
        "gate1_ladder_mismatch_count",
        "gate1_max_abs_delta_to_a1_ladder",
        "gate1_max_rel_delta_to_a1_ladder",
        "journee_row_count",
        "journee_ladder_match_count",
        "journee_ladder_mismatch_count",
        "journee_max_abs_delta_to_a1_ladder",
        "journee_max_rel_delta_to_a1_ladder",
        "a1_stated_circular_frequencies_rad_s",
        "a1_converted_omega_sqrt_l_over_g_ladder",
        "frequency_trace_status",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "gate_role",
        "path_diagnostic_status",
        "source_reference",
    ]

    def numeric(row: pd.Series | dict[str, Any], column: str, default: float = float("nan")) -> float:
        try:
            return float(row[column])
        except (KeyError, TypeError, ValueError):
            return default

    def row_length(row: pd.Series | dict[str, Any]) -> float:
        length = numeric(row, "hull_length_m")
        if not np.isfinite(length):
            length = numeric(row, "length_m", 3.0)
        return length if np.isfinite(length) and length > 0.0 else 3.0

    def row_gravity(row: pd.Series | dict[str, Any]) -> float:
        gravity = numeric(row, "gravity_m_s2", 9.80665)
        return gravity if np.isfinite(gravity) and gravity > 0.0 else 9.80665

    def ladder_for(length: float, gravity: float) -> tuple[np.ndarray, np.ndarray]:
        circular = np.asarray([3.0, 4.0, 5.0, 6.0, 7.0, 8.0, 10.0, 12.0], dtype=float)
        converted = circular * math.sqrt(float(length) / float(gravity))
        return circular, converted

    def ladder_row(
        source: str,
        source_row: int,
        row: pd.Series,
        *,
        abs_tolerance: float,
        rel_tolerance: float,
    ) -> dict[str, Any]:
        length = row_length(row)
        gravity = row_gravity(row)
        circular, converted = ladder_for(length, gravity)
        omega = numeric(row, "omega_e_sqrt_l_over_g")
        if np.isfinite(omega):
            index = int(np.argmin(np.abs(converted - omega)))
            nearest = float(converted[index])
            nearest_rad = float(circular[index])
            abs_delta = float(abs(omega - nearest))
            rel_delta = float(abs_delta / max(abs(nearest), 1.0e-300))
            match = bool(abs_delta <= abs_tolerance or rel_delta <= rel_tolerance)
        else:
            nearest = float("nan")
            nearest_rad = float("nan")
            abs_delta = float("nan")
            rel_delta = float("nan")
            match = False
        if not np.isfinite(omega):
            status = "missing_frequency"
        elif match:
            status = "matches_a1_stated_frequency_ladder"
        else:
            status = "does_not_match_a1_stated_frequency_ladder"
        return {
            "benchmark": benchmark,
            "source": source,
            "source_row": int(source_row),
            "coefficient": str(row.get("coefficient", "")).strip().upper(),
            "omega_e_sqrt_l_over_g": omega,
            "reference_value": numeric(row, "reference_value"),
            "length_m": length,
            "gravity_m_s2": gravity,
            "nearest_a1_circular_frequency_rad_s": nearest_rad,
            "nearest_a1_omega_sqrt_l_over_g": nearest,
            "omega_abs_delta_to_a1_ladder": abs_delta,
            "omega_rel_delta_to_a1_ladder": rel_delta,
            "a1_ladder_match": match,
            "a1_stated_circular_frequencies_rad_s": ";".join(f"{value:.12g}" for value in circular),
            "a1_converted_omega_sqrt_l_over_g_ladder": ";".join(f"{value:.12g}" for value in converted),
            "frequency_trace_status": status,
            "candidate_default_gate_eligible": False,
            "candidate_exclusion_reason": (
                "This audit freezes frequency provenance only; it does not replace the sparse Ma figure Gate 1 "
                "with Journee table rows or any fitted frequency pairing."
            ),
            "gate_role": "diagnostic_a1_frequency_ladder_not_hard_gate",
            "path_diagnostic_status": "INFO",
        }

    if comparison.empty or "omega_e_sqrt_l_over_g" not in comparison.columns:
        detail = pd.DataFrame(columns=detail_columns)
        circular, converted = ladder_for(3.0, 9.80665)
        summary = pd.DataFrame(
            [
                {
                    "benchmark": benchmark,
                    "gate1_row_count": 0,
                    "gate1_ladder_match_count": 0,
                    "gate1_ladder_mismatch_count": 0,
                    "gate1_max_abs_delta_to_a1_ladder": float("nan"),
                    "gate1_max_rel_delta_to_a1_ladder": float("nan"),
                    "journee_row_count": 0,
                    "journee_ladder_match_count": 0,
                    "journee_ladder_mismatch_count": 0,
                    "journee_max_abs_delta_to_a1_ladder": float("nan"),
                    "journee_max_rel_delta_to_a1_ladder": float("nan"),
                    "a1_stated_circular_frequencies_rad_s": ";".join(f"{value:.12g}" for value in circular),
                    "a1_converted_omega_sqrt_l_over_g_ladder": ";".join(f"{value:.12g}" for value in converted),
                    "frequency_trace_status": "missing_gate1_comparison_frequency_rows",
                    "candidate_default_gate_eligible": False,
                    "candidate_exclusion_reason": "diagnostic input unavailable",
                    "gate_role": "diagnostic_a1_frequency_ladder_not_hard_gate",
                    "path_diagnostic_status": "NOT_EVALUATED",
                    "source_reference": str(reference_path),
                }
            ],
            columns=summary_columns,
        )
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    rows: list[dict[str, Any]] = []
    for index, row in comparison.reset_index(drop=True).iterrows():
        rows.append(
            ladder_row(
                "gate1_sparse_ma_figure_row",
                int(index),
                row,
                abs_tolerance=0.03,
                rel_tolerance=0.03,
            )
        )
    if reference_path.exists():
        journee = pd.read_csv(reference_path)
        if "omega_e_sqrt_l_over_g" in journee.columns:
            for index, row in journee.reset_index(drop=True).iterrows():
                candidate = row.copy()
                if "length_m" not in candidate:
                    candidate["length_m"] = 3.0
                rows.append(
                    ladder_row(
                        "journee_table_row",
                        int(index),
                        candidate,
                        abs_tolerance=0.08,
                        rel_tolerance=0.04,
                    )
                )

    detail = pd.DataFrame(rows, columns=detail_columns)
    gate = detail[detail["source"].astype(str).eq("gate1_sparse_ma_figure_row")].copy()
    journee = detail[detail["source"].astype(str).eq("journee_table_row")].copy()

    def count_matches(frame: pd.DataFrame) -> tuple[int, int, float, float]:
        if frame.empty:
            return 0, 0, float("nan"), float("nan")
        matches = frame["a1_ladder_match"].astype(bool)
        abs_delta = pd.to_numeric(frame["omega_abs_delta_to_a1_ladder"], errors="coerce")
        rel_delta = pd.to_numeric(frame["omega_rel_delta_to_a1_ladder"], errors="coerce")
        return (
            int(matches.sum()),
            int((~matches).sum()),
            float(abs_delta.max()) if abs_delta.notna().any() else float("nan"),
            float(rel_delta.max()) if rel_delta.notna().any() else float("nan"),
        )

    gate_match, gate_mismatch, gate_abs_max, gate_rel_max = count_matches(gate)
    journee_match, journee_mismatch, journee_abs_max, journee_rel_max = count_matches(journee)
    circular, converted = ladder_for(3.0, 9.80665)
    if len(gate) and gate_mismatch == len(gate) and len(journee) and journee_match == len(journee):
        status = "gate1_sparse_figure_frequencies_do_not_match_a1_ladder_but_journee_table_does"
    elif len(gate) and gate_mismatch > 0:
        status = "gate1_sparse_figure_frequencies_partly_mismatch_a1_ladder"
    elif len(gate):
        status = "gate1_sparse_figure_frequencies_match_a1_ladder"
    else:
        status = "a1_frequency_ladder_not_evaluable"
    summary = pd.DataFrame(
        [
            {
                "benchmark": benchmark,
                "gate1_row_count": int(len(gate)),
                "gate1_ladder_match_count": gate_match,
                "gate1_ladder_mismatch_count": gate_mismatch,
                "gate1_max_abs_delta_to_a1_ladder": gate_abs_max,
                "gate1_max_rel_delta_to_a1_ladder": gate_rel_max,
                "journee_row_count": int(len(journee)),
                "journee_ladder_match_count": journee_match,
                "journee_ladder_mismatch_count": journee_mismatch,
                "journee_max_abs_delta_to_a1_ladder": journee_abs_max,
                "journee_max_rel_delta_to_a1_ladder": journee_rel_max,
                "a1_stated_circular_frequencies_rad_s": ";".join(f"{value:.12g}" for value in circular),
                "a1_converted_omega_sqrt_l_over_g_ladder": ";".join(f"{value:.12g}" for value in converted),
                "frequency_trace_status": status,
                "candidate_default_gate_eligible": False,
                "candidate_exclusion_reason": (
                    "Reference frequency ambiguity is documented but does not authorize changing the hard Gate 1 "
                    "dataset without an explicit benchmark policy decision."
                ),
                "gate_role": "diagnostic_a1_frequency_ladder_not_hard_gate",
                "path_diagnostic_status": "INFO",
                "source_reference": str(reference_path),
            }
        ],
        columns=summary_columns,
    )
    detail.to_csv(detail_path, index=False)
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _write_ma2005_journee_frequency_gate_probe(
    comparison: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
    hydro_model: str = MA2005_MATCHED_BIE_MODEL,
    bem_free_surface_panel_count_per_side: int = 4,
    bem_body_panel_count: int | None = None,
    reference_path: Path | None = None,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Run the current provider at nearest Journee table frequencies.

    This is intentionally diagnostic-only.  It answers whether the sparse Ma
    figure probe would become a pass merely by switching to tabulated Journee
    frequencies and integrated coefficient values.
    """

    detail_path = out_dir / f"{benchmark}_journee_frequency_gate_probe.csv"
    summary_path = out_dir / f"{benchmark}_journee_frequency_gate_probe_summary.csv"
    if reference_path is None:
        reference_path = (
            Path(__file__).resolve().parents[1]
            / "benchmarks"
            / "ma2005"
            / "journee1992_wigley_iii_forced_coefficients.csv"
        )

    if comparison.empty or not reference_path.exists():
        detail = pd.DataFrame()
        summary = pd.DataFrame(
            [
                {
                    "benchmark": benchmark,
                    "row_count": 0,
                    "pass_count": 0,
                    "fail_count": 0,
                    "max_gate_error_ratio": float("nan"),
                    "median_gate_error_ratio": float("nan"),
                    "diagnostic_conclusion": "journee_frequency_probe_reference_not_available",
                    "candidate_default_gate_eligible": False,
                    "gate_role": "journee_frequency_probe_not_hard_gate",
                    "path_diagnostic_status": "NOT_EVALUATED",
                    "source_reference": str(reference_path),
                }
            ]
        )
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    table = pd.read_csv(reference_path)
    required = {"coefficient", "omega_e_sqrt_l_over_g", "reference_value"}
    if not required.issubset(comparison.columns) or not required.issubset(table.columns):
        detail = pd.DataFrame()
        summary = pd.DataFrame(
            [
                {
                    "benchmark": benchmark,
                    "row_count": 0,
                    "pass_count": 0,
                    "fail_count": 0,
                    "max_gate_error_ratio": float("nan"),
                    "median_gate_error_ratio": float("nan"),
                    "diagnostic_conclusion": "journee_frequency_probe_missing_required_columns",
                    "candidate_default_gate_eligible": False,
                    "gate_role": "journee_frequency_probe_not_hard_gate",
                    "path_diagnostic_status": "NOT_EVALUATED",
                    "source_reference": str(reference_path),
                }
            ]
        )
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    probe_rows: list[pd.Series] = []
    row_sources: list[dict[str, Any]] = []
    for source_index, current in comparison.iterrows():
        coeff = str(current["coefficient"]).strip().upper()
        current_omega = pd.to_numeric(pd.Series([current["omega_e_sqrt_l_over_g"]]), errors="coerce").iloc[0]
        candidates = table[table["coefficient"].astype(str).str.strip().str.upper().eq(coeff)].copy()
        if candidates.empty or not np.isfinite(current_omega):
            continue
        candidates["omega_numeric"] = pd.to_numeric(candidates["omega_e_sqrt_l_over_g"], errors="coerce")
        candidates = candidates[candidates["omega_numeric"].notna()].copy()
        if candidates.empty:
            continue
        candidates["omega_abs_delta"] = (candidates["omega_numeric"] - float(current_omega)).abs()
        nearest = candidates.loc[candidates["omega_abs_delta"].idxmin()].copy()
        row = current.copy()
        row["omega_e_sqrt_l_over_g"] = float(nearest["omega_numeric"])
        row["reference_value"] = float(nearest["reference_value"])
        row["source_figure"] = nearest.get("source_table", "")
        row["source_note"] = nearest.get("source_note", "")
        probe_rows.append(row)
        row_sources.append(
            {
                "source_row": int(source_index),
                "coefficient": coeff,
                "current_gate_omega_e_sqrt_l_over_g": float(current_omega),
                "current_gate_reference_value": float(current["reference_value"]),
                "journee_omega_e_sqrt_l_over_g": float(nearest["omega_numeric"]),
                "journee_reference_value": float(nearest["reference_value"]),
                "omega_abs_delta_vs_current_gate": float(nearest["omega_abs_delta"]),
                "source_table": nearest.get("source_table", ""),
                "source_url": nearest.get("source_url", ""),
                "source_lines": nearest.get("source_lines", ""),
            }
        )

    rows: list[dict[str, Any]] = []
    matrix_cache: dict[tuple[float | int | str, ...], object] = {}
    for probe_index, row in enumerate(probe_rows):
        source = row_sources[probe_index]
        coeff = str(row["coefficient"]).strip().upper()
        try:
            expected = float(row["reference_value"])
            calc = _ma2005_computed_coefficient(
                row,
                hydro_model=hydro_model,
                bem_free_surface_panel_count_per_side=bem_free_surface_panel_count_per_side,
                bem_body_panel_count=bem_body_panel_count,
                matrix_cache=matrix_cache,
                benchmark_base_dir=reference_path.parent,
            )
            actual = float(calc["computed_value"])
            _, row_idx, col_idx = _coefficient_matrix_indices(coeff)
            tolerance = 0.15 if row_idx == col_idx else 0.30
            metrics = _ma2005_error_metrics(
                expected,
                actual,
                tolerance,
                row_idx,
                col_idx,
                str(row.get("normalization", "ma2005")),
            )
            rows.append(
                {
                    "benchmark": benchmark,
                    "probe_row": int(probe_index),
                    **source,
                    "reference_value": expected,
                    "computed_value": actual,
                    "raw_computed_value": float(calc.get("raw_value", float("nan"))),
                    "abs_error": float(metrics["abs_error"]),
                    "rel_error": float(metrics["rel_error"]),
                    "tolerance": float(tolerance),
                    "effective_abs_tolerance": float(metrics["effective_abs_tolerance"]),
                    "gate_error_ratio": float(metrics["gate_error_ratio"]),
                    "error_metric": metrics["error_metric"],
                    "status": str(metrics["status"]),
                    "provider_route": calc.get("provider_route", ""),
                    "provider_formulation": calc.get("provider_formulation", ""),
                    "solver_status": calc.get("solver_status", ""),
                    "hydro_model": hydro_model,
                    "candidate_default_gate_eligible": False,
                    "gate_role": "journee_frequency_probe_not_hard_gate",
                    "path_diagnostic_status": "INFO",
                }
            )
        except Exception as exc:
            rows.append(
                {
                    "benchmark": benchmark,
                    "probe_row": int(probe_index),
                    **source,
                    "reference_value": float(row.get("reference_value", float("nan"))),
                    "computed_value": float("nan"),
                    "raw_computed_value": float("nan"),
                    "abs_error": float("nan"),
                    "rel_error": float("nan"),
                    "tolerance": float("nan"),
                    "effective_abs_tolerance": float("nan"),
                    "gate_error_ratio": float("nan"),
                    "error_metric": "exception",
                    "status": "FAIL",
                    "provider_route": "",
                    "provider_formulation": "",
                    "solver_status": str(exc),
                    "hydro_model": hydro_model,
                    "candidate_default_gate_eligible": False,
                    "gate_role": "journee_frequency_probe_not_hard_gate",
                    "path_diagnostic_status": "INFO",
                }
            )

    detail = pd.DataFrame(rows)
    if detail.empty:
        max_gate = float("nan")
        median_gate = float("nan")
        pass_count = 0
        fail_count = 0
        conclusion = "journee_frequency_probe_rows_missing"
    else:
        gate = pd.to_numeric(detail["gate_error_ratio"], errors="coerce")
        max_gate = float(gate.max()) if gate.notna().any() else float("nan")
        median_gate = float(gate.median()) if gate.notna().any() else float("nan")
        pass_count = int(detail["status"].astype(str).eq("PASS").sum())
        fail_count = int(detail["status"].astype(str).eq("FAIL").sum())
        conclusion = (
            "journee_frequency_probe_all_rows_pass"
            if fail_count == 0 and len(detail) > 0
            else "journee_frequency_probe_still_fails_default_provider"
        )
    summary = pd.DataFrame(
        [
            {
                "benchmark": benchmark,
                "row_count": int(len(detail)),
                "pass_count": pass_count,
                "fail_count": fail_count,
                "max_gate_error_ratio": max_gate,
                "median_gate_error_ratio": median_gate,
                "diagnostic_conclusion": conclusion,
                "candidate_default_gate_eligible": False,
                "gate_role": "journee_frequency_probe_not_hard_gate",
                "path_diagnostic_status": "INFO",
                "source_reference": str(reference_path),
            }
        ]
    )
    detail.to_csv(detail_path, index=False)
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _write_ma2005_journee_paired_table_gate_probe(
    comparison: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
    hydro_model: str = MA2005_MATCHED_BIE_MODEL,
    bem_free_surface_panel_count_per_side: int = 4,
    bem_body_panel_count: int | None = None,
    reference_path: Path | None = None,
) -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    """Run the current provider at all Journee table rows and pair same-frequency A/B values."""

    detail_path = out_dir / f"{benchmark}_journee_paired_table_gate_probe.csv"
    summary_path = out_dir / f"{benchmark}_journee_paired_table_gate_probe_summary.csv"
    pair_detail_path = out_dir / f"{benchmark}_journee_paired_complex_force_probe.csv"
    pair_summary_path = out_dir / f"{benchmark}_journee_paired_complex_force_probe_summary.csv"
    if reference_path is None:
        reference_path = (
            Path(__file__).resolve().parents[1]
            / "benchmarks"
            / "ma2005"
            / "journee1992_wigley_iii_forced_coefficients.csv"
        )

    summary_columns = [
        "benchmark",
        "row_count",
        "pass_count",
        "fail_count",
        "unique_frequency_count",
        "max_gate_error_ratio",
        "median_gate_error_ratio",
        "diagnostic_conclusion",
        "candidate_default_gate_eligible",
        "gate_role",
        "path_diagnostic_status",
        "source_reference",
    ]
    pair_summary_columns = [
        "benchmark",
        "pair_count",
        "pass_pair_count",
        "fail_pair_count",
        "paired_cells",
        "paired_frequencies",
        "max_pair_force_residual_norm",
        "median_pair_force_residual_norm",
        "max_member_gate_error_ratio",
        "diagnostic_conclusion",
        "candidate_default_gate_eligible",
        "gate_role",
        "path_diagnostic_status",
        "source_reference",
    ]
    component_probe_columns = (
        "matched_actual_force_assembly_route",
        "matched_body_pressure_component_raw",
        "matched_body_pressure_component_value",
        "matched_time_derivative_component_raw",
        "matched_time_derivative_component_value",
        "matched_pressure_gradient_component_raw",
        "matched_pressure_gradient_component_value",
        "matched_stokes_body_forward_component_raw",
        "matched_stokes_body_forward_component_value",
        "matched_row_measure_transport_component_raw",
        "matched_row_measure_transport_component_value",
        "matched_end_term_component_raw",
        "matched_end_term_component_value",
        "matched_force_closure_residual_raw",
        "matched_force_closure_residual_value",
        "matched_dominant_force_component",
        "matched_dominant_force_component_value",
        "matched_heave_body_normal_velocity_norm_max",
        "matched_pitch_body_normal_velocity_norm_max",
        "matched_heave_body_potential_norm_max",
        "matched_pitch_body_potential_norm_max",
        "matched_heave_body_pressure_time_derivative_norm_max",
        "matched_pitch_body_pressure_time_derivative_norm_max",
        "matched_heave_body_pressure_forward_speed_norm_max",
        "matched_pitch_body_pressure_forward_speed_norm_max",
        "matched_heave_body_pressure_forward_to_time_norm_ratio_max",
        "matched_pitch_body_pressure_forward_to_time_norm_ratio_max",
    )

    def empty_outputs(conclusion: str, status: str = "NOT_EVALUATED"):
        detail = pd.DataFrame()
        summary = pd.DataFrame(
            [
                {
                    "benchmark": benchmark,
                    "row_count": 0,
                    "pass_count": 0,
                    "fail_count": 0,
                    "unique_frequency_count": 0,
                    "max_gate_error_ratio": float("nan"),
                    "median_gate_error_ratio": float("nan"),
                    "diagnostic_conclusion": conclusion,
                    "candidate_default_gate_eligible": False,
                    "gate_role": "journee_paired_table_probe_not_hard_gate",
                    "path_diagnostic_status": status,
                    "source_reference": str(reference_path),
                }
            ],
            columns=summary_columns,
        )
        pair_detail = pd.DataFrame()
        pair_summary = pd.DataFrame(
            [
                {
                    "benchmark": benchmark,
                    "pair_count": 0,
                    "pass_pair_count": 0,
                    "fail_pair_count": 0,
                    "paired_cells": "",
                    "paired_frequencies": "",
                    "max_pair_force_residual_norm": float("nan"),
                    "median_pair_force_residual_norm": float("nan"),
                    "max_member_gate_error_ratio": float("nan"),
                    "diagnostic_conclusion": conclusion,
                    "candidate_default_gate_eligible": False,
                    "gate_role": "journee_paired_complex_force_probe_not_hard_gate",
                    "path_diagnostic_status": status,
                    "source_reference": str(reference_path),
                }
            ],
            columns=pair_summary_columns,
        )
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        pair_detail.to_csv(pair_detail_path, index=False)
        pair_summary.to_csv(pair_summary_path, index=False)
        return detail, summary, pair_detail, pair_summary

    if comparison.empty or not reference_path.exists():
        return empty_outputs("journee_paired_table_probe_reference_not_available")

    table = pd.read_csv(reference_path)
    required = {"coefficient", "omega_e_sqrt_l_over_g", "reference_value"}
    if not required.issubset(comparison.columns) or not required.issubset(table.columns):
        return empty_outputs("journee_paired_table_probe_missing_required_columns")

    def numeric(row: pd.Series | None, column: str, default: float = float("nan")) -> float:
        if row is None or column not in row:
            return default
        try:
            return float(row[column])
        except (TypeError, ValueError):
            return default

    def suffix(coefficient: str) -> str:
        text = str(coefficient).strip().upper()
        return text[1:] if len(text) == 3 and text[0] in {"A", "B"} else text

    def omega_rad_s(row: pd.Series) -> float:
        omega_bar = numeric(row, "omega_e_sqrt_l_over_g")
        length = numeric(row, "hull_length_m", numeric(row, "length_m"))
        gravity = numeric(row, "gravity_m_s2", 9.80665)
        if np.isfinite(omega_bar) and np.isfinite(length) and length > 0.0 and gravity > 0.0:
            return float(omega_bar * np.sqrt(gravity / length))
        return float("nan")

    def raw_reference(row: pd.Series) -> float:
        return numeric(row, "reference_value") * numeric(row, "normalization_scale", 1.0)

    def raw_computed(row: pd.Series) -> float:
        raw = numeric(row, "raw_computed_value")
        if np.isfinite(raw):
            return raw
        return numeric(row, "computed_value") * numeric(row, "normalization_scale", 1.0)

    def force_from_raw(a_raw: float, b_raw: float, omega: float) -> complex:
        if not (np.isfinite(a_raw) and np.isfinite(b_raw) and np.isfinite(omega) and omega > 0.0):
            return complex(float("nan"), float("nan"))
        return complex(a_raw * omega**2, -b_raw * omega)

    def force_residual(candidate: complex, reference: complex) -> float:
        if not (
            np.isfinite(candidate.real)
            and np.isfinite(candidate.imag)
            and np.isfinite(reference.real)
            and np.isfinite(reference.imag)
        ):
            return float("nan")
        return float(abs(candidate - reference) / max(abs(reference), 1.0e-300))

    template_by_coefficient = {
        str(row["coefficient"]).strip().upper(): row
        for _, row in comparison.iterrows()
        if "coefficient" in row
    }
    fallback_template = comparison.iloc[0]
    rows: list[dict[str, Any]] = []
    matrix_cache: dict[tuple[float | int | str, ...], object] = {}
    table = table.copy()
    table["_coefficient_upper"] = table["coefficient"].astype(str).str.strip().str.upper()
    table["_omega_numeric"] = pd.to_numeric(table["omega_e_sqrt_l_over_g"], errors="coerce")
    table = table[table["_coefficient_upper"].isin({"A33", "B33", "A35", "B35", "A53", "B53", "A55", "B55"})]
    table = table[table["_omega_numeric"].notna()].reset_index(drop=True)
    for source_index, ref_row in table.iterrows():
        coeff = str(ref_row["_coefficient_upper"])
        template = template_by_coefficient.get(coeff, fallback_template).copy()
        template["coefficient"] = coeff
        template["omega_e_sqrt_l_over_g"] = float(ref_row["_omega_numeric"])
        template["reference_value"] = float(ref_row["reference_value"])
        template["source_figure"] = ref_row.get("source_table", "")
        template["source_note"] = ref_row.get("source_note", "")
        try:
            expected = float(template["reference_value"])
            calc = _ma2005_computed_coefficient(
                template,
                hydro_model=hydro_model,
                bem_free_surface_panel_count_per_side=bem_free_surface_panel_count_per_side,
                bem_body_panel_count=bem_body_panel_count,
                matrix_cache=matrix_cache,
                benchmark_base_dir=reference_path.parent,
            )
            actual = float(calc["computed_value"])
            _, row_idx, col_idx = _coefficient_matrix_indices(coeff)
            tolerance = 0.15 if row_idx == col_idx else 0.30
            metrics = _ma2005_error_metrics(
                expected,
                actual,
                tolerance,
                row_idx,
                col_idx,
                str(template.get("normalization", "ma2005")),
            )
            rows.append(
                {
                    "benchmark": benchmark,
                    "probe_row": int(len(rows)),
                    "source_row": int(source_index),
                    "hull": str(ref_row.get("hull", template.get("hull", ""))),
                    "speed_case": str(ref_row.get("speed_case", template.get("speed_case", ""))),
                    "motion_test": str(ref_row.get("motion_test", "")),
                    "amplitude": str(ref_row.get("amplitude", "")),
                    "coefficient": coeff,
                    "matrix_cell": suffix(coeff),
                    "omega_e_sqrt_l_over_g": float(ref_row["_omega_numeric"]),
                    "hull_length_m": numeric(template, "hull_length_m", numeric(template, "length_m")),
                    "gravity_m_s2": numeric(template, "gravity_m_s2", 9.80665),
                    "reference_value": expected,
                    "computed_value": actual,
                    "raw_computed_value": float(calc.get("raw_value", float("nan"))),
                    "normalization_scale": numeric(template, "normalization_scale", 1.0),
                    "abs_error": float(metrics["abs_error"]),
                    "rel_error": float(metrics["rel_error"]),
                    "tolerance": float(tolerance),
                    "effective_abs_tolerance": float(metrics["effective_abs_tolerance"]),
                    "gate_error_ratio": float(metrics["gate_error_ratio"]),
                    "error_metric": metrics["error_metric"],
                    "status": str(metrics["status"]),
                    "provider_route": calc.get("provider_route", ""),
                    "provider_formulation": calc.get("provider_formulation", ""),
                    "solver_status": calc.get("solver_status", ""),
                    "hydro_model": hydro_model,
                    "source_table": ref_row.get("source_table", ""),
                    "source_url": ref_row.get("source_url", ""),
                    "source_lines": ref_row.get("source_lines", ""),
                    "source_note": ref_row.get("source_note", ""),
                    "candidate_default_gate_eligible": False,
                    "gate_role": "journee_paired_table_probe_not_hard_gate",
                    "path_diagnostic_status": "INFO",
                    **{column: calc.get(column, "") for column in component_probe_columns},
                }
            )
        except Exception as exc:
            rows.append(
                {
                    "benchmark": benchmark,
                    "probe_row": int(len(rows)),
                    "source_row": int(source_index),
                    "hull": str(ref_row.get("hull", template.get("hull", ""))),
                    "speed_case": str(ref_row.get("speed_case", template.get("speed_case", ""))),
                    "motion_test": str(ref_row.get("motion_test", "")),
                    "amplitude": str(ref_row.get("amplitude", "")),
                    "coefficient": coeff,
                    "matrix_cell": suffix(coeff),
                    "omega_e_sqrt_l_over_g": float(ref_row["_omega_numeric"]),
                    "hull_length_m": numeric(template, "hull_length_m", numeric(template, "length_m")),
                    "gravity_m_s2": numeric(template, "gravity_m_s2", 9.80665),
                    "reference_value": float(ref_row["reference_value"]),
                    "computed_value": float("nan"),
                    "raw_computed_value": float("nan"),
                    "normalization_scale": numeric(template, "normalization_scale", 1.0),
                    "abs_error": float("nan"),
                    "rel_error": float("nan"),
                    "tolerance": float("nan"),
                    "effective_abs_tolerance": float("nan"),
                    "gate_error_ratio": float("nan"),
                    "error_metric": "exception",
                    "status": "FAIL",
                    "provider_route": "",
                    "provider_formulation": "",
                    "solver_status": str(exc),
                    "hydro_model": hydro_model,
                    "source_table": ref_row.get("source_table", ""),
                    "source_url": ref_row.get("source_url", ""),
                    "source_lines": ref_row.get("source_lines", ""),
                    "source_note": ref_row.get("source_note", ""),
                    "candidate_default_gate_eligible": False,
                    "gate_role": "journee_paired_table_probe_not_hard_gate",
                    "path_diagnostic_status": "INFO",
                    **{column: float("nan") for column in component_probe_columns},
                }
            )

    detail = pd.DataFrame(rows)
    if detail.empty:
        max_gate = float("nan")
        median_gate = float("nan")
        pass_count = 0
        fail_count = 0
        frequency_count = 0
        conclusion = "journee_paired_table_probe_rows_missing"
    else:
        gate = pd.to_numeric(detail["gate_error_ratio"], errors="coerce")
        max_gate = float(gate.max()) if gate.notna().any() else float("nan")
        median_gate = float(gate.median()) if gate.notna().any() else float("nan")
        pass_count = int(detail["status"].astype(str).eq("PASS").sum())
        fail_count = int(detail["status"].astype(str).eq("FAIL").sum())
        frequency_count = int(detail["omega_e_sqrt_l_over_g"].nunique())
        conclusion = (
            "journee_paired_table_probe_all_rows_pass"
            if fail_count == 0 and len(detail) > 0
            else "journee_paired_table_probe_still_fails_default_provider"
        )
    summary = pd.DataFrame(
        [
            {
                "benchmark": benchmark,
                "row_count": int(len(detail)),
                "pass_count": pass_count,
                "fail_count": fail_count,
                "unique_frequency_count": frequency_count,
                "max_gate_error_ratio": max_gate,
                "median_gate_error_ratio": median_gate,
                "diagnostic_conclusion": conclusion,
                "candidate_default_gate_eligible": False,
                "gate_role": "journee_paired_table_probe_not_hard_gate",
                "path_diagnostic_status": "INFO",
                "source_reference": str(reference_path),
            }
        ],
        columns=summary_columns,
    )

    pair_rows: list[dict[str, Any]] = []
    if not detail.empty:
        detail["_coefficient_upper"] = detail["coefficient"].astype(str).str.strip().str.upper()
        for (hull, speed_case, motion_test, matrix_cell, omega_bar), group in detail.groupby(
            ["hull", "speed_case", "motion_test", "matrix_cell", "omega_e_sqrt_l_over_g"],
            sort=False,
        ):
            a = group[group["_coefficient_upper"].eq(f"A{matrix_cell}")]
            b = group[group["_coefficient_upper"].eq(f"B{matrix_cell}")]
            if a.empty or b.empty:
                continue
            a_row = a.iloc[0]
            b_row = b.iloc[0]
            omega = omega_rad_s(a_row)
            computed_force = force_from_raw(raw_computed(a_row), raw_computed(b_row), omega)
            reference_force = force_from_raw(raw_reference(a_row), raw_reference(b_row), omega)
            a_gate = numeric(a_row, "gate_error_ratio")
            b_gate = numeric(b_row, "gate_error_ratio")
            residual = force_residual(computed_force, reference_force)
            pair_status = (
                "PASS"
                if str(a_row["status"]) == "PASS" and str(b_row["status"]) == "PASS" and residual <= 1.0
                else "FAIL"
            )
            pair_rows.append(
                {
                    "benchmark": benchmark,
                    "hull": str(hull),
                    "speed_case": str(speed_case),
                    "motion_test": str(motion_test),
                    "matrix_cell": str(matrix_cell),
                    "omega_e_sqrt_l_over_g": float(omega_bar),
                    "omega_rad_s": omega,
                    "paired_coefficients": f"A{matrix_cell},B{matrix_cell}",
                    "a_reference_value": numeric(a_row, "reference_value"),
                    "b_reference_value": numeric(b_row, "reference_value"),
                    "a_computed_value": numeric(a_row, "computed_value"),
                    "b_computed_value": numeric(b_row, "computed_value"),
                    "a_gate_error_ratio": a_gate,
                    "b_gate_error_ratio": b_gate,
                    "member_max_gate_error_ratio": max(a_gate, b_gate),
                    "computed_force_real": computed_force.real,
                    "computed_force_imag": computed_force.imag,
                    "reference_force_real": reference_force.real,
                    "reference_force_imag": reference_force.imag,
                    "pair_force_residual_norm": residual,
                    "a_status": str(a_row["status"]),
                    "b_status": str(b_row["status"]),
                    "pair_status": pair_status,
                    "diagnostic_conclusion": (
                        "journee_same_frequency_complex_pair_passes"
                        if pair_status == "PASS"
                        else "journee_same_frequency_complex_pair_still_fails_default_provider"
                    ),
                    "candidate_default_gate_eligible": False,
                    "gate_role": "journee_paired_complex_force_probe_not_hard_gate",
                    "path_diagnostic_status": "INFO",
                }
            )
    pair_detail = pd.DataFrame(pair_rows)
    if pair_detail.empty:
        pair_summary = pd.DataFrame(
            [
                {
                    "benchmark": benchmark,
                    "pair_count": 0,
                    "pass_pair_count": 0,
                    "fail_pair_count": 0,
                    "paired_cells": "",
                    "paired_frequencies": "",
                    "max_pair_force_residual_norm": float("nan"),
                    "median_pair_force_residual_norm": float("nan"),
                    "max_member_gate_error_ratio": float("nan"),
                    "diagnostic_conclusion": "journee_paired_complex_force_probe_no_pairs",
                    "candidate_default_gate_eligible": False,
                    "gate_role": "journee_paired_complex_force_probe_not_hard_gate",
                    "path_diagnostic_status": "NOT_EVALUATED",
                    "source_reference": str(reference_path),
                }
            ],
            columns=pair_summary_columns,
        )
    else:
        pair_residual = pd.to_numeric(pair_detail["pair_force_residual_norm"], errors="coerce")
        member_gate = pd.to_numeric(pair_detail["member_max_gate_error_ratio"], errors="coerce")
        pass_pair_count = int(pair_detail["pair_status"].astype(str).eq("PASS").sum())
        fail_pair_count = int(pair_detail["pair_status"].astype(str).eq("FAIL").sum())
        pair_summary = pd.DataFrame(
            [
                {
                    "benchmark": benchmark,
                    "pair_count": int(len(pair_detail)),
                    "pass_pair_count": pass_pair_count,
                    "fail_pair_count": fail_pair_count,
                    "paired_cells": ";".join(sorted(set(pair_detail["matrix_cell"].astype(str)))),
                    "paired_frequencies": ";".join(
                        f"{value:.6g}"
                        for value in sorted(
                            pd.to_numeric(pair_detail["omega_e_sqrt_l_over_g"], errors="coerce")
                            .dropna()
                            .unique()
                        )
                    ),
                    "max_pair_force_residual_norm": (
                        float(pair_residual.max()) if pair_residual.notna().any() else float("nan")
                    ),
                    "median_pair_force_residual_norm": (
                        float(pair_residual.median()) if pair_residual.notna().any() else float("nan")
                    ),
                    "max_member_gate_error_ratio": (
                        float(member_gate.max()) if member_gate.notna().any() else float("nan")
                    ),
                    "diagnostic_conclusion": (
                        "journee_paired_complex_force_probe_all_pairs_pass"
                        if fail_pair_count == 0
                        else "journee_paired_complex_force_probe_still_fails_default_provider"
                    ),
                    "candidate_default_gate_eligible": False,
                    "gate_role": "journee_paired_complex_force_probe_not_hard_gate",
                    "path_diagnostic_status": "INFO",
                    "source_reference": str(reference_path),
                }
            ],
            columns=pair_summary_columns,
        )
    detail = detail.drop(columns=["_coefficient_upper"], errors="ignore")
    detail.to_csv(detail_path, index=False)
    summary.to_csv(summary_path, index=False)
    pair_detail.to_csv(pair_detail_path, index=False)
    pair_summary.to_csv(pair_summary_path, index=False)
    return detail, summary, pair_detail, pair_summary


def _write_ma2005_journee_complex_scale_phase_audit(
    pair_detail: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Audit scale and phase requirements for Journee same-frequency A/B pairs."""

    detail_path = out_dir / f"{benchmark}_journee_complex_scale_phase_audit.csv"
    summary_path = out_dir / f"{benchmark}_journee_complex_scale_phase_summary.csv"
    detail_columns = [
        "benchmark",
        "matrix_cell",
        "omega_e_sqrt_l_over_g",
        "paired_coefficients",
        "computed_force_abs",
        "reference_force_abs",
        "computed_force_phase_deg",
        "reference_force_phase_deg",
        "reference_minus_computed_phase_deg",
        "required_complex_scale_real",
        "required_complex_scale_imag",
        "required_complex_scale_abs",
        "required_complex_scale_phase_deg",
        "least_squares_real_scale",
        "least_squares_real_scale_residual_norm",
        "a_required_scale",
        "b_required_scale",
        "a_b_required_scale_ratio",
        "a_b_required_scale_log10_abs_delta",
        "a_b_required_scale_same_sign",
        "same_real_scale_plausible",
        "diagnostic_conclusion",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "gate_role",
        "path_diagnostic_status",
    ]
    summary_columns = [
        "benchmark",
        "pair_count",
        "real_scale_plausible_count",
        "ab_scale_consistent_count",
        "max_real_scale_residual_norm",
        "median_real_scale_residual_norm",
        "complex_scale_abs_min",
        "complex_scale_abs_max",
        "complex_scale_abs_max_over_min",
        "complex_scale_phase_span_deg",
        "max_ab_required_scale_log10_abs_delta",
        "diagnostic_conclusion",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "gate_role",
        "path_diagnostic_status",
    ]
    if pair_detail.empty:
        detail = pd.DataFrame(columns=detail_columns)
        summary = pd.DataFrame(
            [
                {
                    "benchmark": benchmark,
                    "pair_count": 0,
                    "real_scale_plausible_count": 0,
                    "ab_scale_consistent_count": 0,
                    "max_real_scale_residual_norm": float("nan"),
                    "median_real_scale_residual_norm": float("nan"),
                    "complex_scale_abs_min": float("nan"),
                    "complex_scale_abs_max": float("nan"),
                    "complex_scale_abs_max_over_min": float("nan"),
                    "complex_scale_phase_span_deg": float("nan"),
                    "max_ab_required_scale_log10_abs_delta": float("nan"),
                    "diagnostic_conclusion": "journee_complex_scale_phase_no_pairs",
                    "candidate_default_gate_eligible": False,
                    "candidate_exclusion_reason": (
                        "diagnostic-only phase/scale audit; same-frequency A/B pairs are required."
                    ),
                    "gate_role": "diagnostic_journee_complex_scale_phase_not_hard_gate",
                    "path_diagnostic_status": "NOT_EVALUATED",
                }
            ],
            columns=summary_columns,
        )
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    def phase_deg(value: complex) -> float:
        if not (np.isfinite(value.real) and np.isfinite(value.imag)):
            return float("nan")
        return float(np.degrees(np.angle(value)))

    def wrap_phase_delta(value: float) -> float:
        if not np.isfinite(value):
            return float("nan")
        return float((value + 180.0) % 360.0 - 180.0)

    def scalar_ratio(numerator: float, denominator: float) -> float:
        if np.isfinite(numerator) and np.isfinite(denominator) and abs(denominator) > 1e-300:
            return float(numerator / denominator)
        return float("nan")

    rows: list[dict[str, Any]] = []
    for _, row in pair_detail.iterrows():
        computed = complex(
            _numeric_cell(row, "computed_force_real", float("nan")),
            _numeric_cell(row, "computed_force_imag", float("nan")),
        )
        reference = complex(
            _numeric_cell(row, "reference_force_real", float("nan")),
            _numeric_cell(row, "reference_force_imag", float("nan")),
        )
        computed_abs = abs(computed)
        reference_abs = abs(reference)
        if np.isfinite(computed_abs) and computed_abs > 1e-300:
            complex_scale = reference / computed
            real_scale = float(np.real(reference * np.conjugate(computed)) / (computed_abs**2))
            real_scaled = computed * real_scale
            real_residual = float(abs(real_scaled - reference) / max(reference_abs, 1e-300))
        else:
            complex_scale = complex(float("nan"), float("nan"))
            real_scale = float("nan")
            real_residual = float("nan")
        a_scale = scalar_ratio(
            _numeric_cell(row, "a_reference_value", float("nan")),
            _numeric_cell(row, "a_computed_value", float("nan")),
        )
        b_scale = scalar_ratio(
            _numeric_cell(row, "b_reference_value", float("nan")),
            _numeric_cell(row, "b_computed_value", float("nan")),
        )
        ab_ratio = scalar_ratio(a_scale, b_scale)
        if np.isfinite(ab_ratio) and abs(ab_ratio) > 1e-300:
            ab_log_delta = float(abs(np.log10(abs(ab_ratio))))
        else:
            ab_log_delta = float("nan")
        same_sign = bool(np.isfinite(a_scale) and np.isfinite(b_scale) and a_scale * b_scale > 0.0)
        same_real_scale = bool(
            np.isfinite(real_residual)
            and real_residual <= 0.30
            and same_sign
            and np.isfinite(ab_log_delta)
            and ab_log_delta <= np.log10(2.0)
        )
        computed_phase = phase_deg(computed)
        reference_phase = phase_deg(reference)
        phase_delta = wrap_phase_delta(reference_phase - computed_phase)
        if same_real_scale:
            conclusion = "journee_pair_real_scale_phase_consistent"
        elif np.isfinite(real_residual) and real_residual <= 0.30:
            conclusion = "journee_pair_force_phase_matches_but_ab_scales_split"
        else:
            conclusion = "journee_pair_requires_complex_scale_or_pair_specific_phase"
        rows.append(
            {
                "benchmark": benchmark,
                "matrix_cell": str(row.get("matrix_cell", "")),
                "omega_e_sqrt_l_over_g": _numeric_cell(row, "omega_e_sqrt_l_over_g", float("nan")),
                "paired_coefficients": str(row.get("paired_coefficients", "")),
                "computed_force_abs": float(computed_abs),
                "reference_force_abs": float(reference_abs),
                "computed_force_phase_deg": computed_phase,
                "reference_force_phase_deg": reference_phase,
                "reference_minus_computed_phase_deg": phase_delta,
                "required_complex_scale_real": float(complex_scale.real),
                "required_complex_scale_imag": float(complex_scale.imag),
                "required_complex_scale_abs": float(abs(complex_scale)),
                "required_complex_scale_phase_deg": phase_deg(complex_scale),
                "least_squares_real_scale": real_scale,
                "least_squares_real_scale_residual_norm": real_residual,
                "a_required_scale": a_scale,
                "b_required_scale": b_scale,
                "a_b_required_scale_ratio": ab_ratio,
                "a_b_required_scale_log10_abs_delta": ab_log_delta,
                "a_b_required_scale_same_sign": same_sign,
                "same_real_scale_plausible": same_real_scale,
                "diagnostic_conclusion": conclusion,
                "candidate_default_gate_eligible": False,
                "candidate_exclusion_reason": (
                    "per-pair scale/phase requirements are diagnostic only; they cannot enter the default "
                    "provider without a traced equation-level phase convention and full Gate 1 closure."
                ),
                "gate_role": "diagnostic_journee_complex_scale_phase_not_hard_gate",
                "path_diagnostic_status": "INFO",
            }
        )
    detail = pd.DataFrame(rows, columns=detail_columns)
    detail.to_csv(detail_path, index=False)

    real_residual = pd.to_numeric(detail["least_squares_real_scale_residual_norm"], errors="coerce")
    scale_abs = pd.to_numeric(detail["required_complex_scale_abs"], errors="coerce")
    scale_phase = pd.to_numeric(detail["required_complex_scale_phase_deg"], errors="coerce")
    ab_log_delta = pd.to_numeric(detail["a_b_required_scale_log10_abs_delta"], errors="coerce")
    plausible = detail["same_real_scale_plausible"].astype(bool)
    ab_consistent = (
        detail["a_b_required_scale_same_sign"].astype(bool)
        & ab_log_delta.le(np.log10(2.0)).fillna(False)
    )
    if bool(plausible.all()):
        conclusion = "journee_complex_scale_phase_all_pairs_real_scale_consistent_but_untraced"
    elif scale_abs.notna().any() and (
        (float(scale_abs.max() / max(float(scale_abs.min()), 1e-300)) > 10.0)
        or (scale_phase.notna().any() and float(scale_phase.max() - scale_phase.min()) > 45.0)
        or (ab_log_delta.notna().any() and float(ab_log_delta.max()) > 1.0)
    ):
        conclusion = "journee_complex_scale_phase_varies_across_pairs"
    else:
        conclusion = "journee_complex_scale_phase_requires_equation_trace"
    scale_abs_min = float(scale_abs.min()) if scale_abs.notna().any() else float("nan")
    scale_abs_max = float(scale_abs.max()) if scale_abs.notna().any() else float("nan")
    summary = pd.DataFrame(
        [
            {
                "benchmark": benchmark,
                "pair_count": int(len(detail)),
                "real_scale_plausible_count": int(plausible.sum()),
                "ab_scale_consistent_count": int(ab_consistent.sum()),
                "max_real_scale_residual_norm": (
                    float(real_residual.max()) if real_residual.notna().any() else float("nan")
                ),
                "median_real_scale_residual_norm": (
                    float(real_residual.median()) if real_residual.notna().any() else float("nan")
                ),
                "complex_scale_abs_min": scale_abs_min,
                "complex_scale_abs_max": scale_abs_max,
                "complex_scale_abs_max_over_min": (
                    float(scale_abs_max / scale_abs_min)
                    if np.isfinite(scale_abs_min) and abs(scale_abs_min) > 1e-300
                    else float("nan")
                ),
                "complex_scale_phase_span_deg": (
                    float(scale_phase.max() - scale_phase.min()) if scale_phase.notna().any() else float("nan")
                ),
                "max_ab_required_scale_log10_abs_delta": (
                    float(ab_log_delta.max()) if ab_log_delta.notna().any() else float("nan")
                ),
                "diagnostic_conclusion": conclusion,
                "candidate_default_gate_eligible": False,
                "candidate_exclusion_reason": (
                    "The audit can diagnose pair-specific phase/scale demands, but no pair-specific fitted "
                    "scale is allowed into the default Gate 1 provider."
                ),
                "gate_role": "diagnostic_journee_complex_scale_phase_not_hard_gate",
                "path_diagnostic_status": "INFO",
            }
        ],
        columns=summary_columns,
    )
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _write_ma2005_journee_cell35_pitch_column_complex_audit(
    pair_detail: pd.DataFrame,
    complex_scale_phase_detail: pd.DataFrame,
    component_frequency_trend_audit: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Audit the Journee same-frequency cell-35 pitch-column blocker.

    B33 endpoint-forward evidence is a useful local clue, but A35/B35 belong to
    the pitch-radiation column.  This audit narrows the cell-35 failure to the
    same-frequency complex force pair, required scale/phase, and B35 component
    frequency-invariance evidence before any equation-level default migration.
    """

    detail_path = out_dir / f"{benchmark}_journee_cell35_pitch_column_complex_audit.csv"
    summary_path = out_dir / f"{benchmark}_journee_cell35_pitch_column_complex_summary.csv"
    detail_columns = [
        "benchmark",
        "matrix_cell",
        "omega_e_sqrt_l_over_g",
        "paired_coefficients",
        "a35_gate_error_ratio",
        "b35_gate_error_ratio",
        "member_max_gate_error_ratio",
        "pair_force_residual_norm",
        "pair_status",
        "computed_force_phase_deg",
        "reference_force_phase_deg",
        "reference_minus_computed_phase_deg",
        "required_complex_scale_abs",
        "required_complex_scale_phase_deg",
        "a_required_scale",
        "b_required_scale",
        "a_b_required_scale_ratio",
        "a_b_required_scale_log10_abs_delta",
        "a_b_required_scale_same_sign",
        "b35_invariant_component_count",
        "b35_invariant_components",
        "b35_sensitive_component_count",
        "b35_sensitive_components",
        "a35_invariant_component_count",
        "a35_invariant_components",
        "a35_sensitive_component_count",
        "a35_sensitive_components",
        "diagnostic_conclusion",
        "remaining_blocker",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "gate_role",
        "path_diagnostic_status",
    ]
    summary_columns = [
        "benchmark",
        "pair_count",
        "fail_pair_count",
        "max_pair_force_residual_norm",
        "max_member_gate_error_ratio",
        "phase_error_abs_min_deg",
        "phase_error_abs_max_deg",
        "required_complex_scale_abs_min",
        "required_complex_scale_abs_max",
        "required_complex_scale_phase_min_deg",
        "required_complex_scale_phase_max_deg",
        "max_ab_required_scale_log10_abs_delta",
        "b35_invariant_component_count",
        "b35_invariant_components",
        "b35_sensitive_component_count",
        "b35_sensitive_components",
        "a35_invariant_component_count",
        "a35_invariant_components",
        "a35_sensitive_component_count",
        "a35_sensitive_components",
        "diagnostic_conclusion",
        "remaining_blocker",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "gate_role",
        "path_diagnostic_status",
    ]

    def empty_outputs(conclusion: str, status: str = "NOT_EVALUATED") -> tuple[pd.DataFrame, pd.DataFrame]:
        detail = pd.DataFrame(columns=detail_columns)
        summary = pd.DataFrame(
            [
                {
                    "benchmark": benchmark,
                    "pair_count": 0,
                    "fail_pair_count": 0,
                    "max_pair_force_residual_norm": float("nan"),
                    "max_member_gate_error_ratio": float("nan"),
                    "phase_error_abs_min_deg": float("nan"),
                    "phase_error_abs_max_deg": float("nan"),
                    "required_complex_scale_abs_min": float("nan"),
                    "required_complex_scale_abs_max": float("nan"),
                    "required_complex_scale_phase_min_deg": float("nan"),
                    "required_complex_scale_phase_max_deg": float("nan"),
                    "max_ab_required_scale_log10_abs_delta": float("nan"),
                    "b35_invariant_component_count": 0,
                    "b35_invariant_components": "",
                    "b35_sensitive_component_count": 0,
                    "b35_sensitive_components": "",
                    "a35_invariant_component_count": 0,
                    "a35_invariant_components": "",
                    "a35_sensitive_component_count": 0,
                    "a35_sensitive_components": "",
                    "diagnostic_conclusion": conclusion,
                    "remaining_blocker": "Journee same-frequency cell-35 pair or component trend input is missing.",
                    "candidate_default_gate_eligible": False,
                    "candidate_exclusion_reason": "diagnostic input unavailable; no default-route migration allowed.",
                    "gate_role": "diagnostic_journee_cell35_pitch_column_complex_not_hard_gate",
                    "path_diagnostic_status": status,
                }
            ],
            columns=summary_columns,
        )
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    if pair_detail.empty:
        return empty_outputs("journee_cell35_pitch_column_complex_no_pair_rows")
    if "matrix_cell" not in pair_detail.columns:
        return empty_outputs("journee_cell35_pitch_column_complex_missing_matrix_cell")

    def bool_cell(row: pd.Series, column: str) -> bool:
        value = row.get(column, False)
        if isinstance(value, (bool, np.bool_)):
            return bool(value)
        text = str(value).strip().lower()
        return text in {"true", "1", "yes", "y"}

    def match_scale_row(matrix_cell: str, omega_bar: float) -> pd.Series | None:
        if complex_scale_phase_detail.empty or "matrix_cell" not in complex_scale_phase_detail.columns:
            return None
        scale = complex_scale_phase_detail[
            complex_scale_phase_detail["matrix_cell"].astype(str).str.strip().eq(str(matrix_cell))
        ].copy()
        if scale.empty:
            return None
        if "omega_e_sqrt_l_over_g" not in scale.columns or not np.isfinite(omega_bar):
            return scale.iloc[0]
        omega_values = pd.to_numeric(scale["omega_e_sqrt_l_over_g"], errors="coerce")
        delta = (omega_values - float(omega_bar)).abs()
        if not delta.notna().any():
            return scale.iloc[0]
        return scale.iloc[int(np.nanargmin(delta.to_numpy(dtype=float)))]

    def component_names(coefficient: str, flag_column: str) -> list[str]:
        if component_frequency_trend_audit.empty or "coefficient" not in component_frequency_trend_audit.columns:
            return []
        rows = component_frequency_trend_audit[
            component_frequency_trend_audit["coefficient"].astype(str).str.strip().str.upper().eq(coefficient)
        ]
        if rows.empty or flag_column not in rows.columns:
            return []
        names: list[str] = []
        for _, component_row in rows.iterrows():
            if bool_cell(component_row, flag_column):
                names.append(str(component_row.get("component_name", "")))
        return [name for name in names if name]

    def numeric_from_scale(
        scale_row: pd.Series | None,
        pair_row: pd.Series,
        scale_column: str,
        pair_column: str | None = None,
    ) -> float:
        if scale_row is not None and scale_column in scale_row:
            value = _numeric_cell(scale_row, scale_column, float("nan"))
            if np.isfinite(value):
                return value
        if pair_column is not None:
            return _numeric_cell(pair_row, pair_column, float("nan"))
        return float("nan")

    rows: list[dict[str, Any]] = []
    cell35_pairs = pair_detail[pair_detail["matrix_cell"].astype(str).str.strip().eq("35")]
    if cell35_pairs.empty:
        return empty_outputs("journee_cell35_pitch_column_complex_no_cell35_pairs")

    b35_invariant = component_names("B35", "component_values_invariant")
    b35_sensitive = component_names("B35", "component_values_variant")
    a35_invariant = component_names("A35", "component_values_invariant")
    a35_sensitive = component_names("A35", "component_values_variant")
    for _, pair_row in cell35_pairs.iterrows():
        omega_bar = _numeric_cell(pair_row, "omega_e_sqrt_l_over_g", float("nan"))
        scale_row = match_scale_row("35", omega_bar)
        phase_delta = numeric_from_scale(
            scale_row,
            pair_row,
            "reference_minus_computed_phase_deg",
        )
        required_scale_abs = numeric_from_scale(scale_row, pair_row, "required_complex_scale_abs")
        required_scale_phase = numeric_from_scale(scale_row, pair_row, "required_complex_scale_phase_deg")
        ab_log_delta = numeric_from_scale(scale_row, pair_row, "a_b_required_scale_log10_abs_delta")
        pair_residual = _numeric_cell(pair_row, "pair_force_residual_norm", float("nan"))
        member_gate = _numeric_cell(pair_row, "member_max_gate_error_ratio", float("nan"))
        a_gate = _numeric_cell(pair_row, "a_gate_error_ratio", float("nan"))
        b_gate = _numeric_cell(pair_row, "b_gate_error_ratio", float("nan"))
        if np.isfinite(pair_residual) and pair_residual <= 1.0 and not b35_invariant:
            conclusion = "cell35_pitch_column_complex_pair_closes"
        elif b35_invariant and np.isfinite(abs(phase_delta)) and abs(phase_delta) > 30.0:
            conclusion = "cell35_pitch_column_complex_blocked_by_phase_and_b35_invariance"
        elif b35_invariant:
            conclusion = "cell35_pitch_column_complex_blocked_by_b35_component_invariance"
        elif np.isfinite(abs(phase_delta)) and abs(phase_delta) > 30.0:
            conclusion = "cell35_pitch_column_complex_blocked_by_phase"
        else:
            conclusion = "cell35_pitch_column_complex_still_open"
        rows.append(
            {
                "benchmark": benchmark,
                "matrix_cell": "35",
                "omega_e_sqrt_l_over_g": omega_bar,
                "paired_coefficients": str(pair_row.get("paired_coefficients", "A35,B35")),
                "a35_gate_error_ratio": a_gate,
                "b35_gate_error_ratio": b_gate,
                "member_max_gate_error_ratio": member_gate,
                "pair_force_residual_norm": pair_residual,
                "pair_status": str(pair_row.get("pair_status", "")),
                "computed_force_phase_deg": numeric_from_scale(
                    scale_row,
                    pair_row,
                    "computed_force_phase_deg",
                ),
                "reference_force_phase_deg": numeric_from_scale(
                    scale_row,
                    pair_row,
                    "reference_force_phase_deg",
                ),
                "reference_minus_computed_phase_deg": phase_delta,
                "required_complex_scale_abs": required_scale_abs,
                "required_complex_scale_phase_deg": required_scale_phase,
                "a_required_scale": numeric_from_scale(scale_row, pair_row, "a_required_scale"),
                "b_required_scale": numeric_from_scale(scale_row, pair_row, "b_required_scale"),
                "a_b_required_scale_ratio": numeric_from_scale(scale_row, pair_row, "a_b_required_scale_ratio"),
                "a_b_required_scale_log10_abs_delta": ab_log_delta,
                "a_b_required_scale_same_sign": bool_cell(scale_row, "a_b_required_scale_same_sign")
                if scale_row is not None
                else False,
                "b35_invariant_component_count": int(len(b35_invariant)),
                "b35_invariant_components": ";".join(b35_invariant),
                "b35_sensitive_component_count": int(len(b35_sensitive)),
                "b35_sensitive_components": ";".join(b35_sensitive),
                "a35_invariant_component_count": int(len(a35_invariant)),
                "a35_invariant_components": ";".join(a35_invariant),
                "a35_sensitive_component_count": int(len(a35_sensitive)),
                "a35_sensitive_components": ";".join(a35_sensitive),
                "diagnostic_conclusion": conclusion,
                "remaining_blocker": (
                    "Derive the pitch-column pressure-gradient/end-contour moment equation with same-frequency "
                    "complex force closure; B35 damping components must gain the missing frequency dependence "
                    "before any B33 endpoint-forward rule can be generalized."
                ),
                "candidate_default_gate_eligible": False,
                "candidate_exclusion_reason": (
                    "Cell-35 evidence is diagnostic-only; no phase or scale correction may enter the default "
                    "provider until the traced pitch-column equation passes Gate 1."
                ),
                "gate_role": "diagnostic_journee_cell35_pitch_column_complex_not_hard_gate",
                "path_diagnostic_status": "INFO",
            }
        )

    detail = pd.DataFrame(rows, columns=detail_columns)
    detail.to_csv(detail_path, index=False)
    pair_residual = pd.to_numeric(detail["pair_force_residual_norm"], errors="coerce")
    member_gate = pd.to_numeric(detail["member_max_gate_error_ratio"], errors="coerce")
    phase_abs = pd.to_numeric(detail["reference_minus_computed_phase_deg"], errors="coerce").abs()
    scale_abs = pd.to_numeric(detail["required_complex_scale_abs"], errors="coerce")
    scale_phase = pd.to_numeric(detail["required_complex_scale_phase_deg"], errors="coerce")
    ab_log_delta = pd.to_numeric(detail["a_b_required_scale_log10_abs_delta"], errors="coerce")
    fail_pair_count = int((~detail["pair_status"].astype(str).eq("PASS")).sum())
    if int(len(b35_invariant)) > 0 and phase_abs.notna().any() and float(phase_abs.max()) > 30.0:
        conclusion = "cell35_pitch_column_complex_blocker_is_phase_and_b35_damping_invariance"
    elif int(len(b35_invariant)) > 0:
        conclusion = "cell35_pitch_column_complex_blocker_is_b35_damping_invariance"
    elif phase_abs.notna().any() and float(phase_abs.max()) > 30.0:
        conclusion = "cell35_pitch_column_complex_blocker_is_phase"
    elif fail_pair_count == 0:
        conclusion = "cell35_pitch_column_complex_pairs_pass_but_need_trace"
    else:
        conclusion = "cell35_pitch_column_complex_blocker_remains_open"
    summary = pd.DataFrame(
        [
            {
                "benchmark": benchmark,
                "pair_count": int(len(detail)),
                "fail_pair_count": fail_pair_count,
                "max_pair_force_residual_norm": (
                    float(pair_residual.max()) if pair_residual.notna().any() else float("nan")
                ),
                "max_member_gate_error_ratio": (
                    float(member_gate.max()) if member_gate.notna().any() else float("nan")
                ),
                "phase_error_abs_min_deg": float(phase_abs.min()) if phase_abs.notna().any() else float("nan"),
                "phase_error_abs_max_deg": float(phase_abs.max()) if phase_abs.notna().any() else float("nan"),
                "required_complex_scale_abs_min": (
                    float(scale_abs.min()) if scale_abs.notna().any() else float("nan")
                ),
                "required_complex_scale_abs_max": (
                    float(scale_abs.max()) if scale_abs.notna().any() else float("nan")
                ),
                "required_complex_scale_phase_min_deg": (
                    float(scale_phase.min()) if scale_phase.notna().any() else float("nan")
                ),
                "required_complex_scale_phase_max_deg": (
                    float(scale_phase.max()) if scale_phase.notna().any() else float("nan")
                ),
                "max_ab_required_scale_log10_abs_delta": (
                    float(ab_log_delta.max()) if ab_log_delta.notna().any() else float("nan")
                ),
                "b35_invariant_component_count": int(len(b35_invariant)),
                "b35_invariant_components": ";".join(b35_invariant),
                "b35_sensitive_component_count": int(len(b35_sensitive)),
                "b35_sensitive_components": ";".join(b35_sensitive),
                "a35_invariant_component_count": int(len(a35_invariant)),
                "a35_invariant_components": ";".join(a35_invariant),
                "a35_sensitive_component_count": int(len(a35_sensitive)),
                "a35_sensitive_components": ";".join(a35_sensitive),
                "diagnostic_conclusion": conclusion,
                "remaining_blocker": (
                    "Implement a traced pitch-column complex closure for A35/B35 rather than extending the "
                    "B33 endpoint-forward proxy.  The audit points to phase convention and B35 damping "
                    "frequency-invariance as the next formula target."
                ),
                "candidate_default_gate_eligible": False,
                "candidate_exclusion_reason": (
                    "The audit forbids promoting per-cell phase, scale, or endpoint candidates to production "
                    "until all Ma 2005 Gate 1 rows close under one equation-level convention."
                ),
                "gate_role": "diagnostic_journee_cell35_pitch_column_complex_not_hard_gate",
                "path_diagnostic_status": "INFO",
            }
        ],
        columns=summary_columns,
    )
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _write_ma2005_journee_cell35_component_complex_audit(
    paired_table_detail: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Decompose Journee cell-35 complex-force error by matched-BIE force component."""

    detail_path = out_dir / f"{benchmark}_journee_cell35_component_complex_audit.csv"
    summary_path = out_dir / f"{benchmark}_journee_cell35_component_complex_summary.csv"
    components = {
        "time_derivative": (
            "matched_time_derivative_component_raw",
            "matched_time_derivative_component_value",
        ),
        "pressure_gradient": (
            "matched_pressure_gradient_component_raw",
            "matched_pressure_gradient_component_value",
        ),
        "stokes_body_forward": (
            "matched_stokes_body_forward_component_raw",
            "matched_stokes_body_forward_component_value",
        ),
        "row_measure_transport": (
            "matched_row_measure_transport_component_raw",
            "matched_row_measure_transport_component_value",
        ),
        "end_term": (
            "matched_end_term_component_raw",
            "matched_end_term_component_value",
        ),
    }
    candidate_terms = {
        "time_derivative": ("time_derivative",),
        "pressure_gradient": ("pressure_gradient",),
        "stokes_body_forward": ("stokes_body_forward",),
        "row_measure_transport": ("row_measure_transport",),
        "end_term": ("end_term",),
        "time_plus_pressure_gradient": ("time_derivative", "pressure_gradient"),
        "pressure_gradient_plus_end": ("pressure_gradient", "end_term"),
        "time_plus_end": ("time_derivative", "end_term"),
        "time_plus_pressure_gradient_plus_end": (
            "time_derivative",
            "pressure_gradient",
            "end_term",
        ),
        "time_plus_pressure_gradient_plus_stokes_plus_end": (
            "time_derivative",
            "pressure_gradient",
            "stokes_body_forward",
            "end_term",
        ),
    }
    detail_columns = [
        "benchmark",
        "matrix_cell",
        "omega_e_sqrt_l_over_g",
        "omega_rad_s",
        "candidate_name",
        "included_components",
        "a35_component_raw",
        "b35_component_raw",
        "component_force_real",
        "component_force_imag",
        "component_force_abs",
        "component_force_phase_deg",
        "reference_force_real",
        "reference_force_imag",
        "reference_force_abs",
        "reference_force_phase_deg",
        "reference_minus_component_phase_deg",
        "component_abs_over_reference_abs",
        "component_force_residual_norm",
        "component_real_over_reference_real",
        "component_imag_over_reference_imag",
        "diagnostic_conclusion",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "gate_role",
        "path_diagnostic_status",
    ]
    summary_columns = [
        "benchmark",
        "candidate_count",
        "frequency_count",
        "best_candidate_by_median_residual",
        "best_median_residual_norm",
        "default_candidate_median_residual_norm",
        "dominant_single_component_by_median_abs_ratio",
        "dominant_single_component_median_abs_ratio",
        "time_derivative_median_phase_abs_deg",
        "pressure_gradient_median_phase_abs_deg",
        "end_term_median_phase_abs_deg",
        "pressure_gradient_plus_end_median_residual_norm",
        "time_plus_pressure_gradient_plus_end_median_residual_norm",
        "diagnostic_conclusion",
        "remaining_blocker",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "gate_role",
        "path_diagnostic_status",
    ]

    def empty_outputs(conclusion: str, status: str = "NOT_EVALUATED") -> tuple[pd.DataFrame, pd.DataFrame]:
        detail = pd.DataFrame(columns=detail_columns)
        summary = pd.DataFrame(
            [
                {
                    "benchmark": benchmark,
                    "candidate_count": 0,
                    "frequency_count": 0,
                    "best_candidate_by_median_residual": "",
                    "best_median_residual_norm": float("nan"),
                    "default_candidate_median_residual_norm": float("nan"),
                    "dominant_single_component_by_median_abs_ratio": "",
                    "dominant_single_component_median_abs_ratio": float("nan"),
                    "time_derivative_median_phase_abs_deg": float("nan"),
                    "pressure_gradient_median_phase_abs_deg": float("nan"),
                    "end_term_median_phase_abs_deg": float("nan"),
                    "pressure_gradient_plus_end_median_residual_norm": float("nan"),
                    "time_plus_pressure_gradient_plus_end_median_residual_norm": float("nan"),
                    "diagnostic_conclusion": conclusion,
                    "remaining_blocker": "Journee paired-table component inputs are missing.",
                    "candidate_default_gate_eligible": False,
                    "candidate_exclusion_reason": "diagnostic input unavailable; no default-route migration allowed.",
                    "gate_role": "diagnostic_journee_cell35_component_complex_not_hard_gate",
                    "path_diagnostic_status": status,
                }
            ],
            columns=summary_columns,
        )
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    required = {"coefficient", "matrix_cell", "omega_e_sqrt_l_over_g", "reference_value"}
    if paired_table_detail.empty or not required.issubset(paired_table_detail.columns):
        return empty_outputs("journee_cell35_component_complex_missing_required_columns")
    table = paired_table_detail.copy()
    table["_coefficient_upper"] = table["coefficient"].astype(str).str.strip().str.upper()
    table["_matrix_cell"] = table["matrix_cell"].astype(str).str.strip()
    table = table[table["_matrix_cell"].eq("35")]
    table = table[table["_coefficient_upper"].isin({"A35", "B35"})]
    if table.empty:
        return empty_outputs("journee_cell35_component_complex_no_cell35_rows")

    def omega_rad_s(row: pd.Series) -> float:
        omega_bar = _numeric_cell(row, "omega_e_sqrt_l_over_g", float("nan"))
        length = _numeric_cell(row, "hull_length_m", _numeric_cell(row, "length_m", float("nan")))
        gravity = _numeric_cell(row, "gravity_m_s2", 9.80665)
        if np.isfinite(omega_bar) and np.isfinite(length) and length > 0.0 and gravity > 0.0:
            return float(omega_bar * np.sqrt(gravity / length))
        return float("nan")

    def phase_deg(value: complex) -> float:
        if not (np.isfinite(value.real) and np.isfinite(value.imag)):
            return float("nan")
        return float(np.degrees(np.angle(value)))

    def wrap_phase_delta(value: float) -> float:
        if not np.isfinite(value):
            return float("nan")
        return float((value + 180.0) % 360.0 - 180.0)

    def raw_value(row: pd.Series, raw_column: str, value_column: str) -> float:
        raw = _numeric_cell(row, raw_column, float("nan"))
        if np.isfinite(raw):
            return raw
        value = _numeric_cell(row, value_column, float("nan"))
        scale = _numeric_cell(row, "normalization_scale", float("nan"))
        if np.isfinite(value) and np.isfinite(scale):
            return float(value * scale)
        return float("nan")

    def reference_raw(row: pd.Series) -> float:
        value = _numeric_cell(row, "reference_value", float("nan"))
        scale = _numeric_cell(row, "normalization_scale", float("nan"))
        if np.isfinite(value) and np.isfinite(scale):
            return float(value * scale)
        return float("nan")

    def force_from_raw(a_raw: float, b_raw: float, omega: float) -> complex:
        if not (np.isfinite(a_raw) and np.isfinite(b_raw) and np.isfinite(omega) and omega > 0.0):
            return complex(float("nan"), float("nan"))
        return complex(a_raw * omega**2, -b_raw * omega)

    def ratio(numerator: float, denominator: float) -> float:
        if np.isfinite(numerator) and np.isfinite(denominator) and abs(denominator) > 1.0e-300:
            return float(numerator / denominator)
        return float("nan")

    rows: list[dict[str, Any]] = []
    for group_key, group in table.groupby(
        ["hull", "speed_case", "motion_test", "omega_e_sqrt_l_over_g"],
        sort=False,
        dropna=False,
    ):
        a_rows = group[group["_coefficient_upper"].eq("A35")]
        b_rows = group[group["_coefficient_upper"].eq("B35")]
        if a_rows.empty or b_rows.empty:
            continue
        a_row = a_rows.iloc[0]
        b_row = b_rows.iloc[0]
        omega = omega_rad_s(a_row)
        reference_force = force_from_raw(reference_raw(a_row), reference_raw(b_row), omega)
        reference_abs = abs(reference_force)
        reference_phase = phase_deg(reference_force)
        component_raws: dict[str, tuple[float, float]] = {}
        for component_name, (raw_column, value_column) in components.items():
            component_raws[component_name] = (
                raw_value(a_row, raw_column, value_column),
                raw_value(b_row, raw_column, value_column),
            )
        for candidate_name, included in candidate_terms.items():
            a_raw = float(sum(component_raws[name][0] for name in included))
            b_raw = float(sum(component_raws[name][1] for name in included))
            component_force = force_from_raw(a_raw, b_raw, omega)
            component_abs = abs(component_force)
            component_phase = phase_deg(component_force)
            phase_delta = wrap_phase_delta(reference_phase - component_phase)
            residual = (
                float(abs(component_force - reference_force) / max(reference_abs, 1.0e-300))
                if np.isfinite(component_force.real)
                and np.isfinite(component_force.imag)
                and np.isfinite(reference_abs)
                else float("nan")
            )
            abs_ratio = ratio(component_abs, reference_abs)
            if np.isfinite(residual) and residual <= 1.0:
                conclusion = "cell35_component_candidate_within_pair_residual_gate"
            elif np.isfinite(abs_ratio) and abs_ratio > 10.0 and np.isfinite(abs(phase_delta)) and abs(phase_delta) > 60.0:
                conclusion = "cell35_component_over_amplified_and_phase_misaligned"
            elif np.isfinite(abs_ratio) and abs_ratio > 10.0:
                conclusion = "cell35_component_over_amplified"
            elif np.isfinite(abs(phase_delta)) and abs(phase_delta) > 60.0:
                conclusion = "cell35_component_phase_misaligned"
            else:
                conclusion = "cell35_component_candidate_still_open"
            rows.append(
                {
                    "benchmark": benchmark,
                    "matrix_cell": "35",
                    "omega_e_sqrt_l_over_g": _numeric_cell(a_row, "omega_e_sqrt_l_over_g", float("nan")),
                    "omega_rad_s": omega,
                    "candidate_name": candidate_name,
                    "included_components": ";".join(included),
                    "a35_component_raw": a_raw,
                    "b35_component_raw": b_raw,
                    "component_force_real": component_force.real,
                    "component_force_imag": component_force.imag,
                    "component_force_abs": float(component_abs),
                    "component_force_phase_deg": component_phase,
                    "reference_force_real": reference_force.real,
                    "reference_force_imag": reference_force.imag,
                    "reference_force_abs": float(reference_abs),
                    "reference_force_phase_deg": reference_phase,
                    "reference_minus_component_phase_deg": phase_delta,
                    "component_abs_over_reference_abs": abs_ratio,
                    "component_force_residual_norm": residual,
                    "component_real_over_reference_real": ratio(component_force.real, reference_force.real),
                    "component_imag_over_reference_imag": ratio(component_force.imag, reference_force.imag),
                    "diagnostic_conclusion": conclusion,
                    "candidate_default_gate_eligible": False,
                    "candidate_exclusion_reason": (
                        "component-level complex-force candidates diagnose the pitch-column equation chain; "
                        "they are not fitted corrections and cannot enter the default provider."
                    ),
                    "gate_role": "diagnostic_journee_cell35_component_complex_not_hard_gate",
                    "path_diagnostic_status": "INFO",
                }
            )

    detail = pd.DataFrame(rows, columns=detail_columns)
    detail.to_csv(detail_path, index=False)
    if detail.empty:
        return empty_outputs("journee_cell35_component_complex_no_same_frequency_pairs")

    grouped = detail.groupby("candidate_name", sort=False)
    residual_median = grouped["component_force_residual_norm"].apply(
        lambda series: float(pd.to_numeric(series, errors="coerce").median())
    )
    abs_ratio_median = grouped["component_abs_over_reference_abs"].apply(
        lambda series: float(pd.to_numeric(series, errors="coerce").median())
    )
    phase_abs_median = grouped["reference_minus_component_phase_deg"].apply(
        lambda series: float(pd.to_numeric(series, errors="coerce").abs().median())
    )
    best_candidate = str(residual_median.idxmin()) if residual_median.notna().any() else ""
    best_median = float(residual_median.min()) if residual_median.notna().any() else float("nan")
    single_names = [name for name, included in candidate_terms.items() if len(included) == 1]
    single_abs = abs_ratio_median.loc[[name for name in single_names if name in abs_ratio_median.index]]
    dominant_single = str(single_abs.idxmax()) if not single_abs.empty and single_abs.notna().any() else ""
    dominant_single_value = float(single_abs.max()) if not single_abs.empty and single_abs.notna().any() else float("nan")
    default_name = "time_plus_pressure_gradient_plus_end"
    pg_end_name = "pressure_gradient_plus_end"
    default_residual = (
        float(residual_median.loc[default_name]) if default_name in residual_median.index else float("nan")
    )
    pg_end_residual = (
        float(residual_median.loc[pg_end_name]) if pg_end_name in residual_median.index else float("nan")
    )
    time_phase = (
        float(phase_abs_median.loc["time_derivative"])
        if "time_derivative" in phase_abs_median.index
        else float("nan")
    )
    gradient_phase = (
        float(phase_abs_median.loc["pressure_gradient"])
        if "pressure_gradient" in phase_abs_median.index
        else float("nan")
    )
    end_phase = float(phase_abs_median.loc["end_term"]) if "end_term" in phase_abs_median.index else float("nan")
    if (
        np.isfinite(time_phase)
        and np.isfinite(gradient_phase)
        and np.isfinite(end_phase)
        and time_phase > 60.0
        and gradient_phase < time_phase
        and end_phase < time_phase
        and dominant_single in {"pressure_gradient", "time_derivative"}
    ):
        conclusion = "cell35_component_complex_time_pressure_misaligned_gradient_end_over_amplified"
    elif np.isfinite(best_median) and best_median <= 1.0:
        conclusion = "cell35_component_complex_has_partial_candidate_but_default_unclosed"
    else:
        conclusion = "cell35_component_complex_no_component_closes_pair"
    summary = pd.DataFrame(
        [
            {
                "benchmark": benchmark,
                "candidate_count": int(detail["candidate_name"].nunique()),
                "frequency_count": int(detail["omega_e_sqrt_l_over_g"].nunique()),
                "best_candidate_by_median_residual": best_candidate,
                "best_median_residual_norm": best_median,
                "default_candidate_median_residual_norm": default_residual,
                "dominant_single_component_by_median_abs_ratio": dominant_single,
                "dominant_single_component_median_abs_ratio": dominant_single_value,
                "time_derivative_median_phase_abs_deg": time_phase,
                "pressure_gradient_median_phase_abs_deg": gradient_phase,
                "end_term_median_phase_abs_deg": end_phase,
                "pressure_gradient_plus_end_median_residual_norm": pg_end_residual,
                "time_plus_pressure_gradient_plus_end_median_residual_norm": default_residual,
                "diagnostic_conclusion": conclusion,
                "remaining_blocker": (
                    "Trace the pitch-column time-pressure phase and the pressure-gradient/end-contour "
                    "amplitude in the same complex force equation.  Component candidates are evidence, not "
                    "default corrections."
                ),
                "candidate_default_gate_eligible": False,
                "candidate_exclusion_reason": (
                    "No component subset may be promoted unless a single traced equation-level convention "
                    "passes the full Ma 2005 eight-coefficient Gate 1."
                ),
                "gate_role": "diagnostic_journee_cell35_component_complex_not_hard_gate",
                "path_diagnostic_status": "INFO",
            }
        ],
        columns=summary_columns,
    )
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _write_ma2005_journee_cell35_time_pressure_phase_candidate_audit(
    component_complex_detail: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Test diagnostic-only time-pressure phase variants for Journee cell 35."""

    detail_path = out_dir / f"{benchmark}_journee_cell35_time_pressure_phase_candidate_detail.csv"
    summary_path = out_dir / f"{benchmark}_journee_cell35_time_pressure_phase_candidate_summary.csv"
    detail_columns = [
        "benchmark",
        "candidate_name",
        "candidate_operation",
        "omega_e_sqrt_l_over_g",
        "omega_rad_s",
        "candidate_force_real",
        "candidate_force_imag",
        "candidate_force_abs",
        "candidate_force_phase_deg",
        "reference_force_real",
        "reference_force_imag",
        "reference_force_abs",
        "reference_force_phase_deg",
        "reference_minus_candidate_phase_deg",
        "candidate_abs_over_reference_abs",
        "candidate_force_residual_norm",
        "candidate_status",
        "current_default_residual_norm",
        "residual_improvement_vs_current",
        "diagnostic_conclusion",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "gate_role",
        "path_diagnostic_status",
    ]
    summary_columns = [
        "benchmark",
        "candidate_name",
        "candidate_operation",
        "row_count",
        "pass_count",
        "fail_count",
        "median_residual_norm",
        "max_residual_norm",
        "median_phase_abs_deg",
        "median_abs_over_reference_abs",
        "median_residual_improvement_vs_current",
        "improved_frequency_count",
        "worsened_frequency_count",
        "best_candidate_by_median_residual",
        "best_candidate_median_residual_norm",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "diagnostic_conclusion",
        "gate_role",
        "path_diagnostic_status",
    ]

    def empty_outputs(conclusion: str, status: str = "NOT_EVALUATED") -> tuple[pd.DataFrame, pd.DataFrame]:
        detail = pd.DataFrame(columns=detail_columns)
        summary = pd.DataFrame(columns=summary_columns)
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        if status != "EMPTY":
            summary = pd.DataFrame(
                [
                    {
                        "benchmark": benchmark,
                        "candidate_name": "",
                        "candidate_operation": "",
                        "row_count": 0,
                        "pass_count": 0,
                        "fail_count": 0,
                        "median_residual_norm": float("nan"),
                        "max_residual_norm": float("nan"),
                        "median_phase_abs_deg": float("nan"),
                        "median_abs_over_reference_abs": float("nan"),
                        "median_residual_improvement_vs_current": float("nan"),
                        "improved_frequency_count": 0,
                        "worsened_frequency_count": 0,
                        "best_candidate_by_median_residual": "",
                        "best_candidate_median_residual_norm": float("nan"),
                        "candidate_default_gate_eligible": False,
                        "candidate_exclusion_reason": "diagnostic input unavailable; no default-route migration allowed.",
                        "diagnostic_conclusion": conclusion,
                        "gate_role": "diagnostic_journee_cell35_time_pressure_phase_candidate_not_hard_gate",
                        "path_diagnostic_status": status,
                    }
                ],
                columns=summary_columns,
            )
            summary.to_csv(summary_path, index=False)
        return detail, summary

    required = {
        "omega_e_sqrt_l_over_g",
        "candidate_name",
        "component_force_real",
        "component_force_imag",
        "reference_force_real",
        "reference_force_imag",
    }
    if component_complex_detail.empty or not required.issubset(component_complex_detail.columns):
        return empty_outputs("journee_cell35_time_pressure_phase_missing_required_columns")

    def phase_deg(value: complex) -> float:
        if not (np.isfinite(value.real) and np.isfinite(value.imag)):
            return float("nan")
        return float(np.degrees(np.angle(value)))

    def wrap_phase_delta(value: float) -> float:
        if not np.isfinite(value):
            return float("nan")
        return float((value + 180.0) % 360.0 - 180.0)

    def get_force(group: pd.DataFrame, name: str) -> complex:
        rows = group[group["candidate_name"].astype(str).eq(name)]
        if rows.empty:
            return complex(float("nan"), float("nan"))
        row = rows.iloc[0]
        return complex(
            _numeric_cell(row, "component_force_real", float("nan")),
            _numeric_cell(row, "component_force_imag", float("nan")),
        )

    specs = (
        (
            "current_time_plus_gradient_plus_end",
            "Current Eq.30/Eq.32 component composition: time + pressure-gradient + end-contour.",
            lambda time, gradient, end: time + gradient + end,
        ),
        (
            "time_pressure_sign_flipped_plus_gradient_end",
            "Flip only the time-pressure force component, then add pressure-gradient and end-contour.",
            lambda time, gradient, end: -time + gradient + end,
        ),
        (
            "time_pressure_phase_plus_90_plus_gradient_end",
            "Rotate only the time-pressure force component by +90 degrees, then add pressure-gradient and end-contour.",
            lambda time, gradient, end: 1j * time + gradient + end,
        ),
        (
            "time_pressure_phase_minus_90_plus_gradient_end",
            "Rotate only the time-pressure force component by -90 degrees, then add pressure-gradient and end-contour.",
            lambda time, gradient, end: -1j * time + gradient + end,
        ),
        (
            "time_pressure_omitted_gradient_end",
            "Omit time-pressure and retain pressure-gradient plus end-contour.",
            lambda time, gradient, end: gradient + end,
        ),
    )
    rows: list[dict[str, Any]] = []
    for omega_bar, group in component_complex_detail.groupby("omega_e_sqrt_l_over_g", sort=True):
        time = get_force(group, "time_derivative")
        gradient = get_force(group, "pressure_gradient")
        end = get_force(group, "end_term")
        first = group.iloc[0]
        reference = complex(
            _numeric_cell(first, "reference_force_real", float("nan")),
            _numeric_cell(first, "reference_force_imag", float("nan")),
        )
        reference_abs = abs(reference)
        reference_phase = phase_deg(reference)
        current = time + gradient + end
        current_residual = (
            float(abs(current - reference) / max(reference_abs, 1.0e-300))
            if np.isfinite(current.real)
            and np.isfinite(current.imag)
            and np.isfinite(reference_abs)
            else float("nan")
        )
        for candidate_name, operation, build in specs:
            candidate = complex(build(time, gradient, end))
            candidate_abs = abs(candidate)
            candidate_phase = phase_deg(candidate)
            phase_delta = wrap_phase_delta(reference_phase - candidate_phase)
            residual = (
                float(abs(candidate - reference) / max(reference_abs, 1.0e-300))
                if np.isfinite(candidate.real)
                and np.isfinite(candidate.imag)
                and np.isfinite(reference_abs)
                else float("nan")
            )
            improvement = (
                float(current_residual - residual)
                if np.isfinite(current_residual) and np.isfinite(residual)
                else float("nan")
            )
            if np.isfinite(residual) and residual <= 1.0:
                status = "PASS"
            else:
                status = "FAIL"
            if candidate_name == "current_time_plus_gradient_plus_end":
                conclusion = "current_time_pressure_phase_baseline"
            elif status == "PASS" and np.isfinite(improvement) and improvement > 0.0:
                conclusion = "time_pressure_phase_candidate_partially_closes_cell35"
            elif np.isfinite(improvement) and improvement > 0.0:
                conclusion = "time_pressure_phase_candidate_improves_without_closure"
            else:
                conclusion = "time_pressure_phase_candidate_worsens_or_not_decisive"
            rows.append(
                {
                    "benchmark": benchmark,
                    "candidate_name": candidate_name,
                    "candidate_operation": operation,
                    "omega_e_sqrt_l_over_g": _numeric_cell(first, "omega_e_sqrt_l_over_g", float(omega_bar)),
                    "omega_rad_s": _numeric_cell(first, "omega_rad_s", float("nan")),
                    "candidate_force_real": candidate.real,
                    "candidate_force_imag": candidate.imag,
                    "candidate_force_abs": float(candidate_abs),
                    "candidate_force_phase_deg": candidate_phase,
                    "reference_force_real": reference.real,
                    "reference_force_imag": reference.imag,
                    "reference_force_abs": float(reference_abs),
                    "reference_force_phase_deg": reference_phase,
                    "reference_minus_candidate_phase_deg": phase_delta,
                    "candidate_abs_over_reference_abs": (
                        float(candidate_abs / reference_abs)
                        if np.isfinite(reference_abs) and reference_abs > 1.0e-300
                        else float("nan")
                    ),
                    "candidate_force_residual_norm": residual,
                    "candidate_status": status,
                    "current_default_residual_norm": current_residual,
                    "residual_improvement_vs_current": improvement,
                    "diagnostic_conclusion": conclusion,
                    "candidate_default_gate_eligible": False,
                    "candidate_exclusion_reason": (
                        "Time-pressure phase variants are diagnostic-only.  A sign or phase operation cannot "
                        "enter matched_bie_station_sweep unless it is derived from the pressure convention and "
                        "passes the complete Ma 2005 Gate 1."
                    ),
                    "gate_role": "diagnostic_journee_cell35_time_pressure_phase_candidate_not_hard_gate",
                    "path_diagnostic_status": "INFO",
                }
            )

    detail = pd.DataFrame(rows, columns=detail_columns)
    detail.to_csv(detail_path, index=False)
    if detail.empty:
        return empty_outputs("journee_cell35_time_pressure_phase_no_rows", status="EMPTY")

    residual_by_candidate = (
        detail.groupby("candidate_name")["candidate_force_residual_norm"]
        .apply(lambda series: float(pd.to_numeric(series, errors="coerce").median()))
        .sort_values()
    )
    best_candidate = str(residual_by_candidate.index[0]) if not residual_by_candidate.empty else ""
    best_median = float(residual_by_candidate.iloc[0]) if not residual_by_candidate.empty else float("nan")
    summary_rows: list[dict[str, Any]] = []
    for candidate_name, group in detail.groupby("candidate_name", sort=False):
        residual = pd.to_numeric(group["candidate_force_residual_norm"], errors="coerce")
        phase_abs = pd.to_numeric(group["reference_minus_candidate_phase_deg"], errors="coerce").abs()
        abs_ratio = pd.to_numeric(group["candidate_abs_over_reference_abs"], errors="coerce")
        improvement = pd.to_numeric(group["residual_improvement_vs_current"], errors="coerce")
        pass_count = int(group["candidate_status"].astype(str).eq("PASS").sum())
        fail_count = int(group["candidate_status"].astype(str).eq("FAIL").sum())
        improved_count = int(improvement.gt(0.0).sum())
        worsened_count = int(improvement.lt(0.0).sum())
        if candidate_name == best_candidate and pass_count == len(group):
            conclusion = "time_pressure_phase_candidate_closes_cell35_but_needs_full_gate_trace"
        elif candidate_name == best_candidate:
            conclusion = "time_pressure_phase_candidate_best_but_still_unclosed"
        elif improved_count > 0:
            conclusion = "time_pressure_phase_candidate_improves_subset_only"
        else:
            conclusion = "time_pressure_phase_candidate_excluded"
        summary_rows.append(
            {
                "benchmark": benchmark,
                "candidate_name": candidate_name,
                "candidate_operation": str(group["candidate_operation"].iloc[0]),
                "row_count": int(len(group)),
                "pass_count": pass_count,
                "fail_count": fail_count,
                "median_residual_norm": float(residual.median()) if residual.notna().any() else float("nan"),
                "max_residual_norm": float(residual.max()) if residual.notna().any() else float("nan"),
                "median_phase_abs_deg": float(phase_abs.median()) if phase_abs.notna().any() else float("nan"),
                "median_abs_over_reference_abs": float(abs_ratio.median()) if abs_ratio.notna().any() else float("nan"),
                "median_residual_improvement_vs_current": (
                    float(improvement.median()) if improvement.notna().any() else float("nan")
                ),
                "improved_frequency_count": improved_count,
                "worsened_frequency_count": worsened_count,
                "best_candidate_by_median_residual": best_candidate,
                "best_candidate_median_residual_norm": best_median,
                "candidate_default_gate_eligible": False,
                "candidate_exclusion_reason": (
                    "Diagnostic-only phase convention candidate; not eligible for default migration without "
                    "full eight-coefficient Gate 1 closure and a traced pressure-time convention."
                ),
                "diagnostic_conclusion": conclusion,
                "gate_role": "diagnostic_journee_cell35_time_pressure_phase_candidate_not_hard_gate",
                "path_diagnostic_status": "INFO",
            }
        )
    summary = pd.DataFrame(summary_rows, columns=summary_columns).sort_values(
        ["median_residual_norm", "candidate_name"],
        na_position="last",
    )
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _write_ma2005_time_pressure_harmonic_convention_trace_audit(
    comparison: pd.DataFrame,
    pressure_sign_candidate_detail: pd.DataFrame,
    pressure_sign_candidate_summary: pd.DataFrame,
    cell35_phase_candidate_summary: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Trace current time-pressure sign convention against local and full Gate evidence."""

    detail_path = out_dir / f"{benchmark}_time_pressure_harmonic_convention_trace_audit.csv"
    summary_path = out_dir / f"{benchmark}_time_pressure_harmonic_convention_trace_summary.csv"
    detail_columns = [
        "benchmark",
        "coefficient",
        "current_pressure_formula",
        "current_time_harmonic_convention",
        "alternative_pressure_formula",
        "alternative_time_harmonic_convention",
        "matched_selected_pressure_time_formula_ratio_median",
        "current_gate_error_ratio",
        "time_derivative_flipped_gate_error_ratio",
        "time_derivative_flipped_gate_delta_vs_current",
        "time_derivative_flipped_status",
        "time_derivative_flipped_improves",
        "time_derivative_flipped_worsens",
        "diagnostic_conclusion",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "gate_role",
        "path_diagnostic_status",
    ]
    summary_columns = [
        "benchmark",
        "coefficient_count",
        "formula_ratio_min",
        "formula_ratio_max",
        "formula_ratio_all_current",
        "sign_flip_pass_count",
        "sign_flip_fail_count",
        "sign_flip_improved_count",
        "sign_flip_worsened_count",
        "sign_flip_median_gate_error_ratio",
        "sign_flip_max_gate_error_ratio",
        "cell35_best_candidate",
        "cell35_best_pass_count",
        "cell35_best_row_count",
        "cell35_best_median_residual_norm",
        "current_pressure_formula",
        "current_time_harmonic_convention",
        "alternative_pressure_formula",
        "alternative_time_harmonic_convention",
        "diagnostic_conclusion",
        "remaining_blocker",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "gate_role",
        "path_diagnostic_status",
    ]

    def empty_outputs(conclusion: str, status: str = "NOT_EVALUATED") -> tuple[pd.DataFrame, pd.DataFrame]:
        detail = pd.DataFrame(columns=detail_columns)
        summary = pd.DataFrame(
            [
                {
                    "benchmark": benchmark,
                    "coefficient_count": 0,
                    "formula_ratio_min": float("nan"),
                    "formula_ratio_max": float("nan"),
                    "formula_ratio_all_current": False,
                    "sign_flip_pass_count": 0,
                    "sign_flip_fail_count": 0,
                    "sign_flip_improved_count": 0,
                    "sign_flip_worsened_count": 0,
                    "sign_flip_median_gate_error_ratio": float("nan"),
                    "sign_flip_max_gate_error_ratio": float("nan"),
                    "cell35_best_candidate": "",
                    "cell35_best_pass_count": 0,
                    "cell35_best_row_count": 0,
                    "cell35_best_median_residual_norm": float("nan"),
                    "current_pressure_formula": "p_time = -rho*i*omega*phi",
                    "current_time_harmonic_convention": "phi_hat exp(+i omega t)",
                    "alternative_pressure_formula": "p_time = +rho*i*omega*phi",
                    "alternative_time_harmonic_convention": "phi_hat exp(-i omega t)",
                    "diagnostic_conclusion": conclusion,
                    "remaining_blocker": "Required comparison or pressure-sign candidate input is missing.",
                    "candidate_default_gate_eligible": False,
                    "candidate_exclusion_reason": "diagnostic input unavailable; no default-route migration allowed.",
                    "gate_role": "diagnostic_time_pressure_harmonic_convention_trace_not_hard_gate",
                    "path_diagnostic_status": status,
                }
            ],
            columns=summary_columns,
        )
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    if comparison.empty or pressure_sign_candidate_detail.empty:
        return empty_outputs("time_pressure_harmonic_convention_trace_missing_inputs")

    if "coefficient" not in comparison.columns or "coefficient" not in pressure_sign_candidate_detail.columns:
        return empty_outputs("time_pressure_harmonic_convention_trace_missing_required_columns")

    flip_detail = pressure_sign_candidate_detail[
        pressure_sign_candidate_detail["candidate_name"]
        .astype(str)
        .eq("time_derivative_flipped_keep_gradient_end")
    ].copy()
    if flip_detail.empty:
        return empty_outputs("time_pressure_harmonic_convention_trace_missing_sign_flip_candidate")
    flip_by_coeff = {str(row["coefficient"]).strip().upper(): row for _, row in flip_detail.iterrows()}

    rows: list[dict[str, Any]] = []
    for _, row in comparison.iterrows():
        coefficient = str(row.get("coefficient", "")).strip().upper()
        if coefficient not in {"A33", "B33", "A35", "B35", "A53", "B53", "A55", "B55"}:
            continue
        flip = flip_by_coeff.get(coefficient)
        current_gate = _numeric_cell(row, "gate_error_ratio", float("nan"))
        flip_gate = _numeric_cell(flip, "gate_error_ratio", float("nan")) if flip is not None else float("nan")
        delta = (
            float(flip_gate - current_gate)
            if np.isfinite(flip_gate) and np.isfinite(current_gate)
            else float("nan")
        )
        improves = bool(np.isfinite(delta) and delta < 0.0)
        worsens = bool(np.isfinite(delta) and delta > 0.0)
        flip_status = str(flip.get("status", "")) if flip is not None else ""
        formula_ratio = _numeric_cell(row, "matched_selected_pressure_time_formula_ratio_median", float("nan"))
        if flip_status == "PASS":
            conclusion = "alternative_time_harmonic_sign_closes_this_coefficient"
        elif improves:
            conclusion = "alternative_time_harmonic_sign_improves_without_gate_closure"
        elif worsens:
            conclusion = "alternative_time_harmonic_sign_worsens_this_coefficient"
        else:
            conclusion = "alternative_time_harmonic_sign_not_decisive"
        rows.append(
            {
                "benchmark": benchmark,
                "coefficient": coefficient,
                "current_pressure_formula": "p_time = -rho*i*omega*phi",
                "current_time_harmonic_convention": "phi_hat exp(+i omega t)",
                "alternative_pressure_formula": "p_time = +rho*i*omega*phi",
                "alternative_time_harmonic_convention": "phi_hat exp(-i omega t)",
                "matched_selected_pressure_time_formula_ratio_median": formula_ratio,
                "current_gate_error_ratio": current_gate,
                "time_derivative_flipped_gate_error_ratio": flip_gate,
                "time_derivative_flipped_gate_delta_vs_current": delta,
                "time_derivative_flipped_status": flip_status,
                "time_derivative_flipped_improves": improves,
                "time_derivative_flipped_worsens": worsens,
                "diagnostic_conclusion": conclusion,
                "candidate_default_gate_eligible": False,
                "candidate_exclusion_reason": (
                    "This row-level trace compares harmonic sign conventions only.  The alternative sign cannot "
                    "enter the default provider unless it is derived from the governing convention and passes all "
                    "eight Ma 2005 Gate 1 rows."
                ),
                "gate_role": "diagnostic_time_pressure_harmonic_convention_trace_not_hard_gate",
                "path_diagnostic_status": "INFO",
            }
        )

    detail = pd.DataFrame(rows, columns=detail_columns)
    detail.to_csv(detail_path, index=False)
    if detail.empty:
        return empty_outputs("time_pressure_harmonic_convention_trace_no_target_rows")

    ratios = pd.to_numeric(detail["matched_selected_pressure_time_formula_ratio_median"], errors="coerce")
    flip_gates = pd.to_numeric(detail["time_derivative_flipped_gate_error_ratio"], errors="coerce")
    improves = detail["time_derivative_flipped_improves"].astype(bool)
    worsens = detail["time_derivative_flipped_worsens"].astype(bool)
    flip_pass = detail["time_derivative_flipped_status"].astype(str).eq("PASS")
    cell35_best = pd.Series(dtype=object)
    if not cell35_phase_candidate_summary.empty and "candidate_name" in cell35_phase_candidate_summary.columns:
        cell35_best = cell35_phase_candidate_summary.iloc[0]
    cell35_best_name = str(cell35_best.get("candidate_name", "")) if not cell35_best.empty else ""
    cell35_best_pass = int(_numeric_cell(cell35_best, "pass_count", 0.0)) if not cell35_best.empty else 0
    cell35_best_rows = int(_numeric_cell(cell35_best, "row_count", 0.0)) if not cell35_best.empty else 0
    cell35_best_median = (
        _numeric_cell(cell35_best, "median_residual_norm", float("nan")) if not cell35_best.empty else float("nan")
    )
    formula_all_current = bool(ratios.notna().all() and np.allclose(ratios.to_numpy(dtype=float), 1.0))
    if flip_pass.all() and len(detail) > 0:
        conclusion = "alternative_time_harmonic_sign_closes_full_gate_but_requires_trace"
    elif cell35_best_name == "time_pressure_sign_flipped_plus_gradient_end" and not flip_pass.any():
        conclusion = "time_pressure_sign_flip_is_cell35_clue_but_not_global_convention"
    elif int(improves.sum()) > int(worsens.sum()):
        conclusion = "time_pressure_sign_flip_improves_more_rows_but_not_gate"
    else:
        conclusion = "time_pressure_harmonic_convention_trace_excludes_simple_sign_flip"
    summary = pd.DataFrame(
        [
            {
                "benchmark": benchmark,
                "coefficient_count": int(len(detail)),
                "formula_ratio_min": float(ratios.min()) if ratios.notna().any() else float("nan"),
                "formula_ratio_max": float(ratios.max()) if ratios.notna().any() else float("nan"),
                "formula_ratio_all_current": formula_all_current,
                "sign_flip_pass_count": int(flip_pass.sum()),
                "sign_flip_fail_count": int((~flip_pass).sum()),
                "sign_flip_improved_count": int(improves.sum()),
                "sign_flip_worsened_count": int(worsens.sum()),
                "sign_flip_median_gate_error_ratio": (
                    float(flip_gates.median()) if flip_gates.notna().any() else float("nan")
                ),
                "sign_flip_max_gate_error_ratio": (
                    float(flip_gates.max()) if flip_gates.notna().any() else float("nan")
                ),
                "cell35_best_candidate": cell35_best_name,
                "cell35_best_pass_count": cell35_best_pass,
                "cell35_best_row_count": cell35_best_rows,
                "cell35_best_median_residual_norm": cell35_best_median,
                "current_pressure_formula": "p_time = -rho*i*omega*phi",
                "current_time_harmonic_convention": "phi_hat exp(+i omega t)",
                "alternative_pressure_formula": "p_time = +rho*i*omega*phi",
                "alternative_time_harmonic_convention": "phi_hat exp(-i omega t)",
                "diagnostic_conclusion": conclusion,
                "remaining_blocker": (
                    "The code-level pressure formula is internally consistent, but the alternative sign only "
                    "acts as a local cell-35 clue.  A default change still needs a traced harmonic convention, "
                    "pressure-gradient/end-contour amplitude closure, and full eight-coefficient Gate 1 pass."
                ),
                "candidate_default_gate_eligible": False,
                "candidate_exclusion_reason": (
                    "The sign flip is not globally valid under the current Gate 1 evidence; it remains a "
                    "diagnostic target for formula tracing."
                ),
                "gate_role": "diagnostic_time_pressure_harmonic_convention_trace_not_hard_gate",
                "path_diagnostic_status": "INFO",
            }
        ],
        columns=summary_columns,
    )
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _write_ma2005_journee_coefficient_frequency_trend_audit(
    paired_table_detail: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Audit same-coefficient frequency trends in the Journee paired table probe."""

    detail_path = out_dir / f"{benchmark}_journee_coefficient_frequency_trend_audit.csv"
    summary_path = out_dir / f"{benchmark}_journee_coefficient_frequency_trend_summary.csv"
    detail_columns = [
        "benchmark",
        "coefficient",
        "matrix_cell",
        "row_count",
        "unique_frequency_count",
        "frequency_min",
        "frequency_max",
        "reference_min",
        "reference_max",
        "computed_min",
        "computed_max",
        "reference_frequency_sensitivity_ratio",
        "computed_frequency_sensitivity_ratio",
        "computed_to_reference_sensitivity_ratio",
        "required_scale_min",
        "required_scale_max",
        "required_scale_max_over_min_abs",
        "required_scale_sign_change",
        "pass_count",
        "fail_count",
        "max_gate_error_ratio",
        "median_gate_error_ratio",
        "computed_values_invariant",
        "reference_values_variant",
        "diagnostic_conclusion",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "gate_role",
        "path_diagnostic_status",
    ]
    summary_columns = [
        "benchmark",
        "coefficient_count",
        "multi_frequency_coefficient_count",
        "frequency_invariant_computed_count",
        "required_scale_varying_count",
        "max_gate_error_ratio",
        "median_gate_error_ratio",
        "max_reference_frequency_sensitivity_ratio",
        "max_computed_frequency_sensitivity_ratio",
        "max_required_scale_max_over_min_abs",
        "affected_coefficients",
        "diagnostic_conclusion",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "gate_role",
        "path_diagnostic_status",
    ]
    if paired_table_detail.empty or "coefficient" not in paired_table_detail.columns:
        detail = pd.DataFrame(columns=detail_columns)
        summary = pd.DataFrame(
            [
                {
                    "benchmark": benchmark,
                    "coefficient_count": 0,
                    "multi_frequency_coefficient_count": 0,
                    "frequency_invariant_computed_count": 0,
                    "required_scale_varying_count": 0,
                    "max_gate_error_ratio": float("nan"),
                    "median_gate_error_ratio": float("nan"),
                    "max_reference_frequency_sensitivity_ratio": float("nan"),
                    "max_computed_frequency_sensitivity_ratio": float("nan"),
                    "max_required_scale_max_over_min_abs": float("nan"),
                    "affected_coefficients": "",
                    "diagnostic_conclusion": "journee_coefficient_frequency_trend_no_rows",
                    "candidate_default_gate_eligible": False,
                    "candidate_exclusion_reason": "diagnostic input unavailable",
                    "gate_role": "diagnostic_journee_coefficient_frequency_trend_not_hard_gate",
                    "path_diagnostic_status": "NOT_EVALUATED",
                }
            ],
            columns=summary_columns,
        )
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    def values(frame: pd.DataFrame, column: str) -> np.ndarray:
        if column not in frame:
            return np.full(len(frame), np.nan, dtype=float)
        return pd.to_numeric(frame[column], errors="coerce").to_numpy(dtype=float)

    def sensitivity_ratio(series: np.ndarray) -> float:
        finite = series[np.isfinite(series)]
        if finite.size < 2:
            return float("nan")
        denom = max(float(np.max(np.abs(finite))), 1.0e-300)
        return float((np.max(finite) - np.min(finite)) / denom)

    def finite_min(series: np.ndarray) -> float:
        finite = series[np.isfinite(series)]
        return float(np.min(finite)) if finite.size else float("nan")

    def finite_max(series: np.ndarray) -> float:
        finite = series[np.isfinite(series)]
        return float(np.max(finite)) if finite.size else float("nan")

    rows: list[dict[str, Any]] = []
    table = paired_table_detail.copy()
    table["_coefficient_upper"] = table["coefficient"].astype(str).str.strip().str.upper()
    for coefficient, group in table.groupby("_coefficient_upper", sort=True):
        omega = values(group, "omega_e_sqrt_l_over_g")
        reference = values(group, "reference_value")
        computed = values(group, "computed_value")
        gate = values(group, "gate_error_ratio")
        with np.errstate(divide="ignore", invalid="ignore"):
            required_scale = np.where(np.abs(computed) > 1.0e-300, reference / computed, np.nan)
        reference_sensitivity = sensitivity_ratio(reference)
        computed_sensitivity = sensitivity_ratio(computed)
        sensitivity_quotient = (
            float(computed_sensitivity / reference_sensitivity)
            if np.isfinite(computed_sensitivity) and np.isfinite(reference_sensitivity) and reference_sensitivity > 1e-300
            else float("nan")
        )
        scale_abs = np.abs(required_scale[np.isfinite(required_scale)])
        scale_spread = (
            float(np.max(scale_abs) / max(np.min(scale_abs), 1.0e-300))
            if scale_abs.size
            else float("nan")
        )
        scale_signs = np.sign(required_scale[np.isfinite(required_scale)])
        scale_sign_change = bool(np.any(scale_signs > 0.0) and np.any(scale_signs < 0.0))
        computed_invariant = bool(
            np.isfinite(reference_sensitivity)
            and reference_sensitivity > 0.05
            and np.isfinite(computed_sensitivity)
            and computed_sensitivity <= 1e-8
        )
        reference_variant = bool(np.isfinite(reference_sensitivity) and reference_sensitivity > 0.05)
        pass_count = int(group["status"].astype(str).eq("PASS").sum()) if "status" in group.columns else 0
        fail_count = int(group["status"].astype(str).eq("FAIL").sum()) if "status" in group.columns else int(len(group))
        if pass_count == len(group) and len(group) > 0:
            conclusion = "journee_frequency_trend_passes"
        elif computed_invariant:
            conclusion = "computed_frequency_invariant_despite_reference_variation"
        elif scale_sign_change or (np.isfinite(scale_spread) and scale_spread > 2.0):
            conclusion = "required_scale_varies_with_frequency"
        elif np.isfinite(sensitivity_quotient) and (sensitivity_quotient < 0.5 or sensitivity_quotient > 2.0):
            conclusion = "computed_frequency_sensitivity_mismatch"
        else:
            conclusion = "journee_frequency_trend_fails_gate_requires_equation_trace"
        rows.append(
            {
                "benchmark": benchmark,
                "coefficient": str(coefficient),
                "matrix_cell": str(coefficient[1:] if len(coefficient) == 3 else coefficient),
                "row_count": int(len(group)),
                "unique_frequency_count": int(pd.Series(omega[np.isfinite(omega)]).nunique()),
                "frequency_min": finite_min(omega),
                "frequency_max": finite_max(omega),
                "reference_min": finite_min(reference),
                "reference_max": finite_max(reference),
                "computed_min": finite_min(computed),
                "computed_max": finite_max(computed),
                "reference_frequency_sensitivity_ratio": reference_sensitivity,
                "computed_frequency_sensitivity_ratio": computed_sensitivity,
                "computed_to_reference_sensitivity_ratio": sensitivity_quotient,
                "required_scale_min": finite_min(required_scale),
                "required_scale_max": finite_max(required_scale),
                "required_scale_max_over_min_abs": scale_spread,
                "required_scale_sign_change": scale_sign_change,
                "pass_count": pass_count,
                "fail_count": fail_count,
                "max_gate_error_ratio": float(np.nanmax(gate)) if np.isfinite(gate).any() else float("nan"),
                "median_gate_error_ratio": float(np.nanmedian(gate)) if np.isfinite(gate).any() else float("nan"),
                "computed_values_invariant": computed_invariant,
                "reference_values_variant": reference_variant,
                "diagnostic_conclusion": conclusion,
                "candidate_default_gate_eligible": False,
                "candidate_exclusion_reason": (
                    "frequency-trend diagnostics cannot enter the default provider as a fitted correction; "
                    "they only identify missing frequency dependence for equation-level repair."
                ),
                "gate_role": "diagnostic_journee_coefficient_frequency_trend_not_hard_gate",
                "path_diagnostic_status": "INFO",
            }
        )
    detail = pd.DataFrame(rows, columns=detail_columns)
    detail.to_csv(detail_path, index=False)
    if detail.empty:
        summary = pd.DataFrame(columns=summary_columns)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    gate = pd.to_numeric(detail["max_gate_error_ratio"], errors="coerce")
    median_gate = pd.to_numeric(detail["median_gate_error_ratio"], errors="coerce")
    ref_sens = pd.to_numeric(detail["reference_frequency_sensitivity_ratio"], errors="coerce")
    comp_sens = pd.to_numeric(detail["computed_frequency_sensitivity_ratio"], errors="coerce")
    scale_spread = pd.to_numeric(detail["required_scale_max_over_min_abs"], errors="coerce")
    invariant = detail["computed_values_invariant"].astype(bool)
    scale_varying = (
        detail["required_scale_sign_change"].astype(bool)
        | scale_spread.gt(2.0).fillna(False)
    )
    affected = detail[
        invariant
        | detail["diagnostic_conclusion"].astype(str).isin(
            {"required_scale_varies_with_frequency", "computed_frequency_sensitivity_mismatch"}
        )
    ]["coefficient"].astype(str)
    if bool(invariant.any()):
        conclusion = "journee_frequency_trend_contains_invariant_computed_rows"
    elif bool(scale_varying.any()):
        conclusion = "journee_frequency_trend_requires_pair_specific_scales"
    elif detail["fail_count"].astype(int).sum() == 0:
        conclusion = "journee_frequency_trend_all_rows_pass"
    else:
        conclusion = "journee_frequency_trend_fails_without_single_cause"
    summary = pd.DataFrame(
        [
            {
                "benchmark": benchmark,
                "coefficient_count": int(len(detail)),
                "multi_frequency_coefficient_count": int(detail["unique_frequency_count"].astype(int).ge(2).sum()),
                "frequency_invariant_computed_count": int(invariant.sum()),
                "required_scale_varying_count": int(scale_varying.sum()),
                "max_gate_error_ratio": float(gate.max()) if gate.notna().any() else float("nan"),
                "median_gate_error_ratio": float(median_gate.median()) if median_gate.notna().any() else float("nan"),
                "max_reference_frequency_sensitivity_ratio": (
                    float(ref_sens.max()) if ref_sens.notna().any() else float("nan")
                ),
                "max_computed_frequency_sensitivity_ratio": (
                    float(comp_sens.max()) if comp_sens.notna().any() else float("nan")
                ),
                "max_required_scale_max_over_min_abs": (
                    float(scale_spread.max()) if scale_spread.notna().any() else float("nan")
                ),
                "affected_coefficients": ",".join(affected.tolist()),
                "diagnostic_conclusion": conclusion,
                "candidate_default_gate_eligible": False,
                "candidate_exclusion_reason": (
                    "This audit identifies missing or inconsistent frequency dependence but does not apply "
                    "frequency-wise fitted corrections."
                ),
                "gate_role": "diagnostic_journee_coefficient_frequency_trend_not_hard_gate",
                "path_diagnostic_status": "INFO",
            }
        ],
        columns=summary_columns,
    )
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _write_ma2005_journee_component_frequency_trend_audit(
    paired_table_detail: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Audit frequency sensitivity of matched-BIE force components for Journee rows.

    The coefficient-level trend audit tells us whether the total computed value
    varies with frequency.  This component audit localizes that behavior to the
    A1 Eq. (30) time-pressure, Eq. (30) pressure-gradient, Eq. (32) Stokes-body,
    and Eq. (32) end-contour channels.  It is diagnostic-only and never applies
    a frequency-wise correction.
    """

    detail_path = out_dir / f"{benchmark}_journee_component_frequency_trend_audit.csv"
    summary_path = out_dir / f"{benchmark}_journee_component_frequency_trend_summary.csv"
    component_columns = {
        "time_derivative": "matched_time_derivative_component_value",
        "pressure_gradient": "matched_pressure_gradient_component_value",
        "stokes_body_forward": "matched_stokes_body_forward_component_value",
        "end_term": "matched_end_term_component_value",
    }
    detail_columns = [
        "benchmark",
        "coefficient",
        "matrix_cell",
        "component_name",
        "component_column",
        "row_count",
        "unique_frequency_count",
        "frequency_min",
        "frequency_max",
        "reference_frequency_sensitivity_ratio",
        "computed_frequency_sensitivity_ratio",
        "component_frequency_sensitivity_ratio",
        "component_to_reference_sensitivity_ratio",
        "component_abs_median",
        "component_abs_max",
        "component_values_invariant",
        "component_values_variant",
        "computed_values_invariant",
        "reference_values_variant",
        "component_missing",
        "diagnostic_conclusion",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "gate_role",
        "path_diagnostic_status",
    ]
    summary_columns = [
        "benchmark",
        "component_row_count",
        "coefficient_count",
        "frequency_invariant_component_count",
        "frequency_sensitive_component_count",
        "missing_component_count",
        "computed_frequency_invariant_count",
        "max_reference_frequency_sensitivity_ratio",
        "max_computed_frequency_sensitivity_ratio",
        "max_component_frequency_sensitivity_ratio",
        "affected_components",
        "diagnostic_conclusion",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "gate_role",
        "path_diagnostic_status",
    ]

    def empty_outputs(conclusion: str, status: str = "NOT_EVALUATED") -> tuple[pd.DataFrame, pd.DataFrame]:
        detail = pd.DataFrame(columns=detail_columns)
        summary = pd.DataFrame(
            [
                {
                    "benchmark": benchmark,
                    "component_row_count": 0,
                    "coefficient_count": 0,
                    "frequency_invariant_component_count": 0,
                    "frequency_sensitive_component_count": 0,
                    "missing_component_count": 0,
                    "computed_frequency_invariant_count": 0,
                    "max_reference_frequency_sensitivity_ratio": float("nan"),
                    "max_computed_frequency_sensitivity_ratio": float("nan"),
                    "max_component_frequency_sensitivity_ratio": float("nan"),
                    "affected_components": "",
                    "diagnostic_conclusion": conclusion,
                    "candidate_default_gate_eligible": False,
                    "candidate_exclusion_reason": "diagnostic input unavailable",
                    "gate_role": "diagnostic_journee_component_frequency_trend_not_hard_gate",
                    "path_diagnostic_status": status,
                }
            ],
            columns=summary_columns,
        )
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    if paired_table_detail.empty or "coefficient" not in paired_table_detail.columns:
        return empty_outputs("journee_component_frequency_trend_no_rows")
    if not {"omega_e_sqrt_l_over_g", "reference_value", "computed_value"}.issubset(paired_table_detail.columns):
        return empty_outputs("journee_component_frequency_trend_missing_required_columns")

    def values(frame: pd.DataFrame, column: str) -> np.ndarray:
        return pd.to_numeric(frame.get(column, pd.Series(dtype=float)), errors="coerce").to_numpy(dtype=float)

    def sensitivity_ratio(series: np.ndarray) -> float:
        finite = series[np.isfinite(series)]
        if finite.size < 2:
            return float("nan")
        denom = max(float(np.max(np.abs(finite))), 1.0e-300)
        return float((np.max(finite) - np.min(finite)) / denom)

    def finite_min(series: np.ndarray) -> float:
        finite = series[np.isfinite(series)]
        return float(np.min(finite)) if finite.size else float("nan")

    def finite_max(series: np.ndarray) -> float:
        finite = series[np.isfinite(series)]
        return float(np.max(finite)) if finite.size else float("nan")

    rows: list[dict[str, Any]] = []
    table = paired_table_detail.copy()
    table["_coefficient_upper"] = table["coefficient"].astype(str).str.strip().str.upper()
    for coefficient, group in table.groupby("_coefficient_upper", sort=True):
        omega = values(group, "omega_e_sqrt_l_over_g")
        reference = values(group, "reference_value")
        computed = values(group, "computed_value")
        reference_sensitivity = sensitivity_ratio(reference)
        computed_sensitivity = sensitivity_ratio(computed)
        reference_variant = bool(np.isfinite(reference_sensitivity) and reference_sensitivity > 0.05)
        computed_invariant = bool(
            reference_variant
            and np.isfinite(computed_sensitivity)
            and computed_sensitivity <= 1.0e-8
        )
        for component_name, column in component_columns.items():
            component = values(group, column)
            finite_component = component[np.isfinite(component)]
            missing = bool(finite_component.size < 2)
            component_sensitivity = sensitivity_ratio(component)
            component_invariant = bool(
                reference_variant
                and not missing
                and np.isfinite(component_sensitivity)
                and component_sensitivity <= 1.0e-8
            )
            component_variant = bool(np.isfinite(component_sensitivity) and component_sensitivity > 0.05)
            sensitivity_quotient = (
                float(component_sensitivity / reference_sensitivity)
                if np.isfinite(component_sensitivity)
                and np.isfinite(reference_sensitivity)
                and reference_sensitivity > 1.0e-300
                else float("nan")
            )
            if missing:
                conclusion = "component_frequency_trend_missing_values"
            elif component_invariant:
                conclusion = "component_frequency_invariant_despite_reference_variation"
            elif np.isfinite(sensitivity_quotient) and sensitivity_quotient < 0.5:
                conclusion = "component_frequency_sensitivity_too_weak"
            elif np.isfinite(sensitivity_quotient) and sensitivity_quotient > 2.0:
                conclusion = "component_frequency_sensitivity_too_strong"
            elif component_variant:
                conclusion = "component_frequency_sensitive_but_gate_chain_still_open"
            else:
                conclusion = "component_frequency_trend_not_decisive"
            rows.append(
                {
                    "benchmark": benchmark,
                    "coefficient": str(coefficient),
                    "matrix_cell": str(coefficient[1:] if len(coefficient) == 3 else coefficient),
                    "component_name": component_name,
                    "component_column": column,
                    "row_count": int(len(group)),
                    "unique_frequency_count": int(pd.Series(omega[np.isfinite(omega)]).nunique()),
                    "frequency_min": finite_min(omega),
                    "frequency_max": finite_max(omega),
                    "reference_frequency_sensitivity_ratio": reference_sensitivity,
                    "computed_frequency_sensitivity_ratio": computed_sensitivity,
                    "component_frequency_sensitivity_ratio": component_sensitivity,
                    "component_to_reference_sensitivity_ratio": sensitivity_quotient,
                    "component_abs_median": (
                        float(np.median(np.abs(finite_component))) if finite_component.size else float("nan")
                    ),
                    "component_abs_max": (
                        float(np.max(np.abs(finite_component))) if finite_component.size else float("nan")
                    ),
                    "component_values_invariant": component_invariant,
                    "component_values_variant": component_variant,
                    "computed_values_invariant": computed_invariant,
                    "reference_values_variant": reference_variant,
                    "component_missing": missing,
                    "diagnostic_conclusion": conclusion,
                    "candidate_default_gate_eligible": False,
                    "candidate_exclusion_reason": (
                        "component frequency trends localize the missing physics but do not apply fitted "
                        "frequency-wise corrections."
                    ),
                    "gate_role": "diagnostic_journee_component_frequency_trend_not_hard_gate",
                    "path_diagnostic_status": "INFO",
                }
            )

    detail = pd.DataFrame(rows, columns=detail_columns)
    detail.to_csv(detail_path, index=False)
    if detail.empty:
        summary = pd.DataFrame(columns=summary_columns)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    ref_sens = pd.to_numeric(detail["reference_frequency_sensitivity_ratio"], errors="coerce")
    comp_sens = pd.to_numeric(detail["computed_frequency_sensitivity_ratio"], errors="coerce")
    component_sens = pd.to_numeric(detail["component_frequency_sensitivity_ratio"], errors="coerce")
    invariant = detail["component_values_invariant"].astype(bool)
    sensitive = detail["component_values_variant"].astype(bool)
    missing = detail["component_missing"].astype(bool)
    computed_invariant = detail["computed_values_invariant"].astype(bool)
    affected = detail[invariant | detail["diagnostic_conclusion"].astype(str).str.contains("too_", regex=False)]
    affected_components = ";".join(
        f"{row.coefficient}:{row.component_name}" for row in affected.itertuples(index=False)
    )
    if bool(invariant.any()):
        conclusion = "journee_component_frequency_trend_contains_invariant_components"
    elif bool(missing.any()):
        conclusion = "journee_component_frequency_trend_has_missing_component_values"
    elif bool(sensitive.any()):
        conclusion = "journee_component_frequency_trend_components_are_frequency_sensitive_but_gate_open"
    else:
        conclusion = "journee_component_frequency_trend_not_decisive"
    summary = pd.DataFrame(
        [
            {
                "benchmark": benchmark,
                "component_row_count": int(len(detail)),
                "coefficient_count": int(detail["coefficient"].nunique()),
                "frequency_invariant_component_count": int(invariant.sum()),
                "frequency_sensitive_component_count": int(sensitive.sum()),
                "missing_component_count": int(missing.sum()),
                "computed_frequency_invariant_count": int(
                    detail.loc[computed_invariant, "coefficient"].nunique()
                ),
                "max_reference_frequency_sensitivity_ratio": (
                    float(ref_sens.max()) if ref_sens.notna().any() else float("nan")
                ),
                "max_computed_frequency_sensitivity_ratio": (
                    float(comp_sens.max()) if comp_sens.notna().any() else float("nan")
                ),
                "max_component_frequency_sensitivity_ratio": (
                    float(component_sens.max()) if component_sens.notna().any() else float("nan")
                ),
                "affected_components": affected_components,
                "diagnostic_conclusion": conclusion,
                "candidate_default_gate_eligible": False,
                "candidate_exclusion_reason": (
                    "This audit only identifies which force components lack or over-amplify frequency sensitivity."
                ),
                "gate_role": "diagnostic_journee_component_frequency_trend_not_hard_gate",
                "path_diagnostic_status": "INFO",
            }
        ],
        columns=summary_columns,
    )
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _write_ma2005_body_potential_frequency_entry_audit(
    paired_table_detail: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Audit where frequency enters the matched-BIE body-potential chain.

    Same-coefficient Journee rows expose whether the current station sweep is
    doing more than kinematic scaling.  If the body normal-velocity condition
    and the solved body potential have nearly the same frequency sensitivity
    while the nondimensional coefficient remains invariant, the missing piece is
    downstream of the boundary-condition magnitude: free-surface/history
    filtering, local-time transfer, or normalization rather than the final
    A/B coefficient conversion.
    """

    detail_path = out_dir / f"{benchmark}_body_potential_frequency_entry_audit.csv"
    summary_path = out_dir / f"{benchmark}_body_potential_frequency_entry_summary.csv"
    detail_columns = [
        "benchmark",
        "coefficient",
        "matrix_cell",
        "radiation_mode",
        "row_count",
        "unique_frequency_count",
        "frequency_min",
        "frequency_max",
        "frequency_span_ratio",
        "reference_frequency_sensitivity_ratio",
        "computed_frequency_sensitivity_ratio",
        "body_condition_frequency_sensitivity_ratio",
        "body_potential_frequency_sensitivity_ratio",
        "time_pressure_norm_frequency_sensitivity_ratio",
        "forward_pressure_norm_frequency_sensitivity_ratio",
        "body_potential_to_condition_sensitivity_ratio",
        "time_pressure_to_potential_frequency_gain_median",
        "forward_pressure_to_potential_gradient_proxy_median",
        "computed_values_invariant",
        "reference_values_variant",
        "body_potential_tracks_body_condition",
        "body_potential_frequency_filter_missing",
        "diagnostic_conclusion",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "gate_role",
        "path_diagnostic_status",
    ]
    summary_columns = [
        "benchmark",
        "coefficient_count",
        "row_count",
        "tracked_body_condition_count",
        "body_potential_filter_missing_count",
        "computed_frequency_invariant_count",
        "max_reference_frequency_sensitivity_ratio",
        "max_computed_frequency_sensitivity_ratio",
        "max_body_condition_frequency_sensitivity_ratio",
        "max_body_potential_frequency_sensitivity_ratio",
        "affected_coefficients",
        "diagnostic_conclusion",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "gate_role",
        "path_diagnostic_status",
    ]

    def empty_outputs(conclusion: str, status: str = "NOT_EVALUATED") -> tuple[pd.DataFrame, pd.DataFrame]:
        detail = pd.DataFrame(columns=detail_columns)
        summary = pd.DataFrame(
            [
                {
                    "benchmark": benchmark,
                    "coefficient_count": 0,
                    "row_count": 0,
                    "tracked_body_condition_count": 0,
                    "body_potential_filter_missing_count": 0,
                    "computed_frequency_invariant_count": 0,
                    "max_reference_frequency_sensitivity_ratio": float("nan"),
                    "max_computed_frequency_sensitivity_ratio": float("nan"),
                    "max_body_condition_frequency_sensitivity_ratio": float("nan"),
                    "max_body_potential_frequency_sensitivity_ratio": float("nan"),
                    "affected_coefficients": "",
                    "diagnostic_conclusion": conclusion,
                    "candidate_default_gate_eligible": False,
                    "candidate_exclusion_reason": "diagnostic input unavailable",
                    "gate_role": "diagnostic_body_potential_frequency_entry_not_hard_gate",
                    "path_diagnostic_status": status,
                }
            ],
            columns=summary_columns,
        )
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    required = {"coefficient", "omega_e_sqrt_l_over_g", "reference_value", "computed_value"}
    if paired_table_detail.empty or not required.issubset(paired_table_detail.columns):
        return empty_outputs("body_potential_frequency_entry_missing_required_columns")

    def values(frame: pd.DataFrame, column: str) -> np.ndarray:
        return pd.to_numeric(frame.get(column, pd.Series(dtype=float)), errors="coerce").to_numpy(dtype=float)

    def sensitivity_ratio(series: np.ndarray) -> float:
        finite = series[np.isfinite(series)]
        if finite.size < 2:
            return float("nan")
        denom = max(float(np.max(np.abs(finite))), 1.0e-300)
        return float((np.max(finite) - np.min(finite)) / denom)

    def finite_min(series: np.ndarray) -> float:
        finite = series[np.isfinite(series)]
        return float(np.min(finite)) if finite.size else float("nan")

    def finite_max(series: np.ndarray) -> float:
        finite = series[np.isfinite(series)]
        return float(np.max(finite)) if finite.size else float("nan")

    def finite_median(series: np.ndarray) -> float:
        finite = series[np.isfinite(series)]
        return float(np.median(finite)) if finite.size else float("nan")

    def finite_ratio(numerator: np.ndarray, denominator: np.ndarray) -> np.ndarray:
        num = np.asarray(numerator, dtype=float)
        den = np.asarray(denominator, dtype=float)
        out = np.full(num.shape, np.nan, dtype=float)
        mask = np.isfinite(num) & np.isfinite(den) & (np.abs(den) > 1.0e-300)
        out[mask] = num[mask] / den[mask]
        return out

    rows: list[dict[str, Any]] = []
    table = paired_table_detail.copy()
    table["_coefficient_upper"] = table["coefficient"].astype(str).str.strip().str.upper()
    for coefficient, group in table.groupby("_coefficient_upper", sort=True):
        if len(coefficient) == 3 and coefficient[-1] == "3":
            mode = "heave"
        elif len(coefficient) == 3 and coefficient[-1] == "5":
            mode = "pitch"
        else:
            mode = "unknown"
        condition_col = f"matched_{mode}_body_normal_velocity_norm_max"
        potential_col = f"matched_{mode}_body_potential_norm_max"
        time_pressure_col = f"matched_{mode}_body_pressure_time_derivative_norm_max"
        forward_pressure_col = f"matched_{mode}_body_pressure_forward_speed_norm_max"
        omega = values(group, "omega_e_sqrt_l_over_g")
        reference = values(group, "reference_value")
        computed = values(group, "computed_value")
        condition = values(group, condition_col)
        potential = values(group, potential_col)
        time_pressure = values(group, time_pressure_col)
        forward_pressure = values(group, forward_pressure_col)
        frequency_min = finite_min(omega)
        frequency_max = finite_max(omega)
        frequency_span = (
            float(frequency_max / frequency_min)
            if np.isfinite(frequency_min) and abs(frequency_min) > 1.0e-300
            else float("nan")
        )
        ref_sens = sensitivity_ratio(reference)
        comp_sens = sensitivity_ratio(computed)
        condition_sens = sensitivity_ratio(condition)
        potential_sens = sensitivity_ratio(potential)
        time_sens = sensitivity_ratio(time_pressure)
        forward_sens = sensitivity_ratio(forward_pressure)
        potential_condition_ratio = (
            float(potential_sens / condition_sens)
            if np.isfinite(potential_sens) and np.isfinite(condition_sens) and condition_sens > 1.0e-300
            else float("nan")
        )
        reference_variant = bool(np.isfinite(ref_sens) and ref_sens > 0.05)
        computed_invariant = bool(reference_variant and np.isfinite(comp_sens) and comp_sens <= 1.0e-8)
        tracks_condition = bool(
            np.isfinite(potential_condition_ratio)
            and 0.5 <= potential_condition_ratio <= 2.0
            and np.isfinite(condition_sens)
            and condition_sens > 0.05
        )
        filter_missing = bool(computed_invariant and tracks_condition)
        if mode == "unknown":
            conclusion = "body_potential_frequency_entry_unknown_radiation_mode"
        elif not np.isfinite(potential_sens):
            conclusion = "body_potential_frequency_entry_missing_values"
        elif filter_missing:
            conclusion = "body_potential_tracks_kinematic_boundary_condition_only"
        elif reference_variant and np.isfinite(potential_sens) and potential_sens <= 1.0e-8:
            conclusion = "body_potential_frequency_invariant_after_body_condition"
        elif reference_variant and np.isfinite(potential_condition_ratio) and potential_condition_ratio < 0.5:
            conclusion = "body_potential_frequency_sensitivity_too_weak"
        elif reference_variant and np.isfinite(potential_condition_ratio) and potential_condition_ratio > 2.0:
            conclusion = "body_potential_frequency_sensitivity_too_strong"
        elif reference_variant:
            conclusion = "body_potential_frequency_sensitivity_present_but_gate_open"
        else:
            conclusion = "body_potential_frequency_entry_not_decisive"
        rows.append(
            {
                "benchmark": benchmark,
                "coefficient": coefficient,
                "matrix_cell": str(coefficient[1:] if len(coefficient) == 3 else coefficient),
                "radiation_mode": mode,
                "row_count": int(len(group)),
                "unique_frequency_count": int(pd.Series(omega[np.isfinite(omega)]).nunique()),
                "frequency_min": frequency_min,
                "frequency_max": frequency_max,
                "frequency_span_ratio": frequency_span,
                "reference_frequency_sensitivity_ratio": ref_sens,
                "computed_frequency_sensitivity_ratio": comp_sens,
                "body_condition_frequency_sensitivity_ratio": condition_sens,
                "body_potential_frequency_sensitivity_ratio": potential_sens,
                "time_pressure_norm_frequency_sensitivity_ratio": time_sens,
                "forward_pressure_norm_frequency_sensitivity_ratio": forward_sens,
                "body_potential_to_condition_sensitivity_ratio": potential_condition_ratio,
                "time_pressure_to_potential_frequency_gain_median": finite_median(
                    finite_ratio(time_pressure, potential * np.maximum(omega, 1.0e-300))
                ),
                "forward_pressure_to_potential_gradient_proxy_median": finite_median(
                    finite_ratio(forward_pressure, potential)
                ),
                "computed_values_invariant": computed_invariant,
                "reference_values_variant": reference_variant,
                "body_potential_tracks_body_condition": tracks_condition,
                "body_potential_frequency_filter_missing": filter_missing,
                "diagnostic_conclusion": conclusion,
                "candidate_default_gate_eligible": False,
                "candidate_exclusion_reason": (
                    "This audit diagnoses the frequency-entry chain only; it does not apply a fitted "
                    "frequency-dependent correction to the default provider."
                ),
                "gate_role": "diagnostic_body_potential_frequency_entry_not_hard_gate",
                "path_diagnostic_status": "INFO",
            }
        )

    detail = pd.DataFrame(rows, columns=detail_columns)
    detail.to_csv(detail_path, index=False)
    if detail.empty:
        summary = pd.DataFrame(columns=summary_columns)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    tracked = detail["body_potential_tracks_body_condition"].astype(bool)
    missing = detail["body_potential_frequency_filter_missing"].astype(bool)
    computed_invariant = detail["computed_values_invariant"].astype(bool)
    ref_sens = pd.to_numeric(detail["reference_frequency_sensitivity_ratio"], errors="coerce")
    comp_sens = pd.to_numeric(detail["computed_frequency_sensitivity_ratio"], errors="coerce")
    condition_sens = pd.to_numeric(detail["body_condition_frequency_sensitivity_ratio"], errors="coerce")
    potential_sens = pd.to_numeric(detail["body_potential_frequency_sensitivity_ratio"], errors="coerce")
    affected = detail[missing | detail["diagnostic_conclusion"].astype(str).str.contains("too_", regex=False)][
        "coefficient"
    ].astype(str)
    if bool(missing.any()):
        conclusion = "body_potential_frequency_entry_tracks_kinematic_condition_only"
    elif detail["diagnostic_conclusion"].astype(str).eq("body_potential_frequency_entry_missing_values").any():
        conclusion = "body_potential_frequency_entry_has_missing_values"
    elif bool(tracked.any()):
        conclusion = "body_potential_frequency_entry_contains_kinematic_tracking_rows"
    else:
        conclusion = "body_potential_frequency_entry_not_decisive"
    summary = pd.DataFrame(
        [
            {
                "benchmark": benchmark,
                "coefficient_count": int(detail["coefficient"].nunique()),
                "row_count": int(len(detail)),
                "tracked_body_condition_count": int(tracked.sum()),
                "body_potential_filter_missing_count": int(missing.sum()),
                "computed_frequency_invariant_count": int(
                    detail.loc[computed_invariant, "coefficient"].nunique()
                ),
                "max_reference_frequency_sensitivity_ratio": (
                    float(ref_sens.max()) if ref_sens.notna().any() else float("nan")
                ),
                "max_computed_frequency_sensitivity_ratio": (
                    float(comp_sens.max()) if comp_sens.notna().any() else float("nan")
                ),
                "max_body_condition_frequency_sensitivity_ratio": (
                    float(condition_sens.max()) if condition_sens.notna().any() else float("nan")
                ),
                "max_body_potential_frequency_sensitivity_ratio": (
                    float(potential_sens.max()) if potential_sens.notna().any() else float("nan")
                ),
                "affected_coefficients": ",".join(affected.tolist()),
                "diagnostic_conclusion": conclusion,
                "candidate_default_gate_eligible": False,
                "candidate_exclusion_reason": (
                    "The default provider still needs a traced equation-level repair; this audit only narrows "
                    "whether frequency dependence is lost before or after the solved body potential."
                ),
                "gate_role": "diagnostic_body_potential_frequency_entry_not_hard_gate",
                "path_diagnostic_status": "INFO",
            }
        ],
        columns=summary_columns,
    )
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _write_ma2005_local_time_phase_frequency_sensitivity_audit(
    comparison: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
    hydro_model: str = MA2005_MATCHED_BIE_MODEL,
    bem_free_surface_panel_count_per_side: int = 4,
    bem_body_panel_count: int | None = None,
    reference_path: Path | None = None,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Audit whether local-time phase handling gives the matched chain frequency dependence.

    The default matched sweep historically produced nearly frequency-invariant
    nondimensional coefficients for same-cell Journee rows. This diagnostic
    compares the default path with two local-time phase candidates. It is a
    guardrail for the A33/A53 time-pressure chain and never promotes a candidate
    into the default provider.
    """

    detail_path = out_dir / f"{benchmark}_local_time_phase_frequency_sensitivity_audit.csv"
    summary_path = out_dir / f"{benchmark}_local_time_phase_frequency_sensitivity_summary.csv"
    reference_path = (
        Path(reference_path)
        if reference_path is not None
        else Path("benchmarks") / "ma2005" / "journee1992_wigley_iii_forced_coefficients.csv"
    )
    if not reference_path.is_absolute():
        reference_path = Path.cwd() / reference_path

    detail_columns = [
        "benchmark",
        "variant",
        "probe_row",
        "source_row",
        "hull",
        "speed_case",
        "motion_test",
        "coefficient",
        "omega_e_sqrt_l_over_g",
        "reference_value",
        "computed_value",
        "raw_computed_value",
        "gate_error_ratio",
        "status",
        "provider_route",
        "force_assembly_route",
        "provider_formulation",
        "solver_status",
        "matched_apply_local_time_phase",
        "matched_local_time_phase_gradient_correction",
        "candidate_default_gate_eligible",
        "gate_role",
        "path_diagnostic_status",
    ]
    summary_columns = [
        "benchmark",
        "variant",
        "coefficient",
        "row_count",
        "unique_frequency_count",
        "pass_count",
        "fail_count",
        "reference_frequency_sensitivity_ratio",
        "computed_frequency_sensitivity_ratio",
        "max_gate_error_ratio",
        "median_gate_error_ratio",
        "diagnostic_conclusion",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "gate_role",
        "path_diagnostic_status",
        "source_reference",
    ]

    def empty_outputs(reason: str) -> tuple[pd.DataFrame, pd.DataFrame]:
        detail = pd.DataFrame(columns=detail_columns)
        summary = pd.DataFrame(
            [
                {
                    "benchmark": benchmark,
                    "variant": "",
                    "coefficient": "",
                    "row_count": 0,
                    "unique_frequency_count": 0,
                    "pass_count": 0,
                    "fail_count": 0,
                    "reference_frequency_sensitivity_ratio": float("nan"),
                    "computed_frequency_sensitivity_ratio": float("nan"),
                    "max_gate_error_ratio": float("nan"),
                    "median_gate_error_ratio": float("nan"),
                    "diagnostic_conclusion": reason,
                    "candidate_default_gate_eligible": False,
                    "candidate_exclusion_reason": "diagnostic input unavailable",
                    "gate_role": "local_time_phase_frequency_sensitivity_not_hard_gate",
                    "path_diagnostic_status": "NOT_EVALUATED",
                    "source_reference": str(reference_path),
                }
            ],
            columns=summary_columns,
        )
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    if comparison.empty or not reference_path.exists():
        return empty_outputs("local_time_phase_frequency_sensitivity_reference_not_available")

    table = pd.read_csv(reference_path)
    required = {"coefficient", "omega_e_sqrt_l_over_g", "reference_value"}
    if not required.issubset(comparison.columns) or not required.issubset(table.columns):
        return empty_outputs("local_time_phase_frequency_sensitivity_missing_required_columns")

    template_by_coefficient = {
        str(row["coefficient"]).strip().upper(): row
        for _, row in comparison.iterrows()
        if "coefficient" in row
    }
    fallback_template = comparison.iloc[0]
    table = table.copy()
    table["_coefficient_upper"] = table["coefficient"].astype(str).str.strip().str.upper()
    table["_omega_numeric"] = pd.to_numeric(table["omega_e_sqrt_l_over_g"], errors="coerce")
    table = table[table["_coefficient_upper"].isin({"A33", "A35", "A53", "A55"})]
    table = table[table["_omega_numeric"].notna()].reset_index(drop=True)
    if table.empty:
        return empty_outputs("local_time_phase_frequency_sensitivity_no_supported_rows")

    variants: tuple[tuple[str, bool, bool], ...] = (
        ("default_no_local_time_phase", False, False),
        ("local_time_phase_only", True, False),
        ("local_time_phase_with_gradient_correction", True, True),
    )
    rows: list[dict[str, Any]] = []
    caches: dict[str, dict[tuple[float | int | str, ...], object]] = {variant[0]: {} for variant in variants}
    for _, ref_row in table.iterrows():
        coeff = str(ref_row["_coefficient_upper"])
        template = template_by_coefficient.get(coeff, fallback_template).copy()
        template["coefficient"] = coeff
        template["omega_e_sqrt_l_over_g"] = float(ref_row["_omega_numeric"])
        template["reference_value"] = float(ref_row["reference_value"])
        for variant_name, apply_phase, gradient_correction in variants:
            probe = template.copy()
            probe["matched_apply_local_time_phase"] = bool(apply_phase)
            probe["matched_local_time_phase_gradient_correction"] = bool(gradient_correction)
            try:
                calc = _ma2005_computed_coefficient(
                    probe,
                    hydro_model=hydro_model,
                    bem_free_surface_panel_count_per_side=bem_free_surface_panel_count_per_side,
                    bem_body_panel_count=bem_body_panel_count,
                    matrix_cache=caches[variant_name],
                    benchmark_base_dir=reference_path.parent,
                )
                _, row_idx, col_idx = _coefficient_matrix_indices(coeff)
                tolerance = 0.15 if row_idx == col_idx else 0.30
                metrics = _ma2005_error_metrics(
                    float(probe["reference_value"]),
                    float(calc["computed_value"]),
                    tolerance,
                    row_idx,
                    col_idx,
                    str(calc.get("normalization", "ma2005")),
                )
                rows.append(
                    {
                        "benchmark": benchmark,
                        "variant": variant_name,
                        "probe_row": int(len(rows)),
                        "source_row": int(ref_row.name),
                        "hull": str(ref_row.get("hull", probe.get("hull", ""))),
                        "speed_case": str(ref_row.get("speed_case", probe.get("speed_case", ""))),
                        "motion_test": str(ref_row.get("motion_test", "")),
                        "coefficient": coeff,
                        "omega_e_sqrt_l_over_g": float(probe["omega_e_sqrt_l_over_g"]),
                        "reference_value": float(probe["reference_value"]),
                        "computed_value": float(calc["computed_value"]),
                        "raw_computed_value": float(calc.get("raw_value", float("nan"))),
                        "gate_error_ratio": float(metrics["gate_error_ratio"]),
                        "status": str(metrics["status"]),
                        "provider_route": calc.get("provider_route", ""),
                        "provider_formulation": calc.get("provider_formulation", ""),
                        "solver_status": calc.get("solver_status", ""),
                        "matched_apply_local_time_phase": bool(apply_phase),
                        "matched_local_time_phase_gradient_correction": bool(gradient_correction),
                        "candidate_default_gate_eligible": False,
                        "gate_role": "local_time_phase_frequency_sensitivity_not_hard_gate",
                        "path_diagnostic_status": "INFO",
                    }
                )
            except Exception as exc:
                rows.append(
                    {
                        "benchmark": benchmark,
                        "variant": variant_name,
                        "probe_row": int(len(rows)),
                        "source_row": int(ref_row.name),
                        "hull": str(ref_row.get("hull", probe.get("hull", ""))),
                        "speed_case": str(ref_row.get("speed_case", probe.get("speed_case", ""))),
                        "motion_test": str(ref_row.get("motion_test", "")),
                        "coefficient": coeff,
                        "omega_e_sqrt_l_over_g": float(probe["omega_e_sqrt_l_over_g"]),
                        "reference_value": float(probe["reference_value"]),
                        "computed_value": float("nan"),
                        "raw_computed_value": float("nan"),
                        "gate_error_ratio": float("nan"),
                        "status": "FAIL",
                        "provider_route": "",
                        "provider_formulation": "",
                        "solver_status": str(exc),
                        "matched_apply_local_time_phase": bool(apply_phase),
                        "matched_local_time_phase_gradient_correction": bool(gradient_correction),
                        "candidate_default_gate_eligible": False,
                        "gate_role": "local_time_phase_frequency_sensitivity_not_hard_gate",
                        "path_diagnostic_status": "INFO",
                    }
                )
    detail = pd.DataFrame(rows, columns=detail_columns)

    def sensitivity_ratio(values: pd.Series) -> float:
        arr = pd.to_numeric(values, errors="coerce").dropna().to_numpy(dtype=float)
        if arr.size < 2:
            return float("nan")
        return float((np.max(arr) - np.min(arr)) / max(float(np.max(np.abs(arr))), 1.0e-12))

    summary_rows: list[dict[str, Any]] = []
    for (variant_name, coefficient), group in detail.groupby(["variant", "coefficient"], sort=False):
        gate = pd.to_numeric(group["gate_error_ratio"], errors="coerce")
        ref_sensitivity = sensitivity_ratio(group["reference_value"])
        computed_sensitivity = sensitivity_ratio(group["computed_value"])
        pass_count = int(group["status"].astype(str).eq("PASS").sum())
        fail_count = int(group["status"].astype(str).eq("FAIL").sum())
        if pass_count == len(group) and len(group) > 0:
            conclusion = "local_time_phase_frequency_sensitivity_variant_passes_rows"
            exclusion = ""
        elif (
            str(variant_name) == "default_no_local_time_phase"
            and np.isfinite(ref_sensitivity)
            and ref_sensitivity > 1.0e-3
            and np.isfinite(computed_sensitivity)
            and computed_sensitivity <= 1.0e-10
        ):
            conclusion = "default_frequency_invariant_despite_reference_variation"
            exclusion = "default path lacks sufficient same-cell frequency sensitivity in this probe"
        elif np.isfinite(computed_sensitivity) and computed_sensitivity > 1.0e-10:
            conclusion = "candidate_is_frequency_sensitive_but_gate_still_fails"
            exclusion = "diagnostic-only; frequency sensitivity alone does not close Gate 1"
        else:
            conclusion = "candidate_not_frequency_sensitive_and_gate_fails"
            exclusion = "diagnostic-only; neither frequency sensitivity nor Gate 1 closure is achieved"
        summary_rows.append(
            {
                "benchmark": benchmark,
                "variant": str(variant_name),
                "coefficient": str(coefficient),
                "row_count": int(len(group)),
                "unique_frequency_count": int(group["omega_e_sqrt_l_over_g"].nunique()),
                "pass_count": pass_count,
                "fail_count": fail_count,
                "reference_frequency_sensitivity_ratio": ref_sensitivity,
                "computed_frequency_sensitivity_ratio": computed_sensitivity,
                "max_gate_error_ratio": float(gate.max()) if gate.notna().any() else float("nan"),
                "median_gate_error_ratio": float(gate.median()) if gate.notna().any() else float("nan"),
                "diagnostic_conclusion": conclusion,
                "candidate_default_gate_eligible": False,
                "candidate_exclusion_reason": exclusion,
                "gate_role": "local_time_phase_frequency_sensitivity_not_hard_gate",
                "path_diagnostic_status": "INFO",
                "source_reference": str(reference_path),
            }
        )
    summary = pd.DataFrame(summary_rows, columns=summary_columns)
    detail.to_csv(detail_path, index=False)
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _write_ma2005_local_time_phase_component_audit(
    comparison: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
    hydro_model: str = MA2005_MATCHED_BIE_MODEL,
    bem_free_surface_panel_count_per_side: int = 4,
    bem_body_panel_count: int | None = None,
    reference_path: Path | None = None,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Audit how local-time phase candidates change Eq.30/Eq.32 force components.

    This is the component-level companion to the frequency-sensitivity audit.
    It keeps the same diagnostic candidates but records the time-derivative,
    pressure-gradient, Stokes-body, and end-contour contributions so the
    A33/A53 pressure-chain blocker can be traced to a specific term.
    """

    detail_path = out_dir / f"{benchmark}_local_time_phase_component_audit.csv"
    summary_path = out_dir / f"{benchmark}_local_time_phase_component_summary.csv"
    reference_path = (
        Path(reference_path)
        if reference_path is not None
        else Path("benchmarks") / "ma2005" / "journee1992_wigley_iii_forced_coefficients.csv"
    )
    if not reference_path.is_absolute():
        reference_path = Path.cwd() / reference_path

    component_names = ("time_derivative", "pressure_gradient", "stokes_body_forward", "end_term")
    detail_columns = [
        "benchmark",
        "variant",
        "probe_row",
        "source_row",
        "hull",
        "speed_case",
        "motion_test",
        "coefficient",
        "omega_e_sqrt_l_over_g",
        "reference_value",
        "computed_value",
        "raw_computed_value",
        "normalization_scale",
        "gate_error_ratio",
        "status",
        "dominant_component",
        "dominant_component_value",
        "dominant_component_abs_fraction",
        "time_derivative_component_value",
        "pressure_gradient_component_value",
        "stokes_body_forward_component_value",
        "end_term_component_value",
        "time_derivative_component_raw",
        "pressure_gradient_component_raw",
        "stokes_body_forward_component_raw",
        "end_term_component_raw",
        "time_derivative_raw_to_reference_raw_ratio",
        "pressure_gradient_raw_to_reference_raw_ratio",
        "stokes_body_forward_raw_to_reference_raw_ratio",
        "end_term_raw_to_reference_raw_ratio",
        "time_derivative_delta_vs_default",
        "pressure_gradient_delta_vs_default",
        "stokes_body_forward_delta_vs_default",
        "end_term_delta_vs_default",
        "total_delta_vs_default",
        "matched_apply_local_time_phase",
        "matched_local_time_phase_gradient_correction",
        "provider_route",
        "provider_formulation",
        "solver_status",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "gate_role",
        "path_diagnostic_status",
    ]
    summary_columns = [
        "benchmark",
        "variant",
        "coefficient",
        "row_count",
        "unique_frequency_count",
        "pass_count",
        "fail_count",
        "max_gate_error_ratio",
        "median_gate_error_ratio",
        "dominant_component_counts",
        "median_time_derivative_component_value",
        "median_pressure_gradient_component_value",
        "median_stokes_body_forward_component_value",
        "median_end_term_component_value",
        "time_derivative_component_sensitivity_ratio",
        "pressure_gradient_component_sensitivity_ratio",
        "stokes_body_forward_component_sensitivity_ratio",
        "end_term_component_sensitivity_ratio",
        "median_abs_time_derivative_delta_vs_default",
        "median_abs_pressure_gradient_delta_vs_default",
        "median_abs_stokes_body_forward_delta_vs_default",
        "median_abs_end_term_delta_vs_default",
        "median_abs_total_delta_vs_default",
        "diagnostic_conclusion",
        "candidate_default_gate_eligible",
        "candidate_exclusion_reason",
        "gate_role",
        "path_diagnostic_status",
        "source_reference",
    ]

    def empty_outputs(reason: str) -> tuple[pd.DataFrame, pd.DataFrame]:
        detail = pd.DataFrame(columns=detail_columns)
        summary = pd.DataFrame(
            [
                {
                    "benchmark": benchmark,
                    "variant": "",
                    "coefficient": "",
                    "row_count": 0,
                    "unique_frequency_count": 0,
                    "pass_count": 0,
                    "fail_count": 0,
                    "max_gate_error_ratio": float("nan"),
                    "median_gate_error_ratio": float("nan"),
                    "dominant_component_counts": "",
                    "diagnostic_conclusion": reason,
                    "candidate_default_gate_eligible": False,
                    "candidate_exclusion_reason": "diagnostic input unavailable",
                    "gate_role": "local_time_phase_component_audit_not_hard_gate",
                    "path_diagnostic_status": "NOT_EVALUATED",
                    "source_reference": str(reference_path),
                }
            ],
            columns=summary_columns,
        )
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    if comparison.empty or not reference_path.exists():
        return empty_outputs("local_time_phase_component_reference_not_available")

    table = pd.read_csv(reference_path)
    required = {"coefficient", "omega_e_sqrt_l_over_g", "reference_value"}
    if not required.issubset(comparison.columns) or not required.issubset(table.columns):
        return empty_outputs("local_time_phase_component_missing_required_columns")

    template_by_coefficient = {
        str(row["coefficient"]).strip().upper(): row
        for _, row in comparison.iterrows()
        if "coefficient" in row
    }
    fallback_template = comparison.iloc[0]
    table = table.copy()
    table["_coefficient_upper"] = table["coefficient"].astype(str).str.strip().str.upper()
    table["_omega_numeric"] = pd.to_numeric(table["omega_e_sqrt_l_over_g"], errors="coerce")
    table = table[table["_coefficient_upper"].isin({"A33", "A35", "A53", "A55"})]
    table = table[table["_omega_numeric"].notna()].reset_index(drop=True)
    if table.empty:
        return empty_outputs("local_time_phase_component_no_supported_rows")

    variants: tuple[tuple[str, bool, bool], ...] = (
        ("default_no_local_time_phase", False, False),
        ("local_time_phase_only", True, False),
        ("local_time_phase_with_gradient_correction", True, True),
    )

    def numeric(value: Any, default: float = float("nan")) -> float:
        try:
            result = float(value)
        except (TypeError, ValueError):
            return default
        return result if np.isfinite(result) else default

    rows: list[dict[str, Any]] = []
    caches: dict[str, dict[tuple[float | int | str, ...], object]] = {variant[0]: {} for variant in variants}
    for _, ref_row in table.iterrows():
        coeff = str(ref_row["_coefficient_upper"])
        template = template_by_coefficient.get(coeff, fallback_template).copy()
        template["coefficient"] = coeff
        template["omega_e_sqrt_l_over_g"] = float(ref_row["_omega_numeric"])
        template["reference_value"] = float(ref_row["reference_value"])
        for variant_name, apply_phase, gradient_correction in variants:
            probe = template.copy()
            probe["matched_apply_local_time_phase"] = bool(apply_phase)
            probe["matched_local_time_phase_gradient_correction"] = bool(gradient_correction)
            try:
                calc = _ma2005_computed_coefficient(
                    probe,
                    hydro_model=hydro_model,
                    bem_free_surface_panel_count_per_side=bem_free_surface_panel_count_per_side,
                    bem_body_panel_count=bem_body_panel_count,
                    matrix_cache=caches[variant_name],
                    benchmark_base_dir=reference_path.parent,
                )
                _, row_idx, col_idx = _coefficient_matrix_indices(coeff)
                tolerance = 0.15 if row_idx == col_idx else 0.30
                metrics = _ma2005_error_metrics(
                    float(probe["reference_value"]),
                    float(calc["computed_value"]),
                    tolerance,
                    row_idx,
                    col_idx,
                    str(calc.get("normalization", "ma2005")),
                )
                component_values = {
                    name: numeric(calc.get(f"matched_{name}_component_value"))
                    for name in component_names
                }
                component_raw = {
                    name: numeric(calc.get(f"matched_{name}_component_raw"))
                    for name in component_names
                }
                finite_component_abs = {
                    name: abs(value)
                    for name, value in component_values.items()
                    if np.isfinite(value)
                }
                if finite_component_abs:
                    dominant_component = max(finite_component_abs, key=finite_component_abs.get)
                    dominant_value = component_values[dominant_component]
                    abs_sum = sum(finite_component_abs.values())
                    dominant_fraction = abs(dominant_value) / max(abs_sum, 1.0e-300)
                else:
                    dominant_component = ""
                    dominant_value = float("nan")
                    dominant_fraction = float("nan")
                reference_raw = float(probe["reference_value"]) * numeric(calc.get("normalization_scale"), 1.0)
                row_data: dict[str, Any] = {
                    "benchmark": benchmark,
                    "variant": variant_name,
                    "probe_row": int(len(rows)),
                    "source_row": int(ref_row.name),
                    "hull": str(ref_row.get("hull", probe.get("hull", ""))),
                    "speed_case": str(ref_row.get("speed_case", probe.get("speed_case", ""))),
                    "motion_test": str(ref_row.get("motion_test", "")),
                    "coefficient": coeff,
                    "omega_e_sqrt_l_over_g": float(probe["omega_e_sqrt_l_over_g"]),
                    "reference_value": float(probe["reference_value"]),
                    "computed_value": float(calc["computed_value"]),
                    "raw_computed_value": float(calc.get("raw_value", float("nan"))),
                    "normalization_scale": numeric(calc.get("normalization_scale"), 1.0),
                    "gate_error_ratio": float(metrics["gate_error_ratio"]),
                    "status": str(metrics["status"]),
                    "dominant_component": dominant_component,
                    "dominant_component_value": dominant_value,
                    "dominant_component_abs_fraction": dominant_fraction,
                    "matched_apply_local_time_phase": bool(apply_phase),
                    "matched_local_time_phase_gradient_correction": bool(gradient_correction),
                    "provider_route": calc.get("provider_route", ""),
                    "provider_formulation": calc.get("provider_formulation", ""),
                    "solver_status": calc.get("solver_status", ""),
                    "candidate_default_gate_eligible": False,
                    "candidate_exclusion_reason": (
                        "diagnostic-only local-time phase component audit; no candidate can enter the default "
                        "provider without full Gate 1 closure."
                    ),
                    "gate_role": "local_time_phase_component_audit_not_hard_gate",
                    "path_diagnostic_status": "INFO",
                }
                for name in component_names:
                    row_data[f"{name}_component_value"] = component_values[name]
                    row_data[f"{name}_component_raw"] = component_raw[name]
                    row_data[f"{name}_raw_to_reference_raw_ratio"] = (
                        float(component_raw[name] / reference_raw)
                        if abs(reference_raw) > 1.0e-300 and np.isfinite(component_raw[name])
                        else float("nan")
                    )
                rows.append(row_data)
            except Exception as exc:
                row_data = {
                    "benchmark": benchmark,
                    "variant": variant_name,
                    "probe_row": int(len(rows)),
                    "source_row": int(ref_row.name),
                    "hull": str(ref_row.get("hull", probe.get("hull", ""))),
                    "speed_case": str(ref_row.get("speed_case", probe.get("speed_case", ""))),
                    "motion_test": str(ref_row.get("motion_test", "")),
                    "coefficient": coeff,
                    "omega_e_sqrt_l_over_g": float(probe["omega_e_sqrt_l_over_g"]),
                    "reference_value": float(probe["reference_value"]),
                    "computed_value": float("nan"),
                    "raw_computed_value": float("nan"),
                    "normalization_scale": float("nan"),
                    "gate_error_ratio": float("nan"),
                    "status": "FAIL",
                    "dominant_component": "",
                    "dominant_component_value": float("nan"),
                    "dominant_component_abs_fraction": float("nan"),
                    "matched_apply_local_time_phase": bool(apply_phase),
                    "matched_local_time_phase_gradient_correction": bool(gradient_correction),
                    "provider_route": "",
                    "provider_formulation": "",
                    "solver_status": str(exc),
                    "candidate_default_gate_eligible": False,
                    "candidate_exclusion_reason": "diagnostic computation failed",
                    "gate_role": "local_time_phase_component_audit_not_hard_gate",
                    "path_diagnostic_status": "INFO",
                }
                for name in component_names:
                    row_data[f"{name}_component_value"] = float("nan")
                    row_data[f"{name}_component_raw"] = float("nan")
                    row_data[f"{name}_raw_to_reference_raw_ratio"] = float("nan")
                rows.append(row_data)

    detail = pd.DataFrame(rows, columns=[column for column in detail_columns if column in pd.DataFrame(rows).columns])
    if detail.empty:
        return empty_outputs("local_time_phase_component_rows_missing")

    default_lookup = detail[detail["variant"].astype(str).eq("default_no_local_time_phase")].set_index(
        ["source_row", "coefficient"]
    )
    for index, row in detail.iterrows():
        key = (row["source_row"], row["coefficient"])
        default_row = default_lookup.loc[key] if key in default_lookup.index else None
        for name in component_names:
            current = numeric(row.get(f"{name}_component_value"))
            baseline = numeric(default_row.get(f"{name}_component_value") if default_row is not None else np.nan)
            detail.loc[index, f"{name}_delta_vs_default"] = (
                current - baseline if np.isfinite(current) and np.isfinite(baseline) else float("nan")
            )
        current_total = numeric(row.get("computed_value"))
        baseline_total = numeric(default_row.get("computed_value") if default_row is not None else np.nan)
        detail.loc[index, "total_delta_vs_default"] = (
            current_total - baseline_total
            if np.isfinite(current_total) and np.isfinite(baseline_total)
            else float("nan")
        )
    detail = detail.reindex(columns=detail_columns)

    def sensitivity_ratio(values: pd.Series) -> float:
        arr = pd.to_numeric(values, errors="coerce").dropna().to_numpy(dtype=float)
        if arr.size < 2:
            return float("nan")
        return float((np.max(arr) - np.min(arr)) / max(float(np.max(np.abs(arr))), 1.0e-12))

    summary_rows: list[dict[str, Any]] = []
    for (variant_name, coefficient), group in detail.groupby(["variant", "coefficient"], sort=False):
        gate = pd.to_numeric(group["gate_error_ratio"], errors="coerce")
        pass_count = int(group["status"].astype(str).eq("PASS").sum())
        fail_count = int(group["status"].astype(str).eq("FAIL").sum())
        dominant_counts = group["dominant_component"].astype(str).value_counts().to_dict()
        time_sensitivity = sensitivity_ratio(group["time_derivative_component_value"])
        gradient_sensitivity = sensitivity_ratio(group["pressure_gradient_component_value"])
        stokes_sensitivity = sensitivity_ratio(group["stokes_body_forward_component_value"])
        end_sensitivity = sensitivity_ratio(group["end_term_component_value"])
        abs_time_delta = pd.to_numeric(group["time_derivative_delta_vs_default"], errors="coerce").abs()
        abs_gradient_delta = pd.to_numeric(group["pressure_gradient_delta_vs_default"], errors="coerce").abs()
        abs_stokes_delta = pd.to_numeric(group["stokes_body_forward_delta_vs_default"], errors="coerce").abs()
        abs_end_delta = pd.to_numeric(group["end_term_delta_vs_default"], errors="coerce").abs()
        abs_total_delta = pd.to_numeric(group["total_delta_vs_default"], errors="coerce").abs()
        coeff = str(coefficient).upper()
        variant = str(variant_name)
        target_time_chain = coeff in {"A33", "A53"}
        if pass_count == len(group) and len(group) > 0:
            conclusion = "local_time_phase_component_variant_passes_rows"
            exclusion = ""
        elif variant == "default_no_local_time_phase" and target_time_chain and np.isfinite(time_sensitivity) and time_sensitivity <= 1.0e-10:
            conclusion = "default_time_component_frequency_invariant_for_time_pressure_target"
            exclusion = "default Eq.30 time component lacks same-cell frequency sensitivity for A33/A53"
        elif target_time_chain and abs_time_delta.notna().any() and float(abs_time_delta.max()) > 1.0e-9:
            conclusion = "local_time_phase_changes_time_component_but_gate_still_fails"
            exclusion = "diagnostic-only; local-time phase changes the time-pressure component but does not close Gate 1"
        elif variant.endswith("gradient_correction") and abs_gradient_delta.notna().any() and float(abs_gradient_delta.max()) > 1.0e-9:
            conclusion = "local_time_phase_gradient_correction_changes_forward_component_but_gate_still_fails"
            exclusion = "diagnostic-only; gradient correction changes Eq.30 forward component without full Gate closure"
        else:
            conclusion = "local_time_phase_component_candidate_does_not_close_gate"
            exclusion = "diagnostic-only; component changes are insufficient for default promotion"
        summary_rows.append(
            {
                "benchmark": benchmark,
                "variant": variant,
                "coefficient": coeff,
                "row_count": int(len(group)),
                "unique_frequency_count": int(group["omega_e_sqrt_l_over_g"].nunique()),
                "pass_count": pass_count,
                "fail_count": fail_count,
                "max_gate_error_ratio": float(gate.max()) if gate.notna().any() else float("nan"),
                "median_gate_error_ratio": float(gate.median()) if gate.notna().any() else float("nan"),
                "dominant_component_counts": ";".join(
                    f"{key}:{value}" for key, value in sorted(dominant_counts.items())
                ),
                "median_time_derivative_component_value": float(
                    pd.to_numeric(group["time_derivative_component_value"], errors="coerce").median()
                ),
                "median_pressure_gradient_component_value": float(
                    pd.to_numeric(group["pressure_gradient_component_value"], errors="coerce").median()
                ),
                "median_stokes_body_forward_component_value": float(
                    pd.to_numeric(group["stokes_body_forward_component_value"], errors="coerce").median()
                ),
                "median_end_term_component_value": float(
                    pd.to_numeric(group["end_term_component_value"], errors="coerce").median()
                ),
                "time_derivative_component_sensitivity_ratio": time_sensitivity,
                "pressure_gradient_component_sensitivity_ratio": gradient_sensitivity,
                "stokes_body_forward_component_sensitivity_ratio": stokes_sensitivity,
                "end_term_component_sensitivity_ratio": end_sensitivity,
                "median_abs_time_derivative_delta_vs_default": (
                    float(abs_time_delta.median()) if abs_time_delta.notna().any() else float("nan")
                ),
                "median_abs_pressure_gradient_delta_vs_default": (
                    float(abs_gradient_delta.median()) if abs_gradient_delta.notna().any() else float("nan")
                ),
                "median_abs_stokes_body_forward_delta_vs_default": (
                    float(abs_stokes_delta.median()) if abs_stokes_delta.notna().any() else float("nan")
                ),
                "median_abs_end_term_delta_vs_default": (
                    float(abs_end_delta.median()) if abs_end_delta.notna().any() else float("nan")
                ),
                "median_abs_total_delta_vs_default": (
                    float(abs_total_delta.median()) if abs_total_delta.notna().any() else float("nan")
                ),
                "diagnostic_conclusion": conclusion,
                "candidate_default_gate_eligible": False,
                "candidate_exclusion_reason": exclusion,
                "gate_role": "local_time_phase_component_audit_not_hard_gate",
                "path_diagnostic_status": "INFO",
                "source_reference": str(reference_path),
            }
        )
    summary = pd.DataFrame(summary_rows, columns=summary_columns)
    detail.to_csv(detail_path, index=False)
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _write_ma2005_coefficient_conversion_chain_audit(
    comparison: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Audit whether a simple A/B conversion convention can explain Gate 1 misses.

    This is a diagnostic guardrail around the matrix-to-coefficient interface. It
    does not change the provider or select a candidate correction.
    """

    detail_path = out_dir / f"{benchmark}_coefficient_conversion_chain_audit.csv"
    summary_path = out_dir / f"{benchmark}_coefficient_conversion_chain_summary.csv"
    if comparison.empty:
        detail = pd.DataFrame()
        summary = pd.DataFrame()
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    rows: list[dict[str, Any]] = []
    for index, item in comparison.iterrows():
        coefficient = str(item.get("coefficient", "")).strip().upper()
        try:
            prefix, row_idx, col_idx = _coefficient_matrix_indices(coefficient)
            reference = float(item["reference_value"])
            raw = float(item["raw_computed_value"])
            rho = float(item.get("rho_water_kg_m3", 1025.0))
            length = float(item["hull_length_m"])
            gravity = float(item.get("gravity_m_s2", 9.80665))
            if "displacement_volume_m3" in item and not pd.isna(item["displacement_volume_m3"]):
                displacement = float(item["displacement_volume_m3"])
            elif "normalization_scale" in item and not pd.isna(item["normalization_scale"]):
                current_scale = float(item["normalization_scale"])
                documented_power = _ma2005_documented_length_power(row_idx, col_idx)
                damping_factor = math.sqrt(gravity / length) if prefix == "B" else 1.0
                displacement = current_scale / max(rho * length**documented_power * damping_factor, 1.0e-300)
            else:
                displacement = float("nan")
            omega = float(item["omega_e_rad_s"]) if "omega_e_rad_s" in item else (
                float(item["omega_e_sqrt_l_over_g"]) * math.sqrt(gravity / length)
            )
            if not np.isfinite(displacement):
                continue
        except Exception:
            continue

        documented_power = _ma2005_documented_length_power(row_idx, col_idx)
        variants: list[tuple[str, str, float]] = []
        for power in (0, 1, 2):
            scale = _ma2005_scale_for_length_power(prefix, power, rho, length, gravity, displacement)
            variants.append((f"length_power_{power}", f"raw/(rho*disp*L^{power}) with current damping sqrt(g/L)", raw / scale))
        if prefix == "B":
            base = rho * displacement * length**documented_power
            variants.extend(
                [
                    (
                        "damping_no_sqrt",
                        "raw/(rho*disp*L^r), omitting the damping sqrt(g/L) factor",
                        raw / base,
                    ),
                    (
                        "damping_inverse_sqrt",
                        "raw/(rho*disp*L^r*sqrt(L/g)), inverse of the documented damping factor",
                        raw / (base * math.sqrt(length / gravity)),
                    ),
                    (
                        "damping_divide_omega",
                        "raw/(omega*rho*disp*L^r*sqrt(g/L)), tests one extra omega in the raw damping channel",
                        raw / (omega * _ma2005_scale_for_length_power(prefix, documented_power, rho, length, gravity, displacement)),
                    ),
                    (
                        "damping_multiply_omega",
                        "omega*raw/(rho*disp*L^r*sqrt(g/L)), tests one missing omega in the raw damping channel",
                        omega * raw / _ma2005_scale_for_length_power(prefix, documented_power, rho, length, gravity, displacement),
                    ),
                    (
                        "damping_sign_flipped_current",
                        "-raw/(rho*disp*L^r*sqrt(g/L)), tests a final damping sign convention only",
                        -raw / _ma2005_scale_for_length_power(prefix, documented_power, rho, length, gravity, displacement),
                    ),
                ]
            )
        else:
            variants.append(
                (
                    "added_mass_sign_flipped_current",
                    "-raw/(rho*disp*L^r), tests a final added-mass sign convention only",
                    -raw / _ma2005_scale_for_length_power(prefix, documented_power, rho, length, gravity, displacement),
                )
            )
        for variant_name, description, computed in variants:
            metrics = _ma2005_error_metrics(
                reference,
                float(computed),
                0.15 if row_idx == col_idx else 0.30,
                row_idx,
                col_idx,
                "ma2005",
            )
            current_gate = pd.to_numeric(pd.Series([item.get("gate_error_ratio", np.nan)]), errors="coerce").iloc[0]
            rows.append(
                {
                    "benchmark": benchmark,
                    "row": int(index),
                    "coefficient": coefficient,
                    "variant_name": variant_name,
                    "variant_description": description,
                    "reference_value": reference,
                    "computed_value": float(computed),
                    "current_computed_value": float(item.get("computed_value", float("nan"))),
                    "raw_computed_value": raw,
                    "omega_e_rad_s": omega,
                    "documented_length_power": int(documented_power),
                    "gate_error_ratio": float(metrics["gate_error_ratio"]),
                    "current_gate_error_ratio": float(current_gate),
                    "gate_ratio_delta_vs_current": float(metrics["gate_error_ratio"] - current_gate)
                    if np.isfinite(current_gate)
                    else float("nan"),
                    "status": str(metrics["status"]),
                    "candidate_default_gate_eligible": False,
                    "gate_role": "diagnostic_coefficient_conversion_chain_not_hard_gate",
                    "path_diagnostic_status": "INFO",
                }
            )

    detail = pd.DataFrame(rows)
    if detail.empty:
        summary = pd.DataFrame()
    else:
        summary_rows: list[dict[str, Any]] = []
        for variant_name, group in detail.groupby("variant_name", sort=False):
            gates = pd.to_numeric(group["gate_error_ratio"], errors="coerce")
            deltas = pd.to_numeric(group["gate_ratio_delta_vs_current"], errors="coerce")
            statuses = group["status"].astype(str)
            summary_rows.append(
                {
                    "benchmark": benchmark,
                    "variant_name": str(variant_name),
                    "row_count": int(len(group)),
                    "pass_count": int(statuses.eq("PASS").sum()),
                    "fail_count": int(statuses.eq("FAIL").sum()),
                    "max_gate_error_ratio": float(gates.max()) if gates.notna().any() else float("nan"),
                    "median_gate_error_ratio": float(gates.median()) if gates.notna().any() else float("nan"),
                    "improved_row_count": int((deltas < 0.0).sum()) if deltas.notna().any() else 0,
                    "worsened_row_count": int((deltas > 0.0).sum()) if deltas.notna().any() else 0,
                    "candidate_default_gate_eligible": False,
                    "diagnostic_conclusion": (
                        "simple_conversion_variant_passes_all_rows"
                        if statuses.eq("PASS").all()
                        else "simple_conversion_variant_does_not_close_gate"
                    ),
                    "gate_role": "diagnostic_coefficient_conversion_chain_not_hard_gate",
                    "path_diagnostic_status": "INFO",
                }
            )
        summary = pd.DataFrame(summary_rows)
        summary = summary.sort_values(
            ["fail_count", "max_gate_error_ratio", "median_gate_error_ratio", "variant_name"],
            na_position="last",
        ).reset_index(drop=True)
    detail.to_csv(detail_path, index=False)
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _write_ma2005_body_condition_unit_chain_audit(
    comparison: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Audit simple body-condition unit-scale interpretations for Gate 1 misses.

    The matched BIE path currently applies heave/pitch radiation body conditions
    as unit displacement amplitudes, for example ``i omega N3`` and
    ``i omega N5 + U m5``. This diagnostic asks a narrower question: could the
    misses be explained by a simple real-amplitude unit convention, such as a
    unit-velocity or unit-acceleration potential, before we spend more time in
    the matched Eq.23/Eq.24 internals?

    It deliberately does not model the missing complex ``1/i`` phase rotation;
    that requires paired complex force data at the same frequency. Therefore a
    passing row here is still only triage evidence, never a production fix.
    """

    detail_path = out_dir / f"{benchmark}_body_condition_unit_chain_audit.csv"
    summary_path = out_dir / f"{benchmark}_body_condition_unit_chain_summary.csv"
    if comparison.empty:
        detail = pd.DataFrame()
        summary = pd.DataFrame()
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    def finite_float(item: pd.Series, column: str, default: float = float("nan")) -> float:
        if column not in item or pd.isna(item[column]):
            return default
        try:
            return float(item[column])
        except (TypeError, ValueError):
            return default

    rows: list[dict[str, Any]] = []
    for index, item in comparison.iterrows():
        coefficient = str(item.get("coefficient", "")).strip().upper()
        try:
            prefix, row_idx, col_idx = _coefficient_matrix_indices(coefficient)
        except Exception:
            continue
        reference = finite_float(item, "reference_value")
        current = finite_float(item, "computed_value")
        current_gate = finite_float(item, "gate_error_ratio")
        length = finite_float(item, "hull_length_m", 3.0)
        gravity = finite_float(item, "gravity_m_s2", 9.80665)
        omega_nondim = finite_float(item, "omega_e_sqrt_l_over_g")
        omega_dimensional = finite_float(item, "omega_e_rad_s")
        if not np.isfinite(omega_dimensional) and np.isfinite(omega_nondim) and length > 0.0 and gravity > 0.0:
            omega_dimensional = float(omega_nondim * math.sqrt(gravity / length))
        if not all(np.isfinite(value) for value in (reference, current, omega_nondim, omega_dimensional)):
            continue
        if abs(omega_nondim) <= 1e-300 or abs(omega_dimensional) <= 1e-300:
            continue

        tolerance = finite_float(item, "tolerance", 0.15 if row_idx == col_idx else 0.30)
        variant_definitions: tuple[tuple[str, str, float], ...] = (
            (
                "current_unit_displacement",
                "Current default body condition scale; heave uses i*omega*N3 and pitch uses i*omega*N5 plus U*m5.",
                1.0,
            ),
            (
                "remove_dimensional_omega_unit_velocity_proxy",
                "Real-amplitude proxy for interpreting the solved potential as unit velocity in SI time units.",
                1.0 / omega_dimensional,
            ),
            (
                "remove_dimensional_omega2_unit_acceleration_proxy",
                "Real-amplitude proxy for interpreting the solved potential as unit acceleration in SI time units.",
                1.0 / omega_dimensional**2,
            ),
            (
                "remove_nondimensional_omega_unit_velocity_proxy",
                "Real-amplitude proxy for interpreting the solved potential with A1 nondimensional encounter frequency.",
                1.0 / omega_nondim,
            ),
            (
                "remove_nondimensional_omega2_unit_acceleration_proxy",
                "Real-amplitude proxy for removing two powers of the A1 nondimensional encounter frequency.",
                1.0 / omega_nondim**2,
            ),
            (
                "multiply_dimensional_omega_proxy",
                "Opposite real-amplitude proxy: tests whether one dimensional omega is missing upstream.",
                omega_dimensional,
            ),
            (
                "multiply_nondimensional_omega_proxy",
                "Opposite real-amplitude proxy: tests whether one nondimensional omega is missing upstream.",
                omega_nondim,
            ),
        )
        mode_column = "heave" if col_idx == 2 else "pitch" if col_idx == 4 else "other"
        generalized_row = "heave_force" if row_idx == 2 else "pitch_moment" if row_idx == 4 else "other"
        for variant_name, description, factor in variant_definitions:
            computed = current * factor
            metrics = _ma2005_error_metrics(
                reference,
                float(computed),
                tolerance,
                row_idx,
                col_idx,
                "ma2005",
            )
            rows.append(
                {
                    "benchmark": benchmark,
                    "row": int(index),
                    "coefficient": coefficient,
                    "prefix": prefix,
                    "mode_column": mode_column,
                    "generalized_row": generalized_row,
                    "variant_name": variant_name,
                    "variant_description": description,
                    "reference_value": reference,
                    "current_computed_value": current,
                    "computed_value": float(computed),
                    "scale_factor_applied_to_current_value": float(factor),
                    "omega_e_rad_s": omega_dimensional,
                    "omega_e_sqrt_l_over_g": omega_nondim,
                    "gate_error_ratio": float(metrics["gate_error_ratio"]),
                    "current_gate_error_ratio": current_gate,
                    "gate_ratio_delta_vs_current": (
                        float(metrics["gate_error_ratio"] - current_gate)
                        if np.isfinite(current_gate)
                        else float("nan")
                    ),
                    "status": str(metrics["status"]),
                    "phase_rotation_not_represented": True,
                    "candidate_default_gate_eligible": False,
                    "candidate_exclusion_reason": (
                        "Real-amplitude unit proxy only; a default change requires complex same-frequency force "
                        "phase evidence and closure of the complete eight-coefficient Gate 1 set."
                    ),
                    "gate_role": "diagnostic_body_condition_unit_chain_not_hard_gate",
                    "path_diagnostic_status": "INFO",
                }
            )

    detail = pd.DataFrame(rows)
    if detail.empty:
        summary = pd.DataFrame()
    else:
        summary_rows: list[dict[str, Any]] = []
        for variant_name, group in detail.groupby("variant_name", sort=False):
            gates = pd.to_numeric(group["gate_error_ratio"], errors="coerce")
            deltas = pd.to_numeric(group["gate_ratio_delta_vs_current"], errors="coerce")
            statuses = group["status"].astype(str)
            improved = int((deltas < 0.0).sum()) if deltas.notna().any() else 0
            worsened = int((deltas > 0.0).sum()) if deltas.notna().any() else 0
            summary_rows.append(
                {
                    "benchmark": benchmark,
                    "variant_name": str(variant_name),
                    "row_count": int(len(group)),
                    "pass_count": int(statuses.eq("PASS").sum()),
                    "fail_count": int(statuses.eq("FAIL").sum()),
                    "max_gate_error_ratio": float(gates.max()) if gates.notna().any() else float("nan"),
                    "median_gate_error_ratio": float(gates.median()) if gates.notna().any() else float("nan"),
                    "improved_row_count": improved,
                    "worsened_row_count": worsened,
                    "candidate_default_gate_eligible": False,
                    "diagnostic_conclusion": (
                        "unit_scale_proxy_passes_all_rows_but_phase_unverified"
                        if statuses.eq("PASS").all()
                        else "simple_unit_scale_proxy_does_not_close_gate"
                    ),
                    "gate_role": "diagnostic_body_condition_unit_chain_not_hard_gate",
                    "path_diagnostic_status": "INFO",
                }
            )
        summary = pd.DataFrame(summary_rows).sort_values(
            ["fail_count", "max_gate_error_ratio", "median_gate_error_ratio", "variant_name"],
            na_position="last",
        ).reset_index(drop=True)
    detail.to_csv(detail_path, index=False)
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _write_a1_heave_time_pressure_chain_audit(
    out_dir: Path,
    closed_cylinder_detail: pd.DataFrame,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Write a focused closed-section heave time-pressure-chain audit."""

    detail_path = out_dir / "a1_heave_time_pressure_chain.csv"
    summary_path = out_dir / "a1_heave_time_pressure_chain_summary.csv"
    if closed_cylinder_detail.empty:
        detail = pd.DataFrame()
        summary = pd.DataFrame()
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    def num(row: pd.Series, column: str, default: float = float("nan")) -> float:
        if column not in row:
            return default
        try:
            return float(row[column])
        except (TypeError, ValueError):
            return default

    rows: list[dict[str, float | str | bool | int]] = []
    for _, row in closed_cylinder_detail.iterrows():
        omega = max(num(row, "omega_rad_s"), 1e-300)
        expected_added = num(row, "expected_added_mass_per_m")
        raw_added = num(row, "computed_added_mass_per_m")
        corrected_added = num(row, "pressure_sign_corrected_added_mass_per_m")
        raw_damping = num(row, "computed_radiation_damping_per_m")
        corrected_damping = num(row, "pressure_sign_corrected_radiation_damping_per_m")
        tolerance = num(row, "corrected_relative_tolerance", 0.02)
        corrected_error = num(row, "pressure_sign_corrected_relative_error")
        residual = num(row, "source_system_relative_residual")
        potential_residual = num(row, "potential_alignment_relative_residual")
        raw_ratio = num(row, "computed_added_mass_ratio")
        sign_reversal = bool(raw_ratio < 0.0 and num(row, "pressure_sign_corrected_added_mass_ratio") > 0.0)
        chain_pass = bool(
            np.isfinite(corrected_error)
            and corrected_error <= tolerance
            and np.isfinite(residual)
            and residual < 1e-10
            and np.isfinite(potential_residual)
            and potential_residual < 1e-10
        )
        rows.append(
            {
                "audit_case": "closed_circular_cylinder_in_infinite_fluid",
                "checked_chain": "body_normal_velocity -> source_strength -> body_potential -> Eq30_time_pressure -> heave_force",
                "pressure_formula": "p_time = -rho*i*omega*phi",
                "reference_added_mass_formula": "rho*pi*r^2",
                "force_to_added_mass_formula": "A = Re(F)/omega^2; B = -Im(F)/omega",
                "radius_m": num(row, "radius_m"),
                "panel_count": int(num(row, "panel_count")),
                "omega_rad_s": omega,
                "rho_water_kg_m3": num(row, "rho_water_kg_m3"),
                "expected_added_mass_per_m": expected_added,
                "expected_heave_force_real_per_m": float(expected_added * omega**2),
                "computed_added_mass_per_m": raw_added,
                "computed_added_mass_ratio": raw_ratio,
                "computed_heave_force_real_per_m": float(raw_added * omega**2),
                "computed_heave_force_imag_per_m": float(-raw_damping * omega),
                "pressure_sign_corrected_added_mass_per_m": corrected_added,
                "pressure_sign_corrected_added_mass_ratio": num(
                    row,
                    "pressure_sign_corrected_added_mass_ratio",
                ),
                "pressure_sign_corrected_heave_force_real_per_m": float(corrected_added * omega**2),
                "pressure_sign_corrected_heave_force_imag_per_m": float(-corrected_damping * omega),
                "pressure_sign_corrected_relative_error": corrected_error,
                "corrected_relative_tolerance": tolerance,
                "source_system_condition_number": num(row, "source_system_condition_number"),
                "source_system_relative_residual": residual,
                "potential_alignment_scale_to_analytic": num(row, "potential_alignment_scale_to_analytic"),
                "potential_alignment_relative_residual": potential_residual,
                "heave_force_row_norm": num(row, "heave_force_row_norm"),
                "body_normal_velocity_norm": num(row, "body_normal_velocity_norm"),
                "raw_pressure_chain_sign_reversal": sign_reversal,
                "heave_time_pressure_chain_status": "PASS" if chain_pass else "REVIEW",
                "gate1_implication": (
                    "closed_section_inner_chain_magnitude_recovers_analytic_added_mass_after_explicit_sign_correction"
                    if chain_pass and sign_reversal
                    else "closed_section_inner_chain_needs_sign_or_magnitude_review"
                ),
                "production_policy": (
                    "diagnostic_only; this closed-section sign evidence cannot be applied as a production "
                    "Ma2005 correction unless the full Wigley III Gate 1 set passes with equation-traced convention"
                ),
            }
        )
    detail = pd.DataFrame(rows)
    detail.to_csv(detail_path, index=False)

    finest = detail.sort_values("panel_count").iloc[-1]
    summary = pd.DataFrame(
        [
            {
                "audit_case": "closed_circular_cylinder_in_infinite_fluid",
                "checked_chain": "body_normal_velocity -> body_potential -> Eq30_time_pressure -> heave_force",
                "panel_count_finest": int(finest["panel_count"]),
                "expected_added_mass_per_m": float(finest["expected_added_mass_per_m"]),
                "computed_added_mass_ratio_finest": float(finest["computed_added_mass_ratio"]),
                "pressure_sign_corrected_added_mass_ratio_finest": float(
                    finest["pressure_sign_corrected_added_mass_ratio"]
                ),
                "pressure_sign_corrected_relative_error_finest": float(
                    finest["pressure_sign_corrected_relative_error"]
                ),
                "source_system_relative_residual_max": float(detail["source_system_relative_residual"].max()),
                "potential_alignment_relative_residual_finest": float(
                    finest["potential_alignment_relative_residual"]
                ),
                "potential_alignment_scale_to_analytic_finest": float(
                    finest["potential_alignment_scale_to_analytic"]
                ),
                "raw_pressure_chain_sign_reversal_finest": bool(finest["raw_pressure_chain_sign_reversal"]),
                "pass_rows": int(detail["heave_time_pressure_chain_status"].astype(str).eq("PASS").sum()),
                "review_rows": int(detail["heave_time_pressure_chain_status"].astype(str).eq("REVIEW").sum()),
                "diagnostic_conclusion": str(finest["gate1_implication"]),
                "remaining_gate1_blocker": (
                    "A33/A53 still require matched open-section/free-surface/wet-station heave body-potential "
                    "scale audit; the closed cylinder only proves the isolated inner pressure chain is measurable."
                ),
                "gate_role": "diagnostic_a1_heave_time_pressure_chain_not_hard_gate",
            }
        ]
    )
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _ma2005_matched_station_contribution_rows(
    hydro: Any,
    *,
    benchmark: str,
    source_row: int,
    hull: str,
    speed_case: str,
    omega_e_sqrt_l_over_g: float,
    coefficient: str,
    prefix: str,
    row_idx: int,
    col_idx: int,
    normalization_scale: float,
    omega_rad_s: float,
    reference_value: float,
) -> list[dict[str, float | str]]:
    """Return station-wise signed density rows for a matched-BIE Ma 2005 coefficient."""

    hp_row = _ma2005_longitudinal_matrix_index(row_idx)
    hp_col = _ma2005_longitudinal_matrix_index(col_idx)
    if hp_row is None or hp_col is None:
        return []
    breakdown = hydro.contribution_breakdown
    x_m = np.asarray(breakdown.get("station_x_m", np.asarray([], dtype=float)), dtype=float)
    x_over_l = np.asarray(breakdown.get("station_x_over_l", np.asarray([], dtype=float)), dtype=float)
    if x_m.ndim != 2 or x_m.shape[0] < 1:
        return []
    station_count = x_m.shape[1]
    if x_over_l.ndim != 2 or x_over_l.shape[0] < 1 or x_over_l.shape[1] != station_count:
        x_over_l = np.full_like(x_m, np.nan, dtype=float)
    scale = max(float(normalization_scale), 1e-300)

    def density_values(name: str) -> np.ndarray:
        density = np.asarray(breakdown.get(name, np.asarray([], dtype=complex)), dtype=complex)
        if density.ndim != 4 or density.shape[0] < 1 or density.shape[1] != station_count or density.shape[2:] != (2, 2):
            return np.full(station_count, np.nan, dtype=float)
        selected = density[0, :, hp_row, hp_col]
        return np.asarray(
            [
                _ma2005_force_component_to_coefficient_raw(value, prefix, omega_rad_s) / scale
                for value in selected
            ],
            dtype=float,
        )

    total = density_values("heave_pitch_total_force_density_by_station")
    time = density_values("heave_pitch_time_derivative_force_density_by_station")
    gradient = density_values("heave_pitch_forward_speed_force_density_by_station")
    stokes = density_values("heave_pitch_stokes_body_forward_speed_force_density_by_station")

    def sign_label(value: float) -> str:
        if not np.isfinite(value):
            return "nan"
        if value > 0.0:
            return "positive"
        if value < 0.0:
            return "negative"
        return "zero"

    rows: list[dict[str, float | str]] = []
    for station_index in range(station_count):
        rows.append(
            {
                "benchmark": benchmark,
                "source_row": int(source_row),
                "hull": str(hull),
                "speed_case": str(speed_case),
                "omega_e_sqrt_l_over_g": float(omega_e_sqrt_l_over_g),
                "coefficient": str(coefficient),
                "reference_value": float(reference_value),
                "station_index": int(station_index),
                "x_m": float(x_m[0, station_index]),
                "x_over_l": float(x_over_l[0, station_index]),
                "total_density_value_per_m": float(total[station_index]),
                "time_derivative_density_value_per_m": float(time[station_index]),
                "pressure_gradient_density_value_per_m": float(gradient[station_index]),
                "stokes_body_forward_density_value_per_m": float(stokes[station_index]),
                "total_density_sign": sign_label(float(total[station_index])),
                "pressure_gradient_density_sign": sign_label(float(gradient[station_index])),
                "stokes_body_forward_density_sign": sign_label(float(stokes[station_index])),
            }
        )
    return rows


def _ma2005_matched_body_potential_source_audit_rows(
    hydro: Any,
    *,
    benchmark: str,
    source_row: int,
    hull: str,
    speed_case: str,
    omega_e_sqrt_l_over_g: float,
    coefficient: str,
    prefix: str,
    row_idx: int,
    col_idx: int,
    normalization_scale: float,
    omega_rad_s: float,
    reference_value: float,
) -> list[dict[str, float | str | int]]:
    """Return station-wise Eq.30 upstream source diagnostics for one Ma 2005 row."""

    hp_row = _ma2005_longitudinal_matrix_index(row_idx)
    hp_col = _ma2005_longitudinal_matrix_index(col_idx)
    if hp_row is None or hp_col is None:
        return []
    breakdown = hydro.contribution_breakdown
    x_m = np.asarray(breakdown.get("station_x_m", np.asarray([], dtype=float)), dtype=float)
    x_over_l = np.asarray(breakdown.get("station_x_over_l", np.asarray([], dtype=float)), dtype=float)
    if x_m.ndim != 2 or x_m.shape[0] < 1:
        return []
    station_count = x_m.shape[1]
    if x_over_l.ndim != 2 or x_over_l.shape[0] < 1 or x_over_l.shape[1] != station_count:
        x_over_l = np.full_like(x_m, np.nan, dtype=float)
    scale = max(float(normalization_scale), 1e-300)
    mode_name = "heave" if hp_col == 0 else "pitch"
    row_name = "heave_force" if hp_row == 0 else "pitch_moment"

    def station_values(name: str) -> np.ndarray:
        value = np.asarray(breakdown.get(name, np.asarray([], dtype=float)), dtype=float)
        if value.ndim == 2 and value.shape[0] >= 1 and value.shape[1] == station_count:
            return value[0]
        if value.ndim == 1 and value.size == station_count:
            return value
        return np.full(station_count, np.nan, dtype=float)

    def density_values(name: str) -> np.ndarray:
        density = np.asarray(breakdown.get(name, np.asarray([], dtype=complex)), dtype=complex)
        if (
            density.ndim != 4
            or density.shape[0] < 1
            or density.shape[1] != station_count
            or density.shape[2:] != (2, 2)
        ):
            return np.full(station_count, np.nan, dtype=float)
        selected = density[0, :, hp_row, hp_col]
        return np.asarray(
            [
                _ma2005_force_component_to_coefficient_raw(value, prefix, omega_rad_s) / scale
                for value in selected
            ],
            dtype=float,
        )

    def dominant_label(components: dict[str, float]) -> str:
        finite = {name: abs(float(value)) for name, value in components.items() if np.isfinite(float(value))}
        if not finite:
            return "not_available"
        return max(finite, key=finite.get)

    def safe_ratio(numerator: float, denominator: float) -> float:
        if not np.isfinite(numerator) or not np.isfinite(denominator):
            return float("nan")
        if abs(denominator) <= 1e-300:
            return 0.0 if abs(numerator) <= 1e-300 else float(numerator / 1e-300)
        return float(numerator / denominator)

    body_velocity = station_values(f"{mode_name}_body_normal_velocity_norms")
    body_phi = station_values(f"{mode_name}_body_potential_norms")
    body_phi_to_beam2 = station_values(f"{mode_name}_body_potential_norm_to_beam_squared_ratios")
    body_phi_to_area = station_values(f"{mode_name}_body_potential_norm_to_submerged_area_ratios")
    free_phi = station_values(f"{mode_name}_free_surface_potential_norms")
    free_normal = station_values(f"{mode_name}_inner_free_surface_normal_derivative_norms")
    control_phi = station_values(f"{mode_name}_control_potential_norms")
    control_normal = station_values(f"{mode_name}_control_normal_derivative_norms")
    pressure = station_values(f"{mode_name}_body_pressure_norms")
    pressure_time = station_values(f"{mode_name}_body_pressure_time_derivative_norms")
    pressure_forward = station_values(f"{mode_name}_body_pressure_forward_speed_norms")
    pressure_to_phi = station_values(f"{mode_name}_body_pressure_to_body_potential_gains")
    pressure_forward_to_time = station_values(f"{mode_name}_body_pressure_forward_to_time_norm_ratios")
    time_formula = station_values(f"{mode_name}_pressure_time_formula_ratios")
    forward_formula = station_values(f"{mode_name}_pressure_forward_formula_ratios")
    gradient_norm = station_values(f"{mode_name}_body_potential_x_gradient_norms")
    gradient_gain = station_values(f"{mode_name}_body_potential_x_gradient_to_potential_gains")
    gradient_length = station_values(f"{mode_name}_body_potential_x_gradient_characteristic_lengths")
    gradient_gain_l = station_values(f"{mode_name}_body_potential_x_gradient_gain_times_hull_length")
    central_gradient_gain_l = station_values(f"{mode_name}_central_body_potential_x_gradient_gain_times_hull_length")
    forward_gradient_gain_l = station_values(f"{mode_name}_forward_body_potential_x_gradient_gain_times_hull_length")
    backward_gradient_gain_l = station_values(f"{mode_name}_backward_body_potential_x_gradient_gain_times_hull_length")
    phase_aligned_gradient_gain_l = station_values(
        f"{mode_name}_phase_aligned_body_potential_x_gradient_gain_times_hull_length"
    )
    waterplane_beam = station_values("station_waterplane_beams")
    effective_draft = station_values("station_effective_drafts")
    submerged_area = station_values("station_submerged_areas")
    total_density = density_values("heave_pitch_total_force_density_by_station")
    time_density = density_values("heave_pitch_time_derivative_force_density_by_station")
    gradient_density = density_values("heave_pitch_forward_speed_force_density_by_station")
    stokes_density = density_values("heave_pitch_stokes_body_forward_speed_force_density_by_station")

    rows: list[dict[str, float | str | int]] = []
    for station_index in range(station_count):
        density_components = {
            "time_derivative_density": float(time_density[station_index]),
            "pressure_gradient_density": float(gradient_density[station_index]),
            "stokes_body_forward_density": float(stokes_density[station_index]),
        }
        pressure_components = {
            "time_derivative_pressure": float(pressure_time[station_index]),
            "forward_speed_pressure": float(pressure_forward[station_index]),
        }
        rows.append(
            {
                "benchmark": benchmark,
                "source_row": int(source_row),
                "hull": str(hull),
                "speed_case": str(speed_case),
                "omega_e_sqrt_l_over_g": float(omega_e_sqrt_l_over_g),
                "coefficient": str(coefficient),
                "mode_column": mode_name,
                "generalized_row": row_name,
                "reference_value": float(reference_value),
                "station_index": int(station_index),
                "x_m": float(x_m[0, station_index]),
                "x_over_l": float(x_over_l[0, station_index]),
                "waterplane_beam_m": float(waterplane_beam[station_index]),
                "effective_draft_m": float(effective_draft[station_index]),
                "submerged_area_m2": float(submerged_area[station_index]),
                "body_normal_velocity_norm": float(body_velocity[station_index]),
                "body_potential_norm": float(body_phi[station_index]),
                "body_potential_to_body_normal_velocity_gain": safe_ratio(
                    float(body_phi[station_index]),
                    float(body_velocity[station_index]),
                ),
                "body_potential_norm_to_beam_squared_ratio": float(body_phi_to_beam2[station_index]),
                "body_potential_norm_to_submerged_area_ratio": float(body_phi_to_area[station_index]),
                "inner_free_surface_normal_derivative_norm": float(free_normal[station_index]),
                "free_surface_potential_norm": float(free_phi[station_index]),
                "control_potential_norm": float(control_phi[station_index]),
                "control_normal_derivative_norm": float(control_normal[station_index]),
                "body_pressure_norm": float(pressure[station_index]),
                "body_pressure_time_derivative_norm": float(pressure_time[station_index]),
                "body_pressure_forward_speed_norm": float(pressure_forward[station_index]),
                "body_pressure_to_body_potential_gain": float(pressure_to_phi[station_index]),
                "body_pressure_forward_to_time_norm_ratio": float(pressure_forward_to_time[station_index]),
                "pressure_time_formula_ratio": float(time_formula[station_index]),
                "pressure_forward_formula_ratio": float(forward_formula[station_index]),
                "body_potential_x_gradient_norm": float(gradient_norm[station_index]),
                "body_potential_x_gradient_to_potential_gain": float(gradient_gain[station_index]),
                "body_potential_x_gradient_characteristic_length_m": float(gradient_length[station_index]),
                "body_potential_x_gradient_gain_times_l": float(gradient_gain_l[station_index]),
                "central_body_potential_x_gradient_gain_times_l": float(central_gradient_gain_l[station_index]),
                "forward_body_potential_x_gradient_gain_times_l": float(forward_gradient_gain_l[station_index]),
                "backward_body_potential_x_gradient_gain_times_l": float(backward_gradient_gain_l[station_index]),
                "phase_aligned_body_potential_x_gradient_gain_times_l": float(
                    phase_aligned_gradient_gain_l[station_index]
                ),
                "total_density_value_per_m": float(total_density[station_index]),
                "time_derivative_density_value_per_m": float(time_density[station_index]),
                "pressure_gradient_density_value_per_m": float(gradient_density[station_index]),
                "stokes_body_forward_density_value_per_m": float(stokes_density[station_index]),
                "dominant_force_density_component": dominant_label(density_components),
                "dominant_pressure_norm_component": dominant_label(pressure_components),
                "gate_role": "diagnostic_body_potential_source_audit_not_hard_gate",
            }
        )
    return rows


def _ma2005_body_potential_source_audit_summary(data: pd.DataFrame, benchmark: str) -> pd.DataFrame:
    """Summarize station-wise body-potential source diagnostics by coefficient."""

    if data.empty:
        return pd.DataFrame()
    rows: list[dict[str, float | str | int]] = []
    for coefficient, group in data.groupby("coefficient", sort=False):
        body_phi = pd.to_numeric(group["body_potential_norm"], errors="coerce").abs()
        gradient_density = pd.to_numeric(group["pressure_gradient_density_value_per_m"], errors="coerce").abs()
        time_density = pd.to_numeric(group["time_derivative_density_value_per_m"], errors="coerce").abs()
        total_density = pd.to_numeric(group["total_density_value_per_m"], errors="coerce").abs()
        gain_velocity = pd.to_numeric(group["body_potential_to_body_normal_velocity_gain"], errors="coerce")
        gain_area = pd.to_numeric(group["body_potential_norm_to_submerged_area_ratio"], errors="coerce")
        gain_beam = pd.to_numeric(group["body_potential_norm_to_beam_squared_ratio"], errors="coerce")
        gradient_gain_l = pd.to_numeric(group["body_potential_x_gradient_gain_times_l"], errors="coerce")
        forward_to_time = pd.to_numeric(group["body_pressure_forward_to_time_norm_ratio"], errors="coerce")

        def peak_row(series: pd.Series) -> pd.Series:
            if series.notna().any():
                return group.loc[series.idxmax()]
            return group.iloc[0]

        peak_body = peak_row(body_phi)
        peak_gradient = peak_row(gradient_density)
        peak_time = peak_row(time_density)
        peak_total = peak_row(total_density)
        dominant_counts = group["dominant_force_density_component"].astype(str).value_counts()
        rows.append(
            {
                "benchmark": benchmark,
                "coefficient": str(coefficient),
                "mode_column": str(group["mode_column"].iloc[0]),
                "generalized_row": str(group["generalized_row"].iloc[0]),
                "station_count": int(len(group)),
                "peak_body_potential_station_index": int(peak_body["station_index"]),
                "peak_body_potential_x_over_l": float(peak_body["x_over_l"]),
                "peak_body_potential_norm": float(body_phi.loc[peak_body.name]) if body_phi.notna().any() else float("nan"),
                "peak_time_density_station_index": int(peak_time["station_index"]),
                "peak_time_density_x_over_l": float(peak_time["x_over_l"]),
                "peak_time_derivative_density_abs_per_m": (
                    float(time_density.loc[peak_time.name]) if time_density.notna().any() else float("nan")
                ),
                "peak_pressure_gradient_station_index": int(peak_gradient["station_index"]),
                "peak_pressure_gradient_x_over_l": float(peak_gradient["x_over_l"]),
                "peak_pressure_gradient_density_abs_per_m": (
                    float(gradient_density.loc[peak_gradient.name]) if gradient_density.notna().any() else float("nan")
                ),
                "peak_total_density_station_index": int(peak_total["station_index"]),
                "peak_total_density_x_over_l": float(peak_total["x_over_l"]),
                "peak_total_density_abs_per_m": (
                    float(total_density.loc[peak_total.name]) if total_density.notna().any() else float("nan")
                ),
                "max_body_potential_to_body_normal_velocity_gain": (
                    float(gain_velocity.max()) if gain_velocity.notna().any() else float("nan")
                ),
                "max_body_potential_norm_to_beam_squared_ratio": (
                    float(gain_beam.max()) if gain_beam.notna().any() else float("nan")
                ),
                "max_body_potential_norm_to_submerged_area_ratio": (
                    float(gain_area.max()) if gain_area.notna().any() else float("nan")
                ),
                "max_body_potential_x_gradient_gain_times_l": (
                    float(gradient_gain_l.max()) if gradient_gain_l.notna().any() else float("nan")
                ),
                "max_body_pressure_forward_to_time_norm_ratio": (
                    float(forward_to_time.max()) if forward_to_time.notna().any() else float("nan")
                ),
                "dominant_force_density_component": (
                    str(dominant_counts.index[0]) if len(dominant_counts) else "not_available"
                ),
                "dominant_force_density_component_station_count": (
                    int(dominant_counts.iloc[0]) if len(dominant_counts) else 0
                ),
                "gate_role": "diagnostic_body_potential_source_audit_not_hard_gate",
                "path_diagnostic_status": "INFO",
            }
        )
    return pd.DataFrame(rows)


def _ma2005_body_potential_constant_mode_rows(
    hydro: Any,
    *,
    benchmark: str,
    source_row: int,
    hull: str,
    speed_case: str,
    omega_e_sqrt_l_over_g: float,
    coefficient: str,
    prefix: str,
    row_idx: int,
    col_idx: int,
    normalization_scale: float,
    omega_rad_s: float,
    rho_water_kg_m3: float,
    reference_value: float,
) -> list[dict[str, float | str | int | bool]]:
    """Decompose open-body potential into section-constant and centered modes.

    The decomposition is diagnostic only.  A spatially constant potential on
    the open wetted contour contributes to Eq.30 pressure because the contour's
    vertical projected measure is non-zero.  Subtracting that constant is not a
    valid correction unless Eq.23/Eq.24 and the free-surface gauge supply the
    corresponding boundary condition.
    """

    hp_row = _ma2005_longitudinal_matrix_index(row_idx)
    hp_col = _ma2005_longitudinal_matrix_index(col_idx)
    coefficient_name = str(coefficient).strip().upper()
    if hp_row is None or hp_col is None or coefficient_name not in {"A33", "A53"}:
        return []
    breakdown = hydro.contribution_breakdown

    def first_frequency_array(name: str, dtype: Any) -> np.ndarray:
        values = np.asarray(breakdown.get(name, np.asarray([], dtype=dtype)), dtype=dtype)
        if values.ndim < 2 or values.shape[0] < 1:
            return np.asarray([], dtype=dtype)
        return np.asarray(values[0], dtype=dtype)

    x_m = first_frequency_array("station_x_m", float)
    x_over_l = first_frequency_array("station_x_over_l", float)
    pressure_phi = first_frequency_array(f"{'heave' if hp_col == 0 else 'pitch'}_pressure_body_potential_by_station", complex)
    raw_body_phi = first_frequency_array(f"{'heave' if hp_col == 0 else 'pitch'}_body_potential_by_station", complex)
    body_length = first_frequency_array("body_panel_length_by_station", float)
    row_measure_all = first_frequency_array("heave_pitch_pressure_row_measure_by_station", float)
    stored_density_all = first_frequency_array("heave_pitch_time_derivative_force_density_by_station", complex)
    mode_name = "heave" if hp_col == 0 else "pitch"
    free_phi = first_frequency_array(f"{mode_name}_free_surface_potential_by_station", complex)
    free_length = first_frequency_array("inner_free_surface_panel_length_by_station", float)
    control_phi = first_frequency_array(f"{mode_name}_control_potential_by_station", complex)
    control_length = first_frequency_array("control_panel_length_by_station", float)

    if x_m.ndim != 1 or pressure_phi.ndim != 2 or body_length.shape != pressure_phi.shape:
        return []
    station_count, panel_count = pressure_phi.shape
    if x_m.size != station_count:
        return []
    if x_over_l.shape != x_m.shape:
        x_over_l = np.full_like(x_m, np.nan, dtype=float)
    if raw_body_phi.shape != pressure_phi.shape:
        raw_body_phi = pressure_phi.copy()
    if row_measure_all.ndim != 3 or row_measure_all.shape != (station_count, 2, panel_count):
        return []
    if stored_density_all.ndim != 3 or stored_density_all.shape != (station_count, 2, 2):
        stored_density = np.full(station_count, np.nan + 1j * np.nan, dtype=complex)
    else:
        stored_density = stored_density_all[:, hp_row, hp_col]
    row_measure = row_measure_all[:, hp_row, :]

    def weighted_mean(values: np.ndarray, weights: np.ndarray) -> np.ndarray:
        if values.ndim != 2 or weights.shape != values.shape or values.shape[0] != station_count:
            return np.full(station_count, np.nan + 1j * np.nan, dtype=complex)
        denominator = np.sum(weights, axis=1)
        result = np.full(station_count, np.nan + 1j * np.nan, dtype=complex)
        valid = np.isfinite(denominator) & (np.abs(denominator) > 1e-300)
        result[valid] = np.sum(values[valid] * weights[valid], axis=1) / denominator[valid]
        return result

    body_constant = weighted_mean(pressure_phi, body_length)
    raw_body_constant = weighted_mean(raw_body_phi, body_length)
    body_centered = pressure_phi - body_constant[:, None]
    free_constant = weighted_mean(free_phi, free_length)
    control_constant = weighted_mean(control_phi, control_length)
    rho = float(rho_water_kg_m3)
    omega = float(omega_rad_s)
    pressure_factor = -rho * 1j * omega
    full_density = np.sum(pressure_factor * pressure_phi * row_measure, axis=1)
    constant_density = np.sum(pressure_factor * body_constant[:, None] * row_measure, axis=1)
    centered_density = np.sum(pressure_factor * body_centered * row_measure, axis=1)

    def safe_ratio(numerator: float, denominator: float) -> float:
        if not np.isfinite(numerator) or not np.isfinite(denominator):
            return float("nan")
        return float(numerator / max(abs(denominator), 1e-300))

    def phase_deg(value: complex) -> float:
        return float(np.rad2deg(np.angle(value))) if np.isfinite(abs(value)) else float("nan")

    rows: list[dict[str, float | str | int | bool]] = []
    for station_index in range(station_count):
        phi_rms = float(np.sqrt(np.mean(np.abs(pressure_phi[station_index]) ** 2)))
        centered_rms = float(np.sqrt(np.mean(np.abs(body_centered[station_index]) ** 2)))
        density_scale = max(abs(full_density[station_index]), 1e-300)
        reconstruction_residual = abs(
            full_density[station_index] - constant_density[station_index] - centered_density[station_index]
        ) / density_scale
        stored_residual = abs(full_density[station_index] - stored_density[station_index]) / max(
            abs(stored_density[station_index]),
            1e-300,
        )
        body_free_difference = abs(raw_body_constant[station_index] - free_constant[station_index])
        body_control_difference = abs(raw_body_constant[station_index] - control_constant[station_index])
        rows.append(
            {
                "benchmark": benchmark,
                "source_row": int(source_row),
                "hull": str(hull),
                "speed_case": str(speed_case),
                "omega_e_sqrt_l_over_g": float(omega_e_sqrt_l_over_g),
                "omega_rad_s": omega,
                "coefficient": coefficient_name,
                "prefix": str(prefix).strip().upper(),
                "reference_value": float(reference_value),
                "normalization_scale": float(normalization_scale),
                "mode_column": mode_name,
                "generalized_row": "heave_force" if hp_row == 0 else "pitch_moment",
                "station_index": int(station_index),
                "x_m": float(x_m[station_index]),
                "x_over_l": float(x_over_l[station_index]),
                "station_integration_weight_m": float(_trapezoid_station_weights(x_m)[station_index]),
                "body_potential_constant_real": float(np.real(body_constant[station_index])),
                "body_potential_constant_imag": float(np.imag(body_constant[station_index])),
                "body_potential_constant_abs": float(abs(body_constant[station_index])),
                "body_potential_constant_phase_deg": phase_deg(body_constant[station_index]),
                "body_potential_rms": phi_rms,
                "body_potential_centered_rms": centered_rms,
                "body_constant_abs_to_rms_ratio": safe_ratio(abs(body_constant[station_index]), phi_rms),
                "body_centered_rms_to_rms_ratio": safe_ratio(centered_rms, phi_rms),
                "raw_body_potential_constant_abs": float(abs(raw_body_constant[station_index])),
                "free_surface_potential_constant_abs": float(abs(free_constant[station_index])),
                "control_potential_constant_abs": float(abs(control_constant[station_index])),
                "body_to_free_constant_difference_abs": float(body_free_difference),
                "body_to_free_constant_difference_to_body_abs_ratio": safe_ratio(
                    body_free_difference,
                    abs(raw_body_constant[station_index]),
                ),
                "body_to_control_constant_difference_abs": float(body_control_difference),
                "body_to_control_constant_difference_to_body_abs_ratio": safe_ratio(
                    body_control_difference,
                    abs(raw_body_constant[station_index]),
                ),
                "generalized_row_measure_sum": float(np.sum(row_measure[station_index])),
                "time_force_density_full_real": float(np.real(full_density[station_index])),
                "time_force_density_full_imag": float(np.imag(full_density[station_index])),
                "time_force_density_constant_real": float(np.real(constant_density[station_index])),
                "time_force_density_constant_imag": float(np.imag(constant_density[station_index])),
                "time_force_density_centered_real": float(np.real(centered_density[station_index])),
                "time_force_density_centered_imag": float(np.imag(centered_density[station_index])),
                "time_force_density_stored_real": float(np.real(stored_density[station_index])),
                "time_force_density_stored_imag": float(np.imag(stored_density[station_index])),
                "constant_mode_density_abs_to_full_abs_ratio": safe_ratio(
                    abs(constant_density[station_index]),
                    abs(full_density[station_index]),
                ),
                "centered_mode_density_abs_to_full_abs_ratio": safe_ratio(
                    abs(centered_density[station_index]),
                    abs(full_density[station_index]),
                ),
                "density_decomposition_relative_residual": float(reconstruction_residual),
                "stored_time_density_relative_residual": float(stored_residual),
                "candidate_default_gate_eligible": False,
                "candidate_exclusion_reason": (
                    "mode decomposition is diagnostic; no A1 Eq.23/Eq.24 gauge condition currently authorizes "
                    "subtracting the open-body constant potential"
                ),
                "gate_role": "diagnostic_body_potential_constant_mode_not_hard_gate",
            }
        )
    return rows


def _write_ma2005_body_potential_constant_mode_audit(
    rows: list[dict[str, float | str | int | bool]],
    out_dir: Path,
    benchmark: str,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Write station detail and coefficient summary for the constant-mode audit."""

    detail_path = out_dir / f"{benchmark}_body_potential_constant_mode_audit.csv"
    summary_path = out_dir / f"{benchmark}_body_potential_constant_mode_summary.csv"
    detail = pd.DataFrame(rows)
    summary_rows: list[dict[str, float | str | int | bool]] = []
    if not detail.empty:
        for coefficient, group in detail.groupby("coefficient", sort=False):
            weights = pd.to_numeric(group["station_integration_weight_m"], errors="coerce").to_numpy(float)

            def complex_column(real_name: str, imag_name: str) -> np.ndarray:
                return (
                    pd.to_numeric(group[real_name], errors="coerce").to_numpy(float)
                    + 1j * pd.to_numeric(group[imag_name], errors="coerce").to_numpy(float)
                )

            full_force = complex(np.sum(weights * complex_column("time_force_density_full_real", "time_force_density_full_imag")))
            constant_force = complex(
                np.sum(weights * complex_column("time_force_density_constant_real", "time_force_density_constant_imag"))
            )
            centered_force = complex(
                np.sum(weights * complex_column("time_force_density_centered_real", "time_force_density_centered_imag"))
            )
            stored_force = complex(
                np.sum(weights * complex_column("time_force_density_stored_real", "time_force_density_stored_imag"))
            )
            first = group.iloc[0]
            omega = float(first["omega_rad_s"])
            scale = max(float(first["normalization_scale"]), 1e-300)
            prefix = str(first["prefix"])

            def coefficient_value(force: complex) -> float:
                return _ma2005_force_component_to_coefficient_raw(force, prefix, omega) / scale

            full_value = coefficient_value(full_force)
            constant_value = coefficient_value(constant_force)
            centered_value = coefficient_value(centered_force)
            stored_value = coefficient_value(stored_force)
            force_reconstruction_residual = abs(full_force - constant_force - centered_force) / max(
                abs(full_force),
                1e-300,
            )
            stored_force_residual = abs(full_force - stored_force) / max(abs(stored_force), 1e-300)
            constant_force_fraction = abs(constant_force) / max(abs(full_force), 1e-300)
            conclusion = (
                "open_body_potential_station_constant_mode_dominates_eq30_time_pressure"
                if constant_force_fraction >= 0.8
                else "open_body_potential_centered_shape_mode_is_material_in_eq30_time_pressure"
            )
            summary_rows.append(
                {
                    "benchmark": benchmark,
                    "coefficient": str(coefficient),
                    "station_count": int(len(group)),
                    "reference_value": float(first["reference_value"]),
                    "time_pressure_full_coefficient": float(full_value),
                    "time_pressure_constant_mode_coefficient": float(constant_value),
                    "time_pressure_centered_mode_coefficient": float(centered_value),
                    "time_pressure_stored_coefficient": float(stored_value),
                    "constant_mode_force_abs_to_full_abs_ratio": float(constant_force_fraction),
                    "centered_mode_force_abs_to_full_abs_ratio": float(
                        abs(centered_force) / max(abs(full_force), 1e-300)
                    ),
                    "coefficient_decomposition_abs_residual": float(abs(full_value - constant_value - centered_value)),
                    "force_decomposition_relative_residual": float(force_reconstruction_residual),
                    "stored_time_force_relative_residual": float(stored_force_residual),
                    "max_station_density_decomposition_relative_residual": float(
                        pd.to_numeric(group["density_decomposition_relative_residual"], errors="coerce").max()
                    ),
                    "max_station_stored_time_density_relative_residual": float(
                        pd.to_numeric(group["stored_time_density_relative_residual"], errors="coerce").max()
                    ),
                    "median_body_constant_abs_to_rms_ratio": float(
                        pd.to_numeric(group["body_constant_abs_to_rms_ratio"], errors="coerce").median()
                    ),
                    "median_body_centered_rms_to_rms_ratio": float(
                        pd.to_numeric(group["body_centered_rms_to_rms_ratio"], errors="coerce").median()
                    ),
                    "median_body_to_free_constant_difference_to_body_abs_ratio": float(
                        pd.to_numeric(
                            group["body_to_free_constant_difference_to_body_abs_ratio"],
                            errors="coerce",
                        ).median()
                    ),
                    "median_body_to_control_constant_difference_to_body_abs_ratio": float(
                        pd.to_numeric(
                            group["body_to_control_constant_difference_to_body_abs_ratio"],
                            errors="coerce",
                        ).median()
                    ),
                    "diagnostic_conclusion": conclusion,
                    "default_correction_supported": False,
                    "candidate_default_gate_eligible": False,
                    "candidate_exclusion_reason": (
                        "dominance localizes the error but does not establish an A1 gauge condition or permit "
                        "constant-mode subtraction"
                    ),
                    "next_required_evidence": (
                        "trace the section-constant mode through Eq.23 free-surface rows and Eq.24 outer-control "
                        "radiation matching; compare against an independent open-free-surface section solution"
                    ),
                    "gate_role": "diagnostic_body_potential_constant_mode_not_hard_gate",
                }
            )
    summary = pd.DataFrame(summary_rows)
    detail.to_csv(detail_path, index=False)
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _trapezoid_station_weights(x_m: np.ndarray) -> np.ndarray:
    """Return integration weights associated with station-centered density samples."""

    x = np.asarray(x_m, dtype=float)
    if x.ndim != 1:
        raise ValueError("x_m must be one-dimensional.")
    if x.size == 0:
        return np.zeros(0, dtype=float)
    if x.size == 1:
        return np.ones(1, dtype=float)
    order = np.argsort(x)
    sorted_x = x[order]
    weights = np.zeros_like(sorted_x, dtype=float)
    weights[0] = 0.5 * (sorted_x[1] - sorted_x[0])
    weights[-1] = 0.5 * (sorted_x[-1] - sorted_x[-2])
    if sorted_x.size > 2:
        weights[1:-1] = 0.5 * (sorted_x[2:] - sorted_x[:-2])
    restored = np.zeros_like(weights, dtype=float)
    restored[order] = weights
    return restored


def _write_ma2005_heave_time_pressure_station_scale_audit(
    body_potential_source_audit: pd.DataFrame,
    comparison: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Write a Wigley III open-section station-scale audit for A33/A53 time pressure."""

    detail_path = out_dir / f"{benchmark}_heave_time_pressure_station_scale_audit.csv"
    summary_path = out_dir / f"{benchmark}_heave_time_pressure_station_scale_summary.csv"
    if body_potential_source_audit.empty or comparison.empty:
        detail = pd.DataFrame()
        summary = pd.DataFrame()
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    source = body_potential_source_audit[
        body_potential_source_audit["coefficient"].astype(str).isin({"A33", "A53"})
        & body_potential_source_audit["mode_column"].astype(str).eq("heave")
    ].copy()
    route_mask = (
        comparison.get("provider_route", pd.Series("", index=comparison.index))
        .astype(str)
        .eq("matched_bie_station_sweep")
    )
    matched = comparison[comparison["coefficient"].astype(str).isin({"A33", "A53"}) & route_mask].copy()
    if source.empty or matched.empty:
        detail = pd.DataFrame()
        summary = pd.DataFrame()
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    def numeric(row: pd.Series, column: str, default: float = float("nan")) -> float:
        if column not in row:
            return default
        try:
            return float(row[column])
        except (TypeError, ValueError):
            return default

    comparison_by_coefficient = {
        str(row["coefficient"]): row
        for _, row in matched.iterrows()
        if "coefficient" in row
    }

    detail_rows: list[dict[str, float | str | int]] = []
    summary_rows: list[dict[str, float | str | int]] = []
    for coefficient, group in source.groupby("coefficient", sort=False):
        coefficient_name = str(coefficient)
        comp = comparison_by_coefficient.get(coefficient_name)
        if comp is None:
            continue
        ordered = group.copy()
        ordered["x_m_numeric"] = pd.to_numeric(ordered["x_m"], errors="coerce")
        ordered = ordered[np.isfinite(ordered["x_m_numeric"])].sort_values("x_m_numeric").reset_index(drop=True)
        if ordered.empty:
            continue
        x = ordered["x_m_numeric"].to_numpy(dtype=float)
        weights = _trapezoid_station_weights(x)
        time_density = pd.to_numeric(ordered["time_derivative_density_value_per_m"], errors="coerce").to_numpy(
            dtype=float
        )
        contribution = time_density * weights
        abs_contribution = np.abs(contribution)
        abs_sum = float(np.nansum(abs_contribution))
        net = float(np.nansum(contribution))
        positive = float(np.nansum(np.maximum(contribution, 0.0)))
        negative = float(np.nansum(np.minimum(contribution, 0.0)))
        cancellation = float((positive + abs(negative)) / max(abs(net), 1e-300)) if abs_sum > 0.0 else 0.0
        peak_index = int(np.nanargmax(abs_contribution)) if abs_contribution.size else 0
        x_over_l = pd.to_numeric(ordered["x_over_l"], errors="coerce").to_numpy(dtype=float)
        centroid = (
            float(np.nansum(abs_contribution * x_over_l) / max(abs_sum, 1e-300))
            if abs_sum > 0.0
            else float("nan")
        )
        reference = numeric(comp, "reference_value")
        computed = numeric(comp, "computed_value")
        gate_ratio = numeric(comp, "gate_error_ratio")
        time_component = numeric(comp, "matched_time_derivative_component_value")
        integral_residual = net - time_component if np.isfinite(time_component) else float("nan")
        required_scale = reference / net if abs(net) > 1e-300 and np.isfinite(reference) else float("nan")
        computed_over_reference = computed / reference if abs(reference) > 1e-300 else float("nan")
        source_class = (
            "open_section_time_pressure_scale_blocker"
            if str(comp.get("status", "")) == "FAIL"
            else "open_section_time_pressure_regression_guard"
        )
        for station_index, (_, station) in enumerate(ordered.iterrows()):
            area = numeric(station, "submerged_area_m2")
            beam = numeric(station, "waterplane_beam_m")
            body_velocity_norm = numeric(station, "body_normal_velocity_norm")
            body_potential_norm = numeric(station, "body_potential_norm")
            free_potential_norm = numeric(station, "free_surface_potential_norm")
            free_normal_norm = numeric(station, "inner_free_surface_normal_derivative_norm")
            control_potential_norm = numeric(station, "control_potential_norm")
            pressure_time_norm = numeric(station, "body_pressure_time_derivative_norm")
            density = float(time_density[station_index])
            station_contribution = float(contribution[station_index])
            share = float(abs(station_contribution) / max(abs_sum, 1e-300)) if abs_sum > 0.0 else float("nan")
            detail_rows.append(
                {
                    "benchmark": benchmark,
                    "coefficient": coefficient_name,
                    "source_row": int(numeric(station, "source_row", -1)),
                    "station_index": int(numeric(station, "station_index", station_index)),
                    "x_m": float(x[station_index]),
                    "x_over_l": numeric(station, "x_over_l"),
                    "waterplane_beam_m": beam,
                    "effective_draft_m": numeric(station, "effective_draft_m"),
                    "submerged_area_m2": area,
                    "body_normal_velocity_norm": body_velocity_norm,
                    "body_potential_norm": body_potential_norm,
                    "body_potential_to_body_normal_velocity_gain": numeric(
                        station,
                        "body_potential_to_body_normal_velocity_gain",
                    ),
                    "body_potential_norm_to_submerged_area_ratio": numeric(
                        station,
                        "body_potential_norm_to_submerged_area_ratio",
                    ),
                    "free_surface_potential_norm": free_potential_norm,
                    "control_potential_norm": control_potential_norm,
                    "inner_free_surface_normal_derivative_norm": free_normal_norm,
                    "free_surface_potential_to_body_potential_ratio": (
                        float(free_potential_norm / body_potential_norm)
                        if np.isfinite(free_potential_norm)
                        and np.isfinite(body_potential_norm)
                        and abs(body_potential_norm) > 1e-300
                        else float("nan")
                    ),
                    "control_potential_to_body_potential_ratio": (
                        float(control_potential_norm / body_potential_norm)
                        if np.isfinite(control_potential_norm)
                        and np.isfinite(body_potential_norm)
                        and abs(body_potential_norm) > 1e-300
                        else float("nan")
                    ),
                    "inner_free_surface_normal_derivative_to_body_normal_velocity_ratio": (
                        float(free_normal_norm / body_velocity_norm)
                        if np.isfinite(free_normal_norm)
                        and np.isfinite(body_velocity_norm)
                        and abs(body_velocity_norm) > 1e-300
                        else float("nan")
                    ),
                    "time_pressure_to_body_potential_gain": (
                        float(pressure_time_norm / body_potential_norm)
                        if np.isfinite(pressure_time_norm)
                        and np.isfinite(body_potential_norm)
                        and abs(body_potential_norm) > 1e-300
                        else float("nan")
                    ),
                    "time_derivative_pressure_norm": pressure_time_norm,
                    "time_derivative_density_value_per_m": density,
                    "time_derivative_density_per_submerged_area": (
                        float(density / area) if np.isfinite(area) and abs(area) > 1e-300 else float("nan")
                    ),
                    "time_derivative_density_per_beam": (
                        float(density / beam) if np.isfinite(beam) and abs(beam) > 1e-300 else float("nan")
                    ),
                    "station_trapezoid_weight_m": float(weights[station_index]),
                    "station_time_derivative_contribution_value": station_contribution,
                    "station_abs_contribution_share": share,
                    "station_contribution_sign": (
                        "positive" if station_contribution > 0.0 else "negative" if station_contribution < 0.0 else "zero"
                    ),
                    "station_scale_flag": (
                        "peak_abs_time_contribution_station"
                        if station_index == peak_index
                        else "large_abs_time_contribution_station"
                        if share >= 0.10
                        else "background_station"
                    ),
                    "coefficient_reference_value": reference,
                    "coefficient_computed_value": computed,
                    "coefficient_gate_error_ratio": gate_ratio,
                    "coefficient_status": str(comp.get("status", "")),
                    "coefficient_time_component_value": time_component,
                    "station_integral_time_component_value": net,
                    "station_integral_minus_reported_time_component": integral_residual,
                    "required_global_scale_to_reference_from_time_integral": required_scale,
                    "computed_over_reference": computed_over_reference,
                    "failure_source": source_class,
                    "gate_role": "diagnostic_heave_time_pressure_station_scale_not_hard_gate",
                }
            )
        peak_row = ordered.iloc[peak_index]
        peak_area_density = float(
            time_density[peak_index] / max(numeric(peak_row, "submerged_area_m2"), 1e-300)
        )
        free_to_body = pd.to_numeric(
            ordered["free_surface_potential_norm"],
            errors="coerce",
        ) / pd.to_numeric(ordered["body_potential_norm"], errors="coerce").replace(0.0, np.nan)
        control_to_body = pd.to_numeric(
            ordered["control_potential_norm"],
            errors="coerce",
        ) / pd.to_numeric(ordered["body_potential_norm"], errors="coerce").replace(0.0, np.nan)
        free_normal_to_body_velocity = pd.to_numeric(
            ordered["inner_free_surface_normal_derivative_norm"],
            errors="coerce",
        ) / pd.to_numeric(ordered["body_normal_velocity_norm"], errors="coerce").replace(0.0, np.nan)
        summary_rows.append(
            {
                "benchmark": benchmark,
                "coefficient": coefficient_name,
                "station_count": int(len(ordered)),
                "reference_value": reference,
                "computed_value": computed,
                "gate_error_ratio": gate_ratio,
                "coefficient_status": str(comp.get("status", "")),
                "time_component_value": time_component,
                "station_integral_time_component_value": net,
                "station_integral_closure_residual": integral_residual,
                "positive_time_contribution_integral": positive,
                "negative_time_contribution_integral": negative,
                "time_contribution_abs_integral": abs_sum,
                "time_contribution_cancellation_index": cancellation,
                "peak_abs_station_index": int(numeric(peak_row, "station_index", peak_index)),
                "peak_abs_station_x_over_l": numeric(peak_row, "x_over_l"),
                "peak_abs_station_time_density_value_per_m": float(time_density[peak_index]),
                "peak_abs_station_contribution_value": float(contribution[peak_index]),
                "peak_abs_station_contribution_share": (
                    float(abs_contribution[peak_index] / max(abs_sum, 1e-300)) if abs_sum > 0.0 else float("nan")
                ),
                "time_contribution_abs_centroid_x_over_l": centroid,
                "max_body_potential_to_body_normal_velocity_gain": float(
                    pd.to_numeric(ordered["body_potential_to_body_normal_velocity_gain"], errors="coerce").max()
                ),
                "max_body_potential_norm_to_submerged_area_ratio": float(
                    pd.to_numeric(ordered["body_potential_norm_to_submerged_area_ratio"], errors="coerce").max()
                ),
                "max_free_surface_potential_to_body_potential_ratio": (
                    float(free_to_body.max()) if free_to_body.notna().any() else float("nan")
                ),
                "max_control_potential_to_body_potential_ratio": (
                    float(control_to_body.max()) if control_to_body.notna().any() else float("nan")
                ),
                "max_inner_free_surface_normal_derivative_to_body_normal_velocity_ratio": (
                    float(free_normal_to_body_velocity.max())
                    if free_normal_to_body_velocity.notna().any()
                    else float("nan")
                ),
                "peak_time_density_per_submerged_area": peak_area_density,
                "required_global_scale_to_reference_from_time_integral": required_scale,
                "computed_over_reference": computed_over_reference,
                "failure_source": source_class,
                "diagnostic_conclusion": (
                    "A33_A53_time_pressure_integral_is_closed_but_over_scaled_in_open_section_station_chain"
                    if str(comp.get("status", "")) == "FAIL"
                    else "heave_time_pressure_station_chain_passes_current_gate"
                ),
                "remaining_blocker": (
                    "Audit matched open-section/free-surface heave body-potential scale and generalized force row; "
                    "do not apply the closed-cylinder pressure-sign correction unless the complete Wigley III Gate 1 passes."
                ),
                "gate_role": "diagnostic_heave_time_pressure_station_scale_not_hard_gate",
            }
        )
    detail = pd.DataFrame(detail_rows)
    summary = pd.DataFrame(summary_rows)
    detail.to_csv(detail_path, index=False)
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _write_ma2005_heave_free_normal_to_body_potential_audit(
    body_potential_source_audit: pd.DataFrame,
    comparison: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Write a focused A33/A53 audit for free-surface normal derivative transmission."""

    detail_path = out_dir / f"{benchmark}_heave_free_normal_to_body_potential_audit.csv"
    summary_path = out_dir / f"{benchmark}_heave_free_normal_to_body_potential_summary.csv"
    if body_potential_source_audit.empty or comparison.empty:
        detail = pd.DataFrame()
        summary = pd.DataFrame()
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    source = body_potential_source_audit[
        body_potential_source_audit["coefficient"].astype(str).isin({"A33", "A53"})
        & body_potential_source_audit["mode_column"].astype(str).eq("heave")
    ].copy()
    route_mask = (
        comparison.get("provider_route", pd.Series("", index=comparison.index))
        .astype(str)
        .eq("matched_bie_station_sweep")
    )
    matched = comparison[comparison["coefficient"].astype(str).isin({"A33", "A53"}) & route_mask].copy()
    if source.empty or matched.empty:
        detail = pd.DataFrame()
        summary = pd.DataFrame()
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    def numeric(row: pd.Series, column: str, default: float = float("nan")) -> float:
        if column not in row:
            return default
        try:
            return float(row[column])
        except (TypeError, ValueError):
            return default

    def safe_ratio(numerator: float, denominator: float) -> float:
        if not np.isfinite(numerator) or not np.isfinite(denominator):
            return float("nan")
        if abs(denominator) <= 1e-300:
            return 0.0 if abs(numerator) <= 1e-300 else float(numerator / 1e-300)
        return float(numerator / denominator)

    def finite_median(values: np.ndarray) -> float:
        finite = values[np.isfinite(values)]
        if finite.size == 0:
            return float("nan")
        return float(np.median(finite))

    def finite_peak_index(values: np.ndarray) -> int:
        if values.size == 0:
            return 0
        finite = np.isfinite(values)
        if not finite.any():
            return 0
        ranked = np.where(finite, values, -np.inf)
        return int(np.argmax(ranked))

    comparison_by_coefficient = {
        str(row["coefficient"]): row
        for _, row in matched.iterrows()
        if "coefficient" in row
    }

    detail_rows: list[dict[str, float | str | int]] = []
    summary_rows: list[dict[str, float | str | int]] = []
    for coefficient, group in source.groupby("coefficient", sort=False):
        coefficient_name = str(coefficient)
        comp = comparison_by_coefficient.get(coefficient_name)
        if comp is None:
            continue
        ordered = group.copy()
        ordered["x_m_numeric"] = pd.to_numeric(ordered["x_m"], errors="coerce")
        ordered = ordered[np.isfinite(ordered["x_m_numeric"])].sort_values("x_m_numeric").reset_index(drop=True)
        if ordered.empty:
            continue

        x = ordered["x_m_numeric"].to_numpy(dtype=float)
        x_over_l = pd.to_numeric(ordered["x_over_l"], errors="coerce").to_numpy(dtype=float)
        weights = _trapezoid_station_weights(x)
        body_velocity = pd.to_numeric(ordered["body_normal_velocity_norm"], errors="coerce").to_numpy(dtype=float)
        free_normal = pd.to_numeric(
            ordered["inner_free_surface_normal_derivative_norm"],
            errors="coerce",
        ).to_numpy(dtype=float)
        body_phi = pd.to_numeric(ordered["body_potential_norm"], errors="coerce").to_numpy(dtype=float)
        free_phi = pd.to_numeric(ordered["free_surface_potential_norm"], errors="coerce").to_numpy(dtype=float)
        control_phi = pd.to_numeric(ordered["control_potential_norm"], errors="coerce").to_numpy(dtype=float)
        time_density = pd.to_numeric(
            ordered["time_derivative_density_value_per_m"],
            errors="coerce",
        ).to_numpy(dtype=float)
        contribution = time_density * weights
        abs_contribution = np.abs(contribution)
        abs_sum = float(np.nansum(abs_contribution))
        abs_share = abs_contribution / max(abs_sum, 1e-300) if abs_sum > 0.0 else np.full_like(abs_contribution, np.nan)
        free_normal_to_velocity = np.asarray(
            [safe_ratio(free_normal[i], body_velocity[i]) for i in range(len(ordered))],
            dtype=float,
        )
        body_phi_to_free_normal = np.asarray(
            [safe_ratio(body_phi[i], free_normal[i]) for i in range(len(ordered))],
            dtype=float,
        )
        body_phi_to_velocity = np.asarray(
            [safe_ratio(body_phi[i], body_velocity[i]) for i in range(len(ordered))],
            dtype=float,
        )
        free_phi_to_body_phi = np.asarray(
            [safe_ratio(free_phi[i], body_phi[i]) for i in range(len(ordered))],
            dtype=float,
        )
        control_phi_to_body_phi = np.asarray(
            [safe_ratio(control_phi[i], body_phi[i]) for i in range(len(ordered))],
            dtype=float,
        )
        free_normal_peak_index = finite_peak_index(free_normal_to_velocity)
        body_phi_gain_peak_index = finite_peak_index(body_phi_to_free_normal)
        body_velocity_gain_peak_index = finite_peak_index(body_phi_to_velocity)
        time_peak_index = finite_peak_index(abs_contribution)
        finite_corr = np.isfinite(free_normal_to_velocity) & np.isfinite(abs_share)
        if (
            int(finite_corr.sum()) > 1
            and float(np.nanstd(free_normal_to_velocity[finite_corr])) > 0.0
            and float(np.nanstd(abs_share[finite_corr])) > 0.0
        ):
            free_normal_share_corr = float(
                np.corrcoef(free_normal_to_velocity[finite_corr], abs_share[finite_corr])[0, 1]
            )
        else:
            free_normal_share_corr = float("nan")

        reference = numeric(comp, "reference_value")
        computed = numeric(comp, "computed_value")
        gate_ratio = numeric(comp, "gate_error_ratio")
        time_component = numeric(comp, "matched_time_derivative_component_value")
        station_integral = float(np.nansum(contribution))
        required_scale = (
            float(reference / station_integral)
            if np.isfinite(reference) and abs(station_integral) > 1e-300
            else float("nan")
        )
        free_normal_peak_x = float(x_over_l[free_normal_peak_index]) if x_over_l.size else float("nan")
        time_peak_x = float(x_over_l[time_peak_index]) if x_over_l.size else float("nan")
        peak_colocated = (
            bool(np.isfinite(free_normal_peak_x) and np.isfinite(time_peak_x) and abs(free_normal_peak_x - time_peak_x) <= 0.05)
        )
        max_free_normal_ratio = (
            float(np.nanmax(free_normal_to_velocity))
            if np.isfinite(free_normal_to_velocity).any()
            else float("nan")
        )
        if np.isfinite(max_free_normal_ratio) and max_free_normal_ratio > 5.0 and peak_colocated:
            conclusion = "free_normal_gain_colocates_with_peak_time_pressure"
        elif np.isfinite(max_free_normal_ratio) and max_free_normal_ratio > 5.0:
            conclusion = "free_normal_gain_is_large_but_not_colocated_with_peak_time_pressure"
        else:
            conclusion = "free_normal_gain_not_primary_scale_explanation"

        for station_position, (_, station) in enumerate(ordered.iterrows()):
            flags: list[str] = []
            if station_position == free_normal_peak_index:
                flags.append("peak_free_normal_to_body_velocity_station")
            if station_position == body_phi_gain_peak_index:
                flags.append("peak_body_potential_to_free_normal_station")
            if station_position == body_velocity_gain_peak_index:
                flags.append("peak_body_potential_to_body_velocity_station")
            if station_position == time_peak_index:
                flags.append("peak_abs_time_contribution_station")
            detail_rows.append(
                {
                    "benchmark": benchmark,
                    "coefficient": coefficient_name,
                    "source_row": int(numeric(station, "source_row", -1)),
                    "station_index": int(numeric(station, "station_index", station_position)),
                    "x_m": float(x[station_position]),
                    "x_over_l": numeric(station, "x_over_l"),
                    "body_normal_velocity_norm": float(body_velocity[station_position]),
                    "inner_free_surface_normal_derivative_norm": float(free_normal[station_position]),
                    "body_potential_norm": float(body_phi[station_position]),
                    "free_surface_potential_norm": float(free_phi[station_position]),
                    "control_potential_norm": float(control_phi[station_position]),
                    "inner_free_surface_normal_derivative_to_body_normal_velocity_ratio": float(
                        free_normal_to_velocity[station_position]
                    ),
                    "body_potential_to_inner_free_surface_normal_derivative_gain": float(
                        body_phi_to_free_normal[station_position]
                    ),
                    "body_potential_to_body_normal_velocity_gain": float(body_phi_to_velocity[station_position]),
                    "free_surface_potential_to_body_potential_ratio": float(free_phi_to_body_phi[station_position]),
                    "control_potential_to_body_potential_ratio": float(control_phi_to_body_phi[station_position]),
                    "time_derivative_density_value_per_m": float(time_density[station_position]),
                    "station_trapezoid_weight_m": float(weights[station_position]),
                    "station_time_derivative_contribution_value": float(contribution[station_position]),
                    "station_abs_contribution_share": float(abs_share[station_position]),
                    "coefficient_reference_value": reference,
                    "coefficient_computed_value": computed,
                    "coefficient_gate_error_ratio": gate_ratio,
                    "coefficient_status": str(comp.get("status", "")),
                    "coefficient_time_component_value": time_component,
                    "station_integral_time_component_value": station_integral,
                    "required_global_scale_to_reference_from_time_integral": required_scale,
                    "diagnostic_flags": "|".join(flags) if flags else "background_station",
                    "failure_source": "free_normal_to_body_potential_scale_suspect",
                    "gate_role": "diagnostic_free_normal_to_body_potential_not_hard_gate",
                }
            )

        summary_rows.append(
            {
                "benchmark": benchmark,
                "coefficient": coefficient_name,
                "station_count": int(len(ordered)),
                "reference_value": reference,
                "computed_value": computed,
                "gate_error_ratio": gate_ratio,
                "coefficient_status": str(comp.get("status", "")),
                "time_component_value": time_component,
                "station_integral_time_component_value": station_integral,
                "required_global_scale_to_reference_from_time_integral": required_scale,
                "max_inner_free_surface_normal_derivative_to_body_normal_velocity_ratio": max_free_normal_ratio,
                "median_inner_free_surface_normal_derivative_to_body_normal_velocity_ratio": finite_median(
                    free_normal_to_velocity
                ),
                "max_free_normal_ratio_station_index": int(numeric(ordered.iloc[free_normal_peak_index], "station_index")),
                "max_free_normal_ratio_x_over_l": free_normal_peak_x,
                "max_body_potential_to_inner_free_surface_normal_derivative_gain": (
                    float(np.nanmax(body_phi_to_free_normal))
                    if np.isfinite(body_phi_to_free_normal).any()
                    else float("nan")
                ),
                "median_body_potential_to_inner_free_surface_normal_derivative_gain": finite_median(
                    body_phi_to_free_normal
                ),
                "max_body_potential_to_inner_free_surface_normal_derivative_gain_x_over_l": (
                    float(x_over_l[body_phi_gain_peak_index]) if x_over_l.size else float("nan")
                ),
                "max_body_potential_to_body_normal_velocity_gain": (
                    float(np.nanmax(body_phi_to_velocity))
                    if np.isfinite(body_phi_to_velocity).any()
                    else float("nan")
                ),
                "median_body_potential_to_body_normal_velocity_gain": finite_median(body_phi_to_velocity),
                "max_free_surface_potential_to_body_potential_ratio": (
                    float(np.nanmax(free_phi_to_body_phi))
                    if np.isfinite(free_phi_to_body_phi).any()
                    else float("nan")
                ),
                "max_control_potential_to_body_potential_ratio": (
                    float(np.nanmax(control_phi_to_body_phi))
                    if np.isfinite(control_phi_to_body_phi).any()
                    else float("nan")
                ),
                "peak_abs_time_contribution_station_index": int(numeric(ordered.iloc[time_peak_index], "station_index")),
                "peak_abs_time_contribution_x_over_l": time_peak_x,
                "peak_abs_time_contribution_share": (
                    float(abs_share[time_peak_index]) if abs_share.size else float("nan")
                ),
                "free_normal_peak_matches_time_peak": "true" if peak_colocated else "false",
                "free_normal_ratio_to_abs_contribution_share_pearson": free_normal_share_corr,
                "failure_source": "free_normal_to_body_potential_scale_suspect",
                "diagnostic_conclusion": conclusion,
                "remaining_blocker": (
                    "Audit Eq.23/Eq.24 free-surface normal-derivative units, inner/free/control matching signs, "
                    "and station marching initialization before applying any production scale or sign correction."
                ),
                "gate_role": "diagnostic_free_normal_to_body_potential_not_hard_gate",
            }
        )

    detail = pd.DataFrame(detail_rows)
    summary = pd.DataFrame(summary_rows)
    detail.to_csv(detail_path, index=False)
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _write_ma2005_pressure_gradient_startup_spike_audit(
    body_potential_source_audit: pd.DataFrame,
    comparison: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Write a station-integral audit for the first-active-station pressure-gradient spike."""

    detail_path = out_dir / f"{benchmark}_pressure_gradient_startup_spike_audit.csv"
    summary_path = out_dir / f"{benchmark}_pressure_gradient_startup_spike_summary.csv"
    if body_potential_source_audit.empty or comparison.empty:
        detail = pd.DataFrame()
        summary = pd.DataFrame()
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    route_mask = (
        comparison.get("provider_route", pd.Series("", index=comparison.index))
        .astype(str)
        .eq("matched_bie_station_sweep")
    )
    matched = comparison[route_mask].copy()
    if matched.empty:
        detail = pd.DataFrame()
        summary = pd.DataFrame()
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    def numeric(row: pd.Series, column: str, default: float = float("nan")) -> float:
        if column not in row:
            return default
        try:
            return float(row[column])
        except (TypeError, ValueError):
            return default

    def finite_peak_index(values: np.ndarray) -> int:
        if values.size == 0:
            return 0
        finite = np.isfinite(values)
        if not finite.any():
            return 0
        ranked = np.where(finite, values, -np.inf)
        return int(np.argmax(ranked))

    def safe_gate_ratio(value: float, reference: float, effective_abs_tolerance: float) -> float:
        if (
            not np.isfinite(value)
            or not np.isfinite(reference)
            or not np.isfinite(effective_abs_tolerance)
            or effective_abs_tolerance <= 0.0
        ):
            return float("nan")
        return float(abs(value - reference) / effective_abs_tolerance)

    comparison_by_coefficient = {
        str(row["coefficient"]): row
        for _, row in matched.iterrows()
        if "coefficient" in row
    }

    detail_rows: list[dict[str, float | str | int]] = []
    summary_rows: list[dict[str, float | str | int]] = []
    for coefficient, group in body_potential_source_audit.groupby("coefficient", sort=False):
        coefficient_name = str(coefficient)
        comp = comparison_by_coefficient.get(coefficient_name)
        if comp is None:
            continue
        reported_gradient = numeric(comp, "matched_pressure_gradient_component_value")
        if not np.isfinite(reported_gradient):
            continue

        ordered = group.copy()
        ordered["x_m_numeric"] = pd.to_numeric(ordered["x_m"], errors="coerce")
        ordered = ordered[np.isfinite(ordered["x_m_numeric"])].sort_values("x_m_numeric").reset_index(drop=True)
        if ordered.empty:
            continue
        x = ordered["x_m_numeric"].to_numpy(dtype=float)
        x_over_l = pd.to_numeric(ordered["x_over_l"], errors="coerce").to_numpy(dtype=float)
        weights = _trapezoid_station_weights(x)
        gradient_density = pd.to_numeric(
            ordered["pressure_gradient_density_value_per_m"],
            errors="coerce",
        ).to_numpy(dtype=float)
        gradient_gain_l = pd.to_numeric(
            ordered["body_potential_x_gradient_gain_times_l"],
            errors="coerce",
        ).to_numpy(dtype=float)
        body_jump = pd.to_numeric(
            ordered.get("body_potential_adjacent_relative_jump", pd.Series(np.nan, index=ordered.index)),
            errors="coerce",
        ).to_numpy(dtype=float)
        contribution = gradient_density * weights
        abs_contribution = np.abs(contribution)
        abs_sum = float(np.nansum(abs_contribution))
        net = float(np.nansum(contribution))
        positive = float(np.nansum(np.maximum(contribution, 0.0)))
        negative = float(np.nansum(np.minimum(contribution, 0.0)))
        cancellation = (
            float((positive + abs(negative)) / max(abs(net), 1e-300))
            if abs_sum > 0.0
            else float("nan")
        )
        abs_share = abs_contribution / max(abs_sum, 1e-300) if abs_sum > 0.0 else np.zeros_like(abs_contribution)
        peak_index = finite_peak_index(abs_contribution)
        first_index = 0
        second_index = 1 if len(ordered) > 1 else 0
        first_contribution = float(contribution[first_index])
        second_contribution = float(contribution[second_index]) if len(ordered) > 1 else float("nan")
        first_two_contribution = float(np.nansum(contribution[: min(2, len(contribution))]))
        rest_after_first = float(net - first_contribution)
        rest_after_first_two = float(net - first_two_contribution)
        reference = numeric(comp, "reference_value")
        computed = numeric(comp, "computed_value")
        effective_abs_tolerance = numeric(comp, "effective_abs_tolerance")
        current_gate_ratio = numeric(comp, "gate_error_ratio")
        without_first_value = computed - first_contribution if np.isfinite(computed) else float("nan")
        without_first_two_value = computed - first_two_contribution if np.isfinite(computed) else float("nan")
        without_first_gate_ratio = safe_gate_ratio(without_first_value, reference, effective_abs_tolerance)
        without_first_two_gate_ratio = safe_gate_ratio(without_first_two_value, reference, effective_abs_tolerance)
        centroid = (
            float(np.nansum(abs_contribution * x_over_l) / max(abs_sum, 1e-300))
            if abs_sum > 0.0
            else float("nan")
        )
        closure_residual = net - reported_gradient
        first_is_peak = bool(first_index == peak_index)
        first_two_contains_peak = bool(peak_index < 2)
        if first_is_peak and abs_share[first_index] >= 0.25:
            conclusion = "first_active_station_dominates_pressure_gradient_integral"
        elif first_two_contains_peak and float(np.nansum(abs_share[: min(2, len(abs_share))])) >= 0.25:
            conclusion = "first_two_active_stations_dominate_pressure_gradient_integral"
        elif first_is_peak:
            conclusion = "first_active_station_is_peak_but_not_dominant"
        else:
            conclusion = "pressure_gradient_peak_not_limited_to_startup_station"
        if np.isfinite(without_first_gate_ratio) and without_first_gate_ratio <= 1.0:
            diagnostic_candidate_status = "without_first_station_would_pass_this_coefficient_only"
        elif np.isfinite(without_first_two_gate_ratio) and without_first_two_gate_ratio <= 1.0:
            diagnostic_candidate_status = "without_first_two_stations_would_pass_this_coefficient_only"
        else:
            diagnostic_candidate_status = "startup_removal_does_not_pass_this_coefficient"

        for station_position, (_, station) in enumerate(ordered.iterrows()):
            flags: list[str] = []
            if station_position == first_index:
                flags.append("first_active_station")
            if station_position == second_index and len(ordered) > 1:
                flags.append("second_active_station")
            if station_position == peak_index:
                flags.append("peak_abs_pressure_gradient_contribution_station")
            if abs_sum > 0.0 and np.isfinite(abs_share[station_position]) and float(abs_share[station_position]) >= 0.10:
                flags.append("large_abs_pressure_gradient_contribution_station")
            detail_rows.append(
                {
                    "benchmark": benchmark,
                    "coefficient": coefficient_name,
                    "source_row": int(numeric(station, "source_row", -1)),
                    "station_index": int(numeric(station, "station_index", station_position)),
                    "x_m": float(x[station_position]),
                    "x_over_l": numeric(station, "x_over_l"),
                    "station_trapezoid_weight_m": float(weights[station_position]),
                    "pressure_gradient_density_value_per_m": float(gradient_density[station_position]),
                    "station_pressure_gradient_contribution_value": float(contribution[station_position]),
                    "station_abs_pressure_gradient_contribution_share": float(abs_share[station_position]),
                    "station_signed_pressure_gradient_contribution_share_of_net": (
                        float(contribution[station_position] / net) if abs(net) > 1e-300 else float("nan")
                    ),
                    "body_potential_x_gradient_gain_times_l": float(gradient_gain_l[station_position]),
                    "body_potential_adjacent_relative_jump": float(body_jump[station_position]),
                    "reported_pressure_gradient_component_value": reported_gradient,
                    "station_integral_pressure_gradient_value": net,
                    "station_integral_minus_reported_pressure_gradient_component": closure_residual,
                    "current_computed_value": computed,
                    "reference_value": reference,
                    "current_gate_error_ratio": current_gate_ratio,
                    "without_first_station_computed_value": without_first_value,
                    "without_first_station_gate_error_ratio": without_first_gate_ratio,
                    "without_first_two_stations_computed_value": without_first_two_value,
                    "without_first_two_stations_gate_error_ratio": without_first_two_gate_ratio,
                    "diagnostic_flags": "|".join(flags) if flags else "background_station",
                    "diagnostic_candidate_status": diagnostic_candidate_status,
                    "failure_source": "first_active_station_pressure_gradient_spike",
                    "gate_role": "diagnostic_pressure_gradient_startup_spike_not_hard_gate",
                }
            )

        summary_rows.append(
            {
                "benchmark": benchmark,
                "coefficient": coefficient_name,
                "station_count": int(len(ordered)),
                "reference_value": reference,
                "current_computed_value": computed,
                "current_gate_error_ratio": current_gate_ratio,
                "coefficient_status": str(comp.get("status", "")),
                "reported_pressure_gradient_component_value": reported_gradient,
                "station_integral_pressure_gradient_value": net,
                "station_integral_closure_residual": closure_residual,
                "positive_pressure_gradient_contribution_integral": positive,
                "negative_pressure_gradient_contribution_integral": negative,
                "pressure_gradient_abs_integral": abs_sum,
                "pressure_gradient_cancellation_index": cancellation,
                "first_station_index": int(numeric(ordered.iloc[first_index], "station_index", first_index)),
                "first_station_x_over_l": float(x_over_l[first_index]) if x_over_l.size else float("nan"),
                "first_station_pressure_gradient_density_value_per_m": float(gradient_density[first_index]),
                "first_station_pressure_gradient_contribution_value": first_contribution,
                "first_station_abs_contribution_share": float(abs_share[first_index]),
                "second_station_index": int(numeric(ordered.iloc[second_index], "station_index", second_index)),
                "second_station_x_over_l": float(x_over_l[second_index]) if x_over_l.size else float("nan"),
                "second_station_pressure_gradient_density_value_per_m": float(gradient_density[second_index]),
                "second_station_pressure_gradient_contribution_value": second_contribution,
                "second_station_abs_contribution_share": float(abs_share[second_index]),
                "first_two_station_pressure_gradient_contribution_value": first_two_contribution,
                "first_two_station_abs_contribution_share": float(np.nansum(abs_share[: min(2, len(abs_share))])),
                "rest_after_first_station_pressure_gradient_contribution_value": rest_after_first,
                "rest_after_first_two_stations_pressure_gradient_contribution_value": rest_after_first_two,
                "peak_abs_station_index": int(numeric(ordered.iloc[peak_index], "station_index", peak_index)),
                "peak_abs_station_x_over_l": float(x_over_l[peak_index]) if x_over_l.size else float("nan"),
                "peak_abs_station_pressure_gradient_density_value_per_m": float(gradient_density[peak_index]),
                "peak_abs_station_pressure_gradient_contribution_value": float(contribution[peak_index]),
                "peak_abs_station_contribution_share": float(abs_share[peak_index]),
                "peak_abs_station_body_potential_x_gradient_gain_times_l": float(gradient_gain_l[peak_index]),
                "pressure_gradient_abs_centroid_x_over_l": centroid,
                "first_station_is_peak_abs_contribution": "true" if first_is_peak else "false",
                "first_two_stations_contain_peak_abs_contribution": "true" if first_two_contains_peak else "false",
                "without_first_station_computed_value": without_first_value,
                "without_first_station_gate_error_ratio": without_first_gate_ratio,
                "without_first_station_gate_status": (
                    "PASS" if np.isfinite(without_first_gate_ratio) and without_first_gate_ratio <= 1.0 else "FAIL"
                ),
                "without_first_two_stations_computed_value": without_first_two_value,
                "without_first_two_stations_gate_error_ratio": without_first_two_gate_ratio,
                "without_first_two_stations_gate_status": (
                    "PASS"
                    if np.isfinite(without_first_two_gate_ratio) and without_first_two_gate_ratio <= 1.0
                    else "FAIL"
                ),
                "diagnostic_candidate_status": diagnostic_candidate_status,
                "diagnostic_conclusion": conclusion,
                "remaining_blocker": (
                    "Audit longitudinal body-potential derivative stencil, startup/ghost station treatment, "
                    "and Eq.30 forward-speed pressure-gradient sign/phase before applying any station removal "
                    "or smoothing to the production path."
                ),
                "failure_source": "first_active_station_pressure_gradient_spike",
                "gate_role": "diagnostic_pressure_gradient_startup_spike_not_hard_gate",
            }
        )

    detail = pd.DataFrame(detail_rows)
    summary = pd.DataFrame(summary_rows)
    detail.to_csv(detail_path, index=False)
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _ma2005_matched_station_transfer_path_rows(
    hydro: Any,
    *,
    benchmark: str,
    source_row: int,
    hull: str,
    speed_case: str,
    omega_e_sqrt_l_over_g: float,
    coefficient: str,
    prefix: str,
    row_idx: int,
    col_idx: int,
    normalization_scale: float,
    omega_rad_s: float,
    reference_value: float,
) -> list[dict[str, float | str]]:
    """Return adjacent-station rows for the free-surface/body/gradient pressure path."""

    hp_row = _ma2005_longitudinal_matrix_index(row_idx)
    hp_col = _ma2005_longitudinal_matrix_index(col_idx)
    if hp_row is None or hp_col is None:
        return []
    breakdown = hydro.contribution_breakdown
    x_m = np.asarray(breakdown.get("station_x_m", np.asarray([], dtype=float)), dtype=float)
    x_over_l = np.asarray(breakdown.get("station_x_over_l", np.asarray([], dtype=float)), dtype=float)
    if x_m.ndim != 2 or x_m.shape[0] < 1 or x_m.shape[1] < 2:
        return []
    station_count = x_m.shape[1]
    if x_over_l.ndim != 2 or x_over_l.shape[0] < 1 or x_over_l.shape[1] != station_count:
        x_over_l = np.full_like(x_m, np.nan, dtype=float)
    scale = max(float(normalization_scale), 1e-300)
    mode_name = "heave" if hp_col == 0 else "pitch"
    row_name = "heave_force" if hp_row == 0 else "pitch_moment"

    def station_values(name: str) -> np.ndarray:
        value = np.asarray(breakdown.get(name, np.asarray([], dtype=float)), dtype=float)
        if value.ndim == 2 and value.shape[0] >= 1 and value.shape[1] == station_count:
            return value[0]
        if value.ndim == 1 and value.size == station_count:
            return value
        return np.full(station_count, np.nan, dtype=float)

    def adjacent_values(name: str) -> np.ndarray:
        value = np.asarray(breakdown.get(name, np.asarray([], dtype=float)), dtype=float)
        if value.ndim == 2 and value.shape[0] >= 1 and value.shape[1] == station_count - 1:
            return value[0]
        if value.ndim == 1 and value.size == station_count - 1:
            return value
        return np.full(station_count - 1, np.nan, dtype=float)

    def density_values(name: str) -> np.ndarray:
        density = np.asarray(breakdown.get(name, np.asarray([], dtype=complex)), dtype=complex)
        if density.ndim != 4 or density.shape[0] < 1 or density.shape[1] != station_count or density.shape[2:] != (2, 2):
            return np.full(station_count, np.nan, dtype=float)
        selected = density[0, :, hp_row, hp_col]
        return np.asarray(
            [
                _ma2005_force_component_to_coefficient_raw(value, prefix, omega_rad_s) / scale
                for value in selected
            ],
            dtype=float,
        )

    def safe_ratio(numerator: float, denominator: float) -> float:
        if not np.isfinite(numerator) or not np.isfinite(denominator):
            return float("nan")
        if abs(denominator) <= 1e-300:
            return 0.0 if abs(numerator) <= 1e-300 else float(numerator / 1e-300)
        return float(numerator / denominator)

    def pair_max_abs(left: float, right: float) -> float:
        values = [abs(value) for value in (left, right) if np.isfinite(value)]
        return float(max(values)) if values else float("nan")

    def sign_label(value: float) -> str:
        if not np.isfinite(value):
            return "nan"
        if value > 0.0:
            return "positive"
        if value < 0.0:
            return "negative"
        return "zero"

    free_norm = station_values(f"{mode_name}_free_surface_potential_norms")
    free_after_pressure_gain = station_values(f"{mode_name}_body_pressure_to_free_surface_potential_after_gains")
    inner_normal_norm = station_values(f"{mode_name}_inner_free_surface_normal_derivative_norms")
    increment_gain = station_values(f"{mode_name}_free_surface_potential_increment_to_normal_derivative_gains")
    body_norm = station_values(f"{mode_name}_body_potential_norms")
    gradient_norm = station_values(f"{mode_name}_body_potential_x_gradient_norms")
    gradient_gain_l = station_values(f"{mode_name}_body_potential_x_gradient_gain_times_hull_length")
    phase_aligned_gain_l = station_values(f"{mode_name}_phase_aligned_body_potential_x_gradient_gain_times_hull_length")
    phase_aligned_ratio = station_values(f"{mode_name}_phase_aligned_gradient_gain_to_raw_gain_ratios")
    forward_to_time = station_values(f"{mode_name}_body_pressure_forward_to_time_norm_ratios")
    central_gain_l = station_values(f"{mode_name}_central_body_potential_x_gradient_gain_times_hull_length")
    forward_gain_l = station_values(f"{mode_name}_forward_body_potential_x_gradient_gain_times_hull_length")
    backward_gain_l = station_values(f"{mode_name}_backward_body_potential_x_gradient_gain_times_hull_length")
    total_density = density_values("heave_pitch_total_force_density_by_station")
    time_density = density_values("heave_pitch_time_derivative_force_density_by_station")
    pressure_gradient_density = density_values("heave_pitch_forward_speed_force_density_by_station")
    stokes_density = density_values("heave_pitch_stokes_body_forward_speed_force_density_by_station")

    body_jump = adjacent_values(f"{mode_name}_adjacent_body_potential_relative_jumps")
    body_ratio = adjacent_values(f"{mode_name}_adjacent_body_potential_symmetric_norm_ratios")
    body_phase = adjacent_values(f"{mode_name}_adjacent_body_potential_phase_degs")
    body_alignment = adjacent_values(f"{mode_name}_adjacent_body_potential_real_alignments")
    phase_aligned_jump = adjacent_values(f"{mode_name}_phase_aligned_adjacent_body_potential_relative_jumps")
    phase_aligned_phase = adjacent_values(f"{mode_name}_phase_aligned_adjacent_body_potential_phase_degs")
    phase_aligned_alignment = adjacent_values(f"{mode_name}_phase_aligned_adjacent_body_potential_real_alignments")
    panel_mid_y_jump = adjacent_values("body_panel_mid_y_adjacent_relative_jumps")
    panel_mid_z_jump = adjacent_values("body_panel_mid_z_adjacent_relative_jumps")
    panel_normal_jump = adjacent_values("body_panel_normal_adjacent_relative_jumps")
    panel_length_jump = adjacent_values("body_panel_length_adjacent_relative_jumps")
    beam_jump = adjacent_values("station_waterplane_beam_adjacent_relative_jumps")
    draft_jump = adjacent_values("station_effective_draft_adjacent_relative_jumps")
    area_jump = adjacent_values("station_submerged_area_adjacent_relative_jumps")

    rows: list[dict[str, float | str]] = []
    for pair_index in range(station_count - 1):
        left = pair_index
        right = pair_index + 1
        dx = float(x_m[0, right] - x_m[0, left])
        pg_left = float(pressure_gradient_density[left])
        pg_right = float(pressure_gradient_density[right])
        pg_abs_pair = pair_max_abs(pg_left, pg_right)
        pg_sum = pg_left + pg_right if np.isfinite(pg_left) and np.isfinite(pg_right) else float("nan")
        pg_cancellation = (
            float((abs(pg_left) + abs(pg_right)) / max(abs(pg_sum), 1e-300))
            if np.isfinite(pg_sum)
            else float("nan")
        )
        gradient_gain_pair = pair_max_abs(float(gradient_gain_l[left]), float(gradient_gain_l[right]))
        phase_gain_pair = pair_max_abs(float(phase_aligned_gain_l[left]), float(phase_aligned_gain_l[right]))
        phase_ratio_pair = pair_max_abs(float(phase_aligned_ratio[left]), float(phase_aligned_ratio[right]))
        body_to_free_left = safe_ratio(float(body_norm[left]), float(free_norm[left]))
        body_to_free_right = safe_ratio(float(body_norm[right]), float(free_norm[right]))
        rows.append(
            {
                "benchmark": benchmark,
                "source_row": int(source_row),
                "hull": str(hull),
                "speed_case": str(speed_case),
                "omega_e_sqrt_l_over_g": float(omega_e_sqrt_l_over_g),
                "coefficient": str(coefficient),
                "reference_value": float(reference_value),
                "mode_column": mode_name,
                "generalized_row": row_name,
                "pair_index": int(pair_index),
                "left_station_index": int(left),
                "right_station_index": int(right),
                "x_left_m": float(x_m[0, left]),
                "x_right_m": float(x_m[0, right]),
                "x_mid_m": 0.5 * (float(x_m[0, left]) + float(x_m[0, right])),
                "x_left_over_l": float(x_over_l[0, left]),
                "x_right_over_l": float(x_over_l[0, right]),
                "x_mid_over_l": 0.5 * (float(x_over_l[0, left]) + float(x_over_l[0, right])),
                "dx_m": dx,
                "free_surface_potential_norm_left": float(free_norm[left]),
                "free_surface_potential_norm_right": float(free_norm[right]),
                "inner_free_surface_normal_derivative_norm_left": float(inner_normal_norm[left]),
                "inner_free_surface_normal_derivative_norm_right": float(inner_normal_norm[right]),
                "free_surface_increment_to_normal_derivative_gain_left": float(increment_gain[left]),
                "free_surface_increment_to_normal_derivative_gain_right": float(increment_gain[right]),
                "body_potential_norm_left": float(body_norm[left]),
                "body_potential_norm_right": float(body_norm[right]),
                "body_to_free_surface_potential_gain_left": body_to_free_left,
                "body_to_free_surface_potential_gain_right": body_to_free_right,
                "body_pressure_to_free_surface_potential_after_gain_left": float(free_after_pressure_gain[left]),
                "body_pressure_to_free_surface_potential_after_gain_right": float(free_after_pressure_gain[right]),
                "body_potential_adjacent_relative_jump": float(body_jump[pair_index]),
                "body_potential_adjacent_symmetric_norm_ratio": float(body_ratio[pair_index]),
                "body_potential_adjacent_phase_deg": float(body_phase[pair_index]),
                "body_potential_adjacent_real_alignment": float(body_alignment[pair_index]),
                "phase_aligned_body_potential_adjacent_relative_jump": float(phase_aligned_jump[pair_index]),
                "phase_aligned_body_potential_adjacent_phase_deg": float(phase_aligned_phase[pair_index]),
                "phase_aligned_body_potential_adjacent_real_alignment": float(phase_aligned_alignment[pair_index]),
                "body_potential_x_gradient_norm_left": float(gradient_norm[left]),
                "body_potential_x_gradient_norm_right": float(gradient_norm[right]),
                "body_potential_x_gradient_gain_times_l_left": float(gradient_gain_l[left]),
                "body_potential_x_gradient_gain_times_l_right": float(gradient_gain_l[right]),
                "body_potential_x_gradient_gain_times_l_pair_max": gradient_gain_pair,
                "phase_aligned_body_potential_x_gradient_gain_times_l_left": float(phase_aligned_gain_l[left]),
                "phase_aligned_body_potential_x_gradient_gain_times_l_right": float(phase_aligned_gain_l[right]),
                "phase_aligned_body_potential_x_gradient_gain_times_l_pair_max": phase_gain_pair,
                "phase_aligned_gradient_gain_to_raw_gain_ratio_pair_max": phase_ratio_pair,
                "central_gradient_gain_times_l_pair_max": pair_max_abs(
                    float(central_gain_l[left]), float(central_gain_l[right])
                ),
                "forward_gradient_gain_times_l_pair_max": pair_max_abs(
                    float(forward_gain_l[left]), float(forward_gain_l[right])
                ),
                "backward_gradient_gain_times_l_pair_max": pair_max_abs(
                    float(backward_gain_l[left]), float(backward_gain_l[right])
                ),
                "body_pressure_forward_to_time_norm_ratio_left": float(forward_to_time[left]),
                "body_pressure_forward_to_time_norm_ratio_right": float(forward_to_time[right]),
                "total_density_left_value_per_m": float(total_density[left]),
                "total_density_right_value_per_m": float(total_density[right]),
                "time_derivative_density_left_value_per_m": float(time_density[left]),
                "time_derivative_density_right_value_per_m": float(time_density[right]),
                "pressure_gradient_density_left_value_per_m": pg_left,
                "pressure_gradient_density_right_value_per_m": pg_right,
                "pressure_gradient_density_abs_pair_max": pg_abs_pair,
                "pressure_gradient_density_pair_cancellation_index": pg_cancellation,
                "pressure_gradient_density_pair_sign_change": str(sign_label(pg_left) != sign_label(pg_right)),
                "stokes_body_forward_density_left_value_per_m": float(stokes_density[left]),
                "stokes_body_forward_density_right_value_per_m": float(stokes_density[right]),
                "body_panel_mid_y_adjacent_relative_jump": float(panel_mid_y_jump[pair_index]),
                "body_panel_mid_z_adjacent_relative_jump": float(panel_mid_z_jump[pair_index]),
                "body_panel_normal_adjacent_relative_jump": float(panel_normal_jump[pair_index]),
                "body_panel_length_adjacent_relative_jump": float(panel_length_jump[pair_index]),
                "station_waterplane_beam_adjacent_relative_jump": float(beam_jump[pair_index]),
                "station_effective_draft_adjacent_relative_jump": float(draft_jump[pair_index]),
                "station_submerged_area_adjacent_relative_jump": float(area_jump[pair_index]),
                "gate_role": "diagnostic_station_transfer_path_not_hard_gate",
            }
        )
    return rows


def _ma2005_station_transfer_path_summary(data: pd.DataFrame, benchmark: str) -> pd.DataFrame:
    """Summarize adjacent-station transfer-path diagnostics by coefficient."""

    if data.empty:
        return pd.DataFrame()
    summary_rows: list[dict[str, float | str | int]] = []
    for coefficient, group in data.groupby("coefficient", sort=False):
        gradient_abs = pd.to_numeric(group["pressure_gradient_density_abs_pair_max"], errors="coerce")
        peak_index = gradient_abs.idxmax() if gradient_abs.notna().any() else group.index[0]
        peak = group.loc[peak_index]
        jump = pd.to_numeric(group["body_potential_adjacent_relative_jump"], errors="coerce")
        phase = pd.to_numeric(group["body_potential_adjacent_phase_deg"], errors="coerce").abs()
        alignment = pd.to_numeric(group["body_potential_adjacent_real_alignment"], errors="coerce")
        gradient_gain = pd.to_numeric(group["body_potential_x_gradient_gain_times_l_pair_max"], errors="coerce")
        phase_ratio = pd.to_numeric(group["phase_aligned_gradient_gain_to_raw_gain_ratio_pair_max"], errors="coerce")
        pressure_ratio_left = pd.to_numeric(group["body_pressure_forward_to_time_norm_ratio_left"], errors="coerce")
        pressure_ratio_right = pd.to_numeric(group["body_pressure_forward_to_time_norm_ratio_right"], errors="coerce")
        pressure_ratio_max = pd.concat([pressure_ratio_left, pressure_ratio_right]).max()
        body_to_free_left = pd.to_numeric(group["body_to_free_surface_potential_gain_left"], errors="coerce")
        body_to_free_right = pd.to_numeric(group["body_to_free_surface_potential_gain_right"], errors="coerce")
        body_to_free_max = pd.concat([body_to_free_left, body_to_free_right]).max()
        sign_changes = int(group["pressure_gradient_density_pair_sign_change"].astype(str).eq("True").sum())
        summary_rows.append(
            {
                "benchmark": benchmark,
                "coefficient": str(coefficient),
                "pair_count": int(len(group)),
                "peak_pressure_gradient_pair_index": int(peak["pair_index"]),
                "peak_pressure_gradient_x_mid_over_l": float(peak["x_mid_over_l"]),
                "peak_pressure_gradient_density_abs_pair_max": float(gradient_abs.loc[peak_index]),
                "max_body_potential_adjacent_relative_jump": float(jump.max()) if jump.notna().any() else float("nan"),
                "max_body_potential_adjacent_phase_deg_abs": float(phase.max()) if phase.notna().any() else float("nan"),
                "min_body_potential_adjacent_real_alignment": (
                    float(alignment.min()) if alignment.notna().any() else float("nan")
                ),
                "max_body_potential_x_gradient_gain_times_l_pair": (
                    float(gradient_gain.max()) if gradient_gain.notna().any() else float("nan")
                ),
                "max_phase_aligned_gradient_gain_to_raw_gain_ratio_pair": (
                    float(phase_ratio.max()) if phase_ratio.notna().any() else float("nan")
                ),
                "max_body_pressure_forward_to_time_norm_ratio_pair": (
                    float(pressure_ratio_max) if np.isfinite(float(pressure_ratio_max)) else float("nan")
                ),
                "max_body_to_free_surface_potential_gain_pair": (
                    float(body_to_free_max) if np.isfinite(float(body_to_free_max)) else float("nan")
                ),
                "pressure_gradient_density_sign_change_pairs": sign_changes,
                "gate_role": "diagnostic_station_transfer_path_not_hard_gate",
                "path_diagnostic_status": "INFO",
            }
        )
    return pd.DataFrame(summary_rows)


def _write_ma2005_station_mapping_gradient_audit(
    station_transfer_path: pd.DataFrame,
    eq30_component_contribution_audit: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Audit whether forward-gradient failures coincide with station/panel mapping jumps."""

    detail_path = out_dir / f"{benchmark}_station_mapping_gradient_audit.csv"
    summary_path = out_dir / f"{benchmark}_station_mapping_gradient_summary.csv"
    detail_columns = [
        "benchmark",
        "coefficient",
        "coefficient_status",
        "component_failure_source",
        "dominant_current_default_component",
        "reference_value",
        "computed_value",
        "gate_error_ratio",
        "required_pressure_gradient_scale_if_only_adjusted",
        "peak_pressure_gradient_pair_index",
        "peak_pressure_gradient_x_mid_over_l",
        "peak_pressure_gradient_density_abs_pair_max",
        "body_potential_adjacent_relative_jump_at_peak",
        "body_potential_adjacent_phase_deg_at_peak",
        "phase_aligned_body_potential_adjacent_relative_jump_at_peak",
        "body_panel_mid_y_adjacent_relative_jump_at_peak",
        "body_panel_mid_z_adjacent_relative_jump_at_peak",
        "body_panel_normal_adjacent_relative_jump_at_peak",
        "body_panel_length_adjacent_relative_jump_at_peak",
        "station_waterplane_beam_adjacent_relative_jump_at_peak",
        "station_effective_draft_adjacent_relative_jump_at_peak",
        "station_submerged_area_adjacent_relative_jump_at_peak",
        "body_potential_x_gradient_gain_times_l_pair_max_at_peak",
        "phase_aligned_gradient_gain_to_raw_gain_ratio_pair_max_at_peak",
        "central_gradient_gain_times_l_pair_max_at_peak",
        "forward_gradient_gain_times_l_pair_max_at_peak",
        "backward_gradient_gain_times_l_pair_max_at_peak",
        "pressure_gradient_density_pair_sign_change_at_peak",
        "mapping_risk_flags",
        "diagnostic_conclusion",
        "candidate_policy",
        "remaining_blocker",
        "gate_role",
    ]
    summary_columns = [
        "benchmark",
        "row_count",
        "forward_gradient_failure_count",
        "high_mapping_risk_count",
        "peak_near_aft_startup_count",
        "max_body_potential_adjacent_relative_jump_at_peak",
        "max_body_panel_mid_y_adjacent_relative_jump_at_peak",
        "max_body_panel_mid_z_adjacent_relative_jump_at_peak",
        "max_body_panel_normal_adjacent_relative_jump_at_peak",
        "max_body_panel_length_adjacent_relative_jump_at_peak",
        "max_station_waterplane_beam_adjacent_relative_jump_at_peak",
        "max_station_submerged_area_adjacent_relative_jump_at_peak",
        "max_body_potential_x_gradient_gain_times_l_pair_at_peak",
        "max_phase_aligned_gradient_gain_to_raw_gain_ratio_pair_at_peak",
        "diagnostic_conclusion",
        "remaining_blocker",
        "gate_role",
        "path_diagnostic_status",
    ]
    if station_transfer_path.empty or eq30_component_contribution_audit.empty:
        detail = pd.DataFrame(columns=detail_columns)
        summary = pd.DataFrame(columns=summary_columns)
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    def numeric(row: pd.Series | None, column: str, default: float = float("nan")) -> float:
        if row is None or column not in row:
            return default
        try:
            return float(row[column])
        except (TypeError, ValueError):
            return default

    component_by_coefficient = {
        str(row["coefficient"]): row
        for _, row in eq30_component_contribution_audit.iterrows()
        if "coefficient" in row
    }

    detail_rows: list[dict[str, float | str | int]] = []
    for coefficient, raw_group in station_transfer_path.groupby("coefficient", sort=False):
        coefficient_name = str(coefficient)
        component_row = component_by_coefficient.get(coefficient_name)
        if component_row is None:
            continue
        group = raw_group.copy()
        pressure_abs = pd.to_numeric(group["pressure_gradient_density_abs_pair_max"], errors="coerce")
        if not pressure_abs.notna().any():
            continue
        peak_index = pressure_abs.idxmax()
        peak = group.loc[peak_index]
        body_jump = numeric(peak, "body_potential_adjacent_relative_jump")
        phase_abs = abs(numeric(peak, "body_potential_adjacent_phase_deg"))
        phase_aligned_jump = numeric(peak, "phase_aligned_body_potential_adjacent_relative_jump")
        panel_y_jump = numeric(peak, "body_panel_mid_y_adjacent_relative_jump")
        panel_z_jump = numeric(peak, "body_panel_mid_z_adjacent_relative_jump")
        panel_normal_jump = numeric(peak, "body_panel_normal_adjacent_relative_jump")
        panel_length_jump = numeric(peak, "body_panel_length_adjacent_relative_jump")
        beam_jump = numeric(peak, "station_waterplane_beam_adjacent_relative_jump")
        draft_jump = numeric(peak, "station_effective_draft_adjacent_relative_jump")
        area_jump = numeric(peak, "station_submerged_area_adjacent_relative_jump")
        gradient_gain_l = numeric(peak, "body_potential_x_gradient_gain_times_l_pair_max")
        phase_ratio = numeric(peak, "phase_aligned_gradient_gain_to_raw_gain_ratio_pair_max")
        x_mid = numeric(peak, "x_mid_over_l")
        flags: list[str] = []
        if x_mid <= 0.075:
            flags.append("near_aft_startup_region")
        if body_jump >= 0.5:
            flags.append("large_body_potential_adjacent_jump")
        if phase_abs >= 90.0:
            flags.append("large_body_potential_phase_change")
        if phase_aligned_jump >= 0.5:
            flags.append("large_phase_aligned_body_potential_jump")
        if panel_y_jump >= 0.2 or panel_z_jump >= 0.2:
            flags.append("large_panel_midpoint_geometry_jump")
        if panel_normal_jump >= 0.05:
            flags.append("large_panel_normal_jump")
        if panel_length_jump >= 0.05:
            flags.append("large_panel_length_jump")
        if beam_jump >= 0.2 or area_jump >= 0.2:
            flags.append("large_station_geometry_jump")
        if gradient_gain_l >= 20.0:
            flags.append("large_gradient_gain_times_length")
        is_forward_failure = str(component_row.get("component_failure_source", "")).startswith(
            "forward_speed_pressure_gradient"
        )
        high_mapping_risk = bool(
            is_forward_failure
            and (
                body_jump >= 0.5
                or phase_aligned_jump >= 0.5
                or panel_y_jump >= 0.2
                or beam_jump >= 0.2
                or area_jump >= 0.2
                or gradient_gain_l >= 20.0
            )
        )
        if high_mapping_risk:
            conclusion = "forward_gradient_failure_coincides_with_station_mapping_jump"
            blocker = (
                "Derive dphi/dx on a documented fixed surface or replace the finite-difference path with a "
                "validated Eq.32 identity before changing the production gradient."
            )
        elif is_forward_failure:
            conclusion = "forward_gradient_failure_without_large_peak_mapping_jump"
            blocker = "Audit Eq.30 pressure-gradient phase/sign and body-potential derivative convention."
        else:
            conclusion = "not_forward_gradient_dominant_failure"
            blocker = "Use this row as context only; its primary blocker is not station-mapped dphi/dx."
        detail_rows.append(
            {
                "benchmark": benchmark,
                "coefficient": coefficient_name,
                "coefficient_status": str(component_row.get("status", "")),
                "component_failure_source": str(component_row.get("component_failure_source", "")),
                "dominant_current_default_component": str(
                    component_row.get("dominant_current_default_component", "")
                ),
                "reference_value": numeric(component_row, "reference_value"),
                "computed_value": numeric(component_row, "computed_value"),
                "gate_error_ratio": numeric(component_row, "gate_error_ratio"),
                "required_pressure_gradient_scale_if_only_adjusted": numeric(
                    component_row,
                    "required_pressure_gradient_scale_if_only_adjusted",
                ),
                "peak_pressure_gradient_pair_index": int(numeric(peak, "pair_index", -1.0)),
                "peak_pressure_gradient_x_mid_over_l": x_mid,
                "peak_pressure_gradient_density_abs_pair_max": numeric(
                    peak,
                    "pressure_gradient_density_abs_pair_max",
                ),
                "body_potential_adjacent_relative_jump_at_peak": body_jump,
                "body_potential_adjacent_phase_deg_at_peak": numeric(
                    peak,
                    "body_potential_adjacent_phase_deg",
                ),
                "phase_aligned_body_potential_adjacent_relative_jump_at_peak": phase_aligned_jump,
                "body_panel_mid_y_adjacent_relative_jump_at_peak": panel_y_jump,
                "body_panel_mid_z_adjacent_relative_jump_at_peak": panel_z_jump,
                "body_panel_normal_adjacent_relative_jump_at_peak": panel_normal_jump,
                "body_panel_length_adjacent_relative_jump_at_peak": panel_length_jump,
                "station_waterplane_beam_adjacent_relative_jump_at_peak": beam_jump,
                "station_effective_draft_adjacent_relative_jump_at_peak": draft_jump,
                "station_submerged_area_adjacent_relative_jump_at_peak": area_jump,
                "body_potential_x_gradient_gain_times_l_pair_max_at_peak": gradient_gain_l,
                "phase_aligned_gradient_gain_to_raw_gain_ratio_pair_max_at_peak": phase_ratio,
                "central_gradient_gain_times_l_pair_max_at_peak": numeric(
                    peak,
                    "central_gradient_gain_times_l_pair_max",
                ),
                "forward_gradient_gain_times_l_pair_max_at_peak": numeric(
                    peak,
                    "forward_gradient_gain_times_l_pair_max",
                ),
                "backward_gradient_gain_times_l_pair_max_at_peak": numeric(
                    peak,
                    "backward_gradient_gain_times_l_pair_max",
                ),
                "pressure_gradient_density_pair_sign_change_at_peak": str(
                    peak.get("pressure_gradient_density_pair_sign_change", "")
                ),
                "mapping_risk_flags": ";".join(flags) if flags else "none",
                "diagnostic_conclusion": conclusion,
                "candidate_policy": (
                    "diagnostic_only: station mapping evidence can justify the next derivation target, but it "
                    "does not define a production smoothing, deletion, or scale correction."
                ),
                "remaining_blocker": blocker,
                "gate_role": "diagnostic_station_mapping_gradient_not_hard_gate",
            }
        )

    detail = pd.DataFrame(detail_rows, columns=detail_columns)
    if detail.empty:
        summary = pd.DataFrame(columns=summary_columns)
    else:
        forward_failures = detail["component_failure_source"].astype(str).str.startswith(
            "forward_speed_pressure_gradient"
        )
        high_mapping = detail["diagnostic_conclusion"].astype(str).eq(
            "forward_gradient_failure_coincides_with_station_mapping_jump"
        )
        near_aft = detail["mapping_risk_flags"].astype(str).str.contains("near_aft_startup_region", regex=False)
        numeric_columns = {
            "max_body_potential_adjacent_relative_jump_at_peak": "body_potential_adjacent_relative_jump_at_peak",
            "max_body_panel_mid_y_adjacent_relative_jump_at_peak": "body_panel_mid_y_adjacent_relative_jump_at_peak",
            "max_body_panel_mid_z_adjacent_relative_jump_at_peak": "body_panel_mid_z_adjacent_relative_jump_at_peak",
            "max_body_panel_normal_adjacent_relative_jump_at_peak": "body_panel_normal_adjacent_relative_jump_at_peak",
            "max_body_panel_length_adjacent_relative_jump_at_peak": "body_panel_length_adjacent_relative_jump_at_peak",
            "max_station_waterplane_beam_adjacent_relative_jump_at_peak": "station_waterplane_beam_adjacent_relative_jump_at_peak",
            "max_station_submerged_area_adjacent_relative_jump_at_peak": "station_submerged_area_adjacent_relative_jump_at_peak",
            "max_body_potential_x_gradient_gain_times_l_pair_at_peak": "body_potential_x_gradient_gain_times_l_pair_max_at_peak",
            "max_phase_aligned_gradient_gain_to_raw_gain_ratio_pair_at_peak": "phase_aligned_gradient_gain_to_raw_gain_ratio_pair_max_at_peak",
        }
        maxima: dict[str, float] = {}
        for output, source in numeric_columns.items():
            values = pd.to_numeric(detail[source], errors="coerce")
            maxima[output] = float(values.max()) if values.notna().any() else float("nan")
        if bool(high_mapping.any()):
            conclusion = (
                "Forward-gradient-dominant failures coincide with large body-potential, panel, or station-geometry "
                "jumps at the pressure-gradient peak."
            )
            blocker = (
                "Next work should implement or derive a fixed-surface station mapping for dphi/dx, and compare it "
                "against Eq.32 Stokes/end identity without changing the default until the full Gate 1 passes."
            )
        else:
            conclusion = "No forward-gradient-dominant failure coincides with a large mapped-station jump in this audit."
            blocker = "Continue with Eq.30 sign/phase and Eq.32 identity audits."
        summary = pd.DataFrame(
            [
                {
                    "benchmark": benchmark,
                    "row_count": int(len(detail)),
                    "forward_gradient_failure_count": int(forward_failures.sum()),
                    "high_mapping_risk_count": int(high_mapping.sum()),
                    "peak_near_aft_startup_count": int(near_aft.sum()),
                    **maxima,
                    "diagnostic_conclusion": conclusion,
                    "remaining_blocker": blocker,
                    "gate_role": "diagnostic_station_mapping_gradient_not_hard_gate",
                    "path_diagnostic_status": "INFO",
                }
            ],
            columns=summary_columns,
        )
    detail.to_csv(detail_path, index=False)
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _write_ma2005_station_marching_direction_audit(
    comparison: pd.DataFrame,
    station_transfer_path: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Audit A1 local-time marching direction against station storage and gradient peaks.

    The matched station sweep stores stations by increasing ``x`` from the aft
    perpendicular for integration, while A1 Eq. (7) advances local time from the
    forward perpendicular toward the aft end.  This diagnostic makes that
    distinction explicit before any default pressure-gradient or end-term
    correction is attempted.
    """

    detail_path = out_dir / f"{benchmark}_station_marching_direction_audit.csv"
    summary_path = out_dir / f"{benchmark}_station_marching_direction_summary.csv"
    detail_columns = [
        "benchmark",
        "coefficient",
        "provider_route",
        "coefficient_status",
        "reference_value",
        "computed_value",
        "gate_error_ratio",
        "speed_mps",
        "hull_length_m",
        "station_count",
        "station_storage_direction",
        "a1_local_time_formula",
        "a1_expected_marching_direction",
        "solve_order_first_index",
        "solve_order_last_index",
        "solve_order_first_x_over_l",
        "solve_order_last_x_over_l",
        "solve_order_first_local_time_s",
        "solve_order_last_local_time_s",
        "solve_order_x_over_l_monotonic_decreasing",
        "solve_order_local_time_monotonic_increasing",
        "solve_order_matches_a1_local_time",
        "configured_end_station_x_over_l",
        "aft_active_station_x_over_l",
        "selected_forward_speed_force_density_peak_x_over_l",
        "transfer_peak_pressure_gradient_pair_index",
        "transfer_peak_pressure_gradient_x_mid_over_l",
        "pressure_gradient_peak_near_aft_end",
        "pressure_gradient_peak_near_bow_start",
        "pressure_gradient_peak_near_marching_start",
        "diagnostic_flags",
        "diagnostic_conclusion",
        "remaining_blocker",
        "gate_role",
    ]
    summary_columns = [
        "benchmark",
        "row_count",
        "a1_marching_match_count",
        "a1_marching_mismatch_count",
        "aft_to_bow_storage_count",
        "pressure_gradient_peak_near_aft_end_count",
        "pressure_gradient_peak_near_bow_start_count",
        "pressure_gradient_peak_near_marching_start_count",
        "max_gate_error_ratio",
        "min_solve_order_first_x_over_l",
        "max_solve_order_first_x_over_l",
        "min_solve_order_last_x_over_l",
        "max_solve_order_last_x_over_l",
        "diagnostic_conclusion",
        "remaining_blocker",
        "gate_role",
        "path_diagnostic_status",
    ]
    if comparison.empty:
        detail = pd.DataFrame(columns=detail_columns)
        summary = pd.DataFrame(columns=summary_columns)
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    matched = comparison[
        comparison.get("provider_route", pd.Series("", index=comparison.index))
        .astype(str)
        .eq("matched_bie_station_sweep")
    ].copy()
    if matched.empty:
        detail = pd.DataFrame(columns=detail_columns)
        summary = pd.DataFrame(
            [
                {
                    "benchmark": benchmark,
                    "row_count": 0,
                    "a1_marching_match_count": 0,
                    "a1_marching_mismatch_count": 0,
                    "aft_to_bow_storage_count": 0,
                    "pressure_gradient_peak_near_aft_end_count": 0,
                    "pressure_gradient_peak_near_bow_start_count": 0,
                    "pressure_gradient_peak_near_marching_start_count": 0,
                    "max_gate_error_ratio": float("nan"),
                    "min_solve_order_first_x_over_l": float("nan"),
                    "max_solve_order_first_x_over_l": float("nan"),
                    "min_solve_order_last_x_over_l": float("nan"),
                    "max_solve_order_last_x_over_l": float("nan"),
                    "diagnostic_conclusion": "no_matched_bie_rows_available",
                    "remaining_blocker": "Run the matched-BIE provider before auditing A1 station marching direction.",
                    "gate_role": "diagnostic_station_marching_direction_not_hard_gate",
                    "path_diagnostic_status": "NOT_EVALUATED",
                }
            ],
            columns=summary_columns,
        )
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    def numeric(row: pd.Series | None, column: str, default: float = float("nan")) -> float:
        if row is None or column not in row:
            return default
        try:
            return float(row[column])
        except (TypeError, ValueError):
            return default

    def truthy(row: pd.Series | None, column: str) -> bool:
        if row is None or column not in row:
            return False
        return str(row[column]).strip().lower() in {"true", "1", "yes"}

    transfer_peak_by_coefficient: dict[str, pd.Series] = {}
    if not station_transfer_path.empty and "coefficient" in station_transfer_path.columns:
        for coefficient, group in station_transfer_path.groupby("coefficient", sort=False):
            if "pressure_gradient_density_abs_pair_max" in group.columns:
                peak_abs = pd.to_numeric(group["pressure_gradient_density_abs_pair_max"], errors="coerce")
                if peak_abs.notna().any():
                    transfer_peak_by_coefficient[str(coefficient)] = group.loc[peak_abs.idxmax()]

    detail_rows: list[dict[str, float | str | int | bool]] = []
    for _, row in matched.iterrows():
        coefficient = str(row.get("coefficient", ""))
        transfer_peak = transfer_peak_by_coefficient.get(coefficient)
        first_x = numeric(row, "matched_station_solve_order_first_x_over_l")
        last_x = numeric(row, "matched_station_solve_order_last_x_over_l")
        first_time = numeric(row, "matched_station_solve_order_first_local_time_s")
        last_time = numeric(row, "matched_station_solve_order_last_local_time_s")
        end_x = numeric(row, "matched_end_term_station_x_over_l")
        aft_x = numeric(row, "matched_aft_active_station_x_over_l")
        selected_peak_x = numeric(row, "matched_selected_forward_speed_force_density_peak_x_over_l")
        transfer_peak_x = numeric(transfer_peak, "x_mid_over_l")
        peak_x = transfer_peak_x if np.isfinite(transfer_peak_x) else selected_peak_x
        near_aft = bool(np.isfinite(peak_x) and peak_x <= 0.075)
        near_bow = bool(np.isfinite(peak_x) and peak_x >= 0.925)
        solve_matches = truthy(row, "matched_station_solve_order_matches_a1_local_time")
        first_near_bow = bool(np.isfinite(first_x) and first_x >= 0.925)
        peak_near_marching_start = bool(near_bow and first_near_bow)
        flags: list[str] = []
        if not solve_matches:
            flags.append("solve_order_not_a1_bow_to_aft")
        if near_aft:
            flags.append("pressure_gradient_peak_near_aft_terminal_region")
        if near_bow:
            flags.append("pressure_gradient_peak_near_bow_marching_start")
        if first_near_bow and np.isfinite(last_x) and last_x <= 0.075:
            flags.append("solve_order_bow_to_aft_over_active_hull")
        if solve_matches and near_aft and not peak_near_marching_start:
            conclusion = "a1_marching_direction_consistent_gradient_peak_is_aft_terminal"
            blocker = (
                "Do not reverse station marching as a default correction. Continue tracing the aft terminal "
                "pressure-gradient stencil, end-contour station convention, and Eq.31/Eq.32 forward-speed identity."
            )
        elif solve_matches:
            conclusion = "a1_marching_direction_consistent"
            blocker = (
                "Marching direction is not the primary failure source; continue with pressure-gradient, "
                "control-surface matching, and end-term closure audits."
            )
        else:
            conclusion = "a1_marching_direction_mismatch_possible"
            blocker = (
                "Verify solve_order against A1 Eq.7 before changing pressure-gradient signs or station "
                "endpoint corrections."
            )
        detail_rows.append(
            {
                "benchmark": benchmark,
                "coefficient": coefficient,
                "provider_route": str(row.get("provider_route", "")),
                "coefficient_status": str(row.get("status", "")),
                "reference_value": numeric(row, "reference_value"),
                "computed_value": numeric(row, "computed_value"),
                "gate_error_ratio": numeric(row, "gate_error_ratio"),
                "speed_mps": numeric(row, "speed_mps"),
                "hull_length_m": numeric(row, "hull_length_m"),
                "station_count": int(numeric(row, "station_count", 0.0)),
                "station_storage_direction": "increasing_x_from_aft_perpendicular",
                "a1_local_time_formula": "t=(x0-x)/U; x0=forward_perpendicular",
                "a1_expected_marching_direction": "bow_to_aft_decreasing_x_over_l_increasing_local_time",
                "solve_order_first_index": numeric(row, "matched_station_solve_order_first_index"),
                "solve_order_last_index": numeric(row, "matched_station_solve_order_last_index"),
                "solve_order_first_x_over_l": first_x,
                "solve_order_last_x_over_l": last_x,
                "solve_order_first_local_time_s": first_time,
                "solve_order_last_local_time_s": last_time,
                "solve_order_x_over_l_monotonic_decreasing": truthy(
                    row,
                    "matched_station_solve_order_x_over_l_monotonic_decreasing",
                ),
                "solve_order_local_time_monotonic_increasing": truthy(
                    row,
                    "matched_station_solve_order_local_time_monotonic_increasing",
                ),
                "solve_order_matches_a1_local_time": solve_matches,
                "configured_end_station_x_over_l": end_x,
                "aft_active_station_x_over_l": aft_x,
                "selected_forward_speed_force_density_peak_x_over_l": selected_peak_x,
                "transfer_peak_pressure_gradient_pair_index": numeric(transfer_peak, "pair_index", -1.0),
                "transfer_peak_pressure_gradient_x_mid_over_l": transfer_peak_x,
                "pressure_gradient_peak_near_aft_end": near_aft,
                "pressure_gradient_peak_near_bow_start": near_bow,
                "pressure_gradient_peak_near_marching_start": peak_near_marching_start,
                "diagnostic_flags": ";".join(flags) if flags else "none",
                "diagnostic_conclusion": conclusion,
                "remaining_blocker": blocker,
                "gate_role": "diagnostic_station_marching_direction_not_hard_gate",
            }
        )

    detail = pd.DataFrame(detail_rows, columns=detail_columns)
    if detail.empty:
        summary = pd.DataFrame(columns=summary_columns)
    else:
        match = detail["solve_order_matches_a1_local_time"].astype(bool)
        aft_storage = detail["station_storage_direction"].astype(str).eq("increasing_x_from_aft_perpendicular")
        near_aft = detail["pressure_gradient_peak_near_aft_end"].astype(bool)
        near_bow = detail["pressure_gradient_peak_near_bow_start"].astype(bool)
        near_start = detail["pressure_gradient_peak_near_marching_start"].astype(bool)
        gate = pd.to_numeric(detail["gate_error_ratio"], errors="coerce")
        first_x_values = pd.to_numeric(detail["solve_order_first_x_over_l"], errors="coerce")
        last_x_values = pd.to_numeric(detail["solve_order_last_x_over_l"], errors="coerce")
        if bool(match.all()) and bool(near_aft.any()) and not bool(near_start.any()):
            conclusion = "a1_bow_to_aft_marching_confirmed_aft_terminal_gradient_peak_remains"
            blocker = (
                "Station marching reversal is excluded as the default fix. The remaining forward-speed failure "
                "source is downstream in the aft terminal pressure-gradient/end-contour/Eq.31-Eq.32 closure chain."
            )
        elif bool(match.all()):
            conclusion = "a1_bow_to_aft_marching_confirmed"
            blocker = (
                "Continue tracing Eq.30 pressure recovery and whole-ship assembly; station direction is not "
                "currently a supported default correction."
            )
        else:
            conclusion = "a1_marching_direction_not_fully_confirmed"
            blocker = "Inspect solve_order metadata and A1 Eq.7 station coordinate convention before applying fixes."
        summary = pd.DataFrame(
            [
                {
                    "benchmark": benchmark,
                    "row_count": int(len(detail)),
                    "a1_marching_match_count": int(match.sum()),
                    "a1_marching_mismatch_count": int((~match).sum()),
                    "aft_to_bow_storage_count": int(aft_storage.sum()),
                    "pressure_gradient_peak_near_aft_end_count": int(near_aft.sum()),
                    "pressure_gradient_peak_near_bow_start_count": int(near_bow.sum()),
                    "pressure_gradient_peak_near_marching_start_count": int(near_start.sum()),
                    "max_gate_error_ratio": float(gate.max()) if gate.notna().any() else float("nan"),
                    "min_solve_order_first_x_over_l": (
                        float(first_x_values.min()) if first_x_values.notna().any() else float("nan")
                    ),
                    "max_solve_order_first_x_over_l": (
                        float(first_x_values.max()) if first_x_values.notna().any() else float("nan")
                    ),
                    "min_solve_order_last_x_over_l": (
                        float(last_x_values.min()) if last_x_values.notna().any() else float("nan")
                    ),
                    "max_solve_order_last_x_over_l": (
                        float(last_x_values.max()) if last_x_values.notna().any() else float("nan")
                    ),
                    "diagnostic_conclusion": conclusion,
                    "remaining_blocker": blocker,
                    "gate_role": "diagnostic_station_marching_direction_not_hard_gate",
                    "path_diagnostic_status": "INFO",
                }
            ],
            columns=summary_columns,
        )
    detail.to_csv(detail_path, index=False)
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _write_ma2005_aft_terminal_end_closure_audit(
    comparison: pd.DataFrame,
    station_forward_identity_audit: pd.DataFrame,
    end_pressure_closure_detail: pd.DataFrame,
    out_dir: Path,
    benchmark: str,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Audit whether aft-terminal residuals or a shared end-contour scale can close Eq.31/Eq.32."""

    detail_path = out_dir / f"{benchmark}_aft_terminal_end_closure_audit.csv"
    summary_path = out_dir / f"{benchmark}_aft_terminal_end_closure_summary.csv"
    detail_columns = [
        "benchmark",
        "coefficient",
        "provider_route",
        "coefficient_status",
        "reference_value",
        "computed_value",
        "gate_error_ratio",
        "pressure_gradient_integral_value",
        "stokes_body_forward_integral_value",
        "current_end_contour_integral_value",
        "required_end_contour_integral_to_close_identity_value",
        "required_end_contour_scale_to_close_identity",
        "required_end_contour_scale_abs",
        "current_forward_identity_residual_value",
        "abs_forward_identity_residual_sum",
        "terminal_x_0p05_residual_value",
        "terminal_x_0p05_abs_share",
        "terminal_x_0p075_residual_value",
        "terminal_x_0p075_abs_share",
        "terminal_x_0p10_residual_value",
        "terminal_x_0p10_abs_share",
        "terminal_x_0p125_residual_value",
        "terminal_x_0p125_abs_share",
        "terminal_x_0p20_residual_value",
        "terminal_x_0p20_abs_share",
        "peak_abs_residual_x_over_l",
        "peak_abs_residual_station_index",
        "configured_end_station_x_over_l",
        "endpoint_forward_gradient_integral_value",
        "end_to_endpoint_forward_ratio_abs",
        "terminal_band_explains_residual",
        "shared_end_scale_candidate_row_decision",
        "diagnostic_flags",
        "diagnostic_conclusion",
        "remaining_blocker",
        "gate_role",
    ]
    summary_columns = [
        "benchmark",
        "row_count",
        "finite_required_end_scale_count",
        "min_required_end_contour_scale",
        "median_required_end_contour_scale",
        "max_required_end_contour_scale",
        "min_abs_required_end_contour_scale",
        "median_abs_required_end_contour_scale",
        "max_abs_required_end_contour_scale",
        "required_end_contour_scale_abs_spread",
        "required_end_contour_scale_sign_change_count",
        "terminal_x_0p10_high_share_count",
        "terminal_x_0p10_abs_share_min",
        "terminal_x_0p10_abs_share_median",
        "terminal_x_0p10_abs_share_max",
        "end_to_endpoint_forward_ratio_abs_min",
        "end_to_endpoint_forward_ratio_abs_median",
        "end_to_endpoint_forward_ratio_abs_max",
        "row_decision_counts",
        "diagnostic_conclusion",
        "remaining_blocker",
        "gate_role",
        "path_diagnostic_status",
    ]
    if comparison.empty or station_forward_identity_audit.empty:
        detail = pd.DataFrame(columns=detail_columns)
        summary = pd.DataFrame(columns=summary_columns)
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    matched = comparison[
        comparison.get("provider_route", pd.Series("", index=comparison.index))
        .astype(str)
        .eq("matched_bie_station_sweep")
    ].copy()
    if matched.empty:
        detail = pd.DataFrame(columns=detail_columns)
        summary = pd.DataFrame(columns=summary_columns)
        detail.to_csv(detail_path, index=False)
        summary.to_csv(summary_path, index=False)
        return detail, summary

    def numeric(row: pd.Series | None, column: str, default: float = float("nan")) -> float:
        if row is None or column not in row:
            return default
        try:
            return float(row[column])
        except (TypeError, ValueError):
            return default

    def safe_scale(required: float, current: float) -> float:
        if not np.isfinite(required) or not np.isfinite(current) or abs(current) <= 1e-300:
            return float("nan")
        return float(required / current)

    def count_sign_changes(values: pd.Series) -> int:
        finite = pd.to_numeric(values, errors="coerce").dropna().to_numpy(dtype=float)
        finite = finite[np.isfinite(finite) & (np.abs(finite) > 1e-12)]
        if finite.size < 2:
            return 0
        return int(np.any(finite > 0.0) and np.any(finite < 0.0))

    end_by_coefficient: dict[str, pd.Series] = {}
    if not end_pressure_closure_detail.empty and "coefficient" in end_pressure_closure_detail.columns:
        configured = end_pressure_closure_detail[
            end_pressure_closure_detail.get("endpoint_label", pd.Series("", index=end_pressure_closure_detail.index))
            .astype(str)
            .eq("configured_end_station")
        ]
        source = configured if not configured.empty else end_pressure_closure_detail
        for _, row in source.iterrows():
            end_by_coefficient[str(row["coefficient"])] = row

    detail_rows: list[dict[str, float | str | int | bool]] = []
    for _, row in matched.iterrows():
        coefficient = str(row.get("coefficient", ""))
        group = station_forward_identity_audit[
            station_forward_identity_audit.get("coefficient", pd.Series("", index=station_forward_identity_audit.index))
            .astype(str)
            .eq(coefficient)
        ].copy()
        if group.empty:
            continue
        x = pd.to_numeric(group["x_over_l"], errors="coerce").to_numpy(dtype=float)
        residual = pd.to_numeric(group["station_forward_identity_residual_value"], errors="coerce").to_numpy(dtype=float)
        pressure = pd.to_numeric(
            group["pressure_gradient_station_contribution_value"],
            errors="coerce",
        ).to_numpy(dtype=float)
        stokes = pd.to_numeric(
            group["stokes_body_forward_station_contribution_value"],
            errors="coerce",
        ).to_numpy(dtype=float)
        end_station = pd.to_numeric(
            group["end_contour_station_contribution_value"],
            errors="coerce",
        ).to_numpy(dtype=float)
        finite_mask = np.isfinite(x) & np.isfinite(residual)
        if not np.any(finite_mask):
            continue
        x = x[finite_mask]
        residual = residual[finite_mask]
        pressure = pressure[finite_mask]
        stokes = stokes[finite_mask]
        end_station = end_station[finite_mask]
        abs_sum = float(np.sum(np.abs(residual)))
        pressure_integral = float(np.sum(pressure))
        stokes_integral = float(np.sum(stokes))
        end_integral = float(np.sum(end_station))
        identity_residual = float(np.sum(residual))
        required_end = pressure_integral - stokes_integral
        required_scale = safe_scale(required_end, end_integral)
        peak_pos = int(np.argmax(np.abs(residual))) if residual.size else 0
        threshold_data: dict[str, float] = {}
        for threshold, label in (
            (0.05, "0p05"),
            (0.075, "0p075"),
            (0.10, "0p10"),
            (0.125, "0p125"),
            (0.20, "0p20"),
        ):
            mask = x <= threshold + 1e-12
            value = float(np.sum(residual[mask])) if np.any(mask) else 0.0
            share = float(np.sum(np.abs(residual[mask])) / abs_sum) if abs_sum > 0.0 else 0.0
            threshold_data[f"terminal_x_{label}_residual_value"] = value
            threshold_data[f"terminal_x_{label}_abs_share"] = share
        end_row = end_by_coefficient.get(coefficient)
        endpoint_ratio = numeric(end_row, "end_to_endpoint_forward_ratio_abs")
        if not np.isfinite(endpoint_ratio):
            endpoint_ratio = abs(numeric(end_row, "end_to_endpoint_forward_ratio"))
        terminal_explains = bool(threshold_data["terminal_x_0p10_abs_share"] >= 0.75)
        flags: list[str] = []
        if terminal_explains:
            flags.append("terminal_10pct_contains_most_abs_residual")
        else:
            flags.append("terminal_10pct_does_not_contain_most_abs_residual")
        if not np.isfinite(required_scale):
            flags.append("end_scale_not_finite")
            decision = "end_scale_not_evaluable"
        elif abs(required_scale) > 20.0:
            flags.append("large_required_end_scale")
            decision = "required_end_scale_too_large_for_simple_default"
        elif abs(required_scale) < 0.05:
            flags.append("tiny_required_end_scale")
            decision = "required_end_scale_too_small_for_simple_default"
        else:
            decision = "finite_required_end_scale_but_needs_shared_trace"
        if terminal_explains:
            conclusion = "terminal_band_dominates_this_row"
            blocker = (
                "A terminal-band treatment may matter for this coefficient, but it remains diagnostic-only "
                "until all eight coefficients share a formula-derived closure."
            )
        else:
            conclusion = "residual_not_explained_by_simple_aft_terminal_band"
            blocker = (
                "The Eq.31/Eq.32 residual is not confined to the first 10% of the hull; inspect distributed "
                "station derivative, body-potential mapping, and end-contour identity rather than deleting or "
                "scaling only the aft terminal station."
            )
        detail_rows.append(
            {
                "benchmark": benchmark,
                "coefficient": coefficient,
                "provider_route": str(row.get("provider_route", "")),
                "coefficient_status": str(row.get("status", "")),
                "reference_value": numeric(row, "reference_value"),
                "computed_value": numeric(row, "computed_value"),
                "gate_error_ratio": numeric(row, "gate_error_ratio"),
                "pressure_gradient_integral_value": pressure_integral,
                "stokes_body_forward_integral_value": stokes_integral,
                "current_end_contour_integral_value": end_integral,
                "required_end_contour_integral_to_close_identity_value": required_end,
                "required_end_contour_scale_to_close_identity": required_scale,
                "required_end_contour_scale_abs": abs(required_scale) if np.isfinite(required_scale) else float("nan"),
                "current_forward_identity_residual_value": identity_residual,
                "abs_forward_identity_residual_sum": abs_sum,
                **threshold_data,
                "peak_abs_residual_x_over_l": float(x[peak_pos]),
                "peak_abs_residual_station_index": int(
                    numeric(group.iloc[finite_mask.nonzero()[0][peak_pos]], "station_index", -1.0)
                ),
                "configured_end_station_x_over_l": numeric(end_row, "x_over_l"),
                "endpoint_forward_gradient_integral_value": numeric(
                    end_row,
                    "endpoint_forward_gradient_integral_value",
                ),
                "end_to_endpoint_forward_ratio_abs": endpoint_ratio,
                "terminal_band_explains_residual": terminal_explains,
                "shared_end_scale_candidate_row_decision": decision,
                "diagnostic_flags": ";".join(flags) if flags else "none",
                "diagnostic_conclusion": conclusion,
                "remaining_blocker": blocker,
                "gate_role": "diagnostic_aft_terminal_end_closure_not_hard_gate",
            }
        )

    detail = pd.DataFrame(detail_rows, columns=detail_columns)
    if detail.empty:
        summary = pd.DataFrame(columns=summary_columns)
    else:
        scale = pd.to_numeric(detail["required_end_contour_scale_to_close_identity"], errors="coerce")
        finite_scale = scale[np.isfinite(scale)]
        abs_scale = finite_scale.abs()
        share = pd.to_numeric(detail["terminal_x_0p10_abs_share"], errors="coerce")
        end_ratio = pd.to_numeric(detail["end_to_endpoint_forward_ratio_abs"], errors="coerce")
        decisions = detail["shared_end_scale_candidate_row_decision"].astype(str)
        counts: dict[str, int] = {}
        for decision in decisions:
            counts[decision] = counts.get(decision, 0) + 1
        scale_spread = (
            float(abs_scale.max() / max(float(abs_scale.min()), 1e-300))
            if len(abs_scale) and float(abs_scale.min()) > 0.0
            else float("nan")
        )
        if len(finite_scale) < len(detail):
            conclusion = "end_scale_not_finite_for_all_rows_terminal_band_not_sufficient"
        elif np.isfinite(scale_spread) and scale_spread > 2.0:
            conclusion = "required_end_scale_not_shared_across_coefficients"
        elif bool((share >= 0.75).all()):
            conclusion = "aft_terminal_band_dominates_all_rows_requires_formula_trace"
        else:
            conclusion = "aft_terminal_band_and_end_scale_do_not_close_gate1"
        summary = pd.DataFrame(
            [
                {
                    "benchmark": benchmark,
                    "row_count": int(len(detail)),
                    "finite_required_end_scale_count": int(len(finite_scale)),
                    "min_required_end_contour_scale": float(finite_scale.min()) if len(finite_scale) else float("nan"),
                    "median_required_end_contour_scale": (
                        float(finite_scale.median()) if len(finite_scale) else float("nan")
                    ),
                    "max_required_end_contour_scale": float(finite_scale.max()) if len(finite_scale) else float("nan"),
                    "min_abs_required_end_contour_scale": float(abs_scale.min()) if len(abs_scale) else float("nan"),
                    "median_abs_required_end_contour_scale": (
                        float(abs_scale.median()) if len(abs_scale) else float("nan")
                    ),
                    "max_abs_required_end_contour_scale": float(abs_scale.max()) if len(abs_scale) else float("nan"),
                    "required_end_contour_scale_abs_spread": scale_spread,
                    "required_end_contour_scale_sign_change_count": count_sign_changes(scale),
                    "terminal_x_0p10_high_share_count": int((share >= 0.75).sum()) if share.notna().any() else 0,
                    "terminal_x_0p10_abs_share_min": float(share.min()) if share.notna().any() else float("nan"),
                    "terminal_x_0p10_abs_share_median": float(share.median()) if share.notna().any() else float("nan"),
                    "terminal_x_0p10_abs_share_max": float(share.max()) if share.notna().any() else float("nan"),
                    "end_to_endpoint_forward_ratio_abs_min": (
                        float(end_ratio.min()) if end_ratio.notna().any() else float("nan")
                    ),
                    "end_to_endpoint_forward_ratio_abs_median": (
                        float(end_ratio.median()) if end_ratio.notna().any() else float("nan")
                    ),
                    "end_to_endpoint_forward_ratio_abs_max": (
                        float(end_ratio.max()) if end_ratio.notna().any() else float("nan")
                    ),
                    "row_decision_counts": ";".join(
                        f"{key}:{counts[key]}" for key in sorted(counts)
                    )
                    if counts
                    else "none",
                    "diagnostic_conclusion": conclusion,
                    "remaining_blocker": (
                        "Keep aft-terminal deletion, endpoint replacement, and end-contour scaling diagnostic-only. "
                        "The next default-changing work must derive the distributed Eq.31/Eq.32 identity from "
                        "the documented contour orientation and station derivative convention."
                    ),
                    "gate_role": "diagnostic_aft_terminal_end_closure_not_hard_gate",
                    "path_diagnostic_status": "INFO",
                }
            ],
            columns=summary_columns,
        )
    detail.to_csv(detail_path, index=False)
    summary.to_csv(summary_path, index=False)
    return detail, summary


def _ma2005_matched_aft_pair_boundary_rhs_rows(
    hydro: Any,
    *,
    benchmark: str,
    source_row: int,
    hull: str,
    speed_case: str,
    omega_e_sqrt_l_over_g: float,
    coefficient: str,
    prefix: str,
    row_idx: int,
    col_idx: int,
    normalization_scale: float,
    omega_rad_s: float,
    reference_value: float,
) -> list[dict[str, float | str]]:
    """Return first-two-station boundary/RHS rows for matched-BIE failure tracing."""

    hp_row = _ma2005_longitudinal_matrix_index(row_idx)
    hp_col = _ma2005_longitudinal_matrix_index(col_idx)
    if hp_row is None or hp_col is None:
        return []
    breakdown = hydro.contribution_breakdown
    mode_name = "heave" if hp_col == 0 else "pitch"
    row_name = "heave_force" if hp_row == 0 else "pitch_moment"
    x_m = np.asarray(breakdown.get("station_x_m", np.asarray([], dtype=float)), dtype=float)
    x_over_l = np.asarray(breakdown.get("station_x_over_l", np.asarray([], dtype=float)), dtype=float)
    if x_m.ndim != 2 or x_m.shape[0] < 1 or x_m.shape[1] < 2:
        return []
    station_count = x_m.shape[1]
    if x_over_l.ndim != 2 or x_over_l.shape[0] < 1 or x_over_l.shape[1] != station_count:
        x_over_l = np.full_like(x_m, np.nan, dtype=float)
    scale = max(float(normalization_scale), 1e-300)

    def station_values(name: str) -> np.ndarray:
        value = np.asarray(breakdown.get(name, np.asarray([], dtype=float)), dtype=float)
        if value.ndim == 2 and value.shape[0] >= 1 and value.shape[1] == station_count:
            return value[0]
        if value.ndim == 1 and value.size == station_count:
            return value
        return np.full(station_count, np.nan, dtype=float)

    def aft_values(name: str) -> np.ndarray:
        value = np.asarray(breakdown.get(name, np.asarray([], dtype=float)), dtype=float)
        if value.ndim == 2 and value.shape[0] >= 1 and value.shape[1] >= 2:
            return value[0, :2]
        if value.ndim == 1 and value.size >= 2:
            return value[:2]
        return np.full(2, np.nan, dtype=float)

    def density_values(name: str) -> np.ndarray:
        density = np.asarray(breakdown.get(name, np.asarray([], dtype=complex)), dtype=complex)
        if density.ndim != 4 or density.shape[0] < 1 or density.shape[1] != station_count or density.shape[2:] != (2, 2):
            return np.full(station_count, np.nan, dtype=float)
        selected = density[0, :, hp_row, hp_col]
        return np.asarray(
            [
                _ma2005_force_component_to_coefficient_raw(value, prefix, omega_rad_s) / scale
                for value in selected
            ],
            dtype=float,
        )

    def safe_ratio(numerator: float, denominator: float) -> float:
        if not np.isfinite(numerator) or not np.isfinite(denominator) or abs(denominator) <= 1e-300:
            return float("nan")
        return float(numerator / denominator)

    body_phi = station_values(f"{mode_name}_body_potential_norms")
    body_phi_n = station_values(f"{mode_name}_body_normal_velocity_norms")
    free_phi = station_values(f"{mode_name}_free_surface_potential_norms")
    free_phi_n = station_values(f"{mode_name}_inner_free_surface_normal_derivative_norms")
    control_phi = station_values(f"{mode_name}_control_potential_norms")
    control_phi_n = station_values(f"{mode_name}_control_normal_derivative_norms")
    outer_history_rhs = station_values(f"{mode_name}_outer_history_rhs_norms")
    pressure_time = station_values(f"{mode_name}_body_pressure_time_derivative_norms")
    pressure_forward = station_values(f"{mode_name}_body_pressure_forward_speed_norms")
    pressure_total = station_values(f"{mode_name}_body_pressure_norms")
    forward_to_time = station_values(f"{mode_name}_body_pressure_forward_to_time_norm_ratios")
    total_rhs = aft_values(f"{mode_name}_aft_pair_total_rhs_norms")
    rhs_residual = aft_values(f"{mode_name}_aft_pair_source_sum_relative_residuals")
    rhs_body = aft_values(f"{mode_name}_aft_pair_body_normal_velocity_rhs_norms")
    rhs_free = aft_values(f"{mode_name}_aft_pair_inner_free_surface_potential_rhs_norms")
    rhs_history = aft_values(f"{mode_name}_aft_pair_outer_control_history_rhs_norms")
    rhs_body_ratio = aft_values(f"{mode_name}_aft_pair_body_normal_velocity_rhs_to_total_ratios")
    rhs_free_ratio = aft_values(f"{mode_name}_aft_pair_inner_free_surface_potential_rhs_to_total_ratios")
    rhs_history_ratio = aft_values(f"{mode_name}_aft_pair_outer_control_history_rhs_to_total_ratios")
    total_density = density_values("heave_pitch_total_force_density_by_station")
    time_density = density_values("heave_pitch_time_derivative_force_density_by_station")
    pressure_gradient_density = density_values("heave_pitch_forward_speed_force_density_by_station")
    stokes_density = density_values("heave_pitch_stokes_body_forward_speed_force_density_by_station")

    rows: list[dict[str, float | str]] = []
    for station_index in range(2):
        rows.append(
            {
                "benchmark": benchmark,
                "source_row": int(source_row),
                "hull": str(hull),
                "speed_case": str(speed_case),
                "omega_e_sqrt_l_over_g": float(omega_e_sqrt_l_over_g),
                "coefficient": str(coefficient),
                "reference_value": float(reference_value),
                "mode_column": mode_name,
                "generalized_row": row_name,
                "station_local_index": int(station_index),
                "x_m": float(x_m[0, station_index]),
                "x_over_l": float(x_over_l[0, station_index]),
                "body_phi_solution_norm": float(body_phi[station_index]),
                "body_phi_n_known_norm": float(body_phi_n[station_index]),
                "body_phi_to_phi_n_norm_ratio": safe_ratio(
                    float(body_phi[station_index]),
                    float(body_phi_n[station_index]),
                ),
                "free_phi_known_norm": float(free_phi[station_index]),
                "free_phi_n_solution_norm": float(free_phi_n[station_index]),
                "free_phi_n_to_phi_norm_ratio": safe_ratio(
                    float(free_phi_n[station_index]),
                    float(free_phi[station_index]),
                ),
                "control_phi_solution_norm": float(control_phi[station_index]),
                "control_phi_n_solution_norm": float(control_phi_n[station_index]),
                "control_phi_n_to_phi_norm_ratio": safe_ratio(
                    float(control_phi_n[station_index]),
                    float(control_phi[station_index]),
                ),
                "outer_history_rhs_norm": float(outer_history_rhs[station_index]),
                "matched_rhs_total_norm": float(total_rhs[station_index]),
                "matched_rhs_body_normal_velocity_norm": float(rhs_body[station_index]),
                "matched_rhs_inner_free_surface_potential_norm": float(rhs_free[station_index]),
                "matched_rhs_outer_control_history_norm": float(rhs_history[station_index]),
                "matched_rhs_body_normal_velocity_to_total_ratio": float(rhs_body_ratio[station_index]),
                "matched_rhs_inner_free_surface_potential_to_total_ratio": float(rhs_free_ratio[station_index]),
                "matched_rhs_outer_control_history_to_total_ratio": float(rhs_history_ratio[station_index]),
                "matched_rhs_source_sum_relative_residual": float(rhs_residual[station_index]),
                "body_pressure_total_norm": float(pressure_total[station_index]),
                "body_pressure_time_derivative_norm": float(pressure_time[station_index]),
                "body_pressure_forward_speed_norm": float(pressure_forward[station_index]),
                "body_pressure_forward_to_time_norm_ratio": float(forward_to_time[station_index]),
                "total_density_value_per_m": float(total_density[station_index]),
                "time_derivative_density_value_per_m": float(time_density[station_index]),
                "pressure_gradient_density_value_per_m": float(pressure_gradient_density[station_index]),
                "stokes_body_forward_density_value_per_m": float(stokes_density[station_index]),
                "gate_role": "diagnostic_aft_pair_boundary_rhs_not_hard_gate",
            }
        )
    return rows


def _ma2005_aft_pair_boundary_rhs_summary(data: pd.DataFrame, benchmark: str) -> pd.DataFrame:
    """Summarize aft-pair boundary/RHS diagnostics by coefficient."""

    if data.empty:
        return pd.DataFrame()
    rows: list[dict[str, float | str | int]] = []
    for coefficient, group in data.groupby("coefficient", sort=False):
        gradient = pd.to_numeric(group["pressure_gradient_density_value_per_m"], errors="coerce").abs()
        peak_index = gradient.idxmax() if gradient.notna().any() else group.index[0]
        peak = group.loc[peak_index]
        rhs_body = pd.to_numeric(group["matched_rhs_body_normal_velocity_to_total_ratio"], errors="coerce")
        rhs_free = pd.to_numeric(group["matched_rhs_inner_free_surface_potential_to_total_ratio"], errors="coerce")
        rhs_history = pd.to_numeric(group["matched_rhs_outer_control_history_to_total_ratio"], errors="coerce")
        forward_to_time = pd.to_numeric(group["body_pressure_forward_to_time_norm_ratio"], errors="coerce")
        body_phi_ratio = pd.to_numeric(group["body_phi_to_phi_n_norm_ratio"], errors="coerce")
        rows.append(
            {
                "benchmark": benchmark,
                "coefficient": str(coefficient),
                "station_count": int(len(group)),
                "peak_pressure_gradient_station_local_index": int(peak["station_local_index"]),
                "peak_pressure_gradient_x_over_l": float(peak["x_over_l"]),
                "peak_pressure_gradient_density_abs": float(gradient.loc[peak_index]),
                "max_body_pressure_forward_to_time_norm_ratio": (
                    float(forward_to_time.max()) if forward_to_time.notna().any() else float("nan")
                ),
                "max_rhs_body_normal_velocity_to_total_ratio": (
                    float(rhs_body.max()) if rhs_body.notna().any() else float("nan")
                ),
                "max_rhs_inner_free_surface_potential_to_total_ratio": (
                    float(rhs_free.max()) if rhs_free.notna().any() else float("nan")
                ),
                "max_rhs_outer_control_history_to_total_ratio": (
                    float(rhs_history.max()) if rhs_history.notna().any() else float("nan")
                ),
                "max_body_phi_to_phi_n_norm_ratio": (
                    float(body_phi_ratio.max()) if body_phi_ratio.notna().any() else float("nan")
                ),
                "max_rhs_source_sum_relative_residual": float(
                    pd.to_numeric(group["matched_rhs_source_sum_relative_residual"], errors="coerce").max()
                ),
                "gate_role": "diagnostic_aft_pair_boundary_rhs_not_hard_gate",
                "path_diagnostic_status": "INFO",
            }
        )
    return pd.DataFrame(rows)


def _ma2005_matched_inner_free_surface_rhs_block_rows(
    hydro: Any,
    *,
    benchmark: str,
    source_row: int,
    hull: str,
    speed_case: str,
    omega_e_sqrt_l_over_g: float,
    coefficient: str,
    row_idx: int,
    col_idx: int,
    reference_value: float,
) -> list[dict[str, float | str | int]]:
    """Return Eq. (23) inner-free-surface-potential matrix-block diagnostic rows."""

    hp_row = _ma2005_longitudinal_matrix_index(row_idx)
    hp_col = _ma2005_longitudinal_matrix_index(col_idx)
    if hp_row is None or hp_col is None:
        return []
    breakdown = hydro.contribution_breakdown
    mode_name = "heave" if hp_col == 0 else "pitch"
    row_name = "heave_force" if hp_row == 0 else "pitch_moment"
    x_m = np.asarray(breakdown.get("station_x_m", np.asarray([], dtype=float)), dtype=float)
    x_over_l = np.asarray(breakdown.get("station_x_over_l", np.asarray([], dtype=float)), dtype=float)
    if x_m.ndim != 2 or x_m.shape[0] < 1 or x_m.shape[1] < 2:
        return []
    station_count = min(2, x_m.shape[1])
    if x_over_l.ndim != 2 or x_over_l.shape[0] < 1 or x_over_l.shape[1] != x_m.shape[1]:
        x_over_l = np.full_like(x_m, np.nan, dtype=float)
    row_block_names_raw = np.asarray(
        breakdown.get(
            "aft_pair_inner_free_surface_rhs_row_block_names",
            np.asarray(("eq23_body", "eq23_free_surface", "eq23_inner_control"), dtype=str),
        )
    )
    row_block_names = [str(value) for value in row_block_names_raw.tolist()]

    def panel_values(name: str) -> np.ndarray:
        value = np.asarray(
            breakdown.get(f"{mode_name}_aft_pair_inner_free_surface_rhs_block_{name}", np.asarray([], dtype=float)),
            dtype=float,
        )
        if value.ndim == 4 and value.shape[0] >= 1 and value.shape[1] >= station_count:
            return value[0, :station_count]
        return np.full((station_count, len(row_block_names), 0), np.nan, dtype=float)

    def block_values(name: str) -> np.ndarray:
        value = np.asarray(
            breakdown.get(f"{mode_name}_aft_pair_inner_free_surface_rhs_block_{name}", np.asarray([], dtype=float)),
            dtype=float,
        )
        if value.ndim == 3 and value.shape[0] >= 1 and value.shape[1] >= station_count:
            return value[0, :station_count]
        return np.full((station_count, len(row_block_names)), np.nan, dtype=float)

    panel_y = panel_values("free_surface_panel_y_m")
    panel_length = panel_values("free_surface_panel_length_m")
    phi_abs = panel_values("free_surface_potential_abs")
    phi_phase = panel_values("free_surface_potential_phase_degs")
    matrix_column = panel_values("matrix_column_norms")
    contribution = panel_values("contribution_norms")
    panel_to_row = panel_values("panel_to_row_block_ratios")
    panel_to_total = panel_values("panel_to_total_ratios")
    panel_alignment = panel_values("panel_to_row_block_alignments")
    panel_phase = panel_values("panel_to_row_block_phase_degs")
    row_block_rhs = block_values("row_block_free_rhs_norms")
    row_to_total = block_values("row_block_to_total_ratios")
    row_alignment = block_values("row_block_to_total_alignments")
    row_phase = block_values("row_block_to_total_phase_degs")
    total_free = np.asarray(
        breakdown.get(
            f"{mode_name}_aft_pair_inner_free_surface_rhs_block_total_free_rhs_norms",
            np.asarray([], dtype=float),
        ),
        dtype=float,
    )
    if total_free.ndim == 2 and total_free.shape[0] >= 1 and total_free.shape[1] >= station_count:
        total_free = total_free[0, :station_count]
    else:
        total_free = np.full(station_count, np.nan, dtype=float)

    if contribution.shape[2] == 0:
        return []
    rows: list[dict[str, float | str | int]] = []
    for station_index in range(station_count):
        for row_block_index, row_block_name in enumerate(row_block_names):
            for panel_index in range(contribution.shape[2]):
                rows.append(
                    {
                        "benchmark": benchmark,
                        "source_row": int(source_row),
                        "hull": str(hull),
                        "speed_case": str(speed_case),
                        "omega_e_sqrt_l_over_g": float(omega_e_sqrt_l_over_g),
                        "coefficient": str(coefficient),
                        "reference_value": float(reference_value),
                        "mode_column": mode_name,
                        "generalized_row": row_name,
                        "station_local_index": int(station_index),
                        "x_m": float(x_m[0, station_index]),
                        "x_over_l": float(x_over_l[0, station_index]),
                        "row_block_index": int(row_block_index),
                        "row_block_name": str(row_block_name),
                        "free_surface_panel_index": int(panel_index),
                        "free_surface_panel_y_m": float(panel_y[station_index, row_block_index, panel_index]),
                        "free_surface_panel_length_m": float(
                            panel_length[station_index, row_block_index, panel_index]
                        ),
                        "free_surface_potential_abs": float(phi_abs[station_index, row_block_index, panel_index]),
                        "free_surface_potential_phase_deg": float(
                            phi_phase[station_index, row_block_index, panel_index]
                        ),
                        "matrix_column_norm": float(matrix_column[station_index, row_block_index, panel_index]),
                        "row_block_contribution_norm": float(
                            contribution[station_index, row_block_index, panel_index]
                        ),
                        "row_block_free_rhs_norm": float(row_block_rhs[station_index, row_block_index]),
                        "total_free_rhs_norm": float(total_free[station_index]),
                        "row_block_to_total_free_rhs_norm_ratio": float(
                            row_to_total[station_index, row_block_index]
                        ),
                        "panel_to_row_block_free_rhs_norm_ratio": float(
                            panel_to_row[station_index, row_block_index, panel_index]
                        ),
                        "panel_to_total_free_rhs_norm_ratio": float(
                            panel_to_total[station_index, row_block_index, panel_index]
                        ),
                        "panel_to_row_block_real_alignment": float(
                            panel_alignment[station_index, row_block_index, panel_index]
                        ),
                        "panel_to_row_block_phase_deg": float(
                            panel_phase[station_index, row_block_index, panel_index]
                        ),
                        "row_block_to_total_real_alignment": float(row_alignment[station_index, row_block_index]),
                        "row_block_to_total_phase_deg": float(row_phase[station_index, row_block_index]),
                        "gate_role": "diagnostic_inner_free_surface_rhs_block_not_hard_gate",
                    }
                )
    return rows


def _ma2005_inner_free_surface_rhs_block_summary(data: pd.DataFrame, benchmark: str) -> pd.DataFrame:
    """Summarize Eq. (23) inner-free-surface RHS block diagnostics by coefficient."""

    if data.empty:
        return pd.DataFrame()
    rows: list[dict[str, float | str | int]] = []
    for coefficient, group in data.groupby("coefficient", sort=False):
        contribution = pd.to_numeric(group["row_block_contribution_norm"], errors="coerce")
        peak_index = contribution.idxmax() if contribution.notna().any() else group.index[0]
        peak = group.loc[peak_index]
        row_ratio = pd.to_numeric(group["row_block_to_total_free_rhs_norm_ratio"], errors="coerce")
        panel_total_ratio = pd.to_numeric(group["panel_to_total_free_rhs_norm_ratio"], errors="coerce")
        panel_row_ratio = pd.to_numeric(group["panel_to_row_block_free_rhs_norm_ratio"], errors="coerce")
        matrix_norm = pd.to_numeric(group["matrix_column_norm"], errors="coerce")
        rows.append(
            {
                "benchmark": benchmark,
                "coefficient": str(coefficient),
                "row_count": int(len(group)),
                "station_count": int(group["station_local_index"].nunique()),
                "row_block_count": int(group["row_block_name"].nunique()),
                "free_surface_panel_count": int(group["free_surface_panel_index"].nunique()),
                "dominant_station_local_index": int(peak["station_local_index"]),
                "dominant_x_over_l": float(peak["x_over_l"]),
                "dominant_row_block_name": str(peak["row_block_name"]),
                "dominant_free_surface_panel_index": int(peak["free_surface_panel_index"]),
                "dominant_free_surface_panel_y_m": float(peak["free_surface_panel_y_m"]),
                "dominant_row_block_contribution_norm": float(peak["row_block_contribution_norm"]),
                "dominant_panel_to_total_free_rhs_norm_ratio": float(
                    peak["panel_to_total_free_rhs_norm_ratio"]
                ),
                "dominant_panel_to_row_block_free_rhs_norm_ratio": float(
                    peak["panel_to_row_block_free_rhs_norm_ratio"]
                ),
                "dominant_matrix_column_norm": float(peak["matrix_column_norm"]),
                "max_row_block_to_total_free_rhs_norm_ratio": (
                    float(row_ratio.max()) if row_ratio.notna().any() else float("nan")
                ),
                "max_panel_to_total_free_rhs_norm_ratio": (
                    float(panel_total_ratio.max()) if panel_total_ratio.notna().any() else float("nan")
                ),
                "max_panel_to_row_block_free_rhs_norm_ratio": (
                    float(panel_row_ratio.max()) if panel_row_ratio.notna().any() else float("nan")
                ),
                "max_matrix_column_norm": float(matrix_norm.max()) if matrix_norm.notna().any() else float("nan"),
                "gate_role": "diagnostic_inner_free_surface_rhs_block_not_hard_gate",
                "path_diagnostic_status": "INFO",
            }
        )
    return pd.DataFrame(rows)


def _ma2005_inner_free_surface_self_block_candidate_rows(
    row: pd.Series,
    *,
    benchmark: str,
    source_row: int,
    expected: float,
    tolerance: float,
    row_idx: int,
    col_idx: int,
    bem_free_surface_panel_count_per_side: int,
    bem_body_panel_count: int | None,
    matrix_cache: dict[tuple[float | int | str, ...], object],
    benchmark_base_dir: Path | None,
) -> list[dict[str, float | str | int | bool]]:
    """Recompute matched-BIE Ma 2005 rows for diagnostic Eq.23 free-self-block candidates."""

    detail_rows: list[dict[str, float | str | int | bool]] = []
    for candidate in MA2005_INNER_FREE_SURFACE_SELF_BLOCK_CANDIDATES:
        candidate_name = str(candidate["candidate_name"])
        variant = row.copy()
        variant["matched_inner_a_scale"] = float(candidate["inner_a_scale"])
        variant["matched_inner_diagonal_sign"] = float(candidate["inner_diagonal_sign"])
        variant["matched_inner_free_surface_self_diagonal_scale"] = float(
            candidate["inner_free_surface_self_diagonal_scale"]
        )
        try:
            calc = _ma2005_computed_coefficient(
                variant,
                hydro_model=MA2005_MATCHED_BIE_MODEL,
                bem_free_surface_panel_count_per_side=bem_free_surface_panel_count_per_side,
                bem_body_panel_count=bem_body_panel_count,
                matrix_cache=matrix_cache,
                benchmark_base_dir=benchmark_base_dir,
            )
            metrics = _ma2005_error_metrics(
                expected,
                float(calc["computed_value"]),
                tolerance,
                row_idx,
                col_idx,
                str(calc["normalization"]),
            )
            expected_raw = float(expected) * float(calc["normalization_scale"])
            raw_ratio = (
                float(float(calc["raw_value"]) / expected_raw)
                if abs(expected_raw) > 1e-300
                else float("nan")
            )
            detail_rows.append(
                {
                    "benchmark": benchmark,
                    "source_row": int(source_row),
                    "hull": str(row["hull"]),
                    "speed_case": str(row["speed_case"]),
                    "omega_e_sqrt_l_over_g": float(row["omega_e_sqrt_l_over_g"]),
                    "coefficient": str(row["coefficient"]),
                    "candidate_name": candidate_name,
                    "candidate_description": str(candidate["description"]),
                    "candidate_is_current_default": bool(candidate_name == "current_default"),
                    "reference_value": float(expected),
                    "computed_value": float(calc["computed_value"]),
                    "raw_computed_value": float(calc["raw_value"]),
                    "raw_to_reference_raw_ratio": raw_ratio,
                    "abs_error": float(metrics["abs_error"]),
                    "rel_error": float(metrics["rel_error"]),
                    "tolerance": float(tolerance),
                    "effective_abs_tolerance": float(metrics["effective_abs_tolerance"]),
                    "gate_error_ratio": float(metrics["gate_error_ratio"]),
                    "error_metric": str(metrics["error_metric"]),
                    "candidate_gate_status": str(metrics["status"]),
                    "inner_a_scale": float(candidate["inner_a_scale"]),
                    "inner_diagonal_sign": float(candidate["inner_diagonal_sign"]),
                    "inner_free_surface_self_diagonal_scale": float(
                        candidate["inner_free_surface_self_diagonal_scale"]
                    ),
                    "provider_route": str(calc.get("provider_route", "")),
                    "provider_formulation": str(calc.get("provider_formulation", "")),
                    "gate_role": "diagnostic_inner_free_surface_self_block_candidate_not_hard_gate",
                }
            )
        except Exception as exc:
            detail_rows.append(
                {
                    "benchmark": benchmark,
                    "source_row": int(source_row),
                    "hull": str(row.get("hull", "")),
                    "speed_case": str(row.get("speed_case", "")),
                    "omega_e_sqrt_l_over_g": float(row.get("omega_e_sqrt_l_over_g", float("nan"))),
                    "coefficient": str(row.get("coefficient", "")),
                    "candidate_name": candidate_name,
                    "candidate_description": str(candidate["description"]),
                    "candidate_is_current_default": bool(candidate_name == "current_default"),
                    "reference_value": float(expected),
                    "computed_value": float("nan"),
                    "raw_computed_value": float("nan"),
                    "raw_to_reference_raw_ratio": float("nan"),
                    "abs_error": float("nan"),
                    "rel_error": float("nan"),
                    "tolerance": float(tolerance),
                    "effective_abs_tolerance": float("nan"),
                    "gate_error_ratio": float("nan"),
                    "error_metric": "exception",
                    "candidate_gate_status": "FAIL",
                    "inner_a_scale": float(candidate["inner_a_scale"]),
                    "inner_diagonal_sign": float(candidate["inner_diagonal_sign"]),
                    "inner_free_surface_self_diagonal_scale": float(
                        candidate["inner_free_surface_self_diagonal_scale"]
                    ),
                    "provider_route": "",
                    "provider_formulation": "",
                    "gate_role": "diagnostic_inner_free_surface_self_block_candidate_not_hard_gate",
                    "exception": str(exc),
                }
            )
    return detail_rows


def _ma2005_inner_free_surface_self_block_candidate_summary(
    data: pd.DataFrame,
    benchmark: str,
) -> pd.DataFrame:
    """Summarize diagnostic Eq.23 free-self-block candidates across Ma 2005 coefficient rows."""

    if data.empty:
        return pd.DataFrame()
    order = {
        str(candidate["candidate_name"]): index
        for index, candidate in enumerate(MA2005_INNER_FREE_SURFACE_SELF_BLOCK_CANDIDATES)
    }
    rows: list[dict[str, float | str | int]] = []
    for candidate_name, group in data.groupby("candidate_name", sort=False):
        status = group["candidate_gate_status"].astype(str)
        gate_ratio = pd.to_numeric(group["gate_error_ratio"], errors="coerce")
        abs_error = pd.to_numeric(group["abs_error"], errors="coerce")
        rel_error = pd.to_numeric(group["rel_error"], errors="coerce")
        rows.append(
            {
                "benchmark": benchmark,
                "candidate_name": str(candidate_name),
                "candidate_order": int(order.get(str(candidate_name), 999)),
                "row_count": int(len(group)),
                "pass_count": int(status.eq("PASS").sum()),
                "fail_count": int(status.eq("FAIL").sum()),
                "pass_fraction": float(status.eq("PASS").mean()) if len(group) else float("nan"),
                "median_gate_error_ratio": float(gate_ratio.median()) if gate_ratio.notna().any() else float("nan"),
                "max_gate_error_ratio": float(gate_ratio.max()) if gate_ratio.notna().any() else float("nan"),
                "median_abs_error": float(abs_error.median()) if abs_error.notna().any() else float("nan"),
                "max_abs_error": float(abs_error.max()) if abs_error.notna().any() else float("nan"),
                "median_rel_error": float(rel_error.median()) if rel_error.notna().any() else float("nan"),
                "max_rel_error": float(rel_error.max()) if rel_error.notna().any() else float("nan"),
                "candidate_gate_status": "PASS" if status.eq("PASS").all() else "FAIL",
                "gate_role": "diagnostic_inner_free_surface_self_block_candidate_not_hard_gate",
                "path_diagnostic_status": "INFO",
            }
        )
    summary = pd.DataFrame(rows).sort_values(["candidate_order", "candidate_name"]).reset_index(drop=True)
    finite_max = pd.to_numeric(summary["max_gate_error_ratio"], errors="coerce")
    finite_median = pd.to_numeric(summary["median_gate_error_ratio"], errors="coerce")
    sortable = summary.assign(
        _sort_max=finite_max.where(finite_max.notna(), float("inf")),
        _sort_median=finite_median.where(finite_median.notna(), float("inf")),
    )
    return sortable.sort_values(["_sort_max", "_sort_median", "candidate_order"]).drop(
        columns=["_sort_max", "_sort_median"]
    )


def _ma2005_inner_free_surface_block_coupling_candidate_rows(
    row: pd.Series,
    *,
    benchmark: str,
    source_row: int,
    expected: float,
    tolerance: float,
    row_idx: int,
    col_idx: int,
    current_calc: dict[str, float | str],
    current_gate_error_ratio: float,
    bem_free_surface_panel_count_per_side: int,
    bem_body_panel_count: int | None,
    matrix_cache: dict[tuple[float | int | str, ...], object],
    benchmark_base_dir: Path | None,
) -> list[dict[str, float | str | int | bool]]:
    """Recompute matched-BIE rows for diagnostic Eq.23 free-surface block-coupling candidates."""

    order_by_name = {
        str(candidate["candidate_name"]): index
        for index, candidate in enumerate(MA2005_INNER_FREE_SURFACE_BLOCK_COUPLING_CANDIDATES)
    }

    def calc_float(calc: dict[str, float | str], key: str) -> float:
        try:
            return float(calc.get(key, float("nan")))
        except (TypeError, ValueError):
            return float("nan")

    detail_rows: list[dict[str, float | str | int | bool]] = []
    for candidate in MA2005_INNER_FREE_SURFACE_BLOCK_COUPLING_CANDIDATES:
        candidate_name = str(candidate["candidate_name"])
        known_scale = float(candidate["known_potential_rhs_scale"])
        unknown_scale = float(candidate["unknown_normal_column_scale"])
        try:
            if candidate_name == "current_default":
                calc = current_calc
                recomputed = False
            else:
                variant = row.copy()
                variant["matched_inner_free_surface_known_potential_rhs_scale"] = known_scale
                variant["matched_inner_free_surface_unknown_normal_column_scale"] = unknown_scale
                calc = _ma2005_computed_coefficient(
                    variant,
                    hydro_model=MA2005_MATCHED_BIE_MODEL,
                    bem_free_surface_panel_count_per_side=bem_free_surface_panel_count_per_side,
                    bem_body_panel_count=bem_body_panel_count,
                    matrix_cache=matrix_cache,
                    benchmark_base_dir=benchmark_base_dir,
                )
                recomputed = True
            metrics = _ma2005_error_metrics(
                expected,
                float(calc["computed_value"]),
                tolerance,
                row_idx,
                col_idx,
                str(calc["normalization"]),
            )
            expected_raw = float(expected) * float(calc["normalization_scale"])
            raw_ratio = (
                float(float(calc["raw_value"]) / expected_raw)
                if abs(expected_raw) > 1e-300
                else float("nan")
            )
            gate_error_ratio = float(metrics["gate_error_ratio"])
            detail_rows.append(
                {
                    "benchmark": benchmark,
                    "source_row": int(source_row),
                    "hull": str(row["hull"]),
                    "speed_case": str(row["speed_case"]),
                    "omega_e_sqrt_l_over_g": float(row["omega_e_sqrt_l_over_g"]),
                    "coefficient": str(row["coefficient"]),
                    "candidate_name": candidate_name,
                    "candidate_order": int(order_by_name.get(candidate_name, 999)),
                    "candidate_description": str(candidate["description"]),
                    "candidate_is_current_default": bool(candidate_name == "current_default"),
                    "candidate_recomputed_matched_bie": bool(recomputed),
                    "known_potential_rhs_scale": known_scale,
                    "unknown_normal_column_scale": unknown_scale,
                    "reference_value": float(expected),
                    "computed_value": float(calc["computed_value"]),
                    "raw_computed_value": float(calc["raw_value"]),
                    "raw_to_reference_raw_ratio": raw_ratio,
                    "abs_error": float(metrics["abs_error"]),
                    "rel_error": float(metrics["rel_error"]),
                    "tolerance": float(tolerance),
                    "near_zero_abs_tolerance": float(metrics["near_zero_abs_tolerance"]),
                    "effective_abs_tolerance": float(metrics["effective_abs_tolerance"]),
                    "gate_error_ratio": gate_error_ratio,
                    "current_default_gate_error_ratio": float(current_gate_error_ratio),
                    "gate_ratio_delta_vs_current": (
                        gate_error_ratio - float(current_gate_error_ratio)
                        if np.isfinite(gate_error_ratio)
                        and np.isfinite(float(current_gate_error_ratio))
                        else float("nan")
                    ),
                    "error_metric": str(metrics["error_metric"]),
                    "candidate_gate_status": str(metrics["status"]),
                    "matched_heave_free_surface_potential_norm_max": calc_float(
                        calc,
                        "matched_heave_free_surface_potential_norm_max",
                    ),
                    "matched_pitch_free_surface_potential_norm_max": calc_float(
                        calc,
                        "matched_pitch_free_surface_potential_norm_max",
                    ),
                    "matched_heave_inner_free_surface_normal_derivative_norm_max": calc_float(
                        calc,
                        "matched_heave_inner_free_surface_normal_derivative_norm_max",
                    ),
                    "matched_pitch_inner_free_surface_normal_derivative_norm_max": calc_float(
                        calc,
                        "matched_pitch_inner_free_surface_normal_derivative_norm_max",
                    ),
                    "matched_heave_free_surface_potential_increment_to_normal_derivative_gain_max": calc_float(
                        calc,
                        "matched_heave_free_surface_potential_increment_to_normal_derivative_gain_max",
                    ),
                    "matched_heave_free_surface_potential_increment_normal_derivative_phase_deg_median": calc_float(
                        calc,
                        "matched_heave_free_surface_potential_increment_normal_derivative_phase_deg_median",
                    ),
                    "matched_selected_body_pressure_to_body_potential_gain_max": calc_float(
                        calc,
                        "matched_selected_body_pressure_to_body_potential_gain_max",
                    ),
                    "matched_selected_body_pressure_forward_to_time_norm_ratio_max": calc_float(
                        calc,
                        "matched_selected_body_pressure_forward_to_time_norm_ratio_max",
                    ),
                    "matched_selected_pressure_gradient_component_value": calc_float(
                        calc,
                        "matched_pressure_gradient_component_value",
                    ),
                    "provider_route": str(calc.get("provider_route", "")),
                    "provider_formulation": str(calc.get("provider_formulation", "")),
                    "gate_role": "diagnostic_inner_free_surface_block_coupling_candidate_not_hard_gate",
                }
            )
        except Exception as exc:
            detail_rows.append(
                {
                    "benchmark": benchmark,
                    "source_row": int(source_row),
                    "hull": str(row.get("hull", "")),
                    "speed_case": str(row.get("speed_case", "")),
                    "omega_e_sqrt_l_over_g": float(row.get("omega_e_sqrt_l_over_g", float("nan"))),
                    "coefficient": str(row.get("coefficient", "")),
                    "candidate_name": candidate_name,
                    "candidate_order": int(order_by_name.get(candidate_name, 999)),
                    "candidate_description": str(candidate["description"]),
                    "candidate_is_current_default": bool(candidate_name == "current_default"),
                    "candidate_recomputed_matched_bie": False,
                    "known_potential_rhs_scale": known_scale,
                    "unknown_normal_column_scale": unknown_scale,
                    "reference_value": float(expected),
                    "computed_value": float("nan"),
                    "raw_computed_value": float("nan"),
                    "raw_to_reference_raw_ratio": float("nan"),
                    "abs_error": float("nan"),
                    "rel_error": float("nan"),
                    "tolerance": float(tolerance),
                    "near_zero_abs_tolerance": float("nan"),
                    "effective_abs_tolerance": float("nan"),
                    "gate_error_ratio": float("nan"),
                    "current_default_gate_error_ratio": float(current_gate_error_ratio),
                    "gate_ratio_delta_vs_current": float("nan"),
                    "error_metric": "exception",
                    "candidate_gate_status": "FAIL",
                    "matched_heave_free_surface_potential_norm_max": float("nan"),
                    "matched_pitch_free_surface_potential_norm_max": float("nan"),
                    "matched_heave_inner_free_surface_normal_derivative_norm_max": float("nan"),
                    "matched_pitch_inner_free_surface_normal_derivative_norm_max": float("nan"),
                    "matched_heave_free_surface_potential_increment_to_normal_derivative_gain_max": float("nan"),
                    "matched_heave_free_surface_potential_increment_normal_derivative_phase_deg_median": float("nan"),
                    "matched_selected_body_pressure_to_body_potential_gain_max": float("nan"),
                    "matched_selected_body_pressure_forward_to_time_norm_ratio_max": float("nan"),
                    "matched_selected_pressure_gradient_component_value": float("nan"),
                    "provider_route": "",
                    "provider_formulation": "",
                    "gate_role": "diagnostic_inner_free_surface_block_coupling_candidate_not_hard_gate",
                    "failure_reason": str(exc),
                }
            )
    return detail_rows


def _ma2005_inner_free_surface_block_coupling_candidate_summary(
    data: pd.DataFrame,
    benchmark: str,
) -> pd.DataFrame:
    """Summarize Eq.23 free-surface block-coupling candidates across Ma 2005 rows."""

    if data.empty:
        return pd.DataFrame()
    rows: list[dict[str, float | str | int]] = []
    for candidate_name, group in data.groupby("candidate_name", sort=False):
        status = group["candidate_gate_status"].astype(str)
        gate_ratio = pd.to_numeric(group["gate_error_ratio"], errors="coerce")
        delta = pd.to_numeric(group["gate_ratio_delta_vs_current"], errors="coerce")
        heave_phi = pd.to_numeric(group["matched_heave_free_surface_potential_norm_max"], errors="coerce")
        inner_normal = pd.to_numeric(
            group["matched_heave_inner_free_surface_normal_derivative_norm_max"],
            errors="coerce",
        )
        pressure_gain = pd.to_numeric(
            group["matched_selected_body_pressure_to_body_potential_gain_max"],
            errors="coerce",
        )
        gradient_component = pd.to_numeric(
            group["matched_selected_pressure_gradient_component_value"],
            errors="coerce",
        )
        rows.append(
            {
                "benchmark": benchmark,
                "candidate_name": str(candidate_name),
                "candidate_order": int(pd.to_numeric(group["candidate_order"], errors="coerce").iloc[0]),
                "known_potential_rhs_scale": float(
                    pd.to_numeric(group["known_potential_rhs_scale"], errors="coerce").iloc[0]
                ),
                "unknown_normal_column_scale": float(
                    pd.to_numeric(group["unknown_normal_column_scale"], errors="coerce").iloc[0]
                ),
                "row_count": int(len(group)),
                "pass_count": int(status.eq("PASS").sum()),
                "fail_count": int(status.eq("FAIL").sum()),
                "pass_fraction": float(status.eq("PASS").mean()) if len(group) else float("nan"),
                "median_gate_error_ratio": float(gate_ratio.median()) if gate_ratio.notna().any() else float("nan"),
                "max_gate_error_ratio": float(gate_ratio.max()) if gate_ratio.notna().any() else float("nan"),
                "median_gate_ratio_delta_vs_current": float(delta.median()) if delta.notna().any() else float("nan"),
                "max_gate_ratio_delta_vs_current": float(delta.max()) if delta.notna().any() else float("nan"),
                "improved_row_count": int((delta < 0.0).sum()) if delta.notna().any() else 0,
                "worsened_row_count": int((delta > 0.0).sum()) if delta.notna().any() else 0,
                "median_heave_free_surface_potential_norm_max": (
                    float(heave_phi.median()) if heave_phi.notna().any() else float("nan")
                ),
                "median_heave_inner_free_surface_normal_derivative_norm_max": (
                    float(inner_normal.median()) if inner_normal.notna().any() else float("nan")
                ),
                "median_selected_body_pressure_to_body_potential_gain_max": (
                    float(pressure_gain.median()) if pressure_gain.notna().any() else float("nan")
                ),
                "max_abs_selected_pressure_gradient_component_value": (
                    float(gradient_component.abs().max()) if gradient_component.notna().any() else float("nan")
                ),
                "candidate_gate_status": "PASS" if status.eq("PASS").all() else "FAIL",
                "gate_role": "diagnostic_inner_free_surface_block_coupling_candidate_not_hard_gate",
                "path_diagnostic_status": "INFO",
            }
        )
    summary = pd.DataFrame(rows)
    finite_max = pd.to_numeric(summary["max_gate_error_ratio"], errors="coerce")
    finite_median = pd.to_numeric(summary["median_gate_error_ratio"], errors="coerce")
    sortable = summary.assign(
        _sort_max=finite_max.where(finite_max.notna(), float("inf")),
        _sort_median=finite_median.where(finite_median.notna(), float("inf")),
    )
    return sortable.sort_values(["_sort_max", "_sort_median", "candidate_order"]).drop(
        columns=["_sort_max", "_sort_median"]
    )


def _ma2005_startup_ghost_station_candidate_detail(
    comparison: pd.DataFrame,
    benchmark: str,
) -> pd.DataFrame:
    """Return diagnostic start-up/ghost-station candidate rows from matched-BIE component columns."""

    if comparison.empty:
        return pd.DataFrame()
    rows: list[dict[str, float | str | int | bool]] = []
    description_by_name = {
        str(candidate["candidate_name"]): str(candidate["description"])
        for candidate in MA2005_STARTUP_GHOST_STATION_CANDIDATES
    }
    order_by_name = {
        str(candidate["candidate_name"]): index
        for index, candidate in enumerate(MA2005_STARTUP_GHOST_STATION_CANDIDATES)
    }

    def value(row: pd.Series, column: str) -> float:
        if column not in row:
            return float("nan")
        try:
            return float(row[column])
        except (TypeError, ValueError):
            return float("nan")

    for _, source in comparison.iterrows():
        expected = value(source, "reference_value")
        scale = max(value(source, "normalization_scale"), 1e-300)
        effective_abs_tolerance = value(source, "effective_abs_tolerance")
        if not np.isfinite(effective_abs_tolerance) or effective_abs_tolerance <= 0.0:
            effective_abs_tolerance = max(value(source, "tolerance") * abs(expected), 1e-12)
        end_value = value(source, "matched_end_term_component_value")
        candidates = {
            "current_default": value(source, "computed_value"),
            "ghost_aft_pressure_plus_end": (
                value(source, "matched_selected_pressure_integral_excluding_aft_active_station_value")
                + end_value
            ),
            "ghost_aft_pressure_no_end": value(
                source,
                "matched_selected_pressure_integral_excluding_aft_active_station_value",
            ),
            "ghost_aft_forward_only_removed_keep_time_end": (
                value(source, "matched_time_derivative_component_value")
                + value(source, "matched_selected_forward_integral_excluding_aft_active_station_value")
                + end_value
            ),
            "ghost_aft_time_only_removed_keep_forward_end": (
                value(source, "matched_selected_time_integral_excluding_aft_active_station_value")
                + value(source, "matched_pressure_gradient_component_value")
                + end_value
            ),
            "bow_pressure_excluded_plus_end": (
                value(source, "matched_selected_pressure_integral_excluding_bow_active_station_value")
                + end_value
            ),
            "both_end_pressure_excluded_plus_end": (
                value(source, "matched_selected_pressure_integral_excluding_end_active_stations_value")
                + end_value
            ),
        }
        reference_raw = expected * scale
        current_gate = value(source, "gate_error_ratio")
        for candidate_name, candidate_value in candidates.items():
            raw_value = candidate_value * scale if np.isfinite(candidate_value) else float("nan")
            abs_error = abs(candidate_value - expected) if np.isfinite(candidate_value) else float("nan")
            rel_error = abs_error / max(abs(expected), 1e-12) if np.isfinite(abs_error) else float("nan")
            gate_error_ratio = (
                abs_error / effective_abs_tolerance
                if np.isfinite(abs_error) and effective_abs_tolerance > 0.0
                else float("nan")
            )
            rows.append(
                {
                    "benchmark": benchmark,
                    "source_row": int(value(source, "row")),
                    "hull": str(source.get("hull", "")),
                    "speed_case": str(source.get("speed_case", "")),
                    "omega_e_sqrt_l_over_g": value(source, "omega_e_sqrt_l_over_g"),
                    "coefficient": str(source.get("coefficient", "")),
                    "candidate_name": candidate_name,
                    "candidate_order": int(order_by_name.get(candidate_name, 999)),
                    "candidate_description": description_by_name.get(candidate_name, ""),
                    "candidate_is_current_default": bool(candidate_name == "current_default"),
                    "reference_value": expected,
                    "computed_value": candidate_value,
                    "raw_computed_value": raw_value,
                    "raw_to_reference_raw_ratio": (
                        float(raw_value / reference_raw)
                        if np.isfinite(raw_value) and abs(reference_raw) > 1e-300
                        else float("nan")
                    ),
                    "abs_error": abs_error,
                    "rel_error": rel_error,
                    "tolerance": value(source, "tolerance"),
                    "effective_abs_tolerance": effective_abs_tolerance,
                    "gate_error_ratio": gate_error_ratio,
                    "current_default_gate_error_ratio": current_gate,
                    "gate_ratio_delta_vs_current": (
                        gate_error_ratio - current_gate
                        if np.isfinite(gate_error_ratio) and np.isfinite(current_gate)
                        else float("nan")
                    ),
                    "candidate_gate_status": "PASS" if np.isfinite(gate_error_ratio) and gate_error_ratio <= 1.0 else "FAIL",
                    "gate_role": "diagnostic_startup_ghost_station_candidate_not_hard_gate",
                }
            )
    return pd.DataFrame(rows)


