        "reference_value",
        "computed_value",
        "gate_error_ratio",
        "status",
        "baseline_default_gate_error_ratio",
        "gate_delta_vs_default",
        "matched_clip_inner_free_surface_to_waterline",
        "matched_two_zone_inner_free_surface",
        "matched_inner_free_surface_known_potential_rhs_scale",
        "matched_inner_free_surface_known_potential_body_row_scale",
        "matched_inner_free_surface_known_potential_free_row_scale",
        "matched_inner_free_surface_known_potential_control_row_scale",
        "provider_route",
        "solver_status",
        "diagnostic_conclusion",
        "candidate_default_gate_eligible",
