        benchmark = str(data["benchmark"].iloc[0]) if "benchmark" in data.columns else path.stem.replace(
            "_external_section_frequency_shape_summary",
            "",
        )
        divergent = data[data["shape_status"].astype(str).eq("section_frequency_shape_divergence")]
        if not divergent.empty:
            fragments = []
            for _, row in divergent.head(4).iterrows():
                b33_ratio = row.get("external_to_pdstrip_style_b33_median_ratio", math.nan)
                b33_spread = row.get("external_to_pdstrip_style_b33_ratio_spread", math.nan)
