def _faltinsen_eigenvalue_report_lines(out_dir: Path) -> list[str]:
    path = out_dir / "faltinsen_ch9_eigenvalues.csv"
    if not path.exists():
        return []
    try:
        data = pd.read_csv(path)
    except Exception:  # pragma: no cover - report should not fail validation
        return []
    if data.empty or "mode" not in data.columns:
        return []
    fragments: list[str] = []
    for _, row in data.iterrows():
        try:
            fragments.append(
                f"{row['mode']}: real_err={float(row['real_part_rel_error']):.3g}, "
                f"imag_err={float(row['imaginary_abs_rel_error']):.3g}, status={row['mode_status']}"
            )
        except (TypeError, ValueError):
            continue
    if not fragments:
        return []
    max_real = pd.to_numeric(data["real_part_rel_error"], errors="coerce").max()
    max_imag = pd.to_numeric(data["imaginary_abs_rel_error"], errors="coerce").max()
    overall = "PASS" if data["mode_status"].astype(str).eq("PASS").all() else "FAIL"
    return [
        f"- Faltinsen Table 9.2 eigenvalue comparison: overall={overall}, "
        f"max_real_error={float(max_real):.3g}, max_frequency_error={float(max_imag):.3g}; "
        + "; ".join(fragments)
        + "."
    ]


def _amplitude_shape_report_lines(out_dir: Path) -> list[str]:
    lines: list[str] = []
    for path in sorted(out_dir.glob("*_regular_wave_amplitudes_shape_summary.csv")):
        try:
            data = pd.read_csv(path)
        except Exception:  # pragma: no cover - report should not fail validation
            continue
        if data.empty or "shape_status" not in data.columns:
            continue
        benchmark = str(data["benchmark"].iloc[0]) if "benchmark" in data.columns else path.stem.replace(
            "_shape_summary",
            "",
        )
        failing = data[pd.to_numeric(data["fail_checks"], errors="coerce").fillna(0).gt(0)].copy()
        if failing.empty:
            focus = data.sort_values(["best_fit_normalized_shape_rmse", "metric"]).head(4)
        else:
            focus = failing.sort_values(
                ["fail_checks", "best_fit_normalized_shape_rmse", "metric"],
                ascending=[False, True, True],
            ).head(4)
        fragments: list[str] = []
        for _, row in focus.iterrows():
            try:
                fragments.append(
                    f"{row['metric']}/{row['prediction_model']}: "
                    f"corr={float(row['signed_shape_correlation']):.3g}, "
                    f"scaled_rmse={float(row['best_fit_normalized_shape_rmse']):.3g}, "
                    f"slope_delta={float(row['predicted_minus_reference_log_slope']):.3g}, "
                    f"status={row['shape_status']}"
                )
            except (TypeError, ValueError):
                continue
        if fragments:
            lines.append(f"- `{benchmark}` amplitude shape audit: {'; '.join(fragments)}.")
    return lines


